P.transport["item:99-year-old-port"] = {
  hash = "d7d79a",
  fullHash = "d7d79a",
  text = "99-Year-Old Port. The 99-Year-Old Port is an exceptionally rare bottle of vintage liquor shipped from Booty Bay as a personal gift for Gazlowe. After a cargo accident on the Ratchet docks, it was snatched away by a lunatic named Mad Magglish, who fled into the twisting tunnels outside the Wailing Caverns. Transporting precious freight across the Great Sea always carries risks, but Crane Operator Bigglefuzz made things far worse during a routine morning unloading in Ratchet. Attempting to clear an overwhelming shipment from Booty Bay, the goblin overloaded his crane and brought a mountain of crates crashing down onto the docks. In the chaos, the town eccentric—a troublesome figure known as Mad Magglish—snatched an extraordinarily aged bottle of 99-Year-Old Port and bolted into the hills toward the Wailing Caverns.",
  ["1"] = {
    {file = "Audio/Transport/full_item_99-year-old-port-a557edbc01c387e95b6b/1-0000.mp3", duration = 46.9681633, start = 0},
  },
}
P.transport["item:a-bloodstained-journal-page"] = {
  hash = "fa0bcd",
  fullHash = "fa0bcd",
  text = "A Bloodstained Journal Page. A torn, bloodstained parchment examined during the investigation into Stalvan Mistmantle. A few words remain legible through the thick blood, and Commander Althea Ebonlocke asks that its handwriting be checked. Commander Althea Ebonlocke keeps a vigilant watch over Darkshire and asks for the handwriting on this torn, blood-spattered page to be examined. Despite the thick blood, a few words remain legible enough for Clerk Daltry to compare with the Town Registry.",
  ["1"] = {
    {file = "Audio/Transport/full_item_a-bloodstained-journal-page-8fa4c465024e2cef3d99/1-0000.mp3", duration = 26.7493878, start = 0},
  },
}
P.transport["item:a-clue-to-sanders-treasure"] = {
  hash = "4c81ca",
  fullHash = "4c81ca",
  text = "A Clue to Sanders' Treasure. A Clue to Sanders' Treasure is a weathered parchment left behind by the notorious pirate Captain Sanders. It serves as the second step in a treasure hunt scattered across the bluffs and coastlines of Westfall. Discovered after following Captain Sanders' initial treasure map, this parchment provides directions further inland into Westfall. The scrawled note directs the finder due east from the coast, urging them to climb up the bluffs toward the main road. Sanders hid his next marker inside an old barrel resting near the crumbling stone ruins of an abandoned chimney, leading seekers deeper into the troubled farmlands.",
  ["1"] = {
    {file = "Audio/Transport/full_item_a-clue-to-sanders-treasure-e66afc031bdaa4d1c4bd/1-0000.mp3", duration = 34.8212245, start = 0},
  },
}
P.transport["item:a-dusty-unsent-letter"] = {
  hash = "aeeaec",
  fullHash = "aeeaec",
  text = "A Dusty Unsent Letter. A Dusty Unsent Letter is a forgotten parchment recovered from an old footlocker in Westfall. It offers vital proof that the elusive Stalvan Mistmantle lived in Moonbrook before his disappearance. While searching for the past of the mysterious Stalvan Mistmantle, investigators discover this unsent letter tucked away inside an old footlocker in Moonbrook. Darkshire's town registry still listed his last address as the Moonbrook Schoolhouse, and Clerk Daltry wanted word on whether he had truly lived there. This unmailed correspondence provides the missing link, confirming that Stalvan resided in the Westfall township for a time. Yet its presence also raises ominous questions, as retrieving it disturbs a vengeful Forlorn Spirit that guards the remnants of Stalvan's past with bitter malice.",
  ["1"] = {
    {file = "Audio/Transport/full_item_a-dusty-unsent-letter-5884f38fa103300373db/1-0000.mp3", duration = 44.1730612, start = 0},
  },
}
P.transport["item:a-faded-journal-page"] = {
  hash = "e937d3",
  fullHash = "e937d3",
  text = "A Faded Journal Page. A Faded Journal Page is an old parchment retrieved from an upstairs chest in Marshal Haggard's secluded home in Elwynn Forest. It serves as a vital clue in unraveling the dark history surrounding Stalvan Mistmantle. Left behind inside an old trunk when retired Marshal Haggard took residence near the eastern border of Elwynn Forest, this weathered parchment sat undisturbed for years. With Haggard's failing eyesight preventing him from deciphering it, the page remained neglected until adventurers digging into the legend of Stalvan Mistmantle retrieved it.",
  ["1"] = {
    {file = "Audio/Transport/full_item_a-faded-journal-page-887d7cb4cef661a77156/1-0000.mp3", duration = 31.9216327, start = 0},
  },
}
P.transport["item:a-letter-to-grelin-whitebeard"] = {
  hash = "9600ab",
  fullHash = "9600ab",
  text = "A Letter to Grelin Whitebeard. This sealed correspondence is addressed to Grelin Whitebeard, an experienced dwarf stationed out in the snowy wilderness of Coldridge Valley. Sent from the mountain capital of Ironforge, it serves as a rare dispatch of news and instructions reaching the remote frontier. Life in the snowy basin of Coldridge Valley can be isolated, especially for those stationed beyond the safety of Anvilmar. Letters like this represent the crucial link connecting scouts and scholars in the field to the halls of Ironforge. Carried southward along the mountain paths, the missive brings word from the capital to Grelin Whitebeard's wilderness campsite.",
  ["1"] = {
    {file = "Audio/Transport/full_item_a-letter-to-grelin-whitebeard-6a6251af9c534817d687/1-0000.mp3", duration = 35.2914286, start = 0},
  },
}
P.transport["item:a-mysterious-message"] = {
  hash = "f79319",
  fullHash = "f79319",
  text = "A Mysterious Message. A Mysterious Message is a piece of correspondence intercepted from a courier traveling across Westfall. Addressed among conspirators, the dispatch provides the People's Militia with concrete evidence linking Edwin VanCleef directly to the leadership of the Defias Brotherhood. Carried by a courier journeying between the Defias operations at Moonbrook, the Gold Coast Quarry, and the Jangolode Mine, this message represents a crucial break in Gryan Stoutmantle's investigation. For weeks, the People's Militia suspected organized direction behind the bandit uprising, but lacked irrefutable proof. Intercepting this missive confirms beyond doubt that Edwin VanCleef commands the brotherhood's efforts across the region, directing his network through coded ranks and intermediaries.",
  ["1"] = {
    {file = "Audio/Transport/full_item_a-mysterious-message-0673debbe0c31b15bfe5/1-0000.mp3", duration = 43.8595918, start = 0},
  },
}
P.transport["item:a-simple-compass"] = {
  hash = "fc3459",
  fullHash = "fc3459",
  text = "A Simple Compass. A Simple Compass is an old personal keepsake belonging to the City Architect of Stormwind, Baros Alexston. Stored away inside a small chest at his family's burned-down homestead in Westfall, it serves as a cherished memento of his youth before he rose to prominence in the capital. Long before Baros Alexston became a master architect directing major works in Cathedral Square, he grew up laboring on his family's farm in Westfall. The simple compass was his very first navigational instrument, likely sparking his early interest in geometry, drafting, and exploration. When the Alexston Farmstead fell victim to the Defias Brotherhood's raids and burned, the compass was left behind inside a sturdy chest amidst the ruins, preserved even as the surrounding farmland was overrun by bandits. Baros's father managed to escape the farmstead's destruction but could not carry the family's possessions with him to safety. While the instrument possesses little practical utility to a master builder working within the stone walls of Stormwind City, its emotional significance remains immense. Returning it to Baros offers him a rare, intact link to his humble beginnings and the peaceful countryside of his childhood.",
  ["1"] = {
    {file = "Audio/Transport/full_item_a-simple-compass-d7e1bbae2a4a62a0b425/1-0000.mp3", duration = 67.9967347, start = 0},
  },
}
P.transport["item:a-stack-of-letters"] = {
  hash = "c48316",
  fullHash = "c48316",
  text = "A Stack of Letters. A Stack of Letters is a small bundle of correspondence brought through the mountain pass into Coldridge Valley. Though initially believed to belong entirely to Talin Keeneye, the bundle holds communications meant for multiple scouts stationed in the freezing wilderness. Reaching remote camps within Dun Morogh's rugged mountains is grueling work, and postal runners often rely on passing travelers to carry mail out of Anvilmar. This bundle of letters arrived through the pass destined for scouts stationed deeper in Coldridge Valley. While thought to be solely for Talin Keeneye at his lakeside camp, sorting through the parcel reveals missives meant for other outposts across the snows, including mountaineer Grelin Whitebeard.",
  ["1"] = {
    {file = "Audio/Transport/full_item_a-stack-of-letters-a2d73464abb9a73b1e7b/1-0000.mp3", duration = 38.8963265, start = 0},
  },
}
P.transport["item:a-torn-journal-page"] = {
  hash = "dc9217",
  fullHash = "dc9217",
  text = "A Torn Journal Page. A Torn Journal Page is a tattered piece of parchment recovered from an old shipping crate along the Stormwind City canals. It serves as an essential physical clue into the identity and dark history of Stalvan Mistmantle, connecting the grim happenings in Duskwood to records preserved in Elwynn Forest. Discovered hidden near the bottom of a sealed storage crate beside Stormwind City's canals—tucked beneath old books, family heirlooms, and a ceramic vase—this fragment was left behind among forgotten personal effects. Though damaged and worn, the handwriting upon the page carries a distinct script that points directly to Stalvan Mistmantle's past, prompting investigators to seek out those who might still recognize the hand that penned it.",
  ["1"] = {
    {file = "Audio/Transport/full_item_a-torn-journal-page-a388d4a6fca5298c6b6d/1-0000.mp3", duration = 42.9714286, start = 0},
  },
}
P.transport["item:abercrombie-s-crate"] = {
  hash = "a858c8",
  fullHash = "a858c8",
  text = "Abercrombie's Crate. Abercrombie's Crate is a lost container of delicate tools and collected herbs belonging to the eccentric hermit Abercrombie. It rests abandoned near the entrance of the Vul'Gol Ogre Mound in southern Duskwood after the old man was chased off by marauding ogres. While wandering far from his shack in western Duskwood to gather vegetation, Abercrombie crossed paths with a hostile gang of ogres. Fleeing for his life, the old hermit dropped his crate of precious instruments and harvested botanicals. The ogres hauled his belongings back to their stronghold at the Vul'Gol Ogre Mound, leaving the heavy chest sitting carelessly near their cave mouth.",
  ["1"] = {
    {file = "Audio/Transport/full_item_abercrombie-s-crate-986f930d5259e15d2065/1-0000.mp3", duration = 36.7281633, start = 0},
  },
}
P.transport["item:admiral-proudmoore-s-orders"] = {
  hash = "797b00",
  fullHash = "797b00",
  text = "Admiral Proudmoore's Orders. Admiral Proudmoore's Orders are written battle plans recovered from Kul Tiras forces entrenching themselves along the coastline of Durotar. Penned before the Grand Admiral's defeat at Theramore, the documents outline persistent military strategies that continue to threaten the nascent orc homeland. Even after the death of Grand Admiral Daelin Proudmoore at Theramore, his expeditionary forces refuse to yield. Recovered from Lieutenant Benedict's garrison at Tiragarde Keep, these tactical directives detail long-term maneuvers and fortifications designed to undermine the Horde. The orders prove that the Grand Admiral's offensive in Durotar was no hasty raid, but an organized campaign structured to endure long past his own demise. For the Horde, the recovered documents offer vital insight into Kul Tiras operations and potential reinforcements threatening their borders.",
  ["1"] = {
    {file = "Audio/Transport/full_item_admiral-proudmoore-s-orders-d8391e9336fe978e4541/1-0000.mp3", duration = 47.7779592, start = 0},
  },
}
P.transport["item:ados-fragment"] = {
  hash = "cbdf1e",
  fullHash = "cbdf1e",
  text = "Ados Fragment. The Ados Fragment is an inscribed piece of stone recovered from the Whelgar's Excavation site in the Wetlands. Together with three companion shards, it forms the Goaz Stone, an ancient relic bearing enigmatic Titan inscriptions. Unearthed in the muddy trenches of Whelgar's Excavation, the Ados Fragment is one of four missing pieces required to reconstruct the Goaz Stone. Prior to raptors overrunning the dig site, Prospector Whelgar began translating the primary tablet, only to discover that the inscriptions broke off at crucial moments. The scattered pieces—named Ados, Modr, Golm, and Neru—were lost across the ruins, concealed within ancient containers and dirt mounds amidst prowling beasts.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ados-fragment-0dd39118bd42f8262469/1-0000.mp3", duration = 41.3779592, start = 0},
  },
}
P.transport["item:agamand-family-axe"] = {
  hash = "31a4e9",
  fullHash = "31a4e9",
  text = "Agamand Family Axe. The Agamand Family Axe is an ancestral heirloom preserved within the Agamand family crypt in northern Tirisfal Glades. Once a martial symbol of the wealthy mill-owning dynasty, it is sought by Coleman Farthing to strip the undead family of their remaining dignity. Before the Third War, the Agamand dynasty reigned as prosperous landowners across the northern hills of Tirisfal Glades, maintaining vast mills and a private family crypt. The Agamand Family Axe rested among the ancestral arms entombed alongside deceased patriarchs and warriors, kept intact on underground weapon racks even as the Scourge overran the estate and slaughtered its inhabitants. When the Scourge raised the fallen Agamands as mindless thralls to the Lich King, their former servant Coleman Farthing survived—in undeath—with bitter hatred for his old masters. Farthing blames the family for his own demise and commissions Forsaken wanderers to enter the crypt, strip the weapon racks of the axe, sword, mace, and dagger, and erase the final vestiges of the Agamand heritage.",
  ["1"] = {
    {file = "Audio/Transport/full_item_agamand-family-axe-076016edd64d622b73a9/1-0000.mp3", duration = 59.3502041, start = 0},
  },
}
P.transport["item:agamand-family-dagger"] = {
  hash = "1c7b30",
  fullHash = "1c7b30",
  text = "Agamand Family Dagger. The Agamand Family Dagger is an ancestral heirloom of the fallen Agamand dynasty, resting on weapon racks within their ancestral crypt in northern Tirisfal Glades. Coleman Farthing seeks this blade alongside the rest of their family arsenal to strip his former masters of their remaining legacy and honor. Before the Third War, the Agamand family maintained vast estates and grain mills across the rolling meadows of Tirisfal Glades. Like the rest of their lineage's armaments, the Agamand Family Dagger survived the devastation wrought by the Scourge, locked within the family crypt north of Agamand Mills. Protected by the restless, undead remnants of the household and mindless minions of the Lich King, the dagger represents the prestige and martial heritage that once elevated the family above their servants and tenants. For Coleman Farthing, a Forsaken residing at Brill who died in the Agamands' service, the blade represents bitter resentment rather than noble lineage. Holding the family directly responsible for his death, Farthing directs adventurers into the Agamand Family Crypt to recover the dagger along with the family sword, axe, and mace. In stripping these ancestral armaments from their tomb, Farthing aims to rob the now-Scourge patriarchs of their last vestiges of dignity and ensure the Agamand memory is utterly extinguished.",
  ["1"] = {
    {file = "Audio/Transport/full_item_agamand-family-dagger-e6dd1ff90fb800018238/1-0000.mp3", duration = 78.1322449, start = 0},
  },
}
P.transport["item:agamand-family-mace"] = {
  hash = "575f25",
  fullHash = "575f25",
  text = "Agamand Family Mace. The Agamand Family Mace is an ancestral heirloom preserved within the Agamand Family Crypt in northern Tirisfal Glades. Once a symbol of pride for a wealthy dynasty of northern Lordaeron, it has become an object of spiteful retribution sought by their former servant Coleman Farthing. Before the Third War, the Agamand family held extensive farmlands and windmills in the northern reaches of Tirisfal Glades. Like the rest of the regional aristocracy, they fell before the plague of undeath. The Agamands were reanimated as mindless thralls in service to the Lich King, wandering their ruined estate while their ancient family treasures remained locked within the depths of the family crypt. The Agamand Family Mace is stored among these weapons, an emblem of a forgotten lineage now reduced to shambling Scourge.",
  ["1"] = {
    {file = "Audio/Transport/full_item_agamand-family-mace-d8efa1cded5c999cbf2e/1-0000.mp3", duration = 47.124898, start = 0},
  },
}
P.transport["item:agamand-family-sword"] = {
  hash = "ea14f3",
  fullHash = "ea14f3",
  text = "Agamand Family Sword. The Agamand Family Sword is a tarnished ancestral blade kept inside the Agamand Family Crypt in northern Tirisfal Glades. Once a proud symbol of the wealthy mill-owning dynasty, it is sought by the Forsaken Coleman Farthing to erase the final vestiges of his former masters' legacy. Before the Third War, the Agamand dynasty held immense wealth and influence across the rolling mills of northern Tirisfal Glades. When the Scourge swept through Lordaeron, the family met a gruesome end, their bodies raised into mindless thralls of the Lich King. Their ancestral weapons, including the ceremonial family sword, were sealed away in the Agamand Family Crypt at the northern edge of the mills. Stripping these blades from their burial racks serves not merely as looting, but as a deliberate act to break whatever memory and noble standing remains of the fallen household.",
  ["1"] = {
    {file = "Audio/Transport/full_item_agamand-family-sword-01a2e0f9cadb23c7610f/1-0000.mp3", duration = 49.3714286, start = 0},
  },
}
P.transport["item:ahanu-s-leather-goods"] = {
  hash = "de16c4",
  fullHash = "de16c4",
  text = "Ahanu's Leather Goods. Ahanu's Leather Goods is a bundled consignment of finished leather armor and supplies crafted atop the mesas of Thunder Bluff. Prepared by the leatherworker Ahanu, the parcel is bound for the Crossroads in the Barrens to supply wandering hunters and adventurers. The supply lines of the Horde depend on practical trade between established strongholds and frontier outposts. In Thunder Bluff, the artisan Ahanu works raw hides into finished apparel and gear, preparing this consignment specifically for trade beyond Mulgore. The bundle is destined for Jahan Hawkwing, a merchant operating in the bustling heart of the Barrens at the Crossroads. Because overland travel across the plains is slow, transporting the bundle introduces messengers to the aerial courier network maintained by the tauren, relying on Tal and Devrak's trained wind riders to ferry goods swiftly across long distances.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ahanu-s-leather-goods-df7e411ca20b8b1db91a/1-0000.mp3", duration = 50.3902041, start = 0},
  },
}
P.transport["item:alaric-s-remains"] = {
  hash = "d73b2a",
  fullHash = "d73b2a",
  text = "Alaric's Remains. Alaric's Remains are the recovered bones of an individual once interred in a shallow grave along Silverpine Forest. His lingering spirit bids travelers to carry what is left of him past the Rot Hide gnolls into the towers of Fenris Keep. Unearthed from an unremarkable shallow grave in Silverpine Forest, the remains belong to Alaric, a former resident of Fenris Isle. Rather than linger in an exposed pit, his spirit yearns for the place he cherished in life. He asks whoever unearths his bones to leave his ill-fitting boots behind and bring his skeletal remains directly into the keep, seeking quiet sanctuary far away from the scavengers prowling the mainland.",
  ["1"] = {
    {file = "Audio/Transport/full_item_alaric-s-remains-f8f78b26f92c5eccea96/1-0000.mp3", duration = 37.6946939, start = 0},
  },
}
P.transport["item:alien-egg"] = {
  hash = "f503b9",
  fullHash = "f503b9",
  text = "Alien Egg. The Alien Egg is an unusual and mysterious clutch found guarded by local wind serpents across the canyons of Thousand Needles. Despite its unfamiliar appearance, the native serpents protect the egg fiercely as if it were their own. Its presence has aroused the curiosity and concern of the tauren scouts stationed atop Freewind Post. Discovered resting at the base of the towering spires south and northeast of Freewind Post, the Alien Egg stands out dramatically from the typical fauna of the canyon floor. Rather than abandoning or destroying the odd clutch, the native serpents of the needles fiercely guard it alongside their own nests. Hagar Lightninghoof, a tauren brave keeping watch from the heights of Freewind Post, sought to retrieve the specimen to determine whether it represented a threat to the mesa settlements or merely an unusual variation of local reptilian life.",
  ["1"] = {
    {file = "Audio/Transport/full_item_alien-egg-77cea891d9e4e5323c83/1-0000.mp3", duration = 50.155102, start = 0},
  },
}
P.transport["item:alterac-granite"] = {
  hash = "b5c7cb",
  fullHash = "b5c7cb",
  text = "Alterac Granite. Alterac Granite is a prized, durable stone quarried from the mountainous terrain of northern Lordaeron, specifically around Darrow Hill in the Hillsbrad Foothills. Revered by master stonecutters for its exceptional resilience and grain, it is chosen by King Magni Bronzebeard's royal mason to carve an enduring tribute for fallen soldiers. When King Magni Bronzebeard ordered a monument to commemorate Sully Balloo—a brave dwarven defender who perished in the tragedy at the Thandol Span—ordinary quarry stone would not do. Grand Mason Marblesten, tasked with sculpting the memorial in Ironforge, insisted on obtaining Alterac Granite. Renowned as one of the finest stones available across the Eastern Kingdoms, its legendary durability ensures that the likeness and memory of a fallen hero can endure untarnished for generations. Harvesting Alterac Granite is far from a simple errand. The stone rests around Darrow Hill in the northern reaches of the Hillsbrad Foothills, close to the ruined territories of Alterac. With the region rife with hostile wildlife, lurking syndicate brigands, and lingering strife, retrieving unblemished slabs of this pristine stone requires bold adventurers willing to venture deep into contested lands to secure it for Ironforge's artisans.",
  ["1"] = {
    {file = "Audio/Transport/full_item_alterac-granite-cf4a2c314f8d1320b1fd/1-0000.mp3", duration = 72.8032653, start = 0},
  },
}
P.transport["item:altered-snapjaw-shell"] = {
  hash = "bb0fcb",
  fullHash = "bb0fcb",
  text = "Altered Snapjaw Shell. An Altered Snapjaw Shell is the carapace of a freshwater turtle inhabiting the lush oases of the Barrens. Druids studying the region examine these mutated shells to understand how strange subterranean fissures are warping the local wildlife. The freshwater turtles dwelling within the Lushwater and Stagnant Oases have undergone noticeable, unnatural changes. Believed to be drinking from springs fed by mysterious underground fissures, the oasis snapjaws exhibit altered carapaces that intrigue researchers at the Crossroads. Tonga Runetotem, a tauren druid seeking to divine the health of the land, gathers these shells to determine whether the energies welling up from the deep earth are an unnatural blight or something far stranger.",
  ["1"] = {
    {file = "Audio/Transport/full_item_altered-snapjaw-shell-7c4e64848fd2df990f43/1-0000.mp3", duration = 42.8146939, start = 0},
  },
}
P.transport["item:ambercorn"] = {
  hash = "b3482f",
  fullHash = "b3482f",
  text = "Ambercorn. Ambercorn is a sacred nut that falls from the tall, ancient trees scattered across Mulgore. Infused with natural magic, it serves as a vital reagent in tauren shamanic brews, most notably used to induce spiritual visions during youth trials. Gathered from beneath the sturdy boughs of Mulgore's great trees, ambercorns are more than ordinary nuts to the tauren. Rich with the spiritual vitality of the land, they hold latent magical properties that tauren mystics have understood and utilized for generations. Young hunters and wanderers learn early to keep their eyes on the grass beneath the canopy, honoring the Earth Mother's gifts that fall freely from above. In Bloodhoof Village, the seer Zarlman Two-Moons relies on ambercorn when preparing young tauren for the Rite of Vision. Combined with stones gathered from the plains' pristine water wells, ambercorn is steeped into the potent Water of the Seers. Consuming this ceremonial elixir before the ancestral flames allows an initiate's senses to shift, revealing a guiding spirit animal meant to lead them to their next destination.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ambercorn-940bd835fa0c55bca89b/1-0000.mp3", duration = 62.3804082, start = 0},
  },
}
P.transport["item:amethyst-phial"] = {
  hash = "20754f",
  fullHash = "20754f",
  text = "Amethyst Phial. The Amethyst Phial is a delicate ceremonial vessel entrusted to young night elf adventurers by Corithras Moonrage in Dolanaar. It is crafted specifically to gather and preserve sacred waters from the premier moonwell beneath the Oracle Tree. Entrusted to initiates on Teldrassil, the Amethyst Phial is the final vessel used in the Crown of the Earth pilgrimage. Corithras Moonrage tasks travelers with carrying it to the far northwestern reaches of the boughs, nestled within the Oracle Glade. There, beneath the ancient canopy of the Oracle Tree, lies the island's first and most potent moonwell. The phial is carefully dipped into these radiant waters to draw out the essence of Elune's grace, allowing druids and priestesses to study and tend to the unpredictable growth of the World Tree.",
  ["1"] = {
    {file = "Audio/Transport/full_item_amethyst-phial-a98e67697e458170f500/1-0000.mp3", duration = 44.3297959, start = 0},
  },
}
P.transport["item:an-undelivered-letter"] = {
  hash = "041b83",
  fullHash = "041b83",
  text = "An Undelivered Letter. An Undelivered Letter is a piece of long-forgotten mail left behind in Goldshire's Lion's Pride Inn. Penned years ago by the elusive Stalvan Mistmantle, it serves as a critical clue in unraveling the dark tale of his past. Years ago, a storm drove a traveling courier into the Lion's Pride Inn looking for dry lodging. Near midnight, the terrified messenger fled down the stairs in his sleeping clothes and vanished into the pouring rain, never to return. He abandoned a chest full of belongings on the second floor, including a letter written by Stalvan Mistmantle addressed to an estate in Stormwind City's Canal District.",
  ["1"] = {
    {file = "Audio/Transport/full_item_an-undelivered-letter-a3ae98f5f0c4896bec91/1-0000.mp3", duration = 36.0228571, start = 0},
  },
}
P.transport["item:anaya-s-pendant"] = {
  hash = "a09b94",
  fullHash = "a09b94",
  text = "Anaya's Pendant. Anaya's Pendant is a keepsake carried by the restless ghost of Anaya Dawnrunner among the ruins of Ameth'Aran. It serves as a tragic token of remembrance for her lover, Cerellean Whiteclaw, who survived the Sundering only to find her spirit still tormented millennia later. Ten thousand years ago, during the cataclysmic destruction of the Well of Eternity, the ancient kaldorei city of Ameth'Aran fell in ruin. Believing his beloved Anaya had perished, Cerellean Whiteclaw carried his profound grief into the long slumber alongside Shan'do Malfurion Stormrage. When he at last awakened, he wandered Darkshore only to discover that Anaya's tormented apparition still drifted through Ameth'Aran, bearing this very pendant. Unable to bear raising a hand against her himself, Cerellean asks passing travelers to release her spirit and recover the heirloom.",
  ["1"] = {
    {file = "Audio/Transport/full_item_anaya-s-pendant-997cb010b890126cdced/1-0000.mp3", duration = 49.3714286, start = 0},
  },
}
P.transport["item:ancient-moonstone-seal"] = {
  hash = "65013f",
  fullHash = "65013f",
  text = "Ancient Moonstone Seal. The Ancient Moonstone Seal is a powerful relic of Highborne sorcery forged long before the Sundering. Imbued with potent arcane binding magic, it served as the anchor holding the spirit of Asterion captive within the ruins of Bashal'Aran. Forged by Asterion's former master, the powerful Highborne sorcerer Athrikus Narassin, the Ancient Moonstone Seal was crafted to serve as an unbreakable metaphysical anchor. While the Well of Eternity still stood and Queen Azshara reigned, Athrikus used the artifact to bind Asterion's soul to the pillars of Bashal'Aran. Over ten millennia later, Asterion remained an incorporeal prisoner to its magic, unable to break the ward with any strength or spell he possessed.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ancient-moonstone-seal-0e10b3491508a34c9b83/1-0000.mp3", duration = 43.8595918, start = 0},
  },
}
P.transport["item:ancient-statuette"] = {
  hash = "fc9fcc",
  fullHash = "fc9fcc",
  text = "Ancient Statuette. The Ancient Statuette is a sunken relic recovered from the shores of the Zoram Strand in northwestern Ashenvale. Sought by the night elf Talen, the small effigy originates from the submerged ruins of the ancient city of Zoram. The waters off northwestern Ashenvale conceal the sunken remains of Zoram, a pre-Sundering night elven city lost beneath the waves ten thousand years ago. In recent days, the explorer Talen surveyed the submerged ruins from a small craft, seeking lost historical relics. When a vicious assault by naga drove him ashore, Talen abandoned most of his belongings in his flight, dropping the ancient statuette he had dredged up onto the tideline sand near his scuttled skiff. Talen considers the statuette his most prized possession and the entire justification for braving the monster-infested coast. Rather than merely being a piece of decorative stonework, he believes the effigy serves as an essential key to deciphering the architecture, history, and arcane secrets locked away beneath the surf of Zoram Strand.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ancient-statuette-65be6159b93bb80da5d6/1-0000.mp3", duration = 60.395102, start = 0},
  },
}
P.transport["item:andron-s-ledger"] = {
  hash = "3a17a4",
  fullHash = "3a17a4",
  text = "Andron's Ledger. Andron's Ledger is an intelligence document obtained from Andron Gant in the Undercity. The Deathstalkers seek it as part of an operative's early work gathering information for the Forsaken.",
  ["1"] = {
    {file = "Audio/Transport/full_item_andron-s-ledger-6b08a976d6044e24f703/1-0000.mp3", duration = 9.95265306, start = 0},
  },
}
P.transport["item:another-clue-to-sanders-treasure"] = {
  hash = "fc1ea1",
  fullHash = "fc1ea1",
  text = "Another Clue to Sanders' Treasure. Another Clue to Sanders' Treasure is a weathered parchment slip left behind by the notorious pirate Captain Sanders. Retrieved from an old barrel, it contains directional verse pointing fortune hunters toward a lonely landmark on the bluffs of Westfall. Captain Sanders was careful never to keep his stolen riches in plain sight. Instead of drawing a single map that could be seized at once, he split his instructions into a succession of riddles and buried markers. This scrap of parchment continues the trail, directing whoever holds it to turn north from the previous hiding place and seek out a discarded jug sitting near an isolated windmill towering over the sea cliffs.",
  ["1"] = {
    {file = "Audio/Transport/full_item_another-clue-to-sanders-treasure-a612f1fa96de4aa6d616/1-0000.mp3", duration = 37.3812245, start = 0},
  },
}
P.transport["item:arikara-serpent-skin"] = {
  hash = "4d15ed",
  fullHash = "4d15ed",
  text = "Arikara Serpent Skin. The Arikara Serpent Skin is the scaled hide taken from the mythical wind serpent Arikara atop Darkcloud Pinnacle. Carried back to Whitereach Post, it serves as tangible proof that the vengeance-seeking beast was summoned and slain. Arikara is a formidable wind serpent tied to ancient tauren legend, rumored to seek retribution against Cairne Bloodhoof amid shifting cultural ways. Using enchanted Incendia Powder prepared under the direction of Elder Magatha Grimtotem, champions light the sacred fire atop the burial bluffs of Darkcloud Pinnacle to force the spirit-beast into the physical realm. Stripping the serpent's hide yields the Arikara Serpent Skin—an unmistakable relic of the beast's demise.",
  ["1"] = {
    {file = "Audio/Transport/full_item_arikara-serpent-skin-adc4f184f60bfd31f317/1-0000.mp3", duration = 40.724898, start = 0},
  },
}
P.transport["item:arnak-s-hoof"] = {
  hash = "2dd193",
  fullHash = "2dd193",
  text = "Arnak's Hoof. Arnak's Hoof is the macabre proof of death taken from the criminal Arnak Grimtotem. Hunted down on the bluffs of Darkcloud Pinnacle, Arnak was marked for execution by the defenders of Freewind Post after murdering a fellow tauren and kidnapping his sister. Arnak Grimtotem earned notoriety throughout Thousand Needles as an outlaw whose brutality crossed even the contentious lines of tauren clan politics. After murdering another tauren and abducting the victim's sister, Lakota Windsong, a formal bounty was posted for his death. Arnak holed up on the heights of Darkcloud Pinnacle, surrounded by Grimtotem guards. Slaying him and claiming his severed hoof serves as undeniable confirmation for Cliffwatcher Longhorn at Freewind Post that the murderer has finally answered for his crimes.",
  ["1"] = {
    {file = "Audio/Transport/full_item_arnak-s-hoof-f40b6e7b2b5ee8b1d566/1-0000.mp3", duration = 44.4865306, start = 0},
  },
}
P.transport["item:astor-s-letter-of-introduction"] = {
  hash = "f26195",
  fullHash = "f26195",
  text = "Astor's Letter of Introduction. Astor's Letter of Introduction is a document carried by Astor Hadren, a courier traveling between Silverpine Forest and the Undercity. Taken by aspiring Deathstalkers, the letter serves as cover to infiltrate a suspected conspiracy involving the shopkeeper Andron Gant. Astor Hadren served as a discreet courier moving between Silverpine Forest and the capital. His personal letter of introduction establishes the bearer's bona fides to illicit contacts in the city. When Deathstalker handler Mennet Carkad needed to investigate suspicious leaks within the Undercity, Astor's travels made him an immediate target. By eliminating or robbing Hadren of his papers, an operative can assume his identity and intercept covert communications meant for Astor's eyes alone.",
  ["1"] = {
    {file = "Audio/Transport/full_item_astor-s-letter-of-introduction-984e6d62b6cd106544f5/1-0000.mp3", duration = 44.3297959, start = 0},
  },
}
P.transport["item:ataeric-s-staff"] = {
  hash = "c48fc7",
  fullHash = "c48fc7",
  text = "Ataeric's Staff. Ataeric's Staff is a powerful magical conduit wielded by Archmage Ataeric, a senior Dalaran wizard in Silverpine Forest. It serves as both a focus for manipulating local ley lines and physical proof of the archmage's defeat for the Forsaken at the Sepulcher. Carried by Archmage Ataeric, this staff was used to direct and harness ley energies in southern Silverpine Forest. Under Dalaran's direction, Ataeric attempted to reactivate an ancient ley energy node near the borders of the magocracy's territory. The staff acted as a vital tool for weaving these immense ambient currents, rendering the archmage a formidable threat to nearby Forsaken settlements. Alarmed by Dalaran's magical expansion, Shadow Priest Allister ordered Ataeric's assassination and demanded the recovery of the staff. With Ataeric slain and his staff recovered, the concentrated ley energies collapsed back into dormancy. Bringing the staff to the Sepulcher marked a decisive victory against Dalaran's ambitions, though the Forsaken remain watchful of the latent power remaining in the earth.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ataeric-s-staff-9237ed20431fdddb04a8/1-0000.mp3", duration = 62.484898, start = 0},
  },
}
P.transport["item:athrikus-narassin-s-head"] = {
  hash = "5cf7f8",
  fullHash = "5cf7f8",
  text = "Athrikus Narassin's Head. This severed head is proof of the death of Athrikus Narassin, an ancient warlock who directed dark rituals in northern Darkshore. Taken from the heights of the ruined spire, it serves to confirm the disruption of demonic activity centered around the Tower of Althalaxx. Perched at the pinnacle of the Tower of Althalaxx, Athrikus Narassin commanded a coven of dark sorcerers practicing fel magic along the Darkshore coast. Ancient and entrenched, Narassin coordinated demonic summonings that threatened the surrounding wilderness. Claiming his head shatters the coven's leadership, driving back their immediate foothold in the region, even if the lingering corruption promises future vigilance will be needed.",
  ["1"] = {
    {file = "Audio/Transport/full_item_athrikus-narassin-s-head-c2e1678195cd91ecd08b/1-0000.mp3", duration = 40.5681633, start = 0},
  },
}
P.transport["item:bag-of-empty-ooze-containers"] = {
  hash = "8704d2",
  fullHash = "8704d2",
  text = "Bag of Empty Ooze Containers. The Bag of Empty Ooze Containers is a set of sterile glassware supplied by the gnome researcher Laris Geardawdle in Ironforge. Prepared for delicate field collection, it holds empty sample jars intended to capture pristine, uncorrupted slime specimens across Azeroth. While investigating the bizarre biology of Azeroth's oozes, Laris Geardawdle realized that slime creatures rapidly absorb and mirror the corruption of their surroundings. Having studied tainted residues from places like Felwood, the gnome scientist commissioned these robust sample jars to withstand acidic specimens while preserving their natural state. The satchel holds enough jars for an explorer to gather clean, unpolluted slime from wild, untouched regions—most notably the primordial wilderness of Un'Goro Crater, where ancient glutinous oozes thrive free from demonic taint.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bag-of-empty-ooze-containers-ca80003bea4d4025465f/1-0000.mp3", duration = 48.9012245, start = 0},
  },
}
P.transport["item:balnir-snapdragons"] = {
  hash = "b12732",
  fullHash = "b12732",
  text = "Balnir Snapdragons. Balnir Snapdragons are vibrant flowers cultivated at the Balnir Farmstead in eastern Tirisfal Glades. Naturally receptive to magical currents, they serve the Forsaken as delicate indicators for detecting the creep of Scourge corruption from the bordering Plaguelands. These colorful blooms still grow in the garden of the Balnir Farmstead, a homestead in eastern Tirisfal Glades left in ruin by the fall of Lordaeron and the rise of the Scourge. Lying so close to the Plaguelands to the east, the garden sits right where the Lich King's blight presses against Tirisfal, which makes its flowers a telling place to look for the spread of that corruption. Because snapdragons are unusually sensitive to atmospheric magic, they act as living barometers for magical blights. Anastasia Hartwell and the Forsaken mages in the Undercity seek fresh specimens from the farmstead's window boxes. By turning the plants over to the Royal Apothecary Society, the Undercity hopes to analyze the flora and measure how deeply the Lich King's plague has seeped across the border into Tirisfal's soil.",
  ["1"] = {
    {file = "Audio/Transport/full_item_balnir-snapdragons-e759a1ea7d6b9c0f089c/1-0000.mp3", duration = 59.637551, start = 0},
  },
}
P.transport["item:baron-longshore-s-head"] = {
  hash = "85d950",
  fullHash = "85d950",
  text = "Baron Longshore's Head. This severed head is proof of the death of Baron Longshore, captain of the Southsea Freebooter vessel Heedless. Gazlowe posted a public bounty for the pirate's identifiable remains to protect Ratchet's commercial shipping along the Merchant Coast. Operating out of camps along the Merchant Coast south of Ratchet, Baron Longshore directed raids against regional merchant vessels on behalf of the Southsea Freebooters. His flagship, the Heedless, posed a direct threat to the goblin trade lanes linking Kalimdor to the Eastern Kingdoms. Gazlowe, Chief Engineer of Ratchet, placed a bounty on Longshore requiring identifiable proof of demise. Delivering the pirate's head satisfies the contract and secures a monetary reward from the port authority.",
  ["1"] = {
    {file = "Audio/Transport/full_item_baron-longshore-s-head-2b12a5092e086ebb896b/1-0000.mp3", duration = 42.0832653, start = 0},
  },
}
P.transport["item:barrel-of-barleybrew-scalder"] = {
  hash = "3e91ce",
  fullHash = "3e91ce",
  text = "Barrel of Barleybrew Scalder. The Barrel of Barleybrew Scalder is a cask of stout ale crafted by the Barleybrew family to prove their brewing prowess against their chief competitors. It is entrusted to covert couriers tasked with infiltrating the Thunderbrew Distillery in Kharanos to stage a sly taste-test sabotage. Brewing is serious business among the dwarves of Dun Morogh, and few rivalries burn hotter than the feud between the Thunderbrews and the Barleybrews. While the Thunderbrews enjoy vast renown and pride of place from their busy distillery in Kharanos, Marleth Barleybrew refuses to sit in their shadow. Rather than relying solely on open taverns, Marleth brews the fiery 'Scalder' to prove his recipes are second to none—hoping that unsuspecting patrons who taste it will realize the Thunderbrews do not hold a monopoly on fine dwarven drink.",
  ["1"] = {
    {file = "Audio/Transport/full_item_barrel-of-barleybrew-scalder-6752686403e0cadd7db6/1-0000.mp3", duration = 45.9232653, start = 0},
  },
}
P.transport["item:barrel-of-shimmer-stout"] = {
  hash = "b40df9",
  fullHash = "b40df9",
  text = "Barrel of Shimmer Stout. A freshly brewed cask of Rejold Barleybrew's experimental dwarven ale, crafted in the cold reaches of Dun Morogh. Known for giving drinkers a potent jolt that supposedly brightens their vision, it is intended as a gift for guards keeping watch on the high mountain passes. Crafted by Rejold Barleybrew after gathering rare ingredients across Dun Morogh, Shimmer Stout represents the latest triumph of the storied Barleybrew family. Dwarven brewers take their craft with deadly seriousness, constantly competing to produce hearty concoctions capable of staving off the freezing mountain chill. Rejold's latest recipe is designed not only to warm the gut, but to sharpen the senses of those stationed out in the freezing winds. This particular barrel is earmarked for Mountaineer Wellart Barleybrew, who stands guard at the southern tower along the pass leading into Loch Modan. Out on the lonely frontier, mountaineers endure bone-chilling cold and prolonged watches between skirmishes with troggs and wildlife. A fresh cask of family ale serves as both a welcome taste of home and an energizing tonic potent enough to make a tired sentry swear he can see clearly through the dark.",
  ["1"] = {
    {file = "Audio/Transport/full_item_barrel-of-shimmer-stout-86848e676f91db5bc26d/1-0000.mp3", duration = 67.2653061, start = 0},
  },
}
P.transport["item:barrel-of-thunder-ale"] = {
  hash = "724590",
  fullHash = "724590",
  text = "Barrel of Thunder Ale. The Barrel of Thunder Ale is a prized keg of Kharanos's signature brew, smuggled straight out of the Thunderbrew Distillery's cellar. Swapped out for a cask of Marleth's Barleybrew Scalder, it serves as undeniable proof of foul play in an escalating brewing rivalry. In Dun Morogh, competition between rival master brewers runs deep, and few disputes are fiercer than the feud between the Thunderbrews of Kharanos and the Barleybrews of Brewnall Village. Marleth Barleybrew sought to slip a barrel of his own Barleybrew Scalder into his rivals' cellar, so that the Thunderbrews' patrons would taste his brew over theirs. This heavy barrel of Thunder Ale was seized in the exchange, dragged out under the noses of the local guards as physical evidence that the switch succeeded.",
  ["1"] = {
    {file = "Audio/Transport/full_item_barrel-of-thunder-ale-01f74b9bee3daf11e30a/1-0000.mp3", duration = 44.564898, start = 0},
  },
}
P.transport["item:barrow-key"] = {
  hash = "efe9a1",
  fullHash = "efe9a1",
  text = "Barrow Key. The Barrow Key is one of three druidic keys hidden within the Talon Den atop Stonetalon Peak. It is kept locked inside a barrow cache to guard the ancient treasures sealed within the den's hoard. Within the subterranean barrows of the Talon Den, night elf druids established elaborate wards to protect their relics from interlopers. The Barrow Key is one piece of this multi-layered lock, concealed inside a specialized cache hidden among the subterranean passages. Accessing it requires the Gatekeeper's Key, ensuring that only those with knowledge of the druids' defensive network can ever hope to claim it.",
  ["1"] = {
    {file = "Audio/Transport/full_item_barrow-key-b5c9b6b439e7a072cde2/1-0000.mp3", duration = 33.6195918, start = 0},
  },
}
P.transport["item:bartleby-s-mug"] = {
  hash = "97e400",
  fullHash = "97e400",
  text = "Bartleby's Mug. Bartleby's Mug is the personal drinking vessel of the stubborn brawler Bartleby in Stormwind. Surrendered only after a tavern brawl and emptied down to the last drop, it serves as proof of a warrior's ability to forcefully persuade an uncooperative opponent. To the casual tavern regular, Bartleby's Mug is nothing more than ordinary drinkware clutched tight by a notoriously stubborn drinker. For a novice warrior training in Stormwind, however, wrestling the vessel away from Bartleby is a test of sheer physical dominance. Bartleby will not relinquish his beloved mug until knocked into submission—and even then, he insists on draining every last drop before handing it over as a trophy.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bartleby-s-mug-d293f5ac9ff7f90508f3/1-0000.mp3", duration = 39.8628571, start = 0},
  },
}
P.transport["item:bathran-s-hair"] = {
  hash = "f24ed8",
  fullHash = "f24ed8",
  text = "Bathran's Hair. Bathran's Hair is a rare, delicate herb found among the ruins of Bathran's Haunt in northwestern Ashenvale. Celebrated in night elf lore for its potent restorative qualities, the plant is believed to mend afflictions of the spirit as well as the flesh. Grown in the shadows of the ancient ruins north of Maestra's Post, Bathran's Hair has long been valued by night elf healers. Unlike common medicinal flora that soothe simple physical wounds, this herb possesses restorative properties said to cure deep ailments of the spirit. When a young night elf in Astranaar falls victim to an insidious, unyielding sickness, the herbalist Orendil Broadleaf seeks strands of this rare plant to brew a vital remedy.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bathran-s-hair-d4c876846b9800b8919d/1-0000.mp3", duration = 41.2995918, start = 0},
  },
}
P.transport["item:battleboar-flank"] = {
  hash = "ed8e43",
  fullHash = "ed8e43",
  text = "Battleboar Flank. Battleboar Flanks are hearty cuts of meat harvested from the vicious battleboars trained by Bristleback quilboar in Mulgore. Collected by young hunters around Camp Narache, they serve both as proof of culled threats and as nourishing sustenance for the tauren tribe. The Bristleback quilboar lurking in Brambleblade Ravine have trained vicious battleboars to encroach on tauren hunting grounds. While these aggressive beasts pose a direct hazard to the young tauren coming of age at Camp Narache, nothing taken from nature is wasted. Grull Hawkwind directs novice hunters to harvest the flanks of these felled beasts alongside their snouts. The cuts of flank provide rich, sustaining meat that is cooked down into hearty stew for the tribe's youth, turning a quilboar weapon of war into vital tribal nourishment.",
  ["1"] = {
    {file = "Audio/Transport/full_item_battleboar-flank-f695d459f2bec672854e/1-0000.mp3", duration = 43.5983673, start = 0},
  },
}
P.transport["item:battleboar-snout"] = {
  hash = "249ade",
  fullHash = "249ade",
  text = "Battleboar Snout. Battleboar Snouts are harvested from the aggressive boars trained by the Bristleback quilboar in Mulgore. Collected by young tauren hunters, they serve both as proof of thinning an invasive threat and as hearty ingredients for tribal cooking in Camp Narache. In the shadow of Red Cloud Mesa, the Bristleback quilboar train malicious battleboars within Brambleblade Ravine to probe tauren hunting grounds. When young braves are sent out by Grull Hawkwind to push back against this encroachment, the snout serves as undeniable proof of a beast brought down. Rather than wasting any part of the kill, the tauren use these snouts alongside cuts of flank to prepare rich, sustaining stews to feed their young.",
  ["1"] = {
    {file = "Audio/Transport/full_item_battleboar-snout-ed0fe061ff13bbde1dba/1-0000.mp3", duration = 39.6277551, start = 0},
  },
}
P.transport["item:battleworn-axe"] = {
  hash = "31384d",
  fullHash = "31384d",
  text = "Battleworn Axe. Battleworn Axes are crude, notch-scarred weapons carried by the Blackrock orcs invading the Redridge Mountains. Marshal Marris accepts these recovered blades in Lakeshire as physical proof of dead invaders threatening the local populace. These heavy, nicked axes serve as standard gear for the Blackrock reavers pushing south from the Burning Steppes into Redridge. For Marshal Marris and the beleaguered town watch of Lakeshire, collecting them serves two purposes: ensuring another marauding orc has fallen, and gathering physical evidence of how heavily armed the encroaching warband truly is. Blackrock invaders have fortified Stonewatch Keep and established footholds in the southeastern pockets of Redridge, effectively trapping townspeople within Lakeshire. Stripping the raiders of their battleworn weapons directly diminishes the arms available to the warband while clearing the roads for Alliance travel.",
  ["1"] = {
    {file = "Audio/Transport/full_item_battleworn-axe-9a39bdfd02ad21089186/1-0000.mp3", duration = 51.5918367, start = 0},
  },
}
P.transport["item:berard-s-journal"] = {
  hash = "da39e3",
  fullHash = "da39e3",
  text = "Berard's Journal. Berard's Journal is a collection of research notes penned by Apothecary Berard before he fell victim to Archmage Arugal's curse. Left behind in Pyrewood Village, the book documents Berard's study of an ancient plague that once wiped out the aquatic life of Lake Lordamere, making it highly valuable to the Royal Apothecary Society. Before Archmage Arugal unleashed his shadow magic across Silverpine Forest, Apothecary Berard was considered one of the Royal Apothecary Society's most promising minds. Stationed in Pyrewood Village, he focused his work on an ancient, virulent blight that had eradicated all aquatic life within Lake Lordamere centuries prior. When Arugal's curse gripped the settlement, Berard's mind was shattered, turning him into another mindless thrall. His detailed field notes remained behind on a bookshelf in his quarters at the Pyrewood Village Inn.",
  ["1"] = {
    {file = "Audio/Transport/full_item_berard-s-journal-9cd87f5263c2fecd3539/1-0000.mp3", duration = 50.0244898, start = 0},
  },
}
P.transport["item:bernice-s-necklace"] = {
  hash = "5250ec",
  fullHash = "5250ec",
  text = "Bernice's Necklace. Bernice's Necklace is a sentimental heirloom belonging to \"Auntie\" Bernice Stonefield of the Stonefield Farm in Elwynn Forest. Originally worn as a lucky charm by her late husband during his military service, the trinket was lost near the Fargodeep Mine and snatched by an opportunistic kobold. Though known locally as Bernice's necklace, the piece originally belonged to Auntie Bernice Stonefield's late husband. A veteran of Stormwind's military campaigns, he carried the charm as a token of good fortune into battle. According to Bernice, the only time tragedy struck was during his final campaign—the one expedition where he forgot to bring his lucky necklace along. Following his death, the keepsake remained one of Bernice's most cherished possessions on the Stonefield Farm.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bernice-s-necklace-c4c0ee6d9b4697672ce7/1-0000.mp3", duration = 44.0946939, start = 0},
  },
}
P.transport["item:besseleth-s-fang"] = {
  hash = "3c464b",
  fullHash = "3c464b",
  text = "Besseleth's Fang. Besseleth's Fang is the massive venomous tooth harvested from the giant spider Besseleth in Sishir Canyon. Carried as proof of her demise, it represents the removal of a deadly threat stalking the trails of Stonetalon Mountains. Sishir Canyon has long been infested by aggressive arachnids, but none strike more terror into travelers than Besseleth. Growing to monstrous proportions, she and her brood turned the gorge into a death trap for wanderers navigating the Webwinder Path at night. The fang itself measures nearly two feet in length and drips with potent venom, making it an unmistakable signature of the broodmother's slaughter. Presenting this grisly trophy brings relief to local defenders who have suffered her venomous strikes.",
  ["1"] = {
    {file = "Audio/Transport/full_item_besseleth-s-fang-458f6767c002a0422d63/1-0000.mp3", duration = 42.0832653, start = 0},
  },
}
P.transport["item:bethor-s-scroll"] = {
  hash = "1bfce4",
  fullHash = "1bfce4",
  text = "Bethor's Scroll. Bethor's Scroll contains magical incantations scribed by Bethor Iceshard to counter the dark sorcery of his former colleague, Thule Ravenclaw. Created to aid Apothecary Renferrel in brewing a protective draught, the scroll is vital for surviving the Scourge necromancy guarding Fenris Isle. Upon examining tainted ichor recovered from Rot Hide gnolls, Bethor Iceshard recognized the handiwork of Thule Ravenclaw. Once a promising young mage of the Kirin Tor, Thule betrayed his brethren to serve the Lich King when the Scourge rose to power. Learning that Thule had survived and was directing Rot Hide attacks across Silverpine Forest from Fenris Isle, Bethor drew upon his intimate knowledge of his former colleague's spellcraft to author this scroll.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bethor-s-scroll-9abfd33f1df68f2611de/1-0000.mp3", duration = 43.3632653, start = 0},
  },
}
P.transport["item:bingles-blastencapper"] = {
  hash = "63c69d",
  fullHash = "63c69d",
  text = "Bingles' Blastencapper. Bingles' Blastencapper is a specialized explosive device designed by the gnome pilot Bingles Blastenheimer. Lost when his gyrocopter plunged into the Loch, it was stolen by local troggs, endangering Bingles' plans to support the liberation of Gnomeregan. Bingles' Blastencapper represents the peak of pilot Bingles Blastenheimer's personal ordnance. Built to deliver decisive aerial strikes against the troggs and leper gnomes overruning Gnomeregan, the explosive was aboard his gyrocopter when mechanical failure sent him plummeting into the waters of the Loch. While Bingles survived, troggs infesting the lake's northern islands pillaged his wreckage and dragged the volatile weapon back to their camps. To Bingles, the Blastencapper is far more than simple salvage. The exiled gnomes are actively preparing to take back their radioactive home, and Bingles considers his gyrocopter and signature munitions vital components of the impending air assault. Recovering this ordnance prevents the indigenous troggs of Loch Modan from accidentally triggering a catastrophe and preserves a valuable weapon for the gnomish resistance.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bingles-blastencapper-3a54f5c3f2ec714adbef/1-0000.mp3", duration = 64.6008163, start = 0},
  },
}
P.transport["item:bingles-hammer"] = {
  hash = "120098",
  fullHash = "120098",
  text = "Bingles' Hammer. Bingles' Hammer is an engineering tool belonging to Bingles Blastenheimer, an eccentric gnome aviator stranded in Loch Modan. After crashing his flying machine into the Loch, hostile troggs scavenged the hammer along with his other specialized gear. Bingles needs it recovered so he can repair his aircraft and aid the war effort to liberate Gnomeregan. When pilot Bingles Blastenheimer plunged into the waters of the Loch, his survival was only the first of his troubles. Troggs inhabiting the freshwater islands quickly raided the crash site, looting his specialized toolkit and high-potency explosives. Among the pilfered gear was his hammer, an indispensable implement for repairing the dented airframe and recalibrating the gyrocopter's mechanical assemblies. Without this essential tool and the rest of his equipment, Bingles remains thoroughly grounded, unable to fly support runs for the gnome liberation forces struggling to reclaim Gnomeregan.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bingles-hammer-7a9835da827b9e7b8075/1-0000.mp3", duration = 52.1665306, start = 0},
  },
}
P.transport["item:bingles-screwdriver"] = {
  hash = "913256",
  fullHash = "913256",
  text = "Bingles' Screwdriver. Bingles' Screwdriver is an essential engineering tool belonging to Bingles Blastenheimer, a gnome pilot who crashed his gyrocopter into the waters of Loch Modan. Following the crash, native troggs plundered the wreckage, scattering Bingles' tool buckets and specialized gear across the loch's northern islands. When Bingles Blastenheimer plummeted into the Loch, he lost more than his flying machine—he lost the specialized equipment needed to repair it. Among the scattered gear was his trusty screwdriver, packed away inside one of several tool buckets snatched up by opportunistic troggs inhabiting the nearby isles. For an engineer stranded in the wilderness, fine adjustment tools like this screwdriver are irreplaceable, especially when assembling delicate gyrocopter mechanisms or handling volatile armaments. Bingles is not merely a recreational aviator; he serves a larger cause dedicated to liberating the fallen city of Gnomeregan from troggs and leper gnomes. His mission relies on combining flight mechanics with his volatile Blastencapper munitions to deliver an aerial assault against the subterranean menace. Recovering this screwdriver alongside his wrench and hammer is crucial for putting his gyrocopter back together and keeping the gnomish airborne counteroffensive alive.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bingles-screwdriver-aacef2b5c4793dd53db7/1-0000.mp3", duration = 72.2285714, start = 0},
  },
}
P.transport["item:bingles-wrench"] = {
  hash = "f3cd0e",
  fullHash = "f3cd0e",
  text = "Bingles' Wrench. Bingles' Wrench is a vital piece of gnomish engineering gear belonging to the pilot Bingles Blastenheimer. Lost when Bingles crash-landed his flying machine into the Loch, it was hauled off by the local troggs alongside the rest of his toolkit. After Bingles Blastenheimer crashed his gyrocopter into the placid waters of the Loch, his survival quickly turned into an ordeal. Troggs inhabiting the small northern islands raided the crash site, looting his specialized supplies and scattering his tools into various buckets across their camps. Bingles' Wrench is one of three critical hand tools needed alongside his high-yield Blastencapper explosives. Without it, Bingles has no hope of repairing his downed gyrocopter, stalling his planned aerial offensive to aid the exiled gnomes fighting to reclaim Gnomeregan.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bingles-wrench-66d48726a6e1d759812b/1-0000.mp3", duration = 47.3861224, start = 0},
  },
}
P.transport["item:black-claw-stout"] = {
  hash = "36b160",
  fullHash = "36b160",
  text = "Black Claw Stout. Black Claw Stout is a special drink prepared by Zardeth of the Black Claw beneath the streets of Stormwind. Concocted for a meddlesome nobleman, it is delivered under the guise of an ordinary tavern beverage.",
  ["1"] = {
    {file = "Audio/Transport/full_item_black-claw-stout-759bb8d9d2a9d1453664/1-0000.mp3", duration = 11.4677551, start = 0},
  },
}
P.transport["item:black-feather-quill"] = {
  hash = "62b64a",
  fullHash = "62b64a",
  text = "Black Feather Quill. The Black Feather Quill is a sacred night elf relic used by the Druids of the Talon during their rites of hibernation and awakening. Stored within a dedicated chest in the Ban'ethil Barrow Den, it is one of several vital focuses needed to safely call slumbering druids back from the Emerald Dream. Night elf druidism relies on deeply attuned sacred items to navigate the threshold between the waking world and the Emerald Dream. The Black Feather Quill, along with the Raven Claw Talisman, the Sapphire of Sky, and the Rune of Nesting, forms the core set of ritual items required to break the delicate hibernation of the Druids of the Talon. Without these focuses, a slumbering druid risks remaining trapped within the Dream indefinitely, unable to rejoin their waking body. When corrupted Gnarlpine furbolgs overran the Ban'ethil Barrow Den, the sacred chests housing these treasures fell into danger. Left unguarded in the winding depths, the relics had to be recovered swiftly by order of Athridas Bearmantle in Dolanaar before the captive druids were lost forever to the Dream.",
  ["1"] = {
    {file = "Audio/Transport/full_item_black-feather-quill-5eccde4f7fc4d37214f6/1-0000.mp3", duration = 62.5371429, start = 0},
  },
}
P.transport["item:blackened-skull"] = {
  hash = "620ceb",
  fullHash = "620ceb",
  text = "Blackened Skull. A blackened skull is the darkened cranial remnant of a Darkeye Bonecaster animating in the Agamand Mills. Deathguard Dillinger in Brill demands these grisly trophies as proof of thinning the mindless Scourge forces threatening Tirisfal Glades. These blackened skulls are salvaged from the Darkeye Bonecasters haunting the Agamand Mills. These skeletal spellcasters direct necromantic malice against the living and the Forsaken alike, attempting to entrench a forward base for the Lich King's armies in northern Tirisfal. Presenting their ruined skulls to Deathguard Dillinger serves as tangible evidence that the Scourge's mystical vanguard is being crushed.",
  ["1"] = {
    {file = "Audio/Transport/full_item_blackened-skull-6a046ace1cd6203b9535/1-0000.mp3", duration = 38.2432653, start = 0},
  },
}
P.transport["item:bloodfeather-belt"] = {
  hash = "fddc89",
  fullHash = "fddc89",
  text = "Bloodfeather Belt. A Bloodfeather Belt is a crude leather strap worn by the Bloodfeather harpies infesting northern Teldrassil. Sentinel Arynia Cloudsbreak collects these belts as proof that local nests encroaching on the Oracle Glade have been cleared. The Bloodfeather harpies have nested aggressively in the boughs around the Oracle Glade, threatening the ancient Oracle Tree and choking travel through northern Teldrassil. When a runner carrying reports to Darnassus was ambushed and slain by the flock, Sentinel Arynia Cloudsbreak called on travelers to strike back directly at their nests. Taking the belts from fallen harpies serves as tangible proof that their numbers are being culled, securing the paths so communication with the capital can resume.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bloodfeather-belt-d4b612f973bc361ef078/1-0000.mp3", duration = 40.2546939, start = 0},
  },
}
P.transport["item:bloodfury-ripper-s-remains"] = {
  hash = "84859d",
  fullHash = "84859d",
  text = "Bloodfury Ripper's Remains. Bloodfury Ripper's Remains are the physical proof recovered from the matriarch of the Bloodfury harpies in the Charred Vale. Sought by Maggran Earthbinder at Sun Rock Retreat, this trophy confirms the death of the brood's ferocious leader, dealing a decisive blow to the harpy presence threatening the local tauren settlement. The Bloodfury harpies nesting within the scorched ruins of the Charred Vale have long posed a savage threat to the travelers and shamans of the Stonetalon Mountains. While culling their numbers thins the immediate danger, Maggran Earthbinder of Sun Rock Retreat recognizes that true reprieve requires eliminating their leadership. Bloodfury Ripper rules her flock almost as a queen, guiding their territorial aggression. Taking her remains is essential proof of her demise, scattering the remaining harpies into disarray and granting peace of mind to the tauren striving to heal and secure their rugged lands.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bloodfury-ripper-s-remains-d2387846544761a7e4c5/1-0000.mp3", duration = 51.7746939, start = 0},
  },
}
P.transport["item:bloodstone-choker"] = {
  hash = "d5f0d6",
  fullHash = "d5f0d6",
  text = "Bloodstone Choker. The Bloodstone Choker is a dark magical talisman crafted from bloodstone, originally held by the warlock mentor Gakin the Darkbinder. Stolen by a treacherous apprentice who fled to the Defias Brotherhood, it serves as a powerful ritual focus capable of piercing the void to draw forth and bind a Voidwalker. Carved from bloodstone, the choker possesses the latent mystical authority required to bridge the mortal world and the twisting shadows of the Twisting Nether. Once returned to Gakin, it is immediately put to the test in the crypts beneath the tavern. A warlock must channel the choker's magic at the underground summoning circle to rip a hostile Voidwalker from the void. Only by subduing the furious entity in direct combat while wielding the talisman can a practitioner prove the willpower necessary to command such a guardian.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bloodstone-choker-9dafc2e8fad704bf152c/1-0000.mp3", duration = 48.0914286, start = 0},
  },
}
P.transport["item:blueleaf-tuber"] = {
  hash = "ebba2c",
  fullHash = "ebba2c",
  text = "Blueleaf Tuber. Blueleaf Tubers are exceptionally rare root vegetables that grow concealed beneath the thorny terrain of Razorfen Kraul. Prized across the world as an exotic culinary delicacy, they are almost impossible to locate with the naked eye. Though native to the Barrens, Blueleaf Tubers grow only in the subterranean depths beneath Razorfen Kraul. Concealed beneath the dense root systems and quilboar briars, they remain hidden to casual foragers. Despite their harsh growing conditions, they fetch an exorbitant price among wealthy gourmands and traders worldwide who savor their unique flavor. Because the roots cannot be easily spotted by surface dwellers, the enterprising goblin Mebok Mizzyrix in Ratchet devised an unusual harvesting method. By training native snufflenose gophers to detect the tubers by scent from fifty paces away, adventurers guided by specialized command sticks can unearth the roots from the soil before quilboar patrols catch wind of the intrusion.",
  ["1"] = {
    {file = "Audio/Transport/full_item_blueleaf-tuber-6cc3cf7959916de65ebd/1-0000.mp3", duration = 57.7567347, start = 0},
  },
}
P.transport["item:book-from-sven-s-farm"] = {
  hash = "54d8b8",
  fullHash = "54d8b8",
  text = "Book from Sven's Farm. The Book from Sven's Farm is a dirt-stained, untitled journal unearthed from the ruins of Sven Yorgen's ransacked homestead in Duskwood. Its fragmented entries reveal that an unknown onlooker witnessed the massacre of Sven's family, sparking a relentless hunt across the shadowed woods. Buried in a loose dirt mound amid the charred remains of Sven's farm in southern Duskwood, this unassuming, weather-damaged volume contains the frantic notes of an anonymous wanderer. The entries offer incomplete glimpses into the tragedy that struck the farmstead, confirming Sven Yorgen's darkest suspicion: someone lurked in the shadows while his family was slain. Because the narrative cuts off abruptly, the book raises more questions than answers, prompting investigators to carry it back to Darkshire in search of anyone who recognizes the handwriting or its enigmatic author.",
  ["1"] = {
    {file = "Audio/Transport/full_item_book-from-sven-s-farm-ceb5a1546f69bd5cff37/1-0000.mp3", duration = 48.1697959, start = 0},
  },
}
P.transport["item:book-stresses-of-iron"] = {
  hash = "284296",
  fullHash = "284296",
  text = "Book: Stresses of Iron. The Stresses of Iron is a scholarly metallurgical text authored by Margulf Blaggon. Originally kept in the Royal Library of Stormwind Keep, it became the focus of an errand between monks after being loaned out to Northshire Abbey for transcribing. Written by Margulf Blaggon, The Stresses of Iron covers the practical and theoretical properties of metallurgy. Kept within the Royal Library in Stormwind Keep under the care of Milton Sheaf, the book was loaned to Northshire Abbey so that Brother Paxton could copy its contents by hand for his own collection. Paxton's transcription took far longer than anticipated, leaving Brother Kristoff in Cathedral Square waiting anxiously for the text to return to the city.",
  ["1"] = {
    {file = "Audio/Transport/full_item_book-stresses-of-iron-3780463b25a5691c5a36/1-0000.mp3", duration = 39.7583673, start = 0},
  },
}
P.transport["item:bottle-of-disease"] = {
  hash = "330175",
  fullHash = "330175",
  text = "Bottle of Disease. A Bottle of Disease is a vial of virulent concoctions brewed by the Forsaken operating in Ashenvale. Found at an encampment near the Dor'Danil Barrow Den, these vials represent an ominous attempt by the undead to introduce blighted plagues into the pristine night elven wilderness. Deep within the ancient canopy of eastern Ashenvale, the Forsaken have crept far past the front lines of the Warsong Outriders. Establishing an outpost near the Dor'Danil Barrow Den, undead alchemists brew foul contagions and seal them within glass bottles. To the night elves guarding Forest Song, these vials are clear evidence of a quiet, insidious offensive aimed at sickening the woodland soil and wildlife rather than engaging in open combat.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bottle-of-disease-9baf749f217ab4b58136/1-0000.mp3", duration = 43.1281633, start = 0},
  },
}
P.transport["item:bottle-of-moonshine"] = {
  hash = "73d514",
  fullHash = "73d514",
  text = "Bottle of Moonshine. A Bottle of Moonshine is a potent alcoholic spirit sold in the gloomy settlement of Darkshire. Barkeep Daniels of Lakeshire urgently seeks a bottle to help restock the town tavern as Blackrock orc incursions cut off regular supply shipments. Lakeshire stands besieged by the Blackrock clan, leaving its local innkeeper, Barkeep Daniels, in dire straits as regular supply caravans fail to arrive. To keep up morale among the town guards and beleaguered townsfolk, Daniels sends couriers across the southern kingdoms to gather regional specialties. Among these is a potent bottle of moonshine brewed and sold at the Scarlet Raven Tavern in neighboring Duskwood, where locals favor stiff drinks to ward off the encroaching dread of the woods.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bottle-of-moonshine-a24b0e60a6fb20695d03/1-0000.mp3", duration = 41.6914286, start = 0},
  },
}
P.transport["item:bottle-of-zombie-juice"] = {
  hash = "e5901a",
  fullHash = "e5901a",
  text = "Bottle of Zombie Juice. A Bottle of Zombie Juice is a potent, foul liquor brewed from the pungent rot blossom found in Duskwood. Procured from the tavern in Darkshire, it is supposedly requested by the reclusive hermit Abercrombie to ward off the chill of the gloomy woods. Brewed from rot blossoms gathered among the shadowed soils of Duskwood, Zombie Juice is a remarkably harsh brew. The bartender who provides it warns that the drink is potent enough to raise the dead. While ordinary folk steer clear of such vile distillations, the eccentric hermit Abercrombie claims it is the only thing capable of keeping him warm on the damp, cold nights out by his lonely shack.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bottle-of-zombie-juice-03eb098c71139569ee6c/1-0000.mp3", duration = 36.1012245, start = 0},
  },
}
P.transport["item:bottom-of-gelkak-s-key"] = {
  hash = "5c6af4",
  fullHash = "5c6af4",
  text = "Bottom of Gelkak's Key. The Bottom of Gelkak's Key is one of three fragments of a shattered mechanical winding key belonging to the shipwrecked gnome pirate Gelkak Gyromast. After his vessel foundered off Darkshore, the piece was scavenged by the shoreline's native reef crawlers. When Gelkak Gyromast's ship was sunk by threshadons off the coast of Darkshore, the gnome was thrown ashore along with his belongings. Among his most prized possessions was the winding key used to activate his mechanical first mate. The key shattered on the coastal rocks into three distinct pieces, and local scavengers immediately descended upon the debris. The bottom piece of the key was snatched up by the aggressive crustaceans wandering the surf—specifically the reef and tide crawlers that pick through the detritus along the tideline.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bottom-of-gelkak-s-key-d1a46405ea08012c4325/1-0000.mp3", duration = 43.6244898, start = 0},
  },
}
P.transport["item:branch-of-cenarius"] = {
  hash = "8c9753",
  fullHash = "8c9753",
  text = "Branch of Cenarius. The Branch of Cenarius is a sacred dryad relic stolen by the vile satyr Geltharis in eastern Ashenvale. Recovering this heirloom was the dying wish of the dryad Anilia, who perished defending it from the woods' corruptors. Revered by the daughters of Cenarius, the Branch of Cenarius represents both the blessing of the Forest Lord and the deep connection his dryads maintain with Ashenvale. The branch was held in high regard by the dryad sisters Anilia and Illiyana until a band of corrupt satyrs ambushed them. The satyr leader, Geltharis, seized the relic and mortally wounded Anilia near the tainted ruins of eastern Ashenvale. With her dying breaths, Anilia pointed northward toward the arch where Geltharis lurks, pleading for a champion to wrest the sacred bough from his claws and restore it to dryad hands at Forest Song.",
  ["1"] = {
    {file = "Audio/Transport/full_item_branch-of-cenarius-5afa53abc7630a0d2af2/1-0000.mp3", duration = 47.124898, start = 0},
  },
}
P.transport["item:brass-collar"] = {
  hash = "faf42e",
  fullHash = "faf42e",
  text = "Brass Collar. The Brass Collar is a sturdy neckpiece worn by Princess, a prize-winning sow owned by the Brackwell family. It serves as tangible proof for Ma Stonefield that the gluttonous beast has been put down before ruining her farm's crops. Princess is no ordinary swine; she is an enormous, ribbon-worthy pig belonging to the Brackwell family who roams around their pumpkin patch east of the Maclure homestead. Unfortunately for her neighbors, her prize-winning size is fueled by a ravenous appetite for the crops at the Stonefield Farm. Tired of losing her valuable vegetables to the wandering glutton, Ma Stonefield seeks someone willing to slay the massive sow. Because Princess wears a prominent brass band around her neck, her collar serves as undeniable proof that the marauding pig will never raid the Stonefield fields again.",
  ["1"] = {
    {file = "Audio/Transport/full_item_brass-collar-96a8022e2dd39d8d714d/1-0000.mp3", duration = 46.4195918, start = 0},
  },
}
P.transport["item:bristleback-attack-plans"] = {
  hash = "078256",
  fullHash = "078256",
  text = "Bristleback Attack Plans. The Bristleback Attack Plans are crude maps and tactical notes drafted by the quilboar of Brambleblade Ravine. They outline a coordinated siege aimed directly at overrunning the tauren settlement of Camp Narache. Hidden deep within a dirt cave in Brambleblade Ravine, these scribbled tactical sketches reveal that the Bristleback quilboar are no longer just skirmishing on the borders of the Red Cloud Mesa. Instead, their leadership planned an organized, sustained assault to push into Camp Narache and wipe out the young tauren training there. Delivering this map to Chief Hawkwind allows the tribe to send word to Bloodhoof Village for reinforcements, blunting the impending invasion before it can begin.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bristleback-attack-plans-961ee45cfc7312951726/1-0000.mp3", duration = 39.3665306, start = 0},
  },
}
P.transport["item:bristleback-belt"] = {
  hash = "7ca233",
  fullHash = "7ca233",
  text = "Bristleback Belt. A Bristleback Belt is a piece of crudely crafted gear worn by the quilboar infesting Brambleblade Ravine. For young tauren coming of age in Camp Narache, collecting these belts serves as physical proof of valor during the Rite of Strength. The Red Cloud tribe tests every youth who aspires to earn respect in Thunder Bluff through the ancient Rites of the Earthmother. The first trial, the Rite of Strength, requires the initiate to protect the tribe from active threats. Because the hostile Bristleback quilboar repeatedly raid tribal food supplies and ambush hunting parties outside Camp Narache, Chief Hawkwind demands the belts of these intruders. Returning twelve belts to the chieftain proves that an initiate can confront danger directly and strike a blow for the tribe's defense. Stripped from Bristleback quilboar warriors and shamans throughout Brambleblade Ravine, these belts are fashioned from rough hide, twine, and scrap. While worthless as apparel to a tauren warrior, they are distinctly quilboar make and serve as unmistakable evidence of a slain enemy. Bringing them back to the camp circle fulfills the proof required by the rite.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bristleback-belt-331bfce52a3f6e3a86e9/1-0000.mp3", duration = 66.9518367, start = 0},
  },
}
P.transport["item:bristleback-quilboar-tusk"] = {
  hash = "661b68",
  fullHash = "661b68",
  text = "Bristleback Quilboar Tusk. Bristleback Quilboar Tusks are harvested from the slain Bristleback quilboar across the northern and central Barrens. Collected as proof of slaughter, they serve as gruesome tokens of vengeance for the grieving orc warrior Mankrik. Bristleback quilboar inhabit thickets and bramble dens throughout the Barrens, fiercely defending their territory against Horde expansion. Their tusks are prominent, jagged ivory used as natural weapons in close quarters. For Mankrik, a veteran warrior stationed at the Crossroads whose wife was lost during a vicious quilboar ambush, these tusks represent more than simple hunter trophies. Collecting dozens of them is a measure of pure retribution, a bloody tally meant to ensure the Bristlebacks suffer as deeply as he has.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bristleback-quilboar-tusk-42c73f80e8305c7a3a91/1-0000.mp3", duration = 42.5012245, start = 0},
  },
}
P.transport["item:brock-s-list"] = {
  hash = "d6e4c4",
  fullHash = "d6e4c4",
  text = "Brock's List. Brock's List is a dispatch compiled by the mining instructor Brock Stoneseeker in Thelsamar. It contains the names of top mining pupils who have earned honorary picks from the guild halls in Ironforge. Mining is the lifeblood of dwarven civilization, and apprentice diggers must prove their skill before they are entrusted with serious work in Khaz Modan's veins. In Thelsamar, the local mining trainer compiles this parchment to reward students who excel in their lessons. The document records those who have earned honorary picks—coveted symbols of competence forged in the capital. Because the honorary tools must be etched and distributed from the capital, the parchment is entrusted to travelers bound for Ironforge. Carried aboard a gryphon from Thelsamar's roost, Brock's List makes its way directly to Golnir Bouldertoe at the Deep Mountain Mining Guild in the Great Forge, where the honored students' names are engraved into stone and steel.",
  ["1"] = {
    {file = "Audio/Transport/full_item_brock-s-list-35e5e21de5f1940aa8d5/1-0000.mp3", duration = 54.1779592, start = 0},
  },
}
P.transport["item:broken-and-battered-samophlange"] = {
  hash = "90c8e5",
  fullHash = "90c8e5",
  text = "Broken and Battered Samophlange. The Broken and Battered Samophlange is an enigmatic mechanical device recovered from Venture Company operations in the Barrens. After a botched tinkering attempt pushed its structural integrity to critical lows, it must be carried to goblin experts in Orgrimmar who might actually understand how it functions. A samophlange is an obscure piece of proprietary machinery designed by the Venture Company for their resource operations in the northern Barrens. When Wenikee Boltbucket attempted to inspect and modify one, she affixed extraneous gauges, levers, and dials to measure its stability. Instead of stabilizing the mechanism, her amateur meddling devastated its structural integrity, leaving it battered and teetering on the verge of ruin. Realizing more gadgets would only cause total failure, she packed off the fragile assembly to someone with real factory experience. Salvaging the broken device requires the insight of someone who has worked directly on Venture Company production lines. This leads travelers to Rilli Greasygob, a former Venture employee now operating out of Nogg's Machine Shop in Orgrimmar's Valley of Honor. Handing over such a battered apparatus immediately catches the engineer's eye, marking anyone daring enough to scavenge from goblin operations as either remarkably daring or foolhardy.",
  ["1"] = {
    {file = "Audio/Transport/full_item_broken-and-battered-samophlange-37a040f24f833726bc45/1-0000.mp3", duration = 72.2285714, start = 0},
  },
}
P.transport["item:broken-samophlange"] = {
  hash = "a1ff08",
  fullHash = "a1ff08",
  text = "Broken Samophlange. The Broken Samophlange is an enigmatic mechanical device recovered from the northern Barrens. Despite its damaged state, its internal gears and shifting parts captivate engineers curious enough to uncover its true function. The samophlange remains one of the stranger contraptions found throughout the northern Barrens. Even when broken, the mechanism exhibits remarkable internal craftsmanship, filled with moving assemblies and fine gears. The Ratchet goblin Sputtervalve accidentally damaged the delicate apparatus before its full operation could be documented. Eager to deliver working results to curious colleagues in Undermine, the finder sought someone skilled enough to restore it, turning to Wenikee Boltbucket—a clever tinkerer stationed near the border outpost of Mor'shan Rampart. Upon examining the ruined apparatus, even an inquisitive mind like Wenikee's cannot immediately deduce what a samophlange is actually designed to do. However, the tantalizing sounds of internal clockwork and its dynamic motion immediately draw her interest. Rather than discarding the ruined junk, the mystery of its design inspires an attempt to repair it and witness its mechanisms working at full capacity.",
  ["1"] = {
    {file = "Audio/Transport/full_item_broken-samophlange-217b75f12c7d2bff9f68/1-0000.mp3", duration = 69.1983673, start = 0},
  },
}
P.transport["item:broken-tools"] = {
  hash = "e23770",
  fullHash = "e23770",
  text = "Broken Tools. Broken Tools are the shattered remnants of dwarven prospector picks, intentionally destroyed at an anvil. They serve as physical proof to Baine Bloodhoof that the invasive dwarven excavation threatening Mulgore's land and wildlife has been disrupted. To the northwest of Bloodhoof Village, dwarven excavators have set up operations to delve into the hills of Mulgore. While the dwarves seek buried ancient history, the tauren view their aggressive excavation as a direct defilement of the Earth Mother. The noise and destruction agitate the local wildlife, particularly the roaming kodo herds. Rather than merely driving the excavators away, young Baine Bloodhoof instructs defenders to confiscate the prospectors' iron picks and shatter them upon a forge, rendering the expedition unable to gouge further into the earth.",
  ["1"] = {
    {file = "Audio/Transport/full_item_broken-tools-bf1ccd2e93728a78ad60/1-0000.mp3", duration = 46.08, start = 0},
  },
}
P.transport["item:bundle-of-crocolisk-skins"] = {
  hash = "8acea7",
  fullHash = "8acea7",
  text = "Bundle of Crocolisk Skins. The Bundle of Crocolisk Skins is a prepared package of cured reptilian hides harvested from the dangerous marshes of the Wetlands. Destined for the leatherworkers of Menethil Harbor, it serves as valuable trade stock for crafting sturdy boots and tough harbor gear. The vast waterways of the Wetlands are teeming with crocolisks, whose tough, water-resistant hides are an essential commodity for the coastal settlement of Menethil Harbor. Hunters braving the bogs collect and cure these skins before sending them westward to local artisans like James Halloran. However, this particular bundle took an unusual detour into an adventurer's hands: the hunter Einar sought a courier purely to avoid returning to town and facing the temper of his frustrated wife, Sida.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bundle-of-crocolisk-skins-bcb43bd1dbd312d91910/1-0000.mp3", duration = 42.24, start = 0},
  },
}
P.transport["item:bundle-of-hides"] = {
  hash = "98b05d",
  fullHash = "98b05d",
  text = "Bundle of Hides. A Bundle of Hides consists of cured skins collected from the beasts of the Barrens, bundled together for transport across central Kalimdor. Bound for the leatherworkers of Thunder Bluff, it serves as a straightforward courier shipment that introduces travelers to the Horde's wind rider flight network. The untamed plains of the Barrens are home to vast herds of kodo, prowling lions, and roving raptors. Hunters along the trade paths skin these creatures not only for meat and survival, but to supply city artisans. Without raw pelts from the wilds, settlements like Thunder Bluff would struggle to sustain their local leathercrafters, who transform dried skins into essential gear, pouches, armor, and bindings for the Horde. Transporting heavy goods overland through the Barrens and up into Mulgore is dangerous and slow, constantly threatened by roaming quilboar and centaur raiders. To speed delivery between the Crossroads and the tauren capital, couriers rely on Devrak's trained wyverns. Handing a bundle of hides to a wind rider courier demonstrates the sheer efficiency of air travel across Kalimdor's fractured terrain.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bundle-of-hides-83f413b94f00b148d0af/1-0000.mp3", duration = 65.9853061, start = 0},
  },
}
P.transport["item:bundle-of-wood"] = {
  hash = "0263e5",
  fullHash = "0263e5",
  text = "Bundle of Wood. Bundles of Wood are tied timber stacks harvested by laborers near the Eastvale Logging Camp in eastern Elwynn Forest. Recently abandoned due to prowling wildlife, they represent critical shipments needed to fulfill local lumber contracts. The Eastvale Logging Camp serves as a primary source of lumber for the Kingdom of Stormwind, sending freshly chopped wood westward to sustain town infrastructure and construction projects. Recently, aggressive local wildlife—specifically forest bears and prowling wolves—pushed into the groves northwest of the camp. Terrified loggers fled for their lives, abandoning freshly gathered Bundles of Wood where they lay among the trees. Facing tight delivery deadlines, camp overseers rely on brave travelers to slip past the predators and retrieve the cut lumber before contracts are breached.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bundle-of-wood-924a1fcc1c231be2f386/1-0000.mp3", duration = 47.6212245, start = 0},
  },
}
P.transport["item:burning-blade-medallion"] = {
  hash = "5fe237",
  fullHash = "5fe237",
  text = "Burning Blade Medallion. The Burning Blade Medallion is a dark talisman carried by cultists lurking within the Valley of Trials. Guarded by dark magic in the depths of the Burning Blade Coven, it serves as direct proof of demonic corruption attempting to subvert the young warriors of Durotar. Discovered deep inside the winding caverns of the Burning Blade Coven, the medallion is held by Yarrog Baneshadow, an agent of the sinister Burning Blade cult. Identified through the divinations of Zureetha Fargaze, the trinket channels dark power amidst the cult's impish familiars and felstalkers. Striking down its bearer and seizing the medallion cuts short an insidious attempt to undermine the Horde's training grounds from within Durotar itself.",
  ["1"] = {
    {file = "Audio/Transport/full_item_burning-blade-medallion-d29fb2ecc143cfae8978/1-0000.mp3", duration = 39.5232653, start = 0},
  },
}
P.transport["item:burning-blood-quest-item"] = {
  hash = "645a57",
  fullHash = "645a57",
  text = "Burning Blood (quest item). Burning Blood is an unnatural fluid harvested from the ferocious Nightbane worgen prowling Duskwood. The Stormwind armorer Grimand Elmore requires twenty vials of this fiery essence to experiment with advanced smithing techniques. The cursed Nightbane worgen infesting Duskwood run hot with a strange, unnatural fury, and their blood burns with literal heat. This searing fluid can be drawn from the beasts haunting the haunted timberlands and the abandoned dig site of Roland's Doom. While grotesque to harvest, the fiery substance holds rare metallurgical properties coveted by master armorers seeking to quench and temper resilient plate. Grimand Elmore, a veteran craftsman working in the Dwarven District of Stormwind, seeks to test novel smithing methods pioneered by his former student Furen Longbeard. To see if these radical forging techniques hold merit, Elmore requires burning blood alongside a dense burning rock held by the worgen chieftain Gutspill. Those willing to face the predatory pack and return with the bubbling fluid are promised sturdy warrior armor forged in the heat of his forge.",
  ["1"] = {
    {file = "Audio/Transport/full_item_burning-blood-quest-item-96c330d1be5eb8b0f081/1-0000.mp3", duration = 62.2236735, start = 0},
  },
}
P.transport["item:burning-rock"] = {
  hash = "5f1c1e",
  fullHash = "5f1c1e",
  text = "Burning Rock. The Burning Rock is an unusual, smoldering mineral recovered from the Nightbane worgen leader Gutspill deep within Roland's Doom in Duskwood. Master blacksmith Grimand Elmore in Stormwind requires this rare curiosity, alongside fiery worgen blood, to forge specialized enchanted armor for promising warriors. Carried by Gutspill, a savage Nightbane worgen lurking in the decrepit shafts of Roland's Doom, the Burning Rock is an anomaly among Duskwood's subterranean horrors. Emitting an unyielding supernatural heat, it caught the attention of Grimand Elmore in Stormwind City. Seeking to test experimental smithing techniques originated by his peer Furen Longbeard, Grimand uses the rock's intrinsic heat and the boiling blood of the local worgen to temper tough armor plate for veteran fighters.",
  ["1"] = {
    {file = "Audio/Transport/full_item_burning-rock-d7a86f6bd8a2996c62c6/1-0000.mp3", duration = 46.1583673, start = 0},
  },
}
P.transport["item:cache-of-zanzil-s-altered-mixture"] = {
  hash = "cdb8d6",
  fullHash = "cdb8d6",
  text = "Cache of Zanzil's Altered Mixture. The Cache of Zanzil's Altered Mixture is a stockpile of potent poison secured inside a locked chest at the Venture Company tower near the Sludge Fen. Named for the jungle troll witch doctor Zanzil, it serves as a critical target for the Shattered Hand in Orgrimmar. North of the Sludge Fen in the Barrens, the Venture Company keeps a tower outpost. A cache of an altered mixture bearing the name of the infamous troll witch doctor Zanzil sits locked inside Grand Foreman Puzik Gallywix's private strongbox at the summit of the tower. A poison has weakened everything in the tower, leaving its goblin inhabitants vulnerable to any intruder bold enough to strike.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cache-of-zanzil-s-altered-mixture-94d969c8551851101b2e/1-0000.mp3", duration = 37.9297959, start = 0},
  },
}
P.transport["item:cactus-apple"] = {
  hash = "e8119d",
  fullHash = "e8119d",
  text = "Cactus Apple. Cactus Apples are tough, moisture-rich fruits harvested from the rugged flora of Durotar's Valley of Trials. Flourishing in the arid desert heat, they are prized by local orcs as a rare, refreshing source of sustenance. The sun-scorched earth of Durotar offers little luxury, forcing its inhabitants to make use of whatever hardy plants survive the elements. Cactus apples grow in clusters around the thick cactuses dotting the Valley of Trials. While difficult to gather without catching a few thorns, the fruit provides vital hydration in the sweltering canyon. A local orc named Galgar gathers these fruits to prepare his signature Cactus Apple Surprise, a cooling confection that brings welcome relief to recruits enduring their harsh initial training.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cactus-apple-bba2e1fd0af776277ad3/1-0000.mp3", duration = 44.8, start = 0},
  },
}
P.transport["item:calor-s-note"] = {
  hash = "80644b",
  fullHash = "80644b",
  text = "Calor's Note. Calor's Note is a scrap of faded parchment written by the woodsman Calor to recommend a tested adventurer to Master Jonathan Carevin. It serves as an introduction into a shadowy cadre operating alongside, yet distinct from, Darkshire's formal town militia. Duskwood offers very little warmth to strangers, and Calor is notoriously hard to impress. Surviving encounters with the bloodthirsty worgen stalking the woods earns his respect, prompting him to draft this brief message. Carried to Darkshire, the faded note acts as a badge of credibility, introducing an outsider directly to Jonathan Carevin. While Darkshire relies on the Night Watch for public defense, Calor and Carevin pursue a grimmer, more clandestine fight. Calor openly laments being outnumbered by the town guard, hoping for enough capable fighters to advance their private war. Delivery of the note grants entry into Carevin's campaign against demons, undead, and the hidden sympathizers abetting Duskwood's decline.",
  ["1"] = {
    {file = "Audio/Transport/full_item_calor-s-note-1084939898fb1db62644/1-0000.mp3", duration = 56.9469388, start = 0},
  },
}
P.transport["item:candle-of-beckoning"] = {
  hash = "136d59",
  fullHash = "136d59",
  text = "Candle of Beckoning. The Candle of Beckoning is an enchanted ritual taper kept by the reclusive necromancer Gunther Arcanus on Brightwater Lake. Placing and lighting the candle upon an altar on a nearby islet summons forth a restless spirit known as Lillith Nefara. Found stored in a crate beside the solitary mage Gunther Arcanus on his island in Brightwater Lake, the Candle of Beckoning serves as an instrument in a dark ritual of summoning. Gunther is a fiercely independent undead sorcerer who broke free of the Lich King's command on his own, remaining wary of the Scourge and the Forsaken alike. To prove your loyalty is not to the Lich King, Gunther directs you to take one of these candles southwest to a smaller islet. There, set upon an old, bloodstained table, the candle's flame pierces the veil between worlds to awaken and beckon the dormant shade of Lillith Nefara, a powerful Scourge agent, so she may be destroyed.",
  ["1"] = {
    {file = "Audio/Transport/full_item_candle-of-beckoning-b22fe42d50f72477ebc7/1-0000.mp3", duration = 50.0767347, start = 0},
  },
}
P.transport["item:cantation-of-manifestation"] = {
  hash = "c05159",
  fullHash = "c05159",
  text = "Cantation of Manifestation. The Cantation of Manifestation is a specialized arcane incantation written on a parchment scroll, used by mages to reveal unseen magical anomalies. In the Undercity, Anastasia Hartwell provides it to apprentices investigating invisible magical entities haunting Algernon's shop in the Apothecarium. The Cantation of Manifestation holds a focused spell designed to pierce magical veils and force incorporeal, invisible beings into the visible spectrum. Kept in the Magic Quarter of the Undercity near Anastasia Hartwell, the scroll is entrusted to capable mages tasked with containing rogue magical anomalies. When read aloud in an area suffering from arcane instability—such as Algernon's alchemical workshop in the Apothecarium—the words force stray rift spawns to materialize, allowing the caster to subdue and trap them within containment coffers for further study.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cantation-of-manifestation-7d02afd8084fea05973e/1-0000.mp3", duration = 50.7297959, start = 0},
  },
}
P.transport["item:canvas-scraps"] = {
  hash = "e6c879",
  fullHash = "e6c879",
  text = "Canvas Scraps. Canvas Scraps are remnants of tough woven fabric carried by human invaders and centaur tribes encroaching upon Durotar. In Razor Hill, aging veteran Furl Scornbrow collects these salvaged swatches to stitch useful travel sacks for fresh Horde recruits. Canvas is not a fabric native to the rough hide-working traditions of the Orcs, but it is abundant among Durotar's enemies. The Kul Tiras marines and sailors entrenched along the eastern shoreline carry heavy canvas gear and sailcloth remnants from their naval excursions. Further inland, the roaming Kolkar centaur repurpose scraps of coarse cloth looted from supply caravans and past conflicts. Defeating these hostiles yields durable remnants that can be salvaged from their camps and gear. Perched atop the Razor Hill watchtower, veteran Furl Scornbrow keeps an eye out for invaders while turning his hands to useful labor. Though past his fighting prime, the old warrior repurposes salvaged enemy fabric into sturdy carrying bags for younger soldiers. By turning the materials of Kul Tiras and the Kolkar against them, Furl equips the new generation of defenders fighting to secure the Horde's borders.",
  ["1"] = {
    {file = "Audio/Transport/full_item_canvas-scraps-41f9329e523095762671/1-0000.mp3", duration = 66.2204082, start = 0},
  },
}
P.transport["item:cask-of-merlot"] = {
  hash = "3035eb",
  fullHash = "3035eb",
  text = "Cask of Merlot. A Cask of Merlot is a barrel of fine red wine produced and sold in Stormwind City. It serves as one of several regional specialty liquors needed by the Lakeshire innkeeper during the supply shortages caused by the Blackrock orc invasion. Harvested and fermented in the heart of the kingdom, this Cask of Merlot comes straight from the cellars of the Galina Winery, nestled along the canals bordering Stormwind's Trade District. Winemaker Roberto Pupellyverbos manages the vintages there, catering to the capital's more refined palates. Unlike the harsh moonshine of Duskwood or the rustic spirits brewed in Elwynn, the merlot represents the refined craft of human vintners operating under the relative safety of the city walls. When the Blackrock clan invaded the Redridge Mountains, supply routes fell apart, cutting Lakeshire off from its standard merchant shipments. Facing parched and terrified locals, Barkeep Daniels tasks willing couriers with undertaking a kingdom-wide run to restock his tavern's cellars. Procuring this cask ensures the defenders and refugees holding out by Lake Everstill have something gentle to wash down their rations.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cask-of-merlot-e8c1198d4d5cedd0b232/1-0000.mp3", duration = 66.0636735, start = 0},
  },
}
P.transport["item:cask-of-scalder"] = {
  hash = "a8640c",
  fullHash = "a8640c",
  text = "Cask of Scalder. A heavy cask of fiery Barleybrew Scalder ale, given to brave adventurers venturing to Stormwind. It serves as both a thirst-quenching gift and an informal currency between old acquaintances. Barleybrew Scalder is a renowned ale capable of warming even the chillest dwarf. Entrusted to travelers who have proven their mettle across the Rethban Gauntlet, this cask is sent directly to Furen Longbeard in Stormwind's Dwarven District. Longbeard, an artisan shieldsmith, considers dry times an intolerable condition, making this potent brew the perfect lever to call in an old favor and secure high-quality dwarven craftsmanship.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cask-of-scalder-d22eb88774f1778f3a82/1-0000.mp3", duration = 36.9632653, start = 0},
  },
}
P.transport["item:cask-of-shimmer-stout"] = {
  hash = "075183",
  fullHash = "075183",
  text = "Cask of Shimmer Stout. The Cask of Shimmer Stout is a sealed barrel of Rejold Barleybrew's potent new ale, crafted in the cold heights of Dun Morogh. Known for its remarkable kick and head-spinning vigor, it is sent eastward across the mountains as a spirited gift for fellow dwarven mountaineers. Brewed in Brewnall Village by Rejold Barleybrew, Shimmer Stout quickly earned high marks among local patrons and mountaineers who braved the biting frosts of Dun Morogh. Impressed by his brother's concoction, Mountaineer Barleybrew commissioned a cask to be hauled through the eastern pass into Loch Modan. Dwarves hold strong drink in high regard as both a social staple and a practical defense against the biting mountain chill, and sharing a fresh vintage with far-flung comrades is a time-honored military tradition. When opened and sampled by Mountaineer Kadrell along his watch in Thelsamar, the brew proves true to its reputation. Far from ordinary tavern draught, a single draught of Shimmer Stout is said to lighten limbs and leave a soldier feeling as though they could take flight—the exact sort of invigorating potion a dwarven scout relies upon while walking long, lonely patrols along the high roads.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cask-of-shimmer-stout-d5421242fa782ed6572c/1-0000.mp3", duration = 65.6718367, start = 0},
  },
}
P.transport["item:cats-eye-emerald"] = {
  hash = "9ff0f1",
  fullHash = "9ff0f1",
  text = "Cats Eye Emerald. The Cats Eye Emerald is an exceptionally large, fist-sized gemstone unearthed within the Boulder Lode Mine in the northern Barrens. Coveted for its immense market value, it quickly became the subject of scheming outside the Venture Company's ranks. When laborers excavating the Venture Company's Boulder Lode Mine, situated northeast of the Sludge Fen, struck a massive emerald, word traveled fast across the savanna. Such rare, high-grade gemstones rarely stay secret for long in goblin-dominated territories. Wharfmaster Dizzywig in Ratchet caught wind of the discovery through the steady trade gossip passing between his docks and Booty Bay, immediately plotting to secure the prize for the open market in Undermine. Rather than reaching common trade channels legitimately, the gemstone was kept under heavy guard by the Venture Company's management inside the mine. Overseers, Enforcers, and chief operators like Boss Copperplug vigilantly defended their valuable prize from both rival cartels and enterprising fortune-hunters seeking to claim Dizzywig's promised fifty-percent cut.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cats-eye-emerald-e7f0edaba6d3a147a388/1-0000.mp3", duration = 63.0334694, start = 0},
  },
}
P.transport["item:cenarion-lunardust"] = {
  hash = "7d6d57",
  fullHash = "7d6d57",
  text = "Cenarion Lunardust. Cenarion Lunardust is a sacred powder bestowed upon young tauren druids by Turak Runetotem on the heights of Thunder Bluff. It is used to awaken the guardian beast Lunaclaw at an ancient Moonkin Stone on the border of Mulgore and the Barrens. Entrusted to initiates ready to claim their place among the Druids of the Claw, Cenarion Lunardust carries the blessings of the Cenarion Circle. When scattered across the Moonkin Stone west of Camp Taurajo, the glowing dust summons forth Lunaclaw, a sacred beast bound to test the initiate. Defeating this guardian tests both physical fortitude and spiritual resolve, allowing the young druid to absorb the strength of body and heart required to assume the form of the bear.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cenarion-lunardust-e98b0016e7370c8ac2a6/1-0000.mp3", duration = 40.4114286, start = 0},
  },
}
P.transport["item:cenarion-moondust"] = {
  hash = "b8fb0e",
  fullHash = "b8fb0e",
  text = "Cenarion Moondust. Cenarion Moondust is a sacred powder entrusted to night elf druids undergoing their trials to become Druids of the Claw. When scattered upon the ancient Moonkin Stone in the hills east of Auberdine, it draws forth Lunaclaw, the feral guardian of the cave. Bestowed by Mathrengyl Bearwalker in Darnassus, Cenarion Moondust serves as the catalyst for a young druid's final trial of heart and body. To commune with and prove oneself against the guardian Lunaclaw, the initiate must journey to the moonkin dens east of Auberdine in Darkshore. Applying the moondust to the ancient Moonkin Stone summons the beast to test the initiate in combat, allowing the druid to internalize the enduring strength needed to channel the form of the bear.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cenarion-moondust-0e6acbd17a8189bb78be/1-0000.mp3", duration = 40.0979592, start = 0},
  },
}
P.transport["item:centaur-bracers"] = {
  hash = "530a33",
  fullHash = "530a33",
  text = "Centaur Bracers. Centaur Bracers are simple leather and iron armbands taken from slain Kolkar centaur throughout the Barrens. Regthar Deathgate collects them west of the Crossroads as proof of culled centaur raiders. The Kolkar tribe poses an unrelenting threat to the Horde's foothold across the arid plains of the Barrens. Stripping the bracers from fallen centaur warriors serves as undeniable proof that another hostile marauder has been removed from the trade roads. Regthar Deathgate, an orc scout stationed along the bluffs west of the Crossroads, issues a standing bounty on these trophies to blunt the tribe's aggression.",
  ["1"] = {
    {file = "Audio/Transport/full_item_centaur-bracers-493cedd793b6039c6eb2/1-0000.mp3", duration = 33.6195918, start = 0},
  },
}
P.transport["item:charred-horn"] = {
  hash = "ec4738",
  fullHash = "ec4738",
  text = "Charred Horn. Charred Horns are the rugged, heat-baked horns harvested from youthful chimaeras dwelling in the crags of the Stonetalon Mountains. Tough enough to withstand harsh elemental forces, they serve as an essential tempering component in specialized armorsmithing. Harvested from fledgling and young chimaeras nesting across the craggy heights of the Stonetalon Mountains, Charred Horns are coveted for their unnatural resistance to flame and blunt force. The dwarven armorsmith Furen Longbeard, working from his forge in Stormwind, requires a collection of these horns to craft fire-hardened mail. Combined with venomous spider fangs from the Wetlands, phlogiston from Razorfen Kraul, and the galvanized horn of a chimaera matriarch, these calcified horns provide the core structural reinforcement necessary to produce an exceptionally resilient suit of protective armor.",
  ["1"] = {
    {file = "Audio/Transport/full_item_charred-horn-f6832e4c94ab8e8592eb/1-0000.mp3", duration = 47.6995918, start = 0},
  },
}
P.transport["item:chest-of-containment-coffers"] = {
  hash = "6a3e37",
  fullHash = "6a3e37",
  text = "Chest of Containment Coffers. The Chest of Containment Coffers contains enchanted receptacles used by mages to capture unstable magical phenomena. It serves as essential equipment for practitioners sent to investigate and safely trap unseen mana anomalies. Magical experimentation and sudden planar rifts frequently spawn volatile, invisible anomalies made entirely of arcane force. Standard physical cages cannot hold entities composed purely of magic. The Chest of Containment Coffers provides mages with specialized, enchanted coffers engineered to entrap and bind these subdued creatures alive. Kept near senior instructors such as Anastasia Hartwell in the Undercity and Jennea Cannon in Stormwind, the chest provides the necessary gear for initiates tasked with surveying anomalies before they can destabilize their surroundings.",
  ["1"] = {
    {file = "Audio/Transport/full_item_chest-of-containment-coffers-0171603306d7c9be03ae/1-0000.mp3", duration = 46.8897959, start = 0},
  },
}
P.transport["item:chief-sharptusk-thornmantle-s-head"] = {
  hash = "8086f9",
  fullHash = "8086f9",
  text = "Chief Sharptusk Thornmantle's Head. Chief Sharptusk Thornmantle's Head is taken as grim proof of victory over the leader of the Bristleback quilboar threatening Red Cloud Mesa. Recovered from the depths of Brambleblade Ravine, it is presented to Brave Windfeather to mark the end of a persistent menace against young tauren braves. The tauren carve their peaceful homeland out of Mulgore through vigilance and strength. The Bristleback quilboar entrenched within Brambleblade Ravine have waged an aggressive campaign against the tribes of Camp Narache, urged on by their ferocious chieftain, Sharptusk Thornmantle. Severing his head serves not out of senseless cruelty, but as definitive proof of his demise and a stark warning to the surviving quilboar clans encroaching upon mesa borders. Brave Windfeather demands the chieftain's head as a rite of passage for fledgling hunters and defenders of the tribe. To the tauren, facing an adversary cunning enough to retaliate and organize an entire war band provides an essential test of martial prowess. Presenting Sharptusk's head fulfills that trial, earning the young combatant an established reputation among the braves of Red Cloud Mesa.",
  ["1"] = {
    {file = "Audio/Transport/full_item_chief-sharptusk-thornmantle-s-head-c4899a9124297edbbbcb/1-0000.mp3", duration = 61.675102, start = 0},
  },
}
P.transport["item:chok-sul-s-head"] = {
  hash = "c4614a",
  fullHash = "c4614a",
  text = "Chok'sul's Head. Chok'sul's Head serves as gruesome physical proof of the death of the Mo'grosh ogre chieftain. Brought to Magistrate Bluntnose in Thelsamar, it secures a formal bounty placed by local dwarven authorities. The ogres of Mo'grosh Stronghold pose a persistent menace to the settlements of Loch Modan, orchestrating assaults against Thelsamar, the excavation sites, and the vital Stonewrought Dam. Magistrate Bluntnose placed a bounty on the brute presumed to be coordinating these attacks: Chok'sul. Given the chaos of the northeastern hills, the magistrate demands undeniable evidence before releasing township funds. The severed head of the ogre chieftain provides the grotesque certainty the dwarven council needs to mark the contract fulfilled.",
  ["1"] = {
    {file = "Audio/Transport/full_item_chok-sul-s-head-0b5c37c444b1943e6971/1-0000.mp3", duration = 42.3444898, start = 0},
  },
}
P.transport["item:clarice-s-pendant"] = {
  hash = "fba1fe",
  fullHash = "fba1fe",
  text = "Clarice's Pendant. Clarice's Pendant is a small keepsake belonging to Clarice Foster, an undead resident of the Pools of Vision in Thunder Bluff. Once a token from her former husband, Yuriv, the jewelry now serves only as a bitter reminder of abandoned family and misplaced devotion to the Light. Clarice's Pendant represents the fractured human past common to many of the Forsaken. Before the Third War consumed Lordaeron, Clarice's husband Yuriv abandoned her and their children to join the fight against the undead, proclaiming that devotion to the Holy Light took precedence over all else. Instead of saving his home, Yuriv perished, leaving his family behind to ultimately succumb to the very Scourge he set out to fight. For Clarice, the pendant is not a cherished memento, but an insulting trinket symbolizing a lifetime spent coming second to zealotry and duty.",
  ["1"] = {
    {file = "Audio/Transport/full_item_clarice-s-pendant-1b4d66b299be05ba003a/1-0000.mp3", duration = 48.0914286, start = 0},
  },
}
P.transport["item:claw-key"] = {
  hash = "b76ac7",
  fullHash = "b76ac7",
  text = "Claw Key. The Claw Key is one of three druidic keys hidden within the Talon Den atop Stonetalon Peak. Alongside the Barrow Key and Sleepers' Key, it is required to unlock the enchanted Talon Den Hoard. The night elf druids established the Talon Den high upon Stonetalon Peak as a sanctuary and repository for powerful relics. To ensure these treasures remained safe from trespassers, they hid them behind a layered security system. The hoard itself is sealed by three distinct enchanted locks: the Barrow Key, the Sleepers' Key, and the Claw Key. Each key is concealed inside a specialized druidic cache resembling a torch within the winding tunnels of the barrow den. The druids did not leave the keys unguarded or freely accessible. Opening the cache that holds the Claw Key requires first acquiring the Gatekeeper's Key, which is tucked away near the barrow entrance. Once retrieved, the Claw Key serves as a vital component in breaking the druids' seal and claiming the riches hidden deep within the mountain.",
  ["1"] = {
    {file = "Audio/Transport/full_item_claw-key-217a7494ac3ec7410535/1-0000.mp3", duration = 57.6783673, start = 0},
  },
}
P.transport["item:cliffspring-river-sample"] = {
  hash = "15616e",
  fullHash = "15616e",
  text = "Cliffspring River Sample. A glass vial containing murky, foul-smelling water drawn from the base of the Cliffspring River waterfall in Darkshore. Gathered on behalf of Thundris Windweaver in Auberdine, the sample provides tangible proof of an encroaching corruption threatening the coastal settlement. The Cliffspring River flows down from the rugged eastern heights of Darkshore, tumbling past ancient stone bridges before washing out into the sea along Mist's Edge. Lately, the river's crystalline waters have turned foul and visibly corrupted. Fearing that the toxic wash will soon contaminate Auberdine's shoreline and water supply, the night elf Thundris Windweaver commissioned travelers to draw this water sample directly from the pool beneath the river's lower waterfall. The sample confirms the worst: unnatural rot is drifting steadily downstream toward the coast.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cliffspring-river-sample-a6f0c1d7c95c6e13e6bf/1-0000.mp3", duration = 46.08, start = 0},
  },
}
P.transport["item:cloth-request"] = {
  hash = "126b50",
  fullHash = "126b50",
  text = "Cloth Request. The Cloth Request is an order slip penned by the Stormwind merchant Harlan Bagley. Addressed to Rema Schneider at the Canal Tailor and Fit Shop, the note seeks fresh bolts and knitted goods to replenish Bagley's rapidly emptying shelves. Written by Harlan Bagley, this trade requisition asks the canal district's clothiers for a fresh resupply of knitted garments and cloth. Bagley notes a sudden, unsettling surge in commerce: ordinary citizens and travelers are stocking up heavily on armor and sturdy wear as if bracing for a brutal season. When delivered to Rema Schneider, the request leaves the tailor puzzled and wary. Rema wonders why city folk are quietly armoring themselves when the House of Nobles has announced no open war, stoking quiet suspicion that the crown's leaders are keeping unrest under wraps.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cloth-request-d39447d55c2d8168902c/1-0000.mp3", duration = 47.8563265, start = 0},
  },
}
P.transport["item:cloven-hoof"] = {
  hash = "d08c0b",
  fullHash = "d08c0b",
  text = "Cloven Hoof. The Cloven Hoof is a mysterious relic guarded deep within Thousand Needles by the Galak centaur tribe. Preserved inside an ancient sacred flame at Splithoof Hold, it emanates an uncharacteristic supernatural energy that tauren scholars are keen to understand. Held within an ancient brazier at the deepest recess of Splithoof Hold, the Cloven Hoof is one of the most treasured relics of the Galak centaur. The artifact is continually enveloped in a magical flame, requiring blessed water to briefly quench the blaze so it can be handled. Centaur society is notoriously brutal and splintered into violent clans, but their reverence for the brazier suggests ritual significance tied directly to their origins. Tauren observers like Rau Cliffrunner at Freewind Post believe the strange aura radiating from the hoof could reveal critical insight into the race that has plagued Kalimdor's plains for generations.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cloven-hoof-de3e1593a642b2c8f53c/1-0000.mp3", duration = 51.9053061, start = 0},
  },
}
P.transport["item:comar-s-heart"] = {
  hash = "fab42c",
  fullHash = "fab42c",
  text = "Comar's Heart. Comar's Heart is a macabre ritual component carved from Comar Villard, a faithful human wanderer searching the marshes of the Wetlands for his lost wife. Forsaken warlocks in the Undercity seek out this relic of pure devotion to feed the summoning rites of a succubus. To bind a creature as capricious and predatory as a succubus, warlocks must bait the demon with true purity and devotion. Carendin Halgar's disciples in the Undercity identify Comar Villard as one of the few men possessing such unblemished fidelity. While his wife was lost amidst the turmoil sweeping the Eastern Kingdoms, Comar stubbornly wanders the sodden roads of the Wetlands, refusing to abandon his search. It is precisely this unwavering love that marks him for slaughter, turning his still-beating heart into the ideal lure for a demonic servant.",
  ["1"] = {
    {file = "Audio/Transport/full_item_comar-s-heart-70ffcc08d1b694e6a1eb/1-0000.mp3", duration = 47.2293878, start = 0},
  },
}
P.transport["item:consecrated-rune"] = {
  hash = "fe420d",
  fullHash = "fe420d",
  text = "Consecrated Rune. A Consecrated Rune is an inscribed sacred item passed to fledgling dwarven paladins training in Coldridge Valley. It serves as an introductory summons from Bromos Grummner, directing initiates to report to Anvilmar and begin their formal duties as Knights of the Silver Hand. Novice dwarven paladins proving themselves in Coldridge Valley are handed a Consecrated Rune once they have shown basic martial competence. Inscribed with sacred words and blessed by the Holy Light, the rune originates from Bromos Grummner, the paladin trainer residing inside Anvilmar. Dwarves hold immense respect for the traditions of the Holy Light introduced to them by their human allies. Reading the rune serves as both an official summons and a symbolic rite of passage, confirming the novice's place among the Knights of the Silver Hand.",
  ["1"] = {
    {file = "Audio/Transport/full_item_consecrated-rune-a2ced99d51b1f75c25fb/1-0000.mp3", duration = 45.3746939, start = 0},
  },
}
P.transport["item:console-key"] = {
  hash = "b2237c",
  fullHash = "b2237c",
  text = "Console Key. The Console Key is a mechanical bypass key held by Tinkerer Sniggles at the Venture Company digsite in the Barrens. It unlocks the main control terminal housing the samophlange, allowing the device to be extracted after the apparatus has been shut down. The Venture Company maintains an extensive industrial outpost in the northern Barrens, reliant on specialized steam-driven machinery regulated by an enigmatic device known as a samophlange. To prevent unauthorized tampering, the apparatus console is locked tight. Only the chief technician on site, Tinkerer Sniggles, carries the Console Key required to pop open the terminal casing and completely cut power to the rig.",
  ["1"] = {
    {file = "Audio/Transport/full_item_console-key-65f9b18c69b0d5aad4b4/1-0000.mp3", duration = 38.4783673, start = 0},
  },
}
P.transport["item:control-console-operating-manual"] = {
  hash = "10a2cf",
  fullHash = "10a2cf",
  text = "Control Console Operating Manual. The Control Console Operating Manual is a technical document detailing how to operate the machinery at the Venture Company research site southwest of Sludge Fen. It contains instructions needed to safely shut down the valves and disengage the mysterious contraption known as a samophlange. The Venture Company operates a secluded drilling and research site in the northern Barrens, southwest of Sludge Fen. In typical goblin fashion, their complex machinery runs on an erratic array of gauges, pressurized valves, and interconnected mechanisms designed to harness a device called a samophlange. Without proper operating procedures, manipulating such volatile contraptions risks catastrophic backfire or complete system lockouts. This operational manual outlines the precise sequence of valve manipulation required to disengage the core apparatus safely without triggering an explosive failure.",
  ["1"] = {
    {file = "Audio/Transport/full_item_control-console-operating-manual-84ab49c8f644962c62c8/1-0000.mp3", duration = 52.9763265, start = 0},
  },
}
P.transport["item:corroded-shrapnel"] = {
  hash = "0e3e6e",
  fullHash = "0e3e6e",
  text = "Corroded Shrapnel. Corroded Shrapnel consists of jagged metal fragments lodged deep within the corrupted treants of the Stonetalon Mountains. Recovered from fallen protectors like Charred and Blackened Ancients, this debris provides physical evidence of the foul weaponry used by the Venture Company during their retreat. When the Venture Company was driven back from the groves of Stonetalon, the goblins unleashed brutal, reckless munitions to cover their escape. Shrapnel from these explosive weapons tore into the valley's defending treants, embedding jagged metal deep within their bark and core. Rather than healing, the ancient guardians slowly fell to corruption, their wood blackening and their fury turning upon anyone who stepped into the vale. The rusted, tainted fragments recovered from these wounded protectors are sought by Kaela Shadowspear so the gnome Gaxim Rustfizzle can analyze the exact mechanisms of the corruption.",
  ["1"] = {
    {file = "Audio/Transport/full_item_corroded-shrapnel-cbacd4d63e24d170762e/1-0000.mp3", duration = 51.8530612, start = 0},
  },
}
P.transport["item:corrupt-manifestation-s-bracers"] = {
  hash = "78dcec",
  fullHash = "78dcec",
  text = "Corrupt Manifestation's Bracers. Corrupt Manifestation's Bracers are the physical remnants recovered from a tainted water elemental on the coast of Silverpine Forest. Taken by shaman initiates undergoing the Call of Water, they serve as a vital component in an elemental cleansing rite atop the Brazier of Everfount. When the Scourge's plague swept through Lordaeron, it did not spare the natural spirits of the land. Along the misty shores of Silverpine Forest west of the Sepulcher, a once-sacred water shrine fell victim to taint, twisting its resident water manifestation into an aggressive, corrupted shade. Shaman initiates are sent to quell the creature and retrieve its bracers. Combined with purest water upon the Brazier of Everfount, these bindings are cast into the flame to undo the defilement and summon forth an unblemished elemental spirit.",
  ["1"] = {
    {file = "Audio/Transport/full_item_corrupt-manifestation-s-bracers-b3670b941e2a66bc2909/1-0000.mp3", duration = 46.9681633, start = 0},
  },
}
P.transport["item:corrupted-brain-stem"] = {
  hash = "6974f9",
  fullHash = "6974f9",
  text = "Corrupted Brain Stem. Corrupted Brain Stems are biological specimens harvested from the twisted naga and satyrs inhabiting Blackfathom Deeps and the Ashenvale coastline. Gershala Nightwhisper of Auberdine seeks them to study the physical deformities wrought by reckless magical corruption. By examining these brains, night elf scholars hope to understand and potentially prevent a similar fate from befalling the blood elves. The satyrs and naga of Kalimdor stand as living testaments to the warping power of forbidden magic and demonic pacts. Long ago, reckless kaldorei highborne were irrevocably transformed into serpent-like aquatic beasts and demonic horned fiends. The brain stems harvested from these creatures exhibit heavy physical mutation, providing direct anatomical proof of how deep corruptive energies burrow into the nervous systems of once-elven beings. In the coastal settlement of Auberdine, the night elf Gershala Nightwhisper observes the troubling rumors surrounding the blood elves of the Eastern Kingdoms. Fearing that their flirtation with demonic sorcery will spawn yet another generation of monsters on Azeroth, Gershala tasks adventurers with venturing into Blackfathom Deeps. By dissecting both naga and satyr tissues, the researcher hopes to map the path of magical degeneration before another elven culture is lost.",
  ["1"] = {
    {file = "Audio/Transport/full_item_corrupted-brain-stem-93ea7c32ab9b5db13b0b/1-0000.mp3", duration = 75.8334694, start = 0},
  },
}
P.transport["item:corrupted-kor-gem"] = {
  hash = "72cc53",
  fullHash = "72cc53",
  text = "Corrupted Kor Gem. A Corrupted Kor Gem is a potent magical conduit warped by the dark rites of the naga residing around Blackfathom Deeps. Spellcasters covet such stones for their capacity to store sheer arcane force, though the gem's tainted state demands purification before it can serve righteous crafts. Kor gems naturally possess the rare ability to capture and contain substantial magical energies, making them invaluable focuses for sorcerers and enchanted smithing. Along the coastline near the ruins of Blackfathom Deeps, however, the resident naga oracles and tide priestesses claim these gems for their own shadowy rituals. Through foul enchantments, the serpent-kin warp the stone, suffusing it with malevolent, sea-borne corruption. While this infusion taints the gem's nature, the core latent power remains potent, drawing those in need of exceptional magical foci to harvest them from the naga.",
  ["1"] = {
    {file = "Audio/Transport/full_item_corrupted-kor-gem-0613639ad60d753b158a/1-0000.mp3", duration = 52.5583673, start = 0},
  },
}
P.transport["item:cougar-claws"] = {
  hash = "fe9325",
  fullHash = "fe9325",
  text = "Cougar Claws. Cougar Claws are harvested from flatland cougars that roam the central plains of Mulgore. They serve as a vital material in tauren ritual craft, embodying the untamed balance and natural ferocity of the wild predators. The flatland cougar is one of the apex hunters of Mulgore's sprawling grasslands, stalking prey with instinctual grace. In tauren tradition, taking the claws of such a predator is not an act of casual slaughter or trophy hunting, but a way to harness the natural spirit of the beast. When goblin operations begin defiling the ancestral waters of the plains, Mull Thunderhorn calls upon young hunters to gather these claws alongside those of prairie stalkers. The tauren believe that the pure, uncorrupted predatory instincts of native beasts can be woven into a ritual totem capable of scouring unnatural toxins and foul sorcery from the poisoned Thunderhorn Water Well.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cougar-claws-8ba1de44bacc5576987b/1-0000.mp3", duration = 53.995102, start = 0},
  },
}
P.transport["item:courser-eye"] = {
  hash = "b90a30",
  fullHash = "b90a30",
  text = "Courser Eye. Courser Eyes are biological reagents harvested from the antlered coursers roaming the highlands of Stonetalon Mountains. Witch Doctor Jin'Zil in Malaka'jin seeks a large quantity of them to prepare a concoction he mockingly refers to as forest magic.",
  ["1"] = {
    {file = "Audio/Transport/full_item_courser-eye-88c53a0af9935f3eb1be/1-0000.mp3", duration = 14.0277551, start = 0},
  },
}
P.transport["item:covert-ops-pack"] = {
  hash = "dd0a84",
  fullHash = "dd0a84",
  text = "Covert Ops Pack. The Covert Ops Pack is a kit of specialized demolitions gear and operational schematics assembled for Alliance espionage in the Stonetalon Mountains. Designed to dismantle the Venture Company's rapacious presence in Windshear Crag, the satchel equips agents to trigger coordinated sabotage while securing high-value technical intelligence. Issued for clandestine strikes deep within Venture Company territory, the Covert Ops Pack pairs brute destructive power with tactical precision. Inside are color-coded NG-5 explosives matched to remote triggers, alongside thorough instructions designated Plan Alpha and Plan Beta. The strategy relies on triggering high-yield distractions at key infrastructure nodes—namely the Cragpool Lake lumber mill and the eastern mine. While goblins scramble to extinguish blazes and assess mechanical failures, an infiltrator slips past the chaos to pilfer critical documents and schematics. The contents of the pack serve a dual purpose for the Alliance in Stonetalon. For the night elf Sentinels, the detonations and theft disrupt the merciless clear-cutting and gouging of the sacred mountainside. For Alliance tinkers, the primary reward lies in the documents themselves. Recovering Venture Company engineering schematics offers rare insights into goblin heavy machinery, revealing mechanical weak points to exploit and allowing Alliance engineers to adapt industrial innovations into their own designs.",
  ["1"] = {
    {file = "Audio/Transport/full_item_covert-ops-pack-14b0c22c8a261e6944be/1-0000.mp3", duration = 83.6440816, start = 0},
  },
}
P.transport["item:crate-of-crash-helmets"] = {
  hash = "b2b108",
  fullHash = "b2b108",
  text = "Crate of Crash Helmets. A heavy supply shipment of dwarven Siege Engine headgear destined for the Shimmering Flats in Thousand Needles. The sturdy helmets are urgently required by the Brassbolts brothers to protect test drivers from concussions caused by their experimental rocket cars. Out across the blinding white expanse of the Shimmering Flats, gnome engineers test the absolute limits of mechanical propulsion. Unfortunately for the test pilots, the experimental rocket cars designed by the Brassbolts brothers move far faster than their steering can reliably handle. With drivers routinely suffering violent crashes and head trauma, ordinary leather caps no longer suffice. To prevent their roster of willing daredevils from vanishing entirely, heavy-duty dwarven Siege Engine helmets are packed and dispatched across the sea to keep drivers conscious—and alive.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crate-of-crash-helmets-6c8d367f2b359bcfbe03/1-0000.mp3", duration = 46.6546939, start = 0},
  },
}
P.transport["item:crate-of-horseshoes"] = {
  hash = "e1fe31",
  fullHash = "e1fe31",
  text = "Crate of Horseshoes. The Crate of Horseshoes is a heavy delivery package containing fifty iron horseshoes forged in Elwynn Forest. Bound for Lakeshire, it represents the vital trade link between Goldshire's smithy and the embattled settlers of Redridge. Packed and hammered shut by the blacksmith Smith Argus in Goldshire, this hefty crate contains fifty freshly forged horseshoes commissioned by Verner Osgood. Lakeshire's local industry struggles under constant pressure from surrounding gnolls and orcs, leaving craftsmen like Verner reliant on Elwynn Forest for essential metal goods. While the crate satisfies Verner's desperate need for equipment, Argus makes sure to include a stern bill of sale, ensuring the Redridge craftsman remembers that even frontier survival comes at a steep price.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crate-of-horseshoes-5bec5e2eaa74f031a469/1-0000.mp3", duration = 44.4081633, start = 0},
  },
}
P.transport["item:crate-of-inn-supplies"] = {
  hash = "776e4e",
  fullHash = "776e4e",
  text = "Crate of Inn Supplies. The Crate of Inn Supplies is a parcel packed in Coldridge Valley destined for the Thunderbrew Distillery in Kharanos. With the mountain pass overrun by troggs, regular supply routes are cut, leaving the inn dependent on passing travelers to carry goods through. Ordinarily, goods flow smoothly between the quiet training grounds of Anvilmar and the bustling towns of Dun Morogh. However, recent trogg incursions have severed Coldridge Pass, cutting off civilian couriers until armed Mountaineer escorts can clear the roads. Packed by Hands Springsprocket, this heavy crate holds essential tavern provisions that Tannok Frosthammer in Kharanos has been waiting on anxiously amid the disruption.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crate-of-inn-supplies-c86e22a8e61ab6ba49a5/1-0000.mp3", duration = 37.1983673, start = 0},
  },
}
P.transport["item:crate-of-lightforge-ingots"] = {
  hash = "7228af",
  fullHash = "7228af",
  text = "Crate of Lightforge Ingots. The Crate of Lightforge Ingots contains rare consecrated metal recovered to forge an instrument capable of defeating the necromancer Morbent Fel. Packed securely for transport, it is destined for the anvils of the Dwarven District in Stormwind. Lightforge iron is an exceptionally rare material, inherently suited to channel holy power against dark entities. Packed away securely in this crate, the ingots represent the hope of Duskwood in its bitter struggle against the necromancer Morbent Fel, whose shadowy protections shrug off ordinary steel. Ordinary smiths cannot simply work with this metal; it takes an artisan who understands its temper and respects its sacred nature.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crate-of-lightforge-ingots-38dc095338d37e8ed7c0/1-0000.mp3", duration = 37.3028571, start = 0},
  },
}
P.transport["item:crate-with-holes"] = {
  hash = "2ab7ce",
  fullHash = "2ab7ce",
  text = "Crate With Holes. A portable transport container provided by the goblin entrepreneur Mebok Mizzyrix in Ratchet. Pierced with air vents, it safely houses a trained Snufflenose Gopher used to track down subterranean culinary delicacies within the quilboar stronghold of Razorfen Kraul. To acquire rare Blueleaf Tubers from the thorny depths of Razorfen Kraul, goblin merchant Mebok Mizzyrix relies on trained Snufflenose Gophers rather than blind digging. Because gophers cannot simply follow an adventurer across the dusty trails of the Barrens on foot, Mebok packs each critter into a well-ventilated wooden crate. Once brought into the humid, root-choked corridors of the quilboar lair, the crate is unlatched, allowing the beast within to follow its keen sense of smell toward buried tubers.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crate-with-holes-fdb2db233893f2713279/1-0000.mp3", duration = 44.1730612, start = 0},
  },
}
P.transport["item:crawler-leg"] = {
  hash = "d921ed",
  fullHash = "d921ed",
  text = "Crawler Leg. A Crawler Leg is a harvested limb taken from the various crabs prowling the mist-shrouded coast of Darkshore. Though worthless to most travelers, these hardy chitinous appendages are surprisingly suited to mechanical improvisation. The crabs of Darkshore—ranging from pygmy tide crawlers to larger reef crawlers—are known for their sturdy, resilient shells. While night elf sentinels pay little mind to the discarded limbs of coastal vermin, the eccentric gnome engineer Wizbang Cranktoggle found an unexpected use for them. Operating out of Auberdine, Wizbang designed his prototype long-distance communication devices, known as buzzboxes, to run on improvised local components. The segmented joints and durable chitin of crawler legs provide the precise mechanical friction and leverage required to repair Buzzbox 827, situated along the shoreline just south of town.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crawler-leg-12fad2fdfc93d03ef534/1-0000.mp3", duration = 50.5469388, start = 0},
  },
}
P.transport["item:creeper-ichor"] = {
  hash = "2d5cdb",
  fullHash = "2d5cdb",
  text = "Creeper Ichor. Creeper Ichor is a rare, virulent fluid harvested from the moss creepers lurking throughout the forests of the Hillsbrad Foothills. It is sought by the Royal Apothecary Society in Tarren Mill as a potent biological agent for formulating novel plagues against the living. In Tarren Mill, Apothecary Lydon conducts experiments to craft deadly new toxins, seeking to eradicate the surrounding human population. Despising the clean air and vibrant life of the foothills, Lydon searches for natural toxins and biological catalysts native to the local wildlife. The venomous fluids of the forest's giant arachnids, particularly the elusive ichor found within mature moss creepers, serve as an ideal base for his Elixir of Suffering. Mixed with other reagents like gray bear tongues, this fluid aids the Forsaken in perfecting their craft of lethal alchemy.",
  ["1"] = {
    {file = "Audio/Transport/full_item_creeper-ichor-0919eb386277ed67a19e/1-0000.mp3", duration = 50.1812245, start = 0},
  },
}
P.transport["item:crocolisk-skin-classic"] = {
  hash = "442ebc",
  fullHash = "442ebc",
  text = "Crocolisk Skin (Classic). Crocolisk skins are harvested from the tough hides of the crocolisks inhabiting the islands and waters of the Loch in Loch Modan. Prized by merchants and leatherworkers for their durability, they fetch a respectable price despite the danger involved in securing them. The cold waters of the Loch teem with aggressive crocolisks that make their dens along the lake's islands and shores. Hunting them is no simple task, as these ferocious beasts possess razor-sharp teeth and thick, resilient scales capable of turning away careless blades. Despite the hazards, hunters operating out of Farstrider Lodge frequently harvest the creatures. Tailors, leatherworkers, and distant merchants continually seek out the skins to craft durable garments and protective armor, making a bundle of undamaged hides a valuable trade commodity in the region.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crocolisk-skin-classic-46068061976ad4fd4a96/1-0000.mp3", duration = 46.2367347, start = 0},
  },
}
P.transport["item:crocolisk-tear-classic"] = {
  hash = "d309cc",
  fullHash = "d309cc",
  text = "Crocolisk Tear (Classic). A Crocolisk Tear is a curious alchemical reagent gathered from the crocolisks inhabiting the waters of Loch Modan. It is sought by Chief Engineer Hinderweir to synthesize a neutralizing mixture capable of disarming Dark Iron explosives. Loch crocolisks are hardy reptiles native to the temperate waters of Loch Modan. While hunters often prize their skins and meat, Chief Engineer Hinderweir discovered an unexpected utility in their secretions. Combined with potent spider venom and resonant ogre minerals, the tear of a crocolisk provides the specific chemical properties needed to counteract volatile Dark Iron demolition charges threatening the Stonewrought Dam.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crocolisk-tear-classic-e045c92c004fdd9850a2/1-0000.mp3", duration = 38.0865306, start = 0},
  },
}
P.transport["item:crossroads-supply-crate"] = {
  hash = "90552e",
  fullHash = "90552e",
  text = "Crossroads Supply Crate. Crossroads Supply Crates contain vital provisions intended for the settlement of the Crossroads in the Barrens. After a caravan was raided along the arid roads, these stolen goods ended up scattered among local Razormane quilboar camps. The crossroads settlement serves as the beating heart of Horde travel through central Kalimdor, but keeping it provisioned across the arid wastes is a constant trial. Caravan routes running through the Barrens are relentlessly stalked by the native Razormane quilboar. During one such ambush, a vital supply shipment destined for the settlement was ransacked. The crates were dragged into the prickly underbrush and dirt dens of nearby quilboar camps, leaving the settlement's commander, Thork, to enlist travelers to recover them before the outpost runs dangerously low on food, tools, and necessities.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crossroads-supply-crate-7c386e62dee4e1505a04/1-0000.mp3", duration = 46.9681633, start = 0},
  },
}
P.transport["item:crude-flint"] = {
  hash = "5975b1",
  fullHash = "5975b1",
  text = "Crude Flint. Crude Flint pieces are rough fire-starting stones carried by the Mosshide gnolls throughout the Wetlands. The gnolls use them to kindle blazes from freshly hewn marsh timber, an act that deeply enrages the local protector, Rethiel the Greenwarden. While crude and unworked, these simple striking flints provide the Mosshide gnolls with their primary means of generating heat and cooking meat amidst the damp bogs of the Wetlands. Unfortunately for the marsh's ecosystem, the Mosshides fell living timber to feed their hearths and bonfires. This reckless harvesting and combustion of living boughs caught the ire of Rethiel the Greenwarden, who perceives each spark struck as an assault against the natural balance. Determined to stop the slaughter of the marsh's trees, Rethiel tasks passing adventurers with systematically stripping the Mosshide pack of their firestones. Rather than repurposing the scavenged flint, the guardian plans to smash every retrieved piece to dust and cast the fragments into the sea, ensuring the gnolls can no longer burn the Wetlands' living wood.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crude-flint-8c6798b650ba5f178bdd/1-0000.mp3", duration = 60.8130612, start = 0},
  },
}
P.transport["item:crystal-kelp-frond"] = {
  hash = "53d820",
  fullHash = "53d820",
  text = "Crystal Kelp Frond. Crystal Kelp Fronds are aquatic plant cuttings gathered from the murlocs inhabiting Crystal Lake in Elwynn Forest. Though native to the ocean, murlocs carry fronds inland, making them an unusual alchemical reagent sought after by William Pestle in Goldshire. Crystal kelp typically thrives in the depths of saltwater oceans, making its presence in the freshwater pools of Elwynn Forest unexpected. The murloc tribes settled along the shores of Crystal Lake gather and hold onto these fronds for reasons of their own. Alchemists value the fronds for their peculiar visual-distorting properties, and William Pestle in Goldshire specifically uses them as the core ingredient in an invisibility liquor designed to help clandestine sweethearts slip past watchful family eyes.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crystal-kelp-frond-61dfd50470c9199d8a61/1-0000.mp3", duration = 44.0946939, start = 0},
  },
}
P.transport["item:crystal-phial"] = {
  hash = "6c1f4a",
  fullHash = "6c1f4a",
  text = "Crystal Phial. A pristine Crystal Phial entrusted to young night elf adventurers by the druid Tenaron Stormgrip in Shadowglen. It is used to draw sacred water from a nearby moonwell, beginning a series of rites meant to honor and nourish the growing World Tree, Teldrassil. Given to novice night elves atop Aldrassil, this delicate glass phial serves a vital ceremonial purpose. Tenaron Stormgrip tasks young protectors with carrying it to the moonwell just north of the bough to collect its glowing waters. While simple in construction, the phial holds water infused with the sacred legacy of the Well of Eternity. Bringing back a Filled Crystal Phial marks the first step of the Crown of the Earth pilgrimage, teaching young kaldorei the precarious balance of magic, history, and nature in their new island home.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crystal-phial-3cc948e3812eb563c3d4/1-0000.mp3", duration = 47.4383673, start = 0},
  },
}
P.transport["item:crystalized-scales"] = {
  hash = "f817e6",
  fullHash = "f817e6",
  text = "Crystalized Scales. Crystalized Scales are the hardened, mineralized hides harvested from basilisks dwelling in harsh Kalimdor environments such as the Charred Vale and Thousand Needles. When ground into a fine powder, these unusual scales serve as an exotic magical reagent coveted by spellcasters in Stormwind. Basilisks that endure extreme environmental heat and ash—particularly those dwelling within Stonetalon's Charred Vale or the shimmering salt flats of Thousand Needles—develop rigid, crystal-encrusted hides. These crystalized scales possess latent arcane resonance, making them exceptionally valuable to scholarly wizards across the Great Sea who experiment with rare spellcraft. In the human kingdom of Stormwind, the mage Collin Mauren actively seeks out adventurers journeying into the Kalimdor frontier to secure these scales. By pulverizing the crystalline mineral layers into dust, Mauren utilizes the particulate material as a vital reagent for newly conceived spells and personal arcane research.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crystalized-scales-4174e476e99548c9b94b/1-0000.mp3", duration = 58.8016327, start = 0},
  },
}
P.transport["item:curative-animal-salve"] = {
  hash = "40a848",
  fullHash = "40a848",
  text = "Curative Animal Salve. Curative Animal Salve is an herbal remedy brewed by druidic herbalists to soothe and heal wildlife afflicted by spreading ecological sickness. Formulated in both Darkshore and the Barrens, it serves as a frontline treatment for sickly creatures suffering from the land's unseen taints. Crafted from locally gathered herbal reagents, Curative Animal Salve is prepared in ten-dose batches to treat wildlife caught in the throes of spreading corruption. In the misty forests of Darkshore, Alanndarian Nightsong directs young druids to apply the ointment to sickly deer wandering between the Cliffspring River and the borders of Ashenvale. Far to the south in the arid expanse of the Barrens, Tonga Runetotem brews an identical remedy to treat sickly gazelles grazing north of the Crossroads. While both herbalists work with local authorities to produce larger supplies, field practitioners administer the salve directly to beasts suffering from environmental malaise. Applying the salve directly eases an animal's suffering, yet the Cenarion Circle views these afflictions as mere symptoms of a much greater disturbance. In Moonglade, Dendrite Starblaze observes that neither the afflicted deer of the coast nor the suffering gazelles of the savannah are random casualties. Instead, they are unwitting victims of a spreading blight that touches Kalimdor from multiple directions. Administering the salve serves as a fundamental rite for initiates, testing their dedication to safeguarding the natural world and mastering the arts of cleansing poison.",
  ["1"] = {
    {file = "Audio/Transport/full_item_curative-animal-salve-4acb80a3ccfa0fd07ca8/1-0000.mp3", duration = 87.1183673, start = 0},
  },
}
P.transport["item:daffodil-bouquet"] = {
  hash = "2f499e",
  fullHash = "2f499e",
  text = "Daffodil Bouquet. The Daffodil Bouquet is a fresh bundle of bright flowers gathered by the herbalist Martie Jainrose in Lakeshire. Intended as a romantic token of appreciation from Guard Parker to Darcy, the gift inadvertently stokes local gossip and petty rivalry. When Guard Parker wishes to express his gratitude to Darcy at the Lakeshire inn for packing his daily lunch, he arranges a gesture through the town's herbalist, Martie Jainrose. Martie prepares a bouquet of daffodils, noting they are her personal favorite. However, when delivered to Darcy, the bright blooms immediately raise suspicions: Darcy recognizes the selection as Martie's signature flower and suspects petty jealousy from the other woman, half-joking that Martie might have poisoned the stems out of spite.",
  ["1"] = {
    {file = "Audio/Transport/full_item_daffodil-bouquet-8009d89d41258111d85f/1-0000.mp3", duration = 43.3632653, start = 0},
  },
}
P.transport["item:daggerspine-scale"] = {
  hash = "1643f0",
  fullHash = "1643f0",
  text = "Daggerspine Scale. A Daggerspine Scale is a tough reptilian scale harvested from the Daggerspine naga prowling the southern shores of the Hillsbrad Foothills. Sought after by the Royal Apothecary Society, these scales serve as a crucial catalyst to activate virulent brews in the Forsaken's ongoing plague experiments. The Royal Apothecary Society constantly seeks biological reagents to enhance their toxins, plagues, and concoctions. When refining the experimental brew known as the Elixir of Agony, the apothecaries discovered that scales taken from the local Daggerspine naga possessed unique reactive properties. When combined with troll regenerative elixirs and murloc organs, the scales help chemically activate dormant contaminating agents suspended in raw mixtures. Procuring them requires hunting along the rocky coastline east of Southshore, braving both the vicious naga tribe and nearby Alliance forces.",
  ["1"] = {
    {file = "Audio/Transport/full_item_daggerspine-scale-c795b6640a559797def8/1-0000.mp3", duration = 51.3044898, start = 0},
  },
}
P.transport["item:dal-bloodclaw-s-skull"] = {
  hash = "d0bb05",
  fullHash = "d0bb05",
  text = "Dal Bloodclaw's Skull. Dal Bloodclaw's Skull is taken from the chieftain of the Thistlefur furbolg in northern Ashenvale. Brought to Raene Wolfrunner in Astranaar, it serves as tangible proof that an imminent attack on the night elf settlement has been averted. The Thistlefur furbolgs residing north of Astranaar have grown rapidly in number and aggression, corrupted alongside much of Ashenvale's ancient forests. Fearing that the growing tribe would soon amass the courage to march directly on Astranaar, the night elf sentinel Raene Wolfrunner ordered the culling of their ranks and the death of their leader, Dal Bloodclaw. Claiming Dal Bloodclaw's Skull serves not as a trophy of petty vengeance, but as grim and undeniable evidence that the tribe's leadership has been shattered, buying the defenders of Astranaar precious time.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dal-bloodclaw-s-skull-df06b06f7bf07d7fcad7/1-0000.mp3", duration = 44.3297959, start = 0},
  },
}
P.transport["item:dalaran-mana-gem"] = {
  hash = "491078",
  fullHash = "491078",
  text = "Dalaran Mana Gem. Dalaran Mana Gems are crystallized arcane reserves carried by Kirin Tor personnel operating in Silverpine Forest. Forsaken spellcasters covet these gems as potent raw components for crafting enchanted vestments like spellfire robes. The mages, conjurors, and guards of the Kirin Tor stationed around Ambermill in Silverpine Forest carry specialized mana gems to focus and replenish their arcane energies. For the Forsaken practitioners in the Magic Quarter of the Undercity, these crystalline conduits represent an accessible source of concentrated magical essence. Although some undead mages acknowledge a shared academic heritage with Dalaran, pragmatic necessity and a philosophy of survival dictate that unyielding rivals are fair game to be stripped of their magical resources. When harvested from fallen Kirin Tor operatives, these gems are brought to tailors like Josef Gregorian in the Undercity alongside bundles of simple linen. While ordinary craftsmen cannot directly channel arcane power, skilled tailors can bind the mana gems into the weave of the cloth. This infusion transforms common thread into enchanted garments capable of bolstering a fledgling spellcaster's connection to the arcane.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dalaran-mana-gem-5d4d377f7516387e3cf3/1-0000.mp3", duration = 69.2767347, start = 0},
  },
}
P.transport["item:dalaran-pendant"] = {
  hash = "712402",
  fullHash = "712402",
  text = "Dalaran Pendant. Dalaran Pendants are magical talismans carried by the Kirin Tor wizards stationed at the village of Ambermill in Silverpine Forest. The Forsaken seek to collect these pendants to disrupt the magi's arcane workings and trace the source of their power. In the village of Ambermill, Kirin Tor sorcerers, conjurers, and protectors actively weave formidable arcane spells threatening Forsaken control over southern Silverpine Forest. Each operative carries an attuned Dalaran Pendant. At the Sepulcher, Shadow Priest Allister tasks Forsaken operatives with recovering these pendants to slow down the mages' efforts and uncover who is guiding their magical weave.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dalaran-pendant-5053ae68680f15daf643/1-0000.mp3", duration = 37.3812245, start = 0},
  },
}
P.transport["item:dalaran-status-report"] = {
  hash = "c5702c",
  fullHash = "c5702c",
  text = "Dalaran Status Report. The Dalaran Status Report is a cache of sensitive intelligence compiled by the Kirin Tor wizards stationed at Ambermill in Silverpine Forest. It details the current state of the rebuilding city of Dalaran, making it a prized document for the Forsaken and the Deathstalkers of Undercity. The Scourge sacked Dalaran and Archimonde brought down its towering spires during the Third War. Its surviving magi removed its protective shield early in the reconstruction and are rebuilding the city in the open. The Kirin Tor also maintains enclaves such as Ambermill in southeastern Silverpine Forest. The Dalaran Status Report contains intelligence about the state of Dalaran sought by the Deathstalkers.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dalaran-status-report-73bfec47f19dabce3425/1-0000.mp3", duration = 40.1763265, start = 0},
  },
}
P.transport["item:dalin-s-heart"] = {
  hash = "b3725e",
  fullHash = "b3725e",
  text = "Dalin's Heart. Dalin's Heart is a macabre ritual component carved from Dalin Forgewright, an honorable man patrolling near the Greymane Wall in Silverpine Forest. Undercity warlocks seek it out as an offering of unblemished purity, intended to lure and bind a succubus to their service. To summon and subjugate a succubus, Undercity warlocks require rare bait: the physical hearts of truly virtuous mortals. Dalin Forgewright earned his dark fate through selfless devotion, spending his days defending desperate Lordaeron refugees barred from safety at the sealed Greymane Wall. His unstinting altruism marks him as an emblem of goodness in a fallen land, making his heart an irresistible prize for demonic seduction rites conducted within the Temple of the Damned.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dalin-s-heart-4b87bf8d950a947f2c2b/1-0000.mp3", duration = 44.0946939, start = 0},
  },
}
P.transport["item:darkhound-blood"] = {
  hash = "8d7b67",
  fullHash = "8d7b67",
  text = "Darkhound Blood. Darkhound Blood is a foul bodily fluid harvested from the tainted canine beasts roaming the fields and forests of Tirisfal Glades. Gathered at the behest of the Royal Apothecary Society, it serves as an early reagent in their dark experiments to engineer a lethal new plague. Under the command of Lady Sylvanas Windrunner, the Royal Apothecary Society strives to develop a virulent contagion capable of wiping out Arthas and his Scourge. Stationed in Brill, Apothecary Johaan theorizes that local beasts, corrupted by dark energies and resilient to the surrounding decay, possess unusual biological properties. By distilling the blood of wild darkhounds, Johaan aims to uncover biological compounds that can resist or propagate virulent necrotic strains.",
  ["1"] = {
    {file = "Audio/Transport/full_item_darkhound-blood-f98f4bfc78ead654276e/1-0000.mp3", duration = 45.7665306, start = 0},
  },
}
P.transport["item:darkshore-grouper"] = {
  hash = "5b0e85",
  fullHash = "5b0e85",
  text = "Darkshore Grouper. Darkshore Grouper is a sturdy saltwater fish native to the misty coastal waters along Darkshore. Prized both as a tasty staple catch and a sporting quarry, it has become harder to harvest from the docks due to murloc activity driving local fishermen from their boats. Found in the cold sea waters of Darkshore, the Darkshore Grouper is a prized catch for coastal anglers. The fish is valued for its culinary versatility, making its way into an array of simple coastal dishes favored by travelers and residents around Auberdine. While it can be hauled out of the surf with basic angling gear, fishermen consider hooking them as enjoyable as eating them. Historically, fishermen such as Gubber Blump took small vessels out into deeper waters to haul in grouper by the dozen. However, increasing aggression from coastal murlocs has grounded most boats around Auberdine. With anglers confined to the shorelines and docks, locals suspect the encroaching murlocs are devouring the local grouper stock, making a good haul harder to come by without patience.",
  ["1"] = {
    {file = "Audio/Transport/full_item_darkshore-grouper-5e5c52173ae059d6693e/1-0000.mp3", duration = 58.9583673, start = 0},
  },
}
P.transport["item:darksoul-shackle"] = {
  hash = "ce5ba4",
  fullHash = "ce5ba4",
  text = "Darksoul Shackle. A Darksoul Shackle is an enchanted fetter worn by the Moonrage Darksoul worgen stalking Silverpine Forest. Crafted under the direction of Archmage Arugal, these implements are sought by Forsaken mages at the Sepulcher seeking to unravel the feral magic gripping the region. When Archmage Arugal unleashed the worgen upon Silverpine Forest, his own arcane mastery proved insufficient to fully direct and sustain the otherworldly beasts. To compensate for his shortcomings, he bound enchanted implements, such as Darksoul Shackles, to his creations. These fetters channel external sorcery into the Moonrage Darksouls, reinforcing their supernatural strength and anchoring the curse that keeps them thrall to Shadowfang Keep.",
  ["1"] = {
    {file = "Audio/Transport/full_item_darksoul-shackle-c021e8d664565b3552de/1-0000.mp3", duration = 42.004898, start = 0},
  },
}
P.transport["item:darnassus-marzipan"] = {
  hash = "d046ed",
  fullHash = "d046ed",
  text = "Darnassus Marzipan. Darnassus Marzipan is a festive confectionery crafted in the night elven capital for the autumn celebration of Hallow's End. Innkeepers in Darnassus hand it out to trick-or-treaters willing to dance for their sweet reward. During Hallow's End, the capital cities of the Alliance take part in lighthearted trick-or-treat traditions. While the dwarves offer sharp mints and Stormwind crafts chewy nougat, the innkeepers of Darnassus prepare delicate marzipan for visitors. Obtaining a piece requires visitors to showcase a bit of festive spirit—specifically, dancing on command for the innkeeper. The confection is one of four regional treats sought by young Jesper, a sick orphan in Stormwind's Cathedral Square who cannot go out to collect sweets himself.",
  ["1"] = {
    {file = "Audio/Transport/full_item_darnassus-marzipan-30c6a5ecb9afb1c97467/1-0000.mp3", duration = 42.004898, start = 0},
  },
}
P.transport["item:darthalia-s-sealed-commendation"] = {
  hash = "f73e25",
  fullHash = "f73e25",
  text = "Darthalia's Sealed Commendation. Darthalia's Sealed Commendation is an official dispatch penned by the Forsaken battle commander in Tarren Mill. It praises a soldier's relentless campaign against the humans of Hillsbrad and delivers word of those victories directly to Undercity's high command. Following the brutal clashes across the Hillsbrad Foothills, High Executor Darthalia drafted this sealed dispatch to officially record victories against Hillsbrad's human defenders and the devastation wrought upon human positions. Sealed to preserve the commander's appraisal from prying eyes, the document is addressed to Varimathras, dreadlord advisor to Lady Sylvanas Windrunner. For the Forsaken leadership in the Royal Quarter, such missives offer tangible proof that Alliance enclaves south of Lordaeron can be broken, freeing northern garrisons to focus on the relentless threat of the Scourge.",
  ["1"] = {
    {file = "Audio/Transport/full_item_darthalia-s-sealed-commendation-113a8c170e70f174d99e/1-0000.mp3", duration = 50.0244898, start = 0},
  },
}
P.transport["item:deadmire-s-tooth"] = {
  hash = "edaee3",
  fullHash = "edaee3",
  text = "Deadmire's Tooth. Deadmire's Tooth is a trophy taken from the ancient crocolisk known as Deadmire, who stalks the murky waters of Dustwallow Marsh. Bringing it to the hunter Melor Stonehoof atop Thunder Bluff proves that the aging predator has been granted a merciful and honorable death. In the traditions of the tauren hunters on Hunter Rise, tracking wild beasts is not merely a test of martial prowess or mindless bloodsport. It is a spiritual covenant of balance, reverence, and occasionally, mercy. Deadmire was once one of the most magnificent crocolisks in Dustwallow Marsh, but his great age turned his final years into excruciating torment. Despite possessing the unyielding spirit and terrifying ferocity of his prime, his massive bones and failing body became a prison of endless pain. Claiming Deadmire's Tooth serves as physical proof to Melor Stonehoof that the beast's prolonged suffering has finally been brought to an end through an honorable hunt.",
  ["1"] = {
    {file = "Audio/Transport/full_item_deadmire-s-tooth-83641dadf0f200569812/1-0000.mp3", duration = 54.1779592, start = 0},
  },
}
P.transport["item:death-cap"] = {
  hash = "6ac276",
  fullHash = "6ac276",
  text = "Death Cap. The Death Cap is a rare, potent fungus found hidden in the shadowed cavern behind Cliffspring Falls in Darkshore. Sought by night elf alchemists for its unique properties, harvesting it requires venturing into a subterranean den warned against by the Grove of the Ancients. The Death Cap grows exclusively in the subterranean dampness of the cave tucked behind Cliffspring Falls, situated along the northeastern mountain ridges of Darkshore. Unlike the more plentiful scaber stalks that carpet the surrounding cavern floor, the Death Cap is scarce and distinct. Night elf herbalists like Barithras Moonshade value the fungus for experimental brewing, though retrieving even a single specimen requires braving a cavern whispered to harbor a nascent corruption.",
  ["1"] = {
    {file = "Audio/Transport/full_item_death-cap-fe43244a1920989e32cf/1-0000.mp3", duration = 43.5461224, start = 0},
  },
}
P.transport["item:deathstalker-report"] = {
  hash = "0ac00f",
  fullHash = "0ac00f",
  text = "Deathstalker Report. The Deathstalker Report is a written dispatch penned by Deathstalker Rane Yorick detailing military reconnaissance in Silverpine Forest. It contains critical tactical intelligence intended for High Executor Hadrec at the Sepulcher regarding local Scourge movements and the state of the Forsaken's forward scouts. Reconnaissance in northern Silverpine Forest is a lethal duty, even for the undead. After finding themselves ambushed and pinned down by Scourge prowling the pine woods, Deathstalkers Rane Yorick and Quinn Yorick had to consolidate their findings into this hurried dispatch. The report summarizes unexpected levels of Scourge resistance threatening Forsaken territorial ambitions in the region. Because Quinn suffered grievous injuries during their mission, the document is entrusted to passing allies to ensure High Executor Hadrec receives word at the Sepulcher without delay.",
  ["1"] = {
    {file = "Audio/Transport/full_item_deathstalker-report-cd7f71d2066ffc1ea77a/1-0000.mp3", duration = 50.2595918, start = 0},
  },
}
P.transport["item:deepfury-s-orders"] = {
  hash = "b32b69",
  fullHash = "b32b69",
  text = "Deepfury's Orders. Deepfury's Orders is a crumpled parchment recovered from the body of Ol' Rustlocke beneath the Thandol Span. It contains grim instructions belonging to the Dark Iron dwarves who ambushed the scouting dwarven defender. While scouting the foundations of the Thandol Span, the dwarven bridge defender Ol' Rustlocke was cornered and slain in a sudden Dark Iron ambush. Clasped beside the scout's clenched fist lay these orders, drafted by the enemy leader, Deepfury. The document serves as direct proof of a coordinated plot targeting the bridge that connects the Wetlands to the Arathi Highlands.",
  ["1"] = {
    {file = "Audio/Transport/full_item_deepfury-s-orders-5df3e635204d3e197cc4/1-0000.mp3", duration = 34.56, start = 0},
  },
}
P.transport["item:deepmoss-egg"] = {
  hash = "f19b36",
  fullHash = "f19b36",
  text = "Deepmoss Egg. Deepmoss Eggs are the clustered clutches laid by deepmoss spiders in the crags and canyons of the Stonetalon Mountains. Coveted by opportunistic goblin merchants in Ratchet, they are destined to become an exotic culinary delicacy in the pirate port of Booty Bay. Deepmoss spiders nest across the craggy heights of the Stonetalon Mountains, particularly throughout Sishir Canyon and beneath the remaining trees of Windshear Crag. The clutches they leave behind contain viable arachnid eggs, sheltered beneath thick webbed sacks and damp mountain moss. While unappealing to most travelers, these egg sacks have caught the eye of goblin commerce. In the southern port of Booty Bay, spider egg omelettes have surfaced as an eccentric gastronomic craze. Because local supplies cannot meet the appetite of wealthy pirates and adventurous gourmands, Ratchet merchant Mebok Mizzyrix coordinates shipments through Wharfmaster Dizzywig. Adventurers brave the venomous broods of Stonetalon to harvest fresh clutches, turning dangerous spider nests into lucrative shipping contracts.",
  ["1"] = {
    {file = "Audio/Transport/full_item_deepmoss-egg-c031b9af9fd80800229e/1-0000.mp3", duration = 62.0669388, start = 0},
  },
}
P.transport["item:defias-docket"] = {
  hash = "b6c0b9",
  fullHash = "b6c0b9",
  text = "Defias Docket. The Defias Docket is a collection of classified operational orders belonging to the Defias Brotherhood, discovered hidden within Addle's Stead in western Duskwood. It contains detailed intelligence concerning an ambitious Defias plot, providing a critical lead in the search for Stormwind's vanished emissary. While pursuing leads on the kingdom's missing diplomat, investigators are pointed toward Duskwood by Master Elling Trias. Watcher Backus notes recent and unusual Defias movements converging on Addle's Stead, a derelict farmstead situated just south of the road leading in from Westfall. Stashed inside a strongbox on the property, the Defias Docket contains complex records detailing the brotherhood's movements, far exceeding simple highway robbery or local banditry.",
  ["1"] = {
    {file = "Audio/Transport/full_item_defias-docket-fafd0833370de718659f/1-0000.mp3", duration = 44.1730612, start = 0},
  },
}
P.transport["item:defias-tower-key"] = {
  hash = "5c4139",
  fullHash = "5c4139",
  text = "Defias Tower Key. The Defias Tower Key is an item stolen from the monstrous sentries guarding Klaven's Tower in Westfall. Carried by the mutated drones defending the site, it represents vital proof of the Defias Brotherhood's dangerous operations and is sought by Stormwind intelligence operatives. Klaven's Tower along the Westfall coastline has long served as a stronghold for the Defias Brotherhood, but recent shipments out of Duskwood brought far more terrifying sentries to its perimeter. Among the guards are malformed Defias drones—undead, spike-ridden abominations. To pierce the defenses and prove the perimeter breached, SI:7 operatives stake out the grounds and mandate that field agents pick the pockets of these grotesque sentinels rather than engage them head-on. The key serves as clear evidence that an infiltrator penetrated the perimeter without sounding an alarm.",
  ["1"] = {
    {file = "Audio/Transport/full_item_defias-tower-key-41b26df6c75e28d06fcd/1-0000.mp3", duration = 48.9012245, start = 0},
  },
}
P.transport["item:deliah-s-ring"] = {
  hash = "0d2a8a",
  fullHash = "0d2a8a",
  text = "Deliah's Ring. Deliah's Ring is an engraved piece of jewelry recovered from a corpse pile amassed by the Rot Hide gnolls in Silverpine Forest. Bearing the inscription 'For Deliah', the keepsake offers a grim trail tracing back to a plague victim stolen from Tirisfal's mass graves. Discovered upon the pockmarked, relatively fresh hand of a corpse among gnoll mounds in Silverpine Forest, the ring is inscribed simply: 'For Deliah'. The discovery reveals that the local Rot Hide gnolls are not merely scavenging battlefields—they are actively raiding the mass graves of Tirisfal Glades and ferrying human and Forsaken corpses south to Fenris Isle for their own vile purposes.",
  ["1"] = {
    {file = "Audio/Transport/full_item_deliah-s-ring-c45b109da6e6d38c7edd/1-0000.mp3", duration = 37.6946939, start = 0},
  },
}
P.transport["item:delivery-to-mathias"] = {
  hash = "ebd602",
  fullHash = "ebd602",
  text = "Delivery to Mathias. The Delivery to Mathias is a sealed parcel entrusted to promising rogues by Keryn Sylvius in Goldshire. Handing it over to Master Mathias Shaw grants an aspiring operative entry into the inner workings of SI:7 in Stormwind. To the untrained eye, carrying a simple parcel from the Lion's Pride Inn to the Stormwind Barracks seems like mundane courier work. Yet for budding rogues, the package serves as an audition for Stormwind Intelligence. Handed over by local trainer Keryn Sylvius, it offers novice cutpurses a direct introduction to Master Mathias Shaw, testing their ability to navigate the capital, keep a low profile, and follow discreet orders without asking questions. Delivering the package brings an operative directly into the heart of SI:7 headquarters in Old Town. Mathias Shaw uses such handoffs to weed out pretenders from true talents. Those who present the parcel without faltering are rewarded with high-stakes field assignments, starting with covert reconnaissance and infiltration against Defias smuggling networks in Elwynn Forest.",
  ["1"] = {
    {file = "Audio/Transport/full_item_delivery-to-mathias-099e90c3ddcfb69294ed/1-0000.mp3", duration = 61.204898, start = 0},
  },
}
P.transport["item:deviate-hide"] = {
  hash = "825fc9",
  fullHash = "825fc9",
  text = "Deviate Hide. Deviate Hides are the mutated skins stripped from the beasts dwelling within the Wailing Caverns. Warped by the corrupting dream of the druid Naralex, these otherworldly pelts are sought by druids looking to repurpose the nightmare's taint into durable leather goods. When the night elf druid Naralex entered his deep slumber beneath the Barrens, his dream turned into an Emerald Nightmare that warped the local cavern ecology. The beasts lurking in the depths transformed into unnatural deviate predators with tough, mutated hides. While inherently touched by evil, these pelts possess unusual, supple resilience that makes them uniquely suited for leathercrafting. Nalpak, perched high above the cavern mouth in the skull-shaped rock formation, collects these hides to study their properties and fashion them into sturdy utility packs.",
  ["1"] = {
    {file = "Audio/Transport/full_item_deviate-hide-caa5ac84ea06a7315931/1-0000.mp3", duration = 46.6546939, start = 0},
  },
}
P.transport["item:devlin-s-remains"] = {
  hash = "f28928",
  fullHash = "f28928",
  text = "Devlin's Remains. Devlin's Remains are the collected skeletal bones of Devlin Agamand, the younger son of the wealthy family who owned the Agamand Mills. Stalking the roads near his ruined ancestral estate as a mindless Scourge thrall, he was struck down to deliver his bones to a vengeful survivor in Brill. In life, Devlin Agamand stood in the shadow of his elder brother Thurman. Where Thurman was gentle and tall, Devlin was remembered as physically frail and viciously sharp-tongued. When the Plague of Undeath swept through northern Tirisfal Glades, the Agamand family failed to protect their lands and laborers. Devlin was among the first to fall, reanimated as a ravenous Scourge ghoul whose frantic, mad chattering haunted the roadside leading up to Agamand Mills. Coleman Farthing, a Forsaken residing in Brill, holds a deep and abiding grudge against the entire Agamand bloodline. Holding them directly responsible for failing his family when the plague arrived, Farthing tasked travelers with laying Devlin to rest and collecting his remains. Farthing sought to display Devlin's bones upon his mantle, savoring the knowledge that his former masters have been reduced to dust and shattered fragments under his heel.",
  ["1"] = {
    {file = "Audio/Transport/full_item_devlin-s-remains-151aea665c769461cee5/1-0000.mp3", duration = 67.9967347, start = 0},
  },
}
P.transport["item:dirt-caked-pendant"] = {
  hash = "a71f8a",
  fullHash = "a71f8a",
  text = "Dirt-Caked Pendant. The Dirt-Caked Pendant is a personal keepsake belonging to the captured orc Dogran. Given to an aspiring warlock in the Barrens, it serves as a crucial emotional bait to lure and bind a succubus in Orgrimmar.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dirt-caked-pendant-e5486d6ec123a224d8cb/1-0000.mp3", duration = 12.4342857, start = 0},
  },
}
P.transport["item:disarming-colloid"] = {
  hash = "293374",
  fullHash = "293374",
  text = "Disarming Colloid. Disarming Colloid is a specialized chemical agent formulated to counter the volatility of Seaforium explosive powder. Provided by the dwarf Ashlan Stonesmirk in the Wetlands, it serves as the crucial stabilizing component in a neutralizing mixture meant to prevent a catastrophic demolition of the Stonewrought Dam. When Ashlan Stonesmirk analyzed the unusual blasting powder left by Dark Iron sappers at the Stonewrought Dam in Loch Modan, he recognized it immediately by its distinct scent and fine silver crystals: Seaforium. While harmless when completely dry, Seaforium becomes immensely destructive upon contact with moisture, making it an existential threat to the waterlogged Stonewrought Dam. To halt this reaction before a detonation occurs, Stonesmirk provided a disarming colloid. When combined with three specific local reagents—lurker venom, crushed Mo'grosh crystal, and a crocolisk tear—this colloid effectively neutralizes the explosive properties of the Seaforium compound.",
  ["1"] = {
    {file = "Audio/Transport/full_item_disarming-colloid-7bc79393f5deeadf5a74/1-0000.mp3", duration = 58.3053061, start = 0},
  },
}
P.transport["item:disarming-mixture"] = {
  hash = "1f9383",
  fullHash = "1f9383",
  text = "Disarming Mixture. Disarming Mixture is a specialized chemical concoction prepared by Chief Engineer Hinderweir at the Stonewrought Dam. Created to neutralize volatile Seaforium explosives, it is used to prevent Dark Iron saboteurs from destroying the massive dwarven structure holding back the waters of Loch Modan. When Dark Iron saboteurs planted a heavy Seaforium charge beneath the foundation of the Stonewrought Dam, standard methods of defusal were far too risky. Lacking immediate Mountaineer support, Chief Engineer Hinderweir combined the Disarming Mixture from ingredients named by the explosives expert Ashlan Stonesmirk to rapidly neutralize the underwater explosive. When stirred directly into the planted powder keg, the solution neutralizes the reactive compounds, reducing a catastrophic explosion to a harmless, fizzling ruin.",
  ["1"] = {
    {file = "Audio/Transport/full_item_disarming-mixture-a01eba5a01c1a7b61f6a/1-0000.mp3", duration = 46.9681633, start = 0},
  },
}
P.transport["item:divined-scroll"] = {
  hash = "e24bc7",
  fullHash = "e24bc7",
  text = "Divined Scroll. The Divined Scroll is an enchanted parchment used by the night elves of Silverwind Refuge to unmask the source of Ashenvale's disturbed waters. By channeling the residual magic within intact water elemental bracers, the scroll reveals the identity of the rogue spellcaster summoning them. The tainted waters of Mystral Lake have long troubled the Sentinels guarding Ashenvale. To pinpoint who is manipulating the water elementals infesting the lake, Sentinel Velene Starstrike provides travelers with an uncharged divining scroll. By gathering intact bracers directly from the slain elementals and using them as an arcane reagent, the latent bindings within the metal bleed into the parchment. The resulting Divined Scroll exposes the magical signature of the rogue wizard behind the infestation.",
  ["1"] = {
    {file = "Audio/Transport/full_item_divined-scroll-4611730afb2b8d9c746b/1-0000.mp3", duration = 45.844898, start = 0},
  },
}
P.transport["item:divining-scroll"] = {
  hash = "ee36f2",
  fullHash = "ee36f2",
  text = "Divining Scroll. The Divining Scroll is an enchanted parchment provided by Sentinel Velene Starstrike at Silverwind Refuge. Its magic allows investigators to trace the magical signature of the unnatural water elementals infesting Ashenvale back to their creator. When corrupt water elementals began rising from the pristine pools of Ashenvale, the Sentinels knew the disturbance was not a natural emergence. Sentinel Velene Starstrike acquired this divination scroll to identify the person responsible. By channeling the scroll's magic through intact elemental bracers as a focusing reagent, the user extracts the summoner's signature, transforming the blank parchment into a Divined Scroll that names the guilty party.",
  ["1"] = {
    {file = "Audio/Transport/full_item_divining-scroll-a318b3295ab9e12b3fca/1-0000.mp3", duration = 39.68, start = 0},
  },
}
P.transport["item:dogran-s-pendant"] = {
  hash = "74d195",
  fullHash = "74d195",
  text = "Dogran's Pendant. Dogran's Pendant is a deeply personal talisman carried by the wounded orc Dogran and bound to the tragedy of his separation from his mate, Zankaja. Within the shadowy circles of Orgrimmar's warlocks, the raw emotional resonance of the pendant is harnessed as a catalyst to lure and bind a succubus. Dogran's Pendant is steeped in personal sorrow, marking the tragic fate of an orc whose love for Zankaja is overshadowed by captivity and crippling wounds. For the warlocks of the Cleft of Shadow, such potent emotions are not merely remnants of grief—they are magical conduits. Demons such as the succubus prey voraciously upon love, yearning, and vulnerability, making the pendant an ideal bait to draw one across the Twisting Nether into Neeru Fireblade's summoning circle.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dogran-s-pendant-d73a2611daa223c355fe/1-0000.mp3", duration = 45.5314286, start = 0},
  },
}
P.transport["item:dolanaar-delivery"] = {
  hash = "5f3da6",
  fullHash = "5f3da6",
  text = "Dolanaar Delivery. The Dolanaar Delivery is a package of harvested herbs sent from the druidic grounds of Shadowglen to the village of Dolanaar. Entrusted to young travelers leaving the sheltered glen, it serves as a simple errand to connect them with Innkeeper Keldamyr down the road. Harvested within the shadowed groves of Aldrassil, this parcel contains fresh herbs gathered for the settlement of Dolanaar. Porthannius, detained by ongoing matters among the druids of Shadowglen, relies on fledgling adventurers bound southward along the road to ferry the bundle safely to Innkeeper Keldamyr. Delivering the parcel brings the traveler straight to the threshold of Dolanaar's inn. Keldamyr receives the goods with gratitude, using the exchange to remind weary wayfarers of the necessity of rest, peace of mind, and the sanctuary offered by an inn's hearth before they venture deeper into Teldrassil.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dolanaar-delivery-78618d08b49f4590243e/1-0000.mp3", duration = 49.4497959, start = 0},
  },
}
P.transport["item:dragonmaw-war-banner"] = {
  hash = "f26d30",
  fullHash = "f26d30",
  text = "Dragonmaw War Banner. Dragonmaw War Banners are rallying standards carried by the Dragonmaw orcs entrenched in the Wetlands. Stamped with the iconography of their clan, they serve as proof of battle for the dwarven defenders of Menethil Harbor seeking to quell the rising orcish threat. Following the Second War, the Dragonmaw clan was shattered after losing control of their enslaved red dragons. The enraged drakes turned on their captors, driving the survivors out of Grim Batol and into the eastern hills. In recent times, the remaining orcs have begun gathering strength once more under Chieftain Nek'rosh, raising their war banners over encampments northeast of Menethil Harbor. These crude, imposing standards represent both their lingering defiance and a direct menace to the marshland settlements. Captain Stoutfist, stationed at Menethil Harbor, tasks Alliance adventurers with striking into the marsh encampments to bring back these banners. Trophies stripped from raiders, centurions, and bone-warders, the banners confirm to the dwarven garrison that the Dragonmaw encampments are being systematically broken before the clan can launch coordinated raids.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dragonmaw-war-banner-f90d63fd01e42081de16/1-0000.mp3", duration = 64.1567347, start = 0},
  },
}
P.transport["item:dried-seeds"] = {
  hash = "dc6b0e",
  fullHash = "dc6b0e",
  text = "Dried Seeds. Dried Seeds are lifeless husks given to travelers by the tauren druid Tonga Runetotem at the Crossroads. They serve as an experimental medium to test the anomalous, life-giving power bubbling up from the fissures beneath the waters of the Barrens.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dried-seeds-fd27016e17310d6802f2/1-0000.mp3", duration = 13.322449, start = 0},
  },
}
P.transport["item:durnan-s-scalding-mornbrew"] = {
  hash = "055635",
  fullHash = "055635",
  text = "Durnan's Scalding Mornbrew. Durnan's Scalding Mornbrew is a freshly poured, piping-hot dwarven beverage intended for Durnan Furcutter in Coldridge Valley. Because the drink quickly loses its heat in the frigid mountain air, it must be rushed directly to Anvilmar before it goes cold. In the biting chill of Coldridge Valley, few comforts rival a mug of fresh mornbrew served piping hot. When a courier gets delayed delivering a round to Grelin Whitebeard, the fresh cup meant for Durnan Furcutter inside Anvilmar risks freezing over. Durnan specifically expects his brew scalding, leaving only a short window of a few minutes to carry the steaming mug up the snowy path into the mountain hall before it cools completely.",
  ["1"] = {
    {file = "Audio/Transport/full_item_durnan-s-scalding-mornbrew-82c8703765c07598d53c/1-0000.mp3", duration = 38.5828571, start = 0},
  },
}
P.transport["item:durotar-tiger-fur"] = {
  hash = "27cf98",
  fullHash = "27cf98",
  text = "Durotar Tiger Fur. Durotar Tiger Fur is harvested from the fierce tigers roaming the tropical Echo Isles off the southeastern coast of Durotar. The Darkspear trolls rely heavily on these pelts to craft cold-weather blankets, sturdy tents, and durable armor as their refugee population steadily expands. In the crowded settlement of Sen'jin Village, resources are perpetually stretched thin. The Darkspear trolls balance the survival of their people against the fragile ecology of their new home, deliberately allowing local tiger populations to thrive until growing needs demand a cull. The thick, hardy furs of the Durotar tigers are carefully cured to produce everyday survival necessities, from basic protective armor to warm blankets that shield the tribe as seasonal weather shifts. Harvesting these pelts requires crossing open water to the Echo Isles, the lush archipelago south of Durotar that the Darkspear once called home before the witch doctor Zalazane drove them out. Alongside the dangers posed by Zalazane's thralls, stalkers among the thick foliage must contend with the patient, predatory nature of the tigers themselves. Experienced troll hunters like Vel'rin Fang speak of spending entire days motionless in the jungle brush just to secure a single clean kill.",
  ["1"] = {
    {file = "Audio/Transport/full_item_durotar-tiger-fur-c6d5593159eb88ae6e21/1-0000.mp3", duration = 73.4302041, start = 0},
  },
}
P.transport["item:duskbat-wing"] = {
  hash = "48a2ca",
  fullHash = "48a2ca",
  text = "Duskbat Wing. A Duskbat Wing is a raw material harvested from the leather-winged bats flitting through the gloom around Deathknell. In the resource-starved Forsaken settlement, these leathery appendages are salvaged and repurposed by local tailors into sturdy makeshift armor for newly risen soldiers. When new undead claw their way from the soil of Deathknell, they emerge bearing little more than rags and brittle bones. Surrounded by the lingering Scourge mindless and hostile wildlife, the fledgling Forsaken must scrape together whatever protective gear they can find. Novice Elreth, assistant to Shadow Priest Sarvis, collects Duskbat Wings alongside wolf paws to piece together and reinforce clothing and armor for freshly raised warriors before they are sent into the wilderness to fight.",
  ["1"] = {
    {file = "Audio/Transport/full_item_duskbat-wing-88bcb22569e7201a4595/1-0000.mp3", duration = 45.2963265, start = 0},
  },
}
P.transport["item:dusky-crab-cakes"] = {
  hash = "35b097",
  fullHash = "35b097",
  text = "Dusky Crab Cakes. Dusky Crab Cakes are a savory dish prepared by Chef Grual in Darkshire to satisfy the desperate hunger of Jitters. The local delicacy has a tangy flavor, and a famished Jitters considers it an exquisite meal.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dusky-crab-cakes-8595910329fd4db3e48e/1-0000.mp3", duration = 12.4342857, start = 0},
  },
}
P.transport["item:dust-devil-debris"] = {
  hash = "e4b6c6",
  fullHash = "e4b6c6",
  text = "Dust Devil Debris. Dust Devil Debris consists of the swirling grit and elemental remnants left behind by the aggressive air spirits wandering Westfall. Mages value these charged particles as magical reagents, using their airy essence to enchant parchment and bind messaging spells into scrolls. The dry plains of Westfall have become increasingly agitated, plagued by violent whirlwinds known as Dust Devils. When struck down, these living storms collapse into a heap of charged dust and grit known as Dust Devil Debris. Rather than being mere dirt, the residue retains a faint trace of the elemental vortex that gave it life. Arcane practitioners like Collin Mauren in Stormwind prize such material for specialized sorcery. By infusing the grit into enchanted ink and parchment, a wizard can bind an airy messaging spell onto a scroll, enabling distant communication across the kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dust-devil-debris-75d91531bb3a9830f72b/1-0000.mp3", duration = 51.8530612, start = 0},
  },
}
P.transport["item:dwarven-tinder"] = {
  hash = "3f3899",
  fullHash = "3f3899",
  text = "Dwarven Tinder. Dwarven Tinder is a specially prepared flammable substance used by Alliance forces in the Wetlands. It was distributed to saboteurs tasked with incinerating the Dragonmaw clan's siege engines before they could be brought against Menethil Harbor. When Alliance scouts discovered that Chieftain Nek'rosh had constructed heavy catapults within the Dragonmaw encampment, Menethil Harbor faced an imminent crisis. Cut off from southern reinforcements by intense fighting in Dun Algaz, the defenders could not survive a prolonged siege. The solution was preemptive sabotage. Provided to volunteers advancing into orcish territory, Dwarven Tinder catches quickly from a struck spark, producing flames intense enough to consume reinforced wooden siege engines in minutes.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dwarven-tinder-8f8ffdcab4a1bad73040/1-0000.mp3", duration = 43.284898, start = 0},
  },
}
P.transport["item:ear-of-balgaras"] = {
  hash = "00ba56",
  fullHash = "00ba56",
  text = "Ear of Balgaras. The Ear of Balgaras serves as grim proof of the death of Balgaras the Foul, a Dark Iron warlock who led the assault on Dun Modr. Recovered from the cowardly commander's corpse, it brings closure to the Ironforge mountaineers defending the northern Wetlands. Dun Modr fell into ruins when Dark Iron invaders sabotaged the Thandol Span and wiped out the local dwarven garrison. Their commander in the field was Balgaras the Foul, a scheming warlock who directed his troops from the shadows while shying away from personal combat. For Longbraid the Grim, the mountain king's officer stationed outside the ruined outpost, justice demanded tangible evidence of the ringleader's fall. Severing Balgaras's ear provides absolute verification that the warlock's reign of terror at the northern border has ended. The loss of Dun Modr cost Longbraid his brother along with dozens of stout soldiers who perished during the collapse of the West Bridge. Presenting the warlock's ear does not mend the shattered span or revive the fallen, but it destabilizes the surviving Dark Iron forces scattered through the northern Wetlands. Without Balgaras to direct them, the remaining raiders become far easier for Ironforge's scouts to contain before another commander is sent from the south.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ear-of-balgaras-a0dd0fd27edbe74e6604/1-0000.mp3", duration = 71.2881633, start = 0},
  },
}
P.transport["item:ebonlocke-s-response-to-solomon"] = {
  hash = "dbdb16",
  fullHash = "dbdb16",
  text = "Ebonlocke's Response to Solomon. Ebonlocke's Response to Solomon is an official letter penned by Lord Ello Ebonlocke, the mayor of Darkshire. Carried back to Lakeshire, it flatly rejects Redridge's desperate plea for military assistance from the Night Watch. Facing blackrock orc incursions, Magistrate Solomon of Lakeshire sought reinforcements from Duskwood after Stormwind ignored his petitions. Lord Ello Ebonlocke's reply is scathing and uncompromising. Ebonlocke points out that the Night Watch exists only because Stormwind abandoned Darkshire when corrupting magic first gripped the woods. Stripping the town of its defenders to aid Redridge would leave Duskwood defenceless, ensuring it fell to evil before the militia even reached the forest's edge.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ebonlocke-s-response-to-solomon-2fe37a922663180aede2/1-0000.mp3", duration = 41.7697959, start = 0},
  },
}
P.transport["item:echeyakee-s-hide"] = {
  hash = "4d7f43",
  fullHash = "4d7f43",
  text = "Echeyakee's Hide. Echeyakee's Hide is the pale pelt taken from the legendary white lion known as Whitemist in the Barrens. Revered by the tauren as an embodiment of mercy and death, the pelt serves as proof of a hunter's prowess for Sergra Darkthorn at the Crossroads. In the Taur-ahe tongue, Echeyakee means Whitemist. The predator earned the title among the savannah lions for his stealthy white coat and the swiftness with which he took down prey, ending their lives before fear or pain could take hold. Claiming the beast's pelt requires summoning the elusive cat near giant kodo bones northeast of the Crossroads with a ceremonial horn. To present this hide to Sergra Darkthorn is not just to prove martial skill, but to honor the predator's silent, merciful end.",
  ["1"] = {
    {file = "Audio/Transport/full_item_echeyakee-s-hide-5bc9de93759ee33f2163/1-0000.mp3", duration = 42.6579592, start = 0},
  },
}
P.transport["item:egalin-s-grimoire"] = {
  hash = "e85f86",
  fullHash = "e85f86",
  text = "Egalin's Grimoire. Egalin's Grimoire is a prized arcane tome detailing the foundational rites required to summon and command a voidwalker. Penned by a master warlock, it serves as an essential teaching text within the Undercity's Temple of the Damned. Written by the master summoner Egalin, this grimoire details the delicate and dangerous process of pulling a being of chaos from the Nether. Egalin was renowned among practitioners for his effortless command over summoned voidwalkers, an ability passed down to his students, including Carendin Halgar. Without the specific formulas and channeling methods recorded in the text, an unprepared summoner risks being torn apart by the very entity they call forth.",
  ["1"] = {
    {file = "Audio/Transport/full_item_egalin-s-grimoire-11800649de7de00c3209/1-0000.mp3", duration = 39.9412245, start = 0},
  },
}
P.transport["item:electropeller"] = {
  hash = "ce7c56",
  fullHash = "ce7c56",
  text = "Electropeller. An electropeller is a specialized mechanical component engineered by the gnome inventor Wizbang Cranktoggle. Intended to power an explosive waterfowl decoy, a full bag of these gadgets was lost across Darkshore's freshwater rivers during an ill-fated nighttime outing. Gnomish engineering requires precision, but the inventors behind it are not always so methodical. Wizbang Cranktoggle, an eccentric gnome operating out of Auberdine, devised the electropeller as a propulsion component for an experimental, self-propelled, exploding duck decoy. While scouting the waterways of Darkshore after having one too many drinks, Cranktoggle blacked out and returned to consciousness hours later with singed hair and an empty pack. His collection of electropellers had tumbled into the freshwater currents, leaving the components scattered throughout Darkshore's rivers and lakes until recovered by patient anglers.",
  ["1"] = {
    {file = "Audio/Transport/full_item_electropeller-9631499d76ab5d384ba7/1-0000.mp3", duration = 53.1069388, start = 0},
  },
}
P.transport["item:elixir-of-pain"] = {
  hash = "82209f",
  fullHash = "82209f",
  text = "Elixir of Pain. The Elixir of Pain is an experimental alchemical concoction brewed by Forsaken apothecaries stationed in Tarren Mill. Distilled using blood harvested across the foothills, the mixture is designed to test biological agents intended to serve Lady Sylvanas's darker ambitions. The Royal Apothecary Society relentlessly pursues new formulas to bolster the Forsaken's position against their mortal neighbors and the Scourge. The Elixir of Pain represents one such trial, blended from freshly harvested ingredients collected around the Hillsbrad Foothills. Concocted with little regard for the living, the potion serves as a proof of concept for volatile substances intended to aid the Dark Lady.",
  ["1"] = {
    {file = "Audio/Transport/full_item_elixir-of-pain-41e63f38099c0b20ea22/1-0000.mp3", duration = 40.2546939, start = 0},
  },
}
P.transport["item:elixir-of-suffering"] = {
  hash = "e202a9",
  fullHash = "e202a9",
  text = "Elixir of Suffering. The Elixir of Suffering is an alchemical concoction brewed by Apothecary Lydon in Tarren Mill. Developed under the orders of the Royal Apothecary Society, the draught is an experimental step toward a virulent plague intended to eradicate both living humans and the Scourge. Within the ruined hamlet of Tarren Mill, Apothecary Lydon tirelessly combines raw reagents gathered from the surrounding wilderness into toxic draughts. The Elixir of Suffering represents an early milestone in the Royal Apothecary Society's overarching mandate: formulating a new plague designed to exterminate the living and dead alike. Lydon tests the lethal brew on his unfortunate assistant, a frog named Umpi, to ensure its potency.",
  ["1"] = {
    {file = "Audio/Transport/full_item_elixir-of-suffering-bc4102db9d7d37f24f24/1-0000.mp3", duration = 42.8146939, start = 0},
  },
}
P.transport["item:elune-s-tear"] = {
  hash = "349d6c",
  fullHash = "349d6c",
  text = "Elune's Tear. Elune's Tear is a rare, luminous mineral found on the central island of Iris Lake in Ashenvale. Revering it as a sacred blessing of the Moon Goddess, night elf herbalists and healers seek the stone for its potent ability to cleanse magical corruption and deadly sickness. Found secluded upon the small islet in Iris Lake east of Astranaar, Elune's Tear is a mystical stone believed to carry the purity of the Moon Goddess herself. The lake itself has not escaped the forest's corruption: its waters have turned a sickly green, and twisted bog beasts roam its shores. The stone is famous among local night elf herbalists and healers—such as Orendil Broadleaf—as an emergency remedy capable of washing away deep-seated corruption when ordinary woodland poultices fail.",
  ["1"] = {
    {file = "Audio/Transport/full_item_elune-s-tear-b96c398a37d54e36322e/1-0000.mp3", duration = 45.6097959, start = 0},
  },
}
P.transport["item:embalming-ichor"] = {
  hash = "9b38c1",
  fullHash = "9b38c1",
  text = "Embalming Ichor. Embalming Ichor is an unnatural preserving fluid harvested from the bodies of Rot Hide gnolls in northern Tirisfal Glades. It sustains the gnolls' animated existence and has drawn the close interest of the Forsaken Apothecaries, who seek to analyze its properties to counter the Scourge. The Rot Hide gnolls infesting Garren's Haunt and the nearby mass graves are not typical wild beasts; they are rotting, preserved thralls deployed by the Scourge to dig up plague victims. Flowing through their decayed veins is Embalming Ichor, a foul fluid that artificially preserves their flesh and grants them enduring unlife. For Magistrate Sevren in Brill, recovering vials of this ichor serves a dual purpose: it confirms the destruction of these graverobbers and provides Royal Apothecary Society researchers with fresh specimens to dissect, study, and weaponize against the Lich King's minions.",
  ["1"] = {
    {file = "Audio/Transport/full_item_embalming-ichor-59a04721cf1faffe0043/1-0000.mp3", duration = 51.6963265, start = 0},
  },
}
P.transport["item:emerald-dreamcatcher"] = {
  hash = "a0bd70",
  fullHash = "a0bd70",
  text = "Emerald Dreamcatcher. The Emerald Dreamcatcher is a sacred night elf amulet crafted to draw subtle vigor from the Emerald Dream. Bestowed upon Tallonkai Swiftroot by the druids of Ban'ethil Barrow Den, it was left behind in Starbreeze Village when the Gnarlpine furbolgs succumbed to corruption and overran the settlement. Crafted under the auspices of Gaerolas Talvethren, the druidic warden of the Ban'ethil Barrow Den, the Emerald Dreamcatcher is an enchanted relic given to only a chosen few. It is designed to siphon ambient energies directly from the Emerald Dream, blessing whoever carries it with fortune and protection. When Starbreeze Village fell to the maddened Gnarlpine furbolg, the amulet was left behind inside a dresser, stranded in the middle of hostile, corrupted territory.",
  ["1"] = {
    {file = "Audio/Transport/full_item_emerald-dreamcatcher-b7df423c027fdfdededd/1-0000.mp3", duration = 45.1395918, start = 0},
  },
}
P.transport["item:empty-blue-waterskin"] = {
  hash = "f519e8",
  fullHash = "f519e8",
  text = "Empty Blue Waterskin. The Empty Blue Waterskin is a ritual vessel given to initiates during the shamanic trials of water. Provided by the hermit Brine in the Barrens, it is carried north into ancient night elf lands to secure a sacred, untainted liquid necessary to fashion the Water Totem. Communing with the spirit of water requires tangible communion with pure, undisturbed sources across Kalimdor. Handed down by the recluse Brine from her hilltop hut in the southern Barrens, the Empty Blue Waterskin represents the final and most perilous gathering task of a shaman's early training. It is destined to hold pristine water taken directly from a secluded fountain deep within the ancient Ruins of Stardust, nestled along the contested borderlands of Ashenvale. Filling this simple container demands that the initiate journey beyond the safety of Horde territory into the ancient groves guarded by nature beasts and night elves. Once dipped into the waters of the ruined sanctuary, the vessel becomes a Filled Blue Waterskin. Combined with samples from the Barrens and Tarren Mill, its contents allow Brine to brew the draught needed to summon and appease the elemental spirit of water.",
  ["1"] = {
    {file = "Audio/Transport/full_item_empty-blue-waterskin-5a67f62fd85a34bb4e5c/1-0000.mp3", duration = 66.0636735, start = 0},
  },
}
P.transport["item:empty-brown-waterskin"] = {
  hash = "ff96ab",
  fullHash = "ff96ab",
  text = "Empty Brown Waterskin. The Empty Brown Waterskin is an elemental vessel provided by Brine during a shaman's trials in the Barrens. Used to gather water from a nearby oasis, it serves as the first physical tool in learning the delicate, contested nature of water in an arid land. In the sun-baked plains of the Barrens, water is far more than a resource; it is life itself and a constant spark for war. The hermit Brine entrusts an initiate with this simple leather skin as the opening trial of the Call of Water. The task seems modest—carry the empty vessel down to the watering hole beneath her dwelling and bring it back full. Yet in drawing from that solitary pool, the bearer immediately confronts the harsh truth of the land: every drop of liquid is jealously guarded by local quilboar who view the oasis as an invaluable hoard, forcing the initiate to understand how water both sustains life and drives mortals to violence.",
  ["1"] = {
    {file = "Audio/Transport/full_item_empty-brown-waterskin-bb11d80c4249e50a0961/1-0000.mp3", duration = 53.2114286, start = 0},
  },
}
P.transport["item:empty-cleansing-bowl"] = {
  hash = "f284b8",
  fullHash = "f284b8",
  text = "Empty Cleansing Bowl. The Empty Cleansing Bowl is a ritual vessel given by Thundris Windweaver to aid in investigating the corruption of the Blackwood furbolgs. When filled at the Auberdine moonwell and combined with food samples, it creates a mixture capable of temporarily breaking a satyr's demonic sway. Entrusted to adventurers by Thundris Windweaver in Auberdine, the Empty Cleansing Bowl is crafted to carry sacred waters from the local moonwell. The night elves discovered that the northern Blackwood furbolgs fell under demonic madness orchestrated by satyrs, who exert their will through enchanted talismans. By drawing pure lunar water into the bowl and blending it with the furbolgs' harvested nuts, grains, and fruits, the vessel produces a blessed meal that temporarily restores sanity to the afflicted creatures, exposing the satyr overseer responsible.",
  ["1"] = {
    {file = "Audio/Transport/full_item_empty-cleansing-bowl-2c25e3a07df865dc8fc8/1-0000.mp3", duration = 47.595102, start = 0},
  },
}
P.transport["item:empty-cliffspring-falls-sampler"] = {
  hash = "7c2155",
  fullHash = "7c2155",
  text = "Empty Cliffspring Falls Sampler. The Empty Cliffspring Falls Sampler is a specialized flask entrusted to novice night elf druids by the Cenarion Circle. It is used to collect a water specimen from the mouth of Cliffspring River cave in Darkshore to help diagnose a foul poison corrupting the local wildlife. Cliffspring Falls provides the principal freshwater source for northern Darkshore, making any disturbance to its headwaters a mortal danger to the local ecosystem. When the native deer population began succumbing to a virulent wasting poison, Dendrite Starblaze of the Cenarion Circle provided these empty samplers to young druids sent out from Moonglade. Druids must venture deep into the cliffs near the falls, right to the entrance of a cave now overrun by hostile naga, to scoop up a viable water sample.",
  ["1"] = {
    {file = "Audio/Transport/full_item_empty-cliffspring-falls-sampler-1f97b58be14a91bc4e50/1-0000.mp3", duration = 45.7665306, start = 0},
  },
}
P.transport["item:empty-dreadmist-peak-sampler"] = {
  hash = "205bf3",
  fullHash = "205bf3",
  text = "Empty Dreadmist Peak Sampler. The Empty Dreadmist Peak Sampler is a specialized Cenarion vessel entrusted to Horde druids to gather tainted water from the summit of Dreadmist Peak. Studying the foul liquid collected in this vial is vital for diagnosing and curing the spreading blight affecting wildlife in the northern Barrens. When a foul affliction began sickening gazelles and destabilizing the fragile ecology of the northern Barrens, druid Dendrite Starblaze suspected that the weather-influencing pools atop Dreadmist Peak were acting as the epicenter. He dispatched druid initiates with empty sampling vessels to brave the mountain's heights—now infested by the demon-worshipping Burning Blade—and extract raw water directly from the pool at the peak.",
  ["1"] = {
    {file = "Audio/Transport/full_item_empty-dreadmist-peak-sampler-6c2c0c437670ffa63d17/1-0000.mp3", duration = 41.8481633, start = 0},
  },
}
P.transport["item:empty-leaden-collection-phial"] = {
  hash = "d9d1ed",
  fullHash = "d9d1ed",
  text = "Empty Leaden Collection Phial. The Empty Leaden Collection Phial is a shielded container designed by gnome tinkerers to harvest radioactive fallout from the ruins of Gnomeregan. Crafted from lead to protect the bearer from lethal contamination, it is used by adventurers assisting Ozzie Togglevolt in Kharanos. Ozzie hopes the captured glow might yield a cure for their afflicted kin—or at least an extraordinarily potent beverage. When the vents of Gnomeregan flooded the subterranean city with toxic radiation to purge the trogg menace, it instead warped the surviving defenders into leper gnomes and irradiated the invading beasts. Seeking to study and reverse the fallout, Ozzie Togglevolt crafted the Empty Leaden Collection Phial. Made of heavy lead to shield handlers from the ambient danger, the specialized vial draws in the noxious green glow lingering on the bodies of Irradiated Invaders and Pillagers that prowl the ruins. Once sealed, the resulting Full Leaden Collection Phial provides the raw, dangerous matter needed for experimental remedies.",
  ["1"] = {
    {file = "Audio/Transport/full_item_empty-leaden-collection-phial-ae60c6acb20c1c40f445/1-0000.mp3", duration = 58.3314286, start = 0},
  },
}
P.transport["item:empty-red-waterskin"] = {
  hash = "9c075f",
  fullHash = "9c075f",
  text = "Empty Red Waterskin. The Empty Red Waterskin is a leather vessel entrusted to fledgling shaman during their elemental trials. It is used to collect fresh, untainted water from a surprising source in the plagued town of Tarren Mill. Given by the hermit Brine in the Barrens, this plain red skin serves a vital spiritual purpose in the Call of Water trials. Initiates are tasked with carrying it far across the sea to the Hillsbrad Foothills, seeking out the town of Tarren Mill. Though the town is occupied by the Forsaken and steeped in undeath, a lone well in its center continues to draw sweet, pristine spring water. Filling the red waterskin captures a vital sample of life persevering amidst blight, which Brine blends into a vial of purest water for the initiate's trial.",
  ["1"] = {
    {file = "Audio/Transport/full_item_empty-red-waterskin-ad6925f6526604c9858b/1-0000.mp3", duration = 43.5461224, start = 0},
  },
}
P.transport["item:empty-sampling-tube"] = {
  hash = "6f15f0",
  fullHash = "6f15f0",
  text = "Empty Sampling Tube. The Empty Sampling Tube is a glass phial provided by Thundris Windweaver in Auberdine. It is intended to collect corrupted water from the Cliffspring River so night elf scholars can study the encroaching taint threatening Darkshore. As the wilderness of Darkshore succumbs to creeping blight, the natural waterways have begun to turn foul. Thundris Windweaver, an investigator stationed in Auberdine, provides this empty glass tube to gather concrete evidence from the Cliffspring River. Drawn from the pool beneath the first waterfall north of town, the resulting sample allows night elf naturalists to examine the nature of the corruption washing toward Mist's Edge.",
  ["1"] = {
    {file = "Audio/Transport/full_item_empty-sampling-tube-0120d8e8c6d5d8e5fafa/1-0000.mp3", duration = 39.0530612, start = 0},
  },
}
P.transport["item:empty-water-tube"] = {
  hash = "b697bc",
  fullHash = "b697bc",
  text = "Empty Water Tube. The Empty Water Tube is a simple glass vessel provided in Auberdine to collect sacred moonwell water. It is meant to carry the blessed liquid up to the strange red crystal perched on the eastern cliffs of Darkshore. Sentinels and scholars studying the mysterious red crystal along Darkshore's eastern ridge require pure lunar essence to test its nature. Because mundane glass or flasks can easily contaminate consecrated water, this sealed vial is specifically entrusted to investigators visiting the moonwell in Auberdine. Once filled, its contents are carried up the mountain slopes to see how the alien mineral responds to Elune's magic.",
  ["1"] = {
    {file = "Audio/Transport/full_item_empty-water-tube-dface78f7fbd2fcae907/1-0000.mp3", duration = 37.0416327, start = 0},
  },
}
P.transport["item:enchanted-gaea-seeds"] = {
  hash = "67c1e1",
  fullHash = "67c1e1",
  text = "Enchanted Gaea Seeds. Enchanted Gaea Seeds are specially prepared botanical seeds meant to bring revitalization to the ravaged landscapes of Kalimdor. Empowered through druidic magic and gathered at Sun Rock Retreat, they are planted directly into the ash-choked soil of the Charred Vale to counteract devastation and rekindle natural growth. The Enchanted Gaea Seeds represent the Horde's druidic efforts to mend the deep scars left across Stonetalon Mountains. After raw Gaea Seeds are gathered and ritually enchanted by Tammra Windfield at Sun Rock Retreat, they carry sufficient resilience to overcome pervasive corruption and elemental blight. When pressed into the fertile dirt mounds that still survive beneath the soot of the Charred Vale, these seeds take root against the harsh conditions, anchoring new life in a landscape dominated by hostile fire elementals and invasive harpies. The goal of planting these enchanted seeds extends beyond simple gardening; it is an active effort to turn the tide in the struggle for Stonetalon's future. The magic woven into the husks allows them to resist lingering corruption and establish a foothold for native flora. As they flourish, the restored vegetation is intended to soothe the agitated fire elementals, crowd out feral harpies, and counter the rampant deforestation driven by the Venture Company's relentless logging operations.",
  ["1"] = {
    {file = "Audio/Transport/full_item_enchanted-gaea-seeds-679315dde92afe103c93/1-0000.mp3", duration = 75.2065306, start = 0},
  },
}
P.transport["item:enchanted-resonite-crystal"] = {
  hash = "704c4b",
  fullHash = "704c4b",
  text = "Enchanted Resonite Crystal. The Enchanted Resonite Crystal is an alchemically altered mineral infused with shamanic magic by Mor'rogal in the Stonetalon Mountains. It is crafted specifically to shatter the Resonite cask binding a slumbering, ancient Earthen named Goggeroc. Raw resonite crystals gathered from the deep caverns of the Stonetalon Mountains possess unusual harmonic and earthen properties. Recognizing the danger slumbering within a sealed subterranean cask, the shaman Mor'rogal altered the raw minerals using his elemental powers. The resulting Enchanted Resonite Crystal serves as a precise tool: when struck against the reinforced Resonite cask, it disrupts the housing and forcibly rouses the giant Earthen Goggeroc while he is still disoriented from his long sleep.",
  ["1"] = {
    {file = "Audio/Transport/full_item_enchanted-resonite-crystal-b514281315e5f6fc3017/1-0000.mp3", duration = 43.7028571, start = 0},
  },
}
P.transport["item:encrypted-memorandum"] = {
  hash = "e5aafe",
  fullHash = "e5aafe",
  text = "Encrypted Memorandum. The Encrypted Memorandum is a coded missive handed to novice rogues starting out in Coldridge Valley. Though disguised as official communication, it is actually a clandestine invitation from the local rogue trainer, Solm Hargrin, calling for solidarity among scoundrels in exile. In the bustling dwarven refuge of Anvilmar, rogues must maintain a low profile. Rather than approaching recruits in plain view, the trainer Solm Hargrin uses the Encrypted Memorandum to establish contact. Masked as an official directive from distant superiors, the coded parchment ensures that fledgling rogues know where to find mentorship without drawing unwanted attention from the local guards or suspicious townsfolk.",
  ["1"] = {
    {file = "Audio/Transport/full_item_encrypted-memorandum-b04b8b2f462a77715835/1-0000.mp3", duration = 41.4563265, start = 0},
  },
}
P.transport["item:encrypted-parchment"] = {
  hash = "c9a170",
  fullHash = "c9a170",
  text = "Encrypted Parchment. The Encrypted Parchment is a ciphered missive delivered to aspiring orc rogues training in the Valley of Trials. Handed over by Gornek, it discreetly directs promising recruits into the shadows of the Den to meet the covert trainer Rwag. Young orcs seeking to prove their martial prowess in the Valley of Trials typically fight out in the open sun. However, those showing an aptitude for stealth, deception, and bladecraft draw a very different kind of attention. The Encrypted Parchment is handed to promising orc rogues by Gornek once they have cut their teeth against the local wildlife. Rather than an open announcement, the message is coded to ensure that only someone with an eye for subterfuge heeds the call. Deciphering the parchment directs the novice deep into the cave known as the Den, past the watchful eye of other clan trainers to find Rwag. There, the recruit learns that the summons was arranged on behalf of the Shattered Hand—an order operating within the Horde's covert network. By answering the parchment, the rogue takes their first step into a world of espionage, shadowcraft, and guarded secrets.",
  ["1"] = {
    {file = "Audio/Transport/full_item_encrypted-parchment-558b6b930eb19c6556d4/1-0000.mp3", duration = 61.3616327, start = 0},
  },
}
P.transport["item:encrypted-rune"] = {
  hash = "3e0032",
  fullHash = "3e0032",
  text = "Encrypted Rune. An Encrypted Rune is a coded summoning message handed to promising new rogues in Coldridge Valley. Delivered covertly, it bids the bearer to decipher its contents and seek out the rogue trainer Solm Hargrin inside Anvilmar. In the sheltered snowy basin of Coldridge Valley, overt recruitment is rarely the style of the local scoundrels and scouts. Instead, novitiates showing a knack for stealth and cunning are slipped an Encrypted Rune. Marked with subtle ciphers, the inscribed stone carries a discreet invitation from Solm Hargrin, the rogue mentor quartered in Anvilmar. It serves as both a private test of literacy in thieves' cant and an introduction to the shadowy craft needed to survive Dun Morogh's harsh wilderness. Deciphering the rune directs new rogues to Solm, who looks to bolster the valley's covert ranks amidst rising local tensions. Beyond basic bladecraft and stealth techniques, Solm emphasizes vigilance and camaraderie, reminding incoming rogues that in this time of strained peace it is all the more important for their kind to stick together.",
  ["1"] = {
    {file = "Audio/Transport/full_item_encrypted-rune-78d6c05fd0f649c71f0b/1-0000.mp3", duration = 64.7053061, start = 0},
  },
}
P.transport["item:encrypted-scroll"] = {
  hash = "3b94b8",
  fullHash = "3b94b8",
  text = "Encrypted Scroll. The Encrypted Scroll is a discreet parchment delivered to promising newly risen rogues in Deathknell. Bearing the seal of David Trias, it directs the recipient to introduce themselves for formal training among the Forsaken's covert operatives. When a freshly awakened Forsaken shows an aptitude for stealth and subterfuge, they do not remain unnoticed for long. The Encrypted Scroll is handed over in Deathknell once a scout proves capable against the mindless Scourge roaming the nearby graveyard. Bearing the personal seal of the rogue trainer David Trias, the scroll instructs the bearer to seek him out in the local inn. It serves as an initial vetting process, pointing fledgling operatives toward the discipline required to serve the Dark Lady rather than wasting their second chance at life as mere pickpockets. The message itself is brief, directing the rogue to establish contact within Deathknell before venturing deeper into Tirisfal Glades. Trias keeps tabs on up-and-coming talent on behalf of the Shadowstalkers, the covert arm of the Forsaken. To survive in Lordaeron, the Forsaken rely heavily on silent blades and cunning scouts to counter the Scarlet Crusade, surviving Alliance enclaves, and leftover Scourge filth. Answering this ciphered summons is the first step toward joining that covert network.",
  ["1"] = {
    {file = "Audio/Transport/full_item_encrypted-scroll-4766287a2dc4bcb59b54/1-0000.mp3", duration = 76.0685714, start = 0},
  },
}
P.transport["item:encrypted-sigil"] = {
  hash = "23f28e",
  fullHash = "23f28e",
  text = "Encrypted Sigil. The Encrypted Sigil is a coded token delivered to newly awakened night elf rogues in Shadowglen. Bearing hidden instructions from the trainer Frahun Shadewhisper, it directs fledgling operatives to initiate their training amidst growing threats to Teldrassil. Within the sheltered hollow of Shadowglen, emerging night elf scouts and infiltrators are contacted through discreet means. The Encrypted Sigil is passed directly into an initiate's hands by a quiet messenger on behalf of Frahun Shadewhisper. Concealing its contents in a manner fitting the profession, the sigil instructs the recipient to report to Frahun near Aldrassil. To Shadewhisper, reading and delivering the token proves an initiate can follow subtle directives and handle covert missives. Frahun uses the summons to stress the necessity of rogues in an unsettled world. With tensions simmering between the night elves and the distant Horde, Shadewhisper reminds his recruits that open warfare is not the only peril facing their people. Rogues must serve as the early eyes and unseen blades of the Kaldorei, gathering intelligence across Teldrassil and learning to strike before threats can take root in the boughs of the World Tree.",
  ["1"] = {
    {file = "Audio/Transport/full_item_encrypted-sigil-8efe0195b421cf67c777/1-0000.mp3", duration = 67.9183673, start = 0},
  },
}
P.transport["item:encrypted-tablet"] = {
  hash = "8d4fc9",
  fullHash = "8d4fc9",
  text = "Encrypted Tablet. The Encrypted Tablet is a coded message delivered to novice Darkspear troll rogues training in the Valley of Trials. Inscribed by the rogue trainer Rwag, it summons promising cutpurses and scouts to his post inside the Den. Novice troll rogues arriving in the Valley of Trials are handed the Encrypted Tablet as their initial directive. Inscribed with ciphered instructions, the slate directs them directly to Rwag, an orc trainer residing within the shaded caves of the Den. Rather than openly broadcasting guild business, the local shadow operatives use these encrypted slates to test comprehension and discreetly draw new talent under official tutelage. Deciphering the tablet introduces recruits to the larger shadow network of the Horde. Upon reporting to Rwag, scouts learn that their progression is scrutinized by shadowy syndicates like the Shattered Hand, who look to valley trainers to ensure prospective cutpurses, spies, and assassins are sharp enough to serve the new nation.",
  ["1"] = {
    {file = "Audio/Transport/full_item_encrypted-tablet-518270fbedfae881bdb1/1-0000.mp3", duration = 55.9020408, start = 0},
  },
}
P.transport["item:essence-of-nightlash"] = {
  hash = "2390df",
  fullHash = "2390df",
  text = "Essence of Nightlash. The Essence of Nightlash is the lingering magical remnant collected from the defeated banshee Nightlash at the Dead Fields. It serves as irrefutable proof for High Executor Hadrec that the Scourge force bolstering the local rot hide gnolls has been broken. At an abandoned farmstead in northern Silverpine known as the Dead Fields, packs of undead rot hide gnolls have entrenched themselves under Scourge command. Initial Forsaken assaults were repeatedly broken not by the feral gnolls, but by their spectral commander: the banshee Nightlash. Calling upon wailing magics, she reinforced the gnoll lines and routed the forces sent from the Sepulcher. Slaying her dissolves her incorporeal form into dust, leaving behind a crystalline, magical essence that represents her permanent dissolution. Because banshees leave behind no corporeal corpse, the Essence of Nightlash is the only physical evidence that the malevolent spirit has been destroyed. High Executor Hadrec at the Sepulcher requires this essence to verify that the Scourge's local foothold has collapsed, allowing the Forsaken to finally secure their northern perimeter and suppress the rot hide threat.",
  ["1"] = {
    {file = "Audio/Transport/full_item_essence-of-nightlash-009275edd0e13ce35c6a/1-0000.mp3", duration = 67.0302041, start = 0},
  },
}
P.transport["item:essential-artificial"] = {
  hash = "875087",
  fullHash = "875087",
  text = "Essential Artificial. An Essential Artificial is a versatile, standardized mechanical component vital to gnomish tinkers and engineers. Left behind in stockpiles during the frantic evacuation of Gnomeregan, these parts are highly sought after by gnomes seeking to rebuild their technological efforts from exile in Ironforge. Before the fall of Gnomeregan, the essential artificial served as a cornerstone of day-to-day gnomish engineering. Described by tinkers as a nigh-universal component, it was integrated into countless contraptions, clockwork wonders, and heavy machinery throughout the subterranean halls. Its standardized nature made it indispensable to smiths and machinists seeking reliable, interchangeable modular parts. When the trogg invasion and subsequent radiation disaster forced the gnomes into a desperate, panicked exodus, massive reserves of these components were abandoned where they sat. They remain stored inside heavy, steam-powered dispensers known as artificial extrapolators scattered across the deeper passages of Gnomeregan. In Tinker Town, master craftsman Klockmort Spannerspan actively recruits daring adventurers to venture back into the contaminated ruins and salvage these parts so research and invention can continue.",
  ["1"] = {
    {file = "Audio/Transport/full_item_essential-artificial-bf9cedfa122f9fc72268/1-0000.mp3", duration = 70.635102, start = 0},
  },
}
P.transport["item:etched-note"] = {
  hash = "da3fa3",
  fullHash = "da3fa3",
  text = "Etched Note. The Etched Note is a formal summons delivered to promising young tauren hunters resting at Camp Narache. Penned by the camp's hunter trainer, Lanka Farshot, the message welcomes the novice into the traditions of the hunt and calls them forward for their initial instruction. Within the safe confines of Camp Narache, young shu'halo are recognized early for their natural inclinations and family lineages. The Etched Note is delivered by a runner on behalf of Lanka Farshot, the resident hunter mentor. It names the hunter as the heart of the tribe while serving as a stern reminder that raw instinct must be tempered through rigorous instruction and a deep reverence for the wilderness of Mulgore. For the tauren, hunting is far more than a practical method of survival—it is an honored, sacred discipline woven into tribal society. The note reminds the reader that hunters blend the roles of warriors, shamans and druids, and that the tribe will look to them for guidance and protection. By presenting the letter to Lanka, the student takes their first official steps into learning weaponcraft, understanding beasts, and fulfilling their duty to defend and sustain the tribes.",
  ["1"] = {
    {file = "Audio/Transport/full_item_etched-note-ac16a61bb89bc0ef908c/1-0000.mp3", duration = 65.5934694, start = 0},
  },
}
P.transport["item:etched-parchment"] = {
  hash = "f2d927",
  fullHash = "f2d927",
  text = "Etched Parchment. The Etched Parchment is a written summons delivered to novice hunters training within Durotar's Valley of Trials. Handed over by Gornek, it directs aspiring wilderness stalkers to seek instruction from the troll trainer Jen'shan. Young orcs and Darkspear trolls seeking their place among the Horde begin their rites in the arid basin of the Valley of Trials. While they prove themselves against the local vermin, Gornek serves as a watchful overseer who guides recruits toward their calling. For those destined to wield bow, gun, and fang, Gornek passes along this etched parchment. It bears a direct message from Jen'shan, a skilled hunter trainer seeking fresh eyes and steady hands. Carrying the parchment to Jen'shan marks the true beginning of a hunter's training in Durotar. Jen'shan emphasizes that walking the wild path is no easy task, requiring just as much dedication to master the beasts of the desert as an arcanist devotes to magic or a shaman gives to the spirits. Reading the parchment and answering her call introduces novitiates to proper marksmanship and wilderness survival.",
  ["1"] = {
    {file = "Audio/Transport/full_item_etched-parchment-c25e5a4aaa1cfe8a62f2/1-0000.mp3", duration = 60.9436735, start = 0},
  },
}
P.transport["item:etched-rune"] = {
  hash = "459be0",
  fullHash = "459be0",
  text = "Etched Rune. The Etched Rune is a carved stone tablet given to aspiring dwarven hunters in Coldridge Valley. It serves as an invitation from the hunter trainer Thorgas Grimson, directing fledglings to seek him out within Anvilmar to begin their formal wilderness instruction. Carved with specific dwarven runes, this small stone tablet is passed along to novices who demonstrate potential out in the snowdrifts of Coldridge Valley. Sent by the mountaineer and hunter trainer Thorgas Grimson, the rune encourages fledgling trackers to pause their outdoor tasks and report to Anvilmar. Reading the stone marks a hunter's first step away from basic survival and toward understanding the deeper craft of the wild—learning to respect the beasts of Dun Morogh, track mountain predators, care for ranged weaponry, and endure the brutal elements.",
  ["1"] = {
    {file = "Audio/Transport/full_item_etched-rune-91db06c52e81d9839f6a/1-0000.mp3", duration = 45.5314286, start = 0},
  },
}
P.transport["item:etched-sigil"] = {
  hash = "7b7c92",
  fullHash = "7b7c92",
  text = "Etched Sigil. An inscribed token delivered to aspiring night elf hunters awakening in Shadowglen. Carried by a woodland runner, it bears a summons from the hunter trainer Ayanna Everstride atop the great bough of Aldrassil. Carved with the marks of the hunt, the Etched Sigil is handed to newly awakened night elf hunters as they step into Shadowglen. The token serves as an official notice and welcome from Ayanna Everstride, the local hunter trainer residing high within the hollowed boughs of Aldrassil. Instructing the novice to seek her out, the sigil begins a lifelong tutelage in archery, wilderness tracking, and the ancient night elven bond between stalker and beast.",
  ["1"] = {
    {file = "Audio/Transport/full_item_etched-sigil-4a2a30c78effd470585f/1-0000.mp3", duration = 39.2097959, start = 0},
  },
}
P.transport["item:explosive-stick-of-gann"] = {
  hash = "f26044",
  fullHash = "f26044",
  text = "Explosive Stick of Gann. The Explosive Stick of Gann is a customized blasting charge assembled by Gann Stonespire using stolen dwarven schematics. It was designed specifically to sabotage the dwarven flying machine stationed at Bael Modan in the southern Barrens. When the dwarven Prospector Khazgorm led the Ironforge excavation into southern Kalimdor, the dwarves drove the Stonespire tauren from their ancestral village and razed their sacred grounds to build the fortress-dig of Bael Modan. Driven by vengeance and a desire to honor his displaced and fallen kin, Gann Stonespire reclaimed Khazgorm's blueprints to turn dwarven engineering against the invaders. By studying the recovered plans, Gann assembled this specialized charge with enough concussive force to wreck heavy machinery.",
  ["1"] = {
    {file = "Audio/Transport/full_item_explosive-stick-of-gann-e8fda2dee83370f60303/1-0000.mp3", duration = 43.2065306, start = 0},
  },
}
P.transport["item:faded-shadowhide-pendant"] = {
  hash = "4431be",
  fullHash = "4431be",
  text = "Faded Shadowhide Pendant. A tarnished talisman once worn by the Shadowhide gnolls of Redridge, enchanted to serve as a conduit for dark orders. To the astonishment of whoever holds it, the pendant also carries a delayed magical message cast by the wizard Theocritus. The Shadowhide gnolls roaming the Redridge Mountains answer to a sinister master named Morganth, coordinating their movements through enchanted pendants. While investigating these talismans from his sanctuary at Tower Azora, the High Mage Theocritus devised an experimental spell to breach their mystical frequency. Though his magical broadcast took weeks to manifest, this faded pendant proved that the gnolls' communication line can be hijacked, opening a path to disrupt their dark master's reach.",
  ["1"] = {
    {file = "Audio/Transport/full_item_faded-shadowhide-pendant-a4f099b11675645f7d3a/1-0000.mp3", duration = 41.6130612, start = 0},
  },
}
P.transport["item:fallen-moonstone"] = {
  hash = "a3c018",
  fullHash = "a3c018",
  text = "Fallen Moonstone. A Fallen Moonstone is a luminous, magically charged stone gathered from the tranquil waters of Fallen Sky Lake in Ashenvale. Imbued with sacred lunar energy, these stones possess potent restorative properties capable of renewing vitality and curing severe frailty. Fallen Moonstones were once gathered in abundance along the shores and shallows of Fallen Sky Lake, southeast of Astranaar. Highly treasured by the night elves for their restorative magic and lunar blessing, they were often sought out to aid in recovery when ordinary remedies proved insufficient. However, harvesting them became treacherous when corrupt Shadethicket bog beasts overran the lake. Their leader, a Shadethicket Oracle, hoarded every stone it could find on a small central island, cutting off the local Kaldorei from a vital source of healing.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fallen-moonstone-ee66e73ed5b57a0de0d3/1-0000.mp3", duration = 46.4195918, start = 0},
  },
}
P.transport["item:fandral-s-message"] = {
  hash = "d80a79",
  fullHash = "d80a79",
  text = "Fandral's Message. Fandral's Message is a missive penned by Arch Druid Fandral Staghelm in Darnassus. It is entrusted to an adventurer to carry across the sea to the Ancient of Lore, Onu, in Darkshore. Written by Arch Druid Fandral Staghelm in the Cenarion Enclave, this sealed dispatch serves as direct correspondence between the acting leader of the night elven druids and Onu, the venerable Ancient of Lore dwelling within the Grove of the Ancients. After receiving reports regarding the state of Teldrassil's Oracle Glade, Staghelm wastes no time pressing couriers into service to send word south of Auberdine. The delivery requires travelers to journey across the waters to Darkshore, bridging the heart of the new World Tree with the older, shadowed mainland.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fandral-s-message-9d7ad3eb06bc29f12e55/1-0000.mp3", duration = 43.7812245, start = 0},
  },
}
P.transport["item:fang-of-vagash"] = {
  hash = "7d9718",
  fullHash = "7d9718",
  text = "Fang of Vagash. The Fang of Vagash is a massive predator tooth taken from the notorious beast Vagash in the snowy crags of Dun Morogh. It serves as tangible proof for local breeders that the marauding monster threatening their prized rams has finally been slain. Dun Morogh's high crags are home to bitter cold and ferocious predators, but none have plagued the local ranches quite like Vagash. Looming in the ridges above the Amberstill Ranch, this savage beast frequently stalks downhill under cover of darkness to slaughter prized rams. With Ironforge's troops already stretched thin, the local herdsmen cannot count on the city guard for protection. Slaying the beast and carving away one of its vicious fangs offers indisputable evidence that the pasturelands are safe once more.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fang-of-vagash-ba17f116d9d08979fc32/1-0000.mp3", duration = 44.7477551, start = 0},
  },
}
P.transport["item:fangore-s-paw"] = {
  hash = "324c18",
  fullHash = "324c18",
  text = "Fangore's Paw. Fangore's Paw is the severed hand of Lieutenant Fangore, a commanding officer among the Shadowhide gnolls in the Redridge Mountains. It serves as gruesome proof of the gnoll chieftain's demise for Magistrate Solomon in Lakeshire. The grim bounty was placed to dismantle the warlord's threat against the besieged township. Lieutenant Fangore acts as a primary field commander for the Shadowhide gnolls encroaching across the Redridge Mountains. Operating in direct service to the renegade mage Morganth, Fangore directs violent assaults against trade roads, outlying farms, and the defenses around Lake Everstill. Because gnoll raiders do not leave traditional uniforms, official seals, or banners to confirm their casualties, the township authorities rely on grim physical evidence. Magistrate Solomon specifically demanded Fangore's paw as unmistakable proof of his execution, allowing the town of Lakeshire to breathe slightly easier amid mounting surrounding perils.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fangore-s-paw-9c36b247ef632dcbd2cc/1-0000.mp3", duration = 54.8832653, start = 0},
  },
}
P.transport["item:farren-s-report"] = {
  hash = "f7a200",
  fullHash = "f7a200",
  text = "Farren's Report. Farren's Report is an official dispatch drafted by Lieutenant Farren Orinelle in Southshore detailing his investigations into the local naga. Farren uses this document to appeal to his former mentor, Major Samuelson in Stormwind Keep, hoping to secure a reassignment back to the capital. Stationed on the embattled coast of Hillsbrad Foothills, Lieutenant Farren Orinelle grew weary of local leadership and the remote frontier. After tasking adventurers with hunting the Daggerspine naga to gather proof of their threat, Orinelle compiled his findings into a formal report. Rather than submitting it to his commanding officer, Marshal Redpath, Farren aimed to send it directly to Major Samuelson, the captain of the guard in Stormwind Keep. Having trained under Samuelson, Farren hoped the document would demonstrate his competence and justify an immediate transfer back to the comforts of Stormwind City.",
  ["1"] = {
    {file = "Audio/Transport/full_item_farren-s-report-ad90f495bec63ec64502/1-0000.mp3", duration = 50.964898, start = 0},
  },
}
P.transport["item:fathom-core"] = {
  hash = "8d122a",
  fullHash = "8d122a",
  text = "Fathom Core. The Fathom Core is a specialized relic recovered from a submerged fathom stone in the depths of Blackfathom Deeps. When deciphered, it provides a comprehensive record of elemental activity in the surrounding region. The Earthen Ring seeks this artifact to discern what dark rituals the Twilight's Hammer cult is conducting beneath Ashenvale. Resting within an ancient fathom stone submerged among the Moonshrine Ruins, the Fathom Core serves as a historical record for elemental phenomena. It registers and preserves shifts, disruptions, and surges in the elements over time. For the shaman of the Earthen Ring stationed at Zoram'gar Outpost, acquiring the core is essential for understanding how the Twilight's Hammer cultists are manipulating the regional elements to serve their own ends.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fathom-core-0c7773affb683d9236b7/1-0000.mp3", duration = 43.7028571, start = 0},
  },
}
P.transport["item:feather-charm"] = {
  hash = "b4c3d1",
  fullHash = "b4c3d1",
  text = "Feather Charm. Feather Charms are crude magical trinkets carried by Frostmane troll novices in the snow-swept valleys of Coldridge Valley. Though fashioned from simple materials, they harbor an innate sorcerous resonance that catches the eye of local warlock mentors. The Frostmane trolls inhabiting the snowy caverns southwest of Anvilmar are known mostly for territorial savagery, but their novices dabble in primitive spellcraft. The feather charms carried by these young trolls hold a faint yet unmistakable magical power. In Anvilmar, warlock instructor Alamar Grimm considers them an intriguing subject of study—surprising for crude trollcraft—and uses them as a proving ground for fledgling warlocks seeking to master the binding of their first imp.",
  ["1"] = {
    {file = "Audio/Transport/full_item_feather-charm-7699607fb51deb6c30ad/1-0000.mp3", duration = 42.3967347, start = 0},
  },
}
P.transport["item:fel-cone"] = {
  hash = "26d3ad",
  fullHash = "26d3ad",
  text = "Fel Cone. Fel Cones are corrupted seed pods that drop from the boughs of Teldrassil, easily spotted by the noxious green fumes drifting from their hulls. Though foul and tainted by dark energies, local night elf defenders find clever uses for them against nearby tricksters. Teldrassil is young, but corruption has already seeped into its living wood. Fel Cones are the visible evidence of this insidious rot—gnarled, fallen pine cones that billow with foul green smoke. Scattered beneath the boughs just east of Dolanaar, these pods are steeped in tainted magic that warps natural flora and makes them dangerous to touch or consume without caution.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fel-cone-b6407a804b488a71fa68/1-0000.mp3", duration = 38.2693878, start = 0},
  },
}
P.transport["item:fel-moss"] = {
  hash = "274e79",
  fullHash = "274e79",
  text = "Fel Moss. Fel Moss is a tainted vegetative substance spreading through the forests of Teldrassil. Carrying demonic and corruptive energies, it is carried by hostile grell and grellkin and poses an insidious threat to the wildlife and native furbolg tribes of the World Tree. Teldrassil was planted to restore the night elves' immortality and heal the natural world, but corruption has already crept into its pristine boughs. Fel Moss is one of the most visible signs of this degradation. Found clinging to and carried by the impish grells and grellkin infesting Shadowglen, this malevolent growth radiates an unnatural, wicked magic. Forest protectors like the dryad Tarindrella have begun gathering samples to measure just how deeply this rot has infiltrated the sacred woodland canopy.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fel-moss-26755ec416a69370a7ee/1-0000.mp3", duration = 44.7216327, start = 0},
  },
}
P.transport["item:felix-s-box"] = {
  hash = "9b9c44",
  fullHash = "9b9c44",
  text = "Felix's Box. Felix's Box is a small container of personal belongings belonging to Felix Whindlebolt, a refugee who fled the fall of Gnomeregan. Lost during the frantic evacuation into Dun Morogh, the box was looted by local Frostmane trolls and carried off to their camps southwest of Anvilmar. When radiation flooded Gnomeregan during the failed attempt to purge the trogg menace, Felix Whindlebolt joined the frantic exodus of gnomes into Coldridge Valley. In his desperation to escape the radioactive fumes, Felix dropped his most prized personal possessions and crafting gear along the snowy road. Before he could recover them, indigenous Frostmane trolls plundered the roadside remnants and dragged his box, along with his chest and bucket of bolts, back to their crude settlements southwest of Anvilmar. Unaccustomed to physical violence and ill-suited for the harsh wilderness of Dun Morogh, Felix was forced to seek the help of passing adventurers in Anvilmar to recover his belongings. Retrieving Felix's Box represents more than just returning a modest container; it restores a piece of normalcy and livelihood to a displaced artisan who lost everything in the catastrophe that consumed his underground homeland.",
  ["1"] = {
    {file = "Audio/Transport/full_item_felix-s-box-0ace3d7c53bbce7d5f2d/1-0000.mp3", duration = 67.4220408, start = 0},
  },
}
P.transport["item:felix-s-bucket-of-bolts"] = {
  hash = "1ad22a",
  fullHash = "1ad22a",
  text = "Felix's Bucket of Bolts. Felix's Bucket of Bolts is a container of spare hardware and tools owned by Felix Whindlebolt, a gnome refugee who fled the fall of Gnomeregan. During his escape into Dun Morogh, the bucket was snatched by local Frostmane trolls and dragged into their nearby camps. When radiation flooded Gnomeregan following the disaster against the troggs, thousands of gnomes fled into the freezing wilds of Dun Morogh with whatever they could carry. Felix Whindlebolt managed to escape with his vital equipment, but in the chaos of his flight toward Anvilmar, he was ambushed by the Frostmane trolls who inhabit the crags southwest of town. The trolls plundered his belongings, including this bucket full of bolts and parts, leaving the artisan stranded without the essential materials needed to ply his craft in exile.",
  ["1"] = {
    {file = "Audio/Transport/full_item_felix-s-bucket-of-bolts-584829507ac78b7d11a0/1-0000.mp3", duration = 46.6546939, start = 0},
  },
}
P.transport["item:felix-s-chest"] = {
  hash = "d0ca90",
  fullHash = "d0ca90",
  text = "Felix's Chest. Felix's Chest is a container of personal belongings lost by the exiled gnome Felix Whindlebolt during the flight from Gnomeregan. Carried away by Frostmane trolls lurking near Coldridge Valley, it sits abandoned within one of their primitive mountain camps. When the subterranean techno-city of Gnomeregan fell to trogg incursions and toxic radioactive fallout, thousands of gnomes fled toward the snowy surface of Dun Morogh with whatever possessions they could carry. Felix Whindlebolt managed to escape the irradiated ruins, but amidst the panic of the evacuation, native Frostmane trolls scavenged the roads and overtook the scattered survivors. Felix lost his primary toolkits and belongings, with his sturdy chest hauled off to the crude camps the trolls maintain in the crags southwest of Anvilmar.",
  ["1"] = {
    {file = "Audio/Transport/full_item_felix-s-chest-cae538d6e57b49762054/1-0000.mp3", duration = 46.1844898, start = 0},
  },
}
P.transport["item:felstalker-hoof"] = {
  hash = "82f758",
  fullHash = "82f758",
  text = "Felstalker Hoof. A Felstalker Hoof is a physical token taken from demonic beasts infesting the Burning Blade Coven in Durotar's Valley of Trials. Young shaman must retrieve these hooves as a trial of readiness before learning to commune with the elemental spirits of the earth. Within the sun-baked Valley of Trials, the trainer Canaga Earthcaller tasks budding shaman with facing the demonic taint threatening Durotar. The Burning Blade Coven to the north harbors vile familiars and demonic felstalkers. Taking the hooves of these fiends is not merely an act of culling pests, but a rigorous test of endurance, resolve, and spirit. Only by subduing these chaotic beasts can an aspiring shaman prove worthy of receiving the secrets of the earth and preparing the ceremonial sapta needed to commune directly with elemental spirits.",
  ["1"] = {
    {file = "Audio/Transport/full_item_felstalker-hoof-47650eab0a4ea3ac4ec4/1-0000.mp3", duration = 46.1844898, start = 0},
  },
}
P.transport["item:fenwick-s-head"] = {
  hash = "e988e1",
  fullHash = "e988e1",
  text = "Fenwick's Head. Fenwick's Head is the grisly proof of execution taken from Fenwick Thatros on the shores of Lordamere Lake. It is claimed by Forsaken rogues operating on direct orders passed down through Lord Varimathras. Within the Rogues' Quarter of the Undercity, Mennet Carkad acts on urgent intelligence routed directly from dreadlord Varimathras. A hostile undead leader named Fenwick Thatros has established a foothold near the decaying docks along Lordamere Lake in Silverpine Forest. To prevent this threat from rallying hostile undead against the Forsaken, Carkad dispatches promising Deathstalkers to locate Thatros, eliminate him, and sever his head as undeniable proof of the kill. Returning Fenwick's Head to Carkad is more than a simple bounty collection; it serves as a crucial trial for Deathstalker operatives. Presenting the severed trophy validates the rogue's competence in infiltration and assassination, opening the door to deeper, more specialized instruction in the shadow arts from the Forsaken masters.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fenwick-s-head-3cc32980999cf7d8cb8a/1-0000.mp3", duration = 58.9583673, start = 0},
  },
}
P.transport["item:fey-dragon-scale"] = {
  hash = "2a5e7f",
  fullHash = "2a5e7f",
  text = "Fey Dragon Scale. A Fey Dragon Scale is a shimmering woodland relic harvested from the elusive faerie dragons living around Stonetalon Peak. It is sought after by the Darkspear witch doctor Jin'Zil, who uses it as an exotic reagent in an alchemical brew mocking night elven nature magic. Faerie dragons are mysterious, elusive creatures tied closely to the wild groves of Kalimdor, particularly the untouched forests around Stonetalon Peak. Their scales carry a natural magical luster reminiscent of the deep woods they guard. While revered by the night elves as harmless woodland spirits and allies, outsiders view them as an untamed source of rare magical ingredients.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fey-dragon-scale-6a0e978b2a87ac2c80db/1-0000.mp3", duration = 39.3665306, start = 0},
  },
}
P.transport["item:filled-amethyst-phial"] = {
  hash = "1ca9f3",
  fullHash = "1ca9f3",
  text = "Filled Amethyst Phial. The Filled Amethyst Phial contains sacred water taken from the ancient moonwell beneath the boughs of the Oracle Tree. Gathered on behalf of Corithras Moonrage, this purified water is used by the Cenarion druids to study the troubled, imperfect growth of Teldrassil. Far to the northwest in Teldrassil lies the Oracle Glade, where the oldest and most potent of the island's moonwells rests beneath the great Oracle Tree. While the lesser moonwells across the boughs serve the day-to-day needs of the night elves, this well's waters are saturated with the raw essence of Elune's grace. Druids tasked with monitoring the health of the World Tree use specialized amethyst phials to collect and preserve this powerful liquid for testing and ritual cleansing.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-amethyst-phial-6c01d4c821654970f204/1-0000.mp3", duration = 40.4897959, start = 0},
  },
}
P.transport["item:filled-blue-waterskin"] = {
  hash = "ed83de",
  fullHash = "ed83de",
  text = "Filled Blue Waterskin. The Filled Blue Waterskin holds pristine water gathered from a fountain at the ancient Ruins of Stardust in Ashenvale. Shaman seeking communion with the water spirits collect this sample as a vital reagent for their trial of passage. Initiates undertaking the Call of Water are directed northward across the border from the Barrens into the dense forests of Ashenvale. Nestled against the mountains dividing Ashenvale from Stonetalon, beyond Lake Mystral, lie the Ruins of Stardust—a secluded elven sanctuary guarded by fierce forest beasts. At the center of this sacred lake stands an untouched fountain. Drawing from its basin into a blue waterskin yields water untainted by corruption or drought, prized by shaman masters for ritual attunement. The water collected within this vessel serves as the final sample required by Brine, a hermit water expert dwelling on a hill in the southern Barrens. Combined with waters gathered from other contrasting wells and springs, this pure essence is distilled into an offering potent enough to manifest and soothe the elemental spirits of water, completing the initiate's trial.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-blue-waterskin-ef94670eb0f112411293/1-0000.mp3", duration = 66.4032653, start = 0},
  },
}
P.transport["item:filled-brown-waterskin"] = {
  hash = "0fbff8",
  fullHash = "0fbff8",
  text = "Filled Brown Waterskin. The Filled Brown Waterskin contains fresh water drawn from a rare pond near Brine's hut in the Barrens. Collected by aspiring shaman, it forms the first fundamental step in brewing the sapta needed to commune with the spirits of water. In the parched expanse of the Barrens, surface water is both a blessing and a battleground. The pond nestled beneath Brine's hut offers precious hydration that draws the desperate and defensive quilboar who dwell nearby. For an initiate walking the path of the shaman, filling this simple leather waterskin is not merely an errand of gathering supplies; it is an elemental lesson. By approaching the pool and witnessing the fierce territorial struggle surrounding it, the novice observes firsthand how the very substance that sustains life in the desert can drive mortal creatures to violence.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-brown-waterskin-608fdeec28bb54587e1d/1-0000.mp3", duration = 46.9681633, start = 0},
  },
}
P.transport["item:filled-cliffspring-falls-sampler"] = {
  hash = "99a961",
  fullHash = "99a961",
  text = "Filled Cliffspring Falls Sampler. The Filled Cliffspring Falls Sampler contains murky water drawn from the headwaters near Cliffspring Falls in Darkshore. Gathered on behalf of the Cenarion Circle, it serves as crucial evidence in uncovering what is poisoning the local deer population. Cliffspring Falls provides the principal drinking water for much of Darkshore, cascading down from the eastern highlands toward the sea. Recently, however, the wildlife relying on these waters—specifically the local deer—have fallen prey to a debilitating, unnatural malady. At the behest of Dendrite Starblaze in Moonglade, druidic initiates retrieve this sample directly from the mouth of a cave infested by hostile naga. The vial holds visibly putrid liquid, confirming that the region's primary fresh water supply is actively corrupted.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-cliffspring-falls-sampler-76bbb1a777403de5e547/1-0000.mp3", duration = 44.9828571, start = 0},
  },
}
P.transport["item:filled-containment-coffer"] = {
  hash = "3b57e2",
  fullHash = "3b57e2",
  text = "Filled Containment Coffer. A Filled Containment Coffer is an enchanted receptacle used by Forsaken spellcasters to trap erratic magical entities. By deploying a Cantation of Manifestation to reveal and weaken rift spawn in the Apothecarium, mages can trap the anomalies inside these reinforced boxes for safe examination. When unexplained magical disturbances manifested within Algernon's shop in the Apothecarium, the Forsaken mage Anastasia Hartwell commissioned practitioners of the arcane to capture the entities responsible. Because the rift creatures exist purely as living magical energy and wander unseen, ordinary cages are useless. Instead, spellcasters reveal the entities with a Cantation of Manifestation, defeat them in combat, and snap these specially prepared containment coffers shut around them. The sealed boxes shield the carrier from volatile magical backlashes while keeping the specimens intact for magical dissection. The presence of living mana creatures in the Undercity poses a serious threat. Once sealed into containment coffers, the captive beasts are transported back to Anastasia Hartwell and the city's scholars. The primary concern among the Forsaken mages is determining whether these intrusions are natural rifts in Azeroth's magical fabric or the preliminary probes of a calculated magical assault aimed at the kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-containment-coffer-642a9515deff78abbd2f/1-0000.mp3", duration = 75.0759184, start = 0},
  },
}
P.transport["item:filled-crystal-phial"] = {
  hash = "9453b2",
  fullHash = "9453b2",
  text = "Filled Crystal Phial. A Filled Crystal Phial contains sacred waters drawn from the moonwell just north of Aldrassil in Shadowglen. Gathered at the instruction of Tenaron Stormgrip, this water serves as a novice's introduction to the sacred and volatile power coursing through Teldrassil. To prepare young night elves before they venture into the wider world, Tenaron Stormgrip sends them to gather water from the moonwell nestled in Shadowglen. The phial holds more than simple spring water; moonwells are infused with residual energies traced back to the ancient Well of Eternity. While the Sentinels honor these sites as blessed shrines of Elune and druids channel their restorative qualities into tending nature, the arcane sorcery of old remains strictly forbidden. Drawing this water is the first step in understanding the sacrifices of Mount Hyjal and the delicate balance required to nurture Teldrassil.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-crystal-phial-487416f1f5ee579ffd88/1-0000.mp3", duration = 49.0579592, start = 0},
  },
}
P.transport["item:filled-cursed-ooze-jar"] = {
  hash = "58cb72",
  fullHash = "58cb72",
  text = "Filled Cursed Ooze Jar. A Filled Cursed Ooze Jar contains the noxious remains of a cursed ooze collected from the corrupted forests of Felwood. It is gathered on behalf of Laris Geardawdle, a gnome scholar in Ironforge seeking to uncover the primordial origins of slimes across Azeroth. While most adventurers avoid the vile puddles and caustic slimes crawling across Kalimdor, the gnomish researcher Laris Geardawdle sees them as a biological mystery. Noticing that slimes appear in diverse environments and observing Forsaken apothecaries diligently harvesting them, Geardawdle developed a controversial theory: oozes might be primordial secretions tied directly to Azeroth's creation. Gathering a sample requires braving Felwood's blighted woods, defeating a cursed ooze, and scooping the acidic matter into an empty jar before it completely dissolves. Securing these pungent samples serves a dual purpose for Geardawdle. Beyond the pursuit of natural science, he hopes a major discovery will cement his reputation within the dwarven-led Explorers' League. In the wake of Gnomeregan's devastating fall, many gnome refugees in Ironforge feel an intense pressure to prove their worth to their dwarven hosts, and Geardawdle believes that unlocking the ancient secrets of ooze will show everyone that welcoming gnomes was no mistake.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-cursed-ooze-jar-e69be20e197dd9ef20b8/1-0000.mp3", duration = 74.7102041, start = 0},
  },
}
P.transport["item:filled-dreadmist-peak-sampler"] = {
  hash = "096d85",
  fullHash = "096d85",
  text = "Filled Dreadmist Peak Sampler. The Filled Dreadmist Peak Sampler is a vial containing corrupted water drawn from the elevated pools atop Dreadmist Peak in the northern Barrens. Gathered by fledgling druids of the Horde, it provides the physical evidence needed by the Cenarion Circle to study a vile affliction poisoning the region's wildlife. The high crags of Dreadmist Peak house natural pools whose mists historically shape weather and rainfall across the northern Barrens. When the demon-worshipping Burning Blade established their coven atop the summit, the water quickly soured. Suspecting that demonic rituals poisoned the vapors feeding the surrounding savanna, Cenarion druids dispatch initiates to capture a specimen using a specialized sampler. The foul liquid inside confirms their worst fears, reeking of corruption potent enough to sicken the herds wandering below.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-dreadmist-peak-sampler-32f6747188bcc0a5a0d1/1-0000.mp3", duration = 47.4383673, start = 0},
  },
}
P.transport["item:filled-etched-phial"] = {
  hash = "ec880f",
  fullHash = "ec880f",
  text = "Filled Etched Phial. A Filled Etched Phial is an ornate dryad vessel laden with consecrated water drawn directly from a night elf moonwell in Ashenvale. Requested by the tauren of Thunder Bluff, this sanctified water possesses the rare spiritual potency required to quench the eternal flame shielding a sacred centaur relic. Obtaining this phial demands infiltrating night elf territory deep within Ashenvale. The empty vessel must first be claimed from the dryads around Raynewood Retreat, whose delicate containers are crafted to hold pure restorative draughts. Filled subsequently at a sacred moonwell near the western bank of the Falfarren River, the phial captures water brimming with celestial, nature-bound power. To the night elves, taking this water uninvited is an act of blatant desecration, but the tauren see it as a vital necessity for addressing a regional threat further south.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-etched-phial-07ef1d3339cd725d1aaf/1-0000.mp3", duration = 49.6065306, start = 0},
  },
}
P.transport["item:filled-jade-phial"] = {
  hash = "f36edd",
  fullHash = "f36edd",
  text = "Filled Jade Phial. The Filled Jade Phial holds sacred waters drawn from the moonwell near Starbreeze Village. Carried back to Dolanaar, it serves as part of an ongoing ritual to replenish the capital's central waters while young night elves learn the history of their people. The druids of Darnassus rely on sacred moonwell waters drawn from across the boughs of Teldrassil to replenish their central wells. Specially crafted vessels, such as the jade phial entrusted to young adventurers by Corithras Moonrage in Dolanaar, are attuned to contain these pure waters safely. By venturing eastward to the moonwell outside Starbreeze Village, initiates collect the vital water while proving their devotion to the maintenance of the World Tree. Returning the Filled Jade Phial to Dolanaar is more than a simple errand; each replenished vessel earns another chapter in the oral history of the kaldorei. Upon receiving the full phial, Corithras Moonrage speaks of the desperate era following the Third War—the burning of Nordrassil, the loss of night elf immortality, the release of the Betrayer, and the sudden disappearance of Shan'do Malfurion Stormrage.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-jade-phial-7f5f2e8c63ef53bc59ee/1-0000.mp3", duration = 65.3322449, start = 0},
  },
}
P.transport["item:filled-pure-sample-jar"] = {
  hash = "5b7243",
  fullHash = "5b7243",
  text = "Filled Pure Sample Jar. A Filled Pure Sample Jar contains an uncorrupted specimen of primordial ooze gathered from the remote wilds. It serves as crucial baseline data for the gnome scholar Laris Geardawdle in Ironforge, who is studying how environmental corruption alters living matter. In his study of oozes across Azeroth, the gnomish researcher Laris Geardawdle discovered a troubling phenomenon: these amorphous creatures absorb and reflect the magical and environmental corruption of their habitats. After cataloging the tainted slimes of Felwood, Laris determined that deciphering the nature of the rot required a control group. A Filled Pure Sample Jar holds ooze harvested from pristine, untainted wilderness—such as the primordial ecology of Un'Goro Crater—offering scholars an unaltered specimen to compare against diseased and corrupted strains. Because oozes are extraordinarily malleable organisms, true 'pure' samples cannot be collected near modern civilization, demonic blights, or necromantic fallout. The glutinous oozes inhabiting the untamed basin of Un'Goro Crater remain relatively isolated from outside corruption, making them an ideal scientific standard for Ironforge's inquiring minds.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-pure-sample-jar-5c5198d504a9fff81460/1-0000.mp3", duration = 70.4783673, start = 0},
  },
}
P.transport["item:filled-red-waterskin"] = {
  hash = "220935",
  fullHash = "220935",
  text = "Filled Red Waterskin. The Filled Red Waterskin contains pristine spring water drawn from the village well in Tarren Mill. Gathering this pure water amidst the blighted ruins held by the Forsaken serves as a vital trial for young shaman seeking communion with the water spirits. While training shaman in the ways of water, the hermit Brine in the Barrens dispatches initiates on a lengthy journey to Tarren Mill in the Hillsbrad Foothills. Amidst the decay and the dead, the town's central well miraculously draws clear, untainted spring water. Brine regards this holy vestige in an unhallowed land as an emblem of enduring spirit—drawing a parallel between the uncorrupted spring and Warchief Thrall's enduring resolve despite profound hardship. Gathering this sample proves an initiate's reverence for water's purity regardless of hostile surroundings.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-red-waterskin-f495e65ec2abe3d81c4e/1-0000.mp3", duration = 48.2481633, start = 0},
  },
}
P.transport["item:filled-tainted-ooze-jar"] = {
  hash = "fda97f",
  fullHash = "fda97f",
  text = "Filled Tainted Ooze Jar. A Filled Tainted Ooze Jar contains viscous, tainted ooze scooped directly from the remains of oozes wandering the corrupted forests of Felwood. Secured in specialized containment jars, these samples are brought to Ironforge to support radical theories regarding the origin of life on Azeroth. The tainted oozes roaming northern Kalimdor carry the deep, lingering corruption of Felwood. Harvesting them requires careful containment using jars provided by gnomish researchers. While most travelers avoid the noxious creatures entirely, collecting these samples provides rare material for natural philosophy and biological study far from the blighted forests. The samples are gathered on behalf of Laris Geardawdle, an ambitious gnome scholar stationed with the Explorers' League in Ironforge. Geardawdle is fascinated by the ubiquitous nature of slimes and noticed that the Forsaken's Royal Apothecary Society has also been taking an active interest in them. Defying popular academic skepticism, he theorizes that slimes and oozes may be primal secretions tied to the very creation of Azeroth itself. Securing these samples is his attempt to prove his standing among dwarven scholars following the tragic fall of Gnomeregan.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-tainted-ooze-jar-0d85d008e9754ceb9596/1-0000.mp3", duration = 70.8702041, start = 0},
  },
}
P.transport["item:filled-tourmaline-phial"] = {
  hash = "5d0fec",
  fullHash = "5d0fec",
  text = "Filled Tourmaline Phial. The Filled Tourmaline Phial holds enchanted waters drawn from the moonwell bordering the Pools of Arlithrien in southern Teldrassil. Collected at the request of Corithras Moonrage, the water serves as part of an effort to monitor the health and balance of the growing World Tree. The Tourmaline Phial is prepared specifically to draw water from the moonwell located southeast of the road to Darnassus, on the shores of the Pools of Arlithrien. Gathering water from this shrine has become fraught with peril due to the sudden aggression of the Gnarlpine furbolgs, peaceful neighbors who have rapidly deteriorated into violent madness. Corithras Moonrage tasks travelers with braving the hostile groves to secure this water, aiming to diagnose the deepening corruption unsettling the land.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-tourmaline-phial-649f2535eca8916bee0e/1-0000.mp3", duration = 42.5795918, start = 0},
  },
}
P.transport["item:filled-vessel"] = {
  hash = "509c4f",
  fullHash = "509c4f",
  text = "Filled Vessel. The Filled Vessel contains purified waters drawn from the various sacred moonwells across Teldrassil. Entrusted to couriers by Corithras Moonrage in Dolanaar, it is delivered to Arch Druid Fandral Staghelm in Darnassus to aid his study of the World Tree's ailments. Teldrassil was planted without the blessings of the Great Aspects, Alexstrasza and Nozdormu, leaving its immense boughs vulnerable to unexpected corruption, strange beasts, and crazed furbolg tribes. In an attempt to monitor and cleanse the burgeoning boughs, night elf acolytes are dispatched to gather water samples from moonwells situated across the boughs. Corithras Moonrage consolidates these gathered phials into a single Filled Vessel, sending it onward to the capital. The mixture serves as a vital sample of Teldrassil's vitality for Arch Druid Fandral Staghelm, who works tirelessly in the Cenarion Enclave to uncover a remedy for the Great Tree's pervasive flaws.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-vessel-41210d3920c3ddc8d012/1-0000.mp3", duration = 57.2081633, start = 0},
  },
}
P.transport["item:final-clue-to-sanders-treasure"] = {
  hash = "3f81d1",
  fullHash = "3f81d1",
  text = "Final Clue to Sanders' Treasure. The Final Clue to Sanders' Treasure is a whiskey-stained note found stuffed inside an old jug on the Westfall coast. It provides the concluding directions left behind by the deceased pirate Captain Sanders, guiding scavengers straight into the open sea to recover his buried booty. Reeling from a heavy stench of spirits, this smudged parchment marks the end of Captain Sanders' convoluted paper trail across Westfall. The late buccaneer, known for leaving cryptic directions across the shoreline, hid his final note deep inside an old whiskey jug along the coast. The instructions are crude yet straightforward: head due west into the ocean waves from the location of the bottle, braving the cold surf until reaching a lonely offshore rock where his ironbound sea chest lies waiting.",
  ["1"] = {
    {file = "Audio/Transport/full_item_final-clue-to-sanders-treasure-47a6affc16440bc1a9f2/1-0000.mp3", duration = 44.4865306, start = 0},
  },
}
P.transport["item:fine-crab-chunks"] = {
  hash = "fd9bf8",
  fullHash = "fd9bf8",
  text = "Fine Crab Chunks. Fine Crab Chunks are prime cuts of meat gathered from the coastal crustaceans roaming the beaches of Darkshore. Highly prized for their culinary versatility, they are sought after by local shore-dwellers and hungry fishermen looking to prepare an endless variety of seafood dishes. The misty, jagged shores of Darkshore are thick with skittering crustaceans, specifically Reef Crawlers and Encrusted Tide Crawlers. While many travelers view these armored shore-prowlers as pests or aggressive hazards along the waterline, enterprising gourmands consider their meat among the finest bounty of the coast. Prized cuts harvested from these creatures yield rich, tender morsels that lend themselves to practically any cooking method imaginable, from boiling and broiling to deep frying and savory stews.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fine-crab-chunks-1ea2b8acaffeed6f7113/1-0000.mp3", duration = 43.6244898, start = 0},
  },
}
P.transport["item:fine-moonstalker-pelt"] = {
  hash = "1479c2",
  fullHash = "1479c2",
  text = "Fine Moonstalker Pelt. A Fine Moonstalker Pelt is the thick, pristine hide taken from the most mature predatory moonstalkers roaming southern Darkshore. Terenthis of Auberdine uses these prized furs to weave an enchanted cloak that allows searchers to slip past the woods' hostile beasts unnoticed. While common moonstalkers prowl throughout the mist-laden forests of Darkshore, only the older moonstalker sires and matriarchs possess coats dense and healthy enough to yield a fine pelt. These powerful wildcats establish territories along the Wildbend River and further south toward the borders of Ashenvale, where they hunt with lethal patience.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fine-moonstalker-pelt-6dc250bacea2c71ce534/1-0000.mp3", duration = 35.1346939, start = 0},
  },
}
P.transport["item:fire-tar"] = {
  hash = "38d12c",
  fullHash = "38d12c",
  text = "Fire Tar. Fire Tar is a volatile substance gathered by Razormane quilboar spellcasters across the eastern Barrens. To Horde shamans, it serves as a crucial ritual component used to brew the Fire Sapta, which grants spiritual communion with the element of fire. Carried almost exclusively by spellcasting Razormane quilboar—including their geomancers, mystics, and thornweavers—fire tar is an alchemical substance tuned closely to flame. While the bristled tribes of the Barrens use it for their own harsh magic and rituals, shamanic instructors recognize it as an essential worldly reagent capable of bridging the gap between mortal senses and raw elemental fury. When young orc and troll shamans are sent to Telf Joolam perched high in Durotar's crags, they are charged with forging their fire totem. Telf requires two key elements tied to heat and flame to brew a fire sapta: a reagent pouch stolen from Burning Blade cultists, and fire tar harvested from the Razormane. Drinking the resulting brew allows the shaman to pierce the veil and perceive the elemental spirits of flame awaiting them atop the nearby peaks.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fire-tar-b66f579b69b7d2adceee/1-0000.mp3", duration = 62.6677551, start = 0},
  },
}
P.transport["item:fizzle-s-claw"] = {
  hash = "a47921",
  fullHash = "a47921",
  text = "Fizzle's Claw. Fizzle's Claw is the severed hand of the goblin warlock Fizzle Darkstorm. Taken from his encampment in Thunder Ridge, it serves as physical proof to the Horde commanders in Razor Hill that a dangerous Burning Blade conspirator has been slain. Orgnil Soulscar, tasked with uprooting shadow cults threatening the orcish homeland, identified Fizzle Darkstorm as an instigator spreading corruption in Thunder Ridge. Demand for Fizzle's claw was not merely out of savagery, but practical necessity: the Horde requires indisputable evidence when a covert warlock operating under the banner of the Burning Blade is eliminated. Thunder Ridge lies just northwest of Razor Hill, making Fizzle's cultist presence an imminent peril to the surrounding territories. By severing the goblin's claw and returning it to Razor Hill, Horde scouts confirmed that the warlock's rituals and his attempts to establish a Burning Blade foothold had been thwarted.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fizzle-s-claw-3500b8733cdc78a148ac/1-0000.mp3", duration = 53.4987755, start = 0},
  },
}
P.transport["item:flagongut-s-fossil"] = {
  hash = "d0ed47",
  fullHash = "d0ed47",
  text = "Flagongut's Fossil. Flagongut's Fossil is an ancient specimen recovered from the dig sites of the Wetlands. Entrusted to the dwarven Explorers' League, it holds latent secrets that Archaeologist Flagongut seeks to decipher using a mysterious relic known as the Stone of Relu. Unearthed as part of the dwarven expeditions across Khaz Modan, this ancient fossil represents more than just petrified stone. Archaeologist Flagongut believes it holds forgotten powers tied to the deep antiquity of the world, comparable to artifacts found across the sea in Darkshore. For safekeeping during regional studies, the fossil was held by Prospector Whelgar at his excavation site in the southern hills of the Wetlands.",
  ["1"] = {
    {file = "Audio/Transport/full_item_flagongut-s-fossil-c6bd0a384e1893490285/1-0000.mp3", duration = 39.2097959, start = 0},
  },
}
P.transport["item:flatland-cougar-femur"] = {
  hash = "6cd0f2",
  fullHash = "6cd0f2",
  text = "Flatland Cougar Femur. A Flatland Cougar Femur is a dense thigh bone taken from the predatory cougars that prowl the golden grasses of Mulgore. It serves as a vital component in a traditional tauren folk remedy used to counter lethal, venomous infections. The flatland cougar is one of Mulgore's most dangerous native stalkers, blending seamlessly with the dry brush until it springs upon unsuspecting prey. While hunters often harvest cougar pelts and claws for leatherworking and trophies, their heavy marrow-rich bones possess practical value in regional medicine. When Maur Raincaller, a tauren of Bloodhoof Village, suffered a venomous wound from the monstrous pink strider Mazzranache, he urgently requested a cougar femur alongside parts from other local beasts. The bone is crushed or boiled to extract its potent properties, forming an antitoxin poultice capable of drawing fever and necrotic venom out of a festering bite.",
  ["1"] = {
    {file = "Audio/Transport/full_item_flatland-cougar-femur-dbc59a136f0739226d98/1-0000.mp3", duration = 53.4987755, start = 0},
  },
}
P.transport["item:flatland-prowler-claw"] = {
  hash = "a8dc7c",
  fullHash = "a8dc7c",
  text = "Flatland Prowler Claw. A Flatland Prowler Claw is taken from the dangerous feline predators that stalk the grassy plains of Mulgore. For aspiring hunters, gathering these claws serves as a traditional rite of passage, demonstrating cunning and martial resolve to the elders of Thunder Bluff. Flatland prowlers are among the most cunning and territorial predators roaming the wind-swept plains of Mulgore. Quick on their feet and adept at ambushing prey in the tall grass, they present a genuine threat to travelers and a worthy test for young hunters. Collecting their sharp claws is not merely a task of survival, but a recognized tradition. Skorn Whitecloud advises promising wanderers to harvest these trophies to present to Melor Stonehoof atop Thunder Bluff's Hunter Rise, proving they possess the resolve and fieldcraft necessary to pursue the hunter's way.",
  ["1"] = {
    {file = "Audio/Transport/full_item_flatland-prowler-claw-2b3b92760701a101dfb0/1-0000.mp3", duration = 47.36, start = 0},
  },
}
P.transport["item:foreman-s-blackjack"] = {
  hash = "48b3c0",
  fullHash = "48b3c0",
  text = "Foreman's Blackjack. The Foreman's Blackjack is a heavy leather-wrapped cosh loaned out to fresh Horde recruits in the Valley of Trials. Taskmasters hand it down as an everyday disciplinary tool to wake slumbering peons and enforce the grueling pace of Durotar's early construction. Building a new home in the rugged desert of Durotar requires massive stockpiles of lumber, and the labor falls squarely on the shoulders of the Horde's peons. In the Valley of Trials, Foreman Thazz'ril relies on the Foreman's Blackjack to keep work crews moving. Rather than dealing lethal blows, this weighted bludgeon is designed to deliver a jarring wake-up call to laborers caught napping beneath the valley's shade trees. It serves as a stark reminder of peon life in the new Horde: grueling, unglamorous, and supervised with an iron fist.",
  ["1"] = {
    {file = "Audio/Transport/full_item_foreman-s-blackjack-ca5c204111bda9e89f0a/1-0000.mp3", duration = 46.2367347, start = 0},
  },
}
P.transport["item:forged-steel-bars"] = {
  hash = "2df73b",
  fullHash = "2df73b",
  text = "Forged Steel Bars. Forged Steel Bars are refined metal ingots belonging to the orc blacksmith Thun'grim Firegaze. Stolen by opportunistic Razormane quilboar during a night raid, they serve as proof of a warrior's resolve to recover stolen property in the Barrens. Forged Steel Bars represent high-quality smithing stock belonging to the visually impaired orc smith Thun'grim Firegaze, who maintains a camp in the northern Barrens. Taking advantage of Thun'grim's failing eyesight, local Razormane quilboar distracted the smith with grunts and snorts while thieves slipped away with an iron chest containing the ingots. Unskilled in metalcrafting fine steel, the quilboar abandoned the unopened container near a ruined wagon in their encampment to the northwest, leaving the bars intact for recovering warriors to reclaim.",
  ["1"] = {
    {file = "Audio/Transport/full_item_forged-steel-bars-e9eae43b9683e47d1da1/1-0000.mp3", duration = 46.0277551, start = 0},
  },
}
P.transport["item:fragments-of-rok-alim"] = {
  hash = "da3321",
  fullHash = "da3321",
  text = "Fragments of Rok'Alim. Fragments of Rok'Alim are the shattered stone remains of a primeval earth elemental roaming the canyons of Thousand Needles. Brought to Dorn Plainstalker at the Weathered Nook, they serve as undeniable physical proof that a warrior has bested an ancient terror in single combat. While most elementals faded from Azeroth following the banishment of the Old Gods, a handful possessed enough raw power to endure on the surface without being summoned by mortal magic. Rok'Alim the Pounder is one such survivor, wandering the canyon flats south of the main thoroughfare. Local centaur know him by the thunderous crashes of his stony fists pulverizing anything foolish enough to wander into his path. Striking down this living remnant of the primordial world yields jagged pieces of dense, animated rock—a trophy fit to prove unmatched physical prowess. For the tauren hermit Dorn Plainstalker, recovering the fragments is the decisive component of the Test of Strength. As part of a series of spiritual and martial rites conducted high within the Weathered Nook, the trial demands that an initiate face an entity of unyielding brute force. Delivering the battered rubble of Rok'Alim proves that an adventurer possesses the bravery and physical might required to survive the harshest perils of Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fragments-of-rok-alim-be71d5984a0c577b16cb/1-0000.mp3", duration = 71.5755102, start = 0},
  },
}
P.transport["item:frostwolf-banner"] = {
  hash = "6360e9",
  fullHash = "6360e9",
  text = "Frostwolf Banner. The Frostwolf Banner is a tribal standard cached deep within Wildpaw Cavern in Alterac Valley. Horde initiates are sent to recover it as an ancestral rite of passage to awaken their battle spirit and earn their first clan insignia. For warriors of the Horde arriving in Alterac Valley, claiming true standing among the Frostwolf clan begins with a trial of grit. Warmaster Laggrond sends new recruits south into the damp, hostile corridors of Wildpaw Cavern, a den swarming with territorial gnolls. Reaching the banner hidden within their depths and returning it unbroken demonstrates courage, proving the warrior's battle rage has awakened and earning them the Frostwolf initiate's insignia.",
  ["1"] = {
    {file = "Audio/Transport/full_item_frostwolf-banner-921a1eef608bd733077b/1-0000.mp3", duration = 41.2995918, start = 0},
  },
}
P.transport["item:full-leaden-collection-phial"] = {
  hash = "0f6911",
  fullHash = "0f6911",
  text = "Full Leaden Collection Phial. A heavy, lead-lined flask filled with irradiated radioactive fallout gathered from the troggs infesting Gnomeregan. The inventor Ozzie Togglevolt requested this hazardous sample in hopes of synthesizing a cure for irradiated leper gnomes—or perhaps concocting a dangerously potent rum. The lead lining of this collection phial is essential to shield the carrier from the volatile green fallout saturating Gnomeregan. The fallout originated when High Tinker Mekkatorque's advisors flooded the lower corridors with toxic radiation to halt the invading troggs, a catastrophe that instead corrupted both troggs and surviving gnomes into maddened, irradiated horrors. By collecting fluid residue directly from Irradiated Invaders and Pillagers, daring adventurers furnish refugee tinkerers like Ozzie Togglevolt and Razzle Sprysprocket in Kharanos with raw materials needed to experiment on remedies.",
  ["1"] = {
    {file = "Audio/Transport/full_item_full-leaden-collection-phial-c71aaba7458a6aa8b3a4/1-0000.mp3", duration = 50.5730612, start = 0},
  },
}
P.transport["item:fungal-spores"] = {
  hash = "932c37",
  fullHash = "932c37",
  text = "Fungal Spores. Fungal Spores are harvested from laden mushrooms growing around the strange oases of the Barrens. Imbued with the mysterious vital energies of these waters, they are prized by Royal Apothecary Society researchers seeking potent reagents for their chemical concoctions. Across the arid plains of the Barrens, emerald oases such as the Forgotten Pools, the Lushwater Oasis, and the Stagnant Oasis pulse with an unusual vitality. The water does more than merely quench thirst; it actively accelerates, alters, and invigorates surrounding flora and wildlife. Mushrooms growing along the damp shores become swollen and heavy with spores that carry this concentrated, volatile growth potential. To naturalists, it is an ecological curiosity; to the Royal Apothecary Society, it is a prime botanical specimen awaiting weaponization or refinement. Apothecaries stationed abroad, such as Apothecary Helbrim at the Crossroads, constantly harvest exotic local reagents to send back to their laboratories or share with distant colleagues like Apothecary Zamah in Thunder Bluff. The spores' altered physiology makes them particularly valuable for concocting potent chemical solutions. The Forsaken value these specimens precisely because their natural properties have already been shifted by the mysterious forces surging beneath the Kalimdor soil.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fungal-spores-1c9859e83d4b3b236785/1-0000.mp3", duration = 76.8783673, start = 0},
  },
}
P.transport["item:furen-s-instructions"] = {
  hash = "679370",
  fullHash = "679370",
  text = "Furen's Instructions. Furen's Instructions is a handwritten parchment given by the master armorer Furen Longbeard in Stormwind. It details the rare and perilous reagents required to forge fire-hardened mail armor for promising Alliance warriors. Furen Longbeard does not hand out exceptional armor lightly. Having already tested a warrior's resolve with simpler smithing tasks, the dwarven craftsman offers to hammer out an extraordinarily resilient suit of mail, provided the adventurer fetches the rare components himself. To ensure nothing is forgotten, Furen provides this detailed checklist, sending his charge across continents on an arduous scavenger hunt. The instructions outline a dangerous journey spanning both the Eastern Kingdoms and Kalimdor. Crafting the hardened links requires dozens of scorched spider fangs from the damp caves of the Wetlands, horns harvested from fire-breathing chimaeras in the crags of Stonetalon Mountains, and a prized galvanized horn from the chimaera matriarch herself. The final, alchemical catalyst is a vial of volatile phlogiston, held deep within the quilboar bastion of Razorfen Kraul.",
  ["1"] = {
    {file = "Audio/Transport/full_item_furen-s-instructions-ab5dca5e7f83be6f5890/1-0000.mp3", duration = 62.72, start = 0},
  },
}
P.transport["item:furen-s-notes"] = {
  hash = "825fbc",
  fullHash = "825fbc",
  text = "Furen's Notes. Furen's Notes are written folios containing the metallurgical and armorsmithing insights discovered by Furen Longbeard in Stormwind. Penned after forging resilient protective gear for veteran warriors, they are dispatched across the Alliance to refine the techniques of fellow craftsmen. When Furen Longbeard completes the rigorous forging of specialized warrior armaments in Stormwind's Dwarven District, he compiles the methods and breakthroughs he discovered along the way into written notes. Dwarven metallurgy is ever-evolving, and Furen makes multiple copies of these treatises so his peers can replicate and expand upon his findings. The documents capture practical advancements in tempering, reinforcing, and shaping armor against lethal combat blows. Furen distributes his notes to trusted contacts within the Alliance's crafting networks. While local masters like Grimand Elmore might scoff at being schooled by a peer they claim to have tutored, the value of the insights cannot be ignored. Copies are even carried overseas across the Great Sea to night elven craftsmen such as Mathiel on the Warrior's Terrace in Darnassus, bridging the gaps between distinct ancestral traditions through shared martial necessity.",
  ["1"] = {
    {file = "Audio/Transport/full_item_furen-s-notes-25d717404be88a99f278/1-0000.mp3", duration = 66.9518367, start = 0},
  },
}
P.transport["item:furlbrow-s-deed"] = {
  hash = "3db3ec",
  fullHash = "3db3ec",
  text = "Furlbrow's Deed. Furlbrow's Deed is the legal property title belonging to Farmer Theodore Furlbrow and his wife Verna for their land in Westfall. Snatched by Defias bandits to serve as a template for forging land claims, it represents the precarious state of honest folk driven from their homes across the kingdom. Signed by Theodore Furlbrow and co-signed by his wife Verna, this paper establishes ownership over their family farm in Westfall. When the Defias Brotherhood overran the region, brigands muscled the couple out and took the document with them into Elwynn Forest. Scrawled notes on the back reveal that the thieves intended to use the official parchment as a template to forge legal deeds for other properties. Stripped of their home and livelihood, the Furlbrows were forced onto the road, left stranded near the border when their wagon broke down.",
  ["1"] = {
    {file = "Audio/Transport/full_item_furlbrow-s-deed-4b3743ccaf397b5f7245/1-0000.mp3", duration = 46.8897959, start = 0},
  },
}
P.transport["item:furlbrow-s-pocket-watch"] = {
  hash = "eff0c8",
  fullHash = "eff0c8",
  text = "Furlbrow's Pocket Watch. Furlbrow's Pocket Watch is a cherished family heirloom belonging to Farmer Furlbrow of Westfall. Given to him by his wife Verna's father on their wedding day, the timepiece was abandoned in haste when Defias bandits seized their pumpkin farm. When Defias hooligans swarmed the Furlbrow Pumpkin Patch, Farmer Furlbrow and his wife Verna were forced to abandon their homestead in the middle of the night. In the frantic rush to escape, the farmer left behind a prized pocket watch, given to him as a wedding gift by his father-in-law. The heirloom remained tucked away inside a wardrobe in the overrun farmhouse, guarded by cutthroats led by Benny Blaanco. For the displaced couple camping along the road, recovering the watch represents preserving one of the few pieces of their former life that the outlaws have not ruined.",
  ["1"] = {
    {file = "Audio/Transport/full_item_furlbrow-s-pocket-watch-b66bd7e3717658085aba/1-0000.mp3", duration = 46.0277551, start = 0},
  },
}
P.transport["item:gaea-seed"] = {
  hash = "626f68",
  fullHash = "626f68",
  text = "Gaea Seed. Gaea Seeds are hardy plant kernels found along the water's edge of Mirkfallon Lake in the Stonetalon Mountains. Treasured by tauren shamans, they are imbued with elemental blessings to help replenish areas ravaged by war and industry. Gaea Seeds are native to Stonetalon Mountains, naturally washing up or growing around the shores of Mirkfallon Lake. While modest in appearance—resembling small, fibrous coconuts—they carry an inherent resilience. As industrial exploitation and conflict scar Stonetalon, shamanic practitioners view these seeds as vital conduits for healing the wounded earth.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gaea-seed-100a246482b0554909af/1-0000.mp3", duration = 34.8995918, start = 0},
  },
}
P.transport["item:gaffer-jack"] = {
  hash = "abee24",
  fullHash = "abee24",
  text = "Gaffer Jack. A Gaffer Jack is a specialized engineering component used for intricate mechanical adjustments, such as tuning stintle pegs. A crate of them was carelessly lost beneath the waves off the coast of Auberdine by the eccentric gnome inventor Wizbang Cranktoggle during his voyage across the sea. Seeking peace and quiet away from the clattering forge-works and noisy taverns of Ironforge, gnome tinkerer Wizbang Cranktoggle booked passage aboard a ship bound for Auberdine. Having indulged in a bit too much drink during the ocean voyage, Wizbang managed to fumble and drop an entire container of gaffer jacks over the railing. These small mechanical fasteners sank into the misty coastal waters of Darkshore, leaving him stranded without the vital parts required to tune his stintle pegs. Because gaffer jacks were spilled into the surf along the shoreline, they occasionally snag on the hooks of patient fishermen casting into the coastal waters of Darkshore. Recovering these lost components allows Wizbang to assemble his bizarre contraptions, though dredging tiny metal hardware out of the open sea remains a testament to both extraordinary patience and pure luck.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gaffer-jack-11a769cc3c0157aec561/1-0000.mp3", duration = 66.1420408, start = 0},
  },
}
P.transport["item:gallywix-s-head"] = {
  hash = "0ae144",
  fullHash = "0ae144",
  text = "Gallywix's Head. Gallywix's Head is a severed trophy taken from Grand Foreman Puzik Gallywix, an overseer of the Venture Company operating at the Sludge Fen in the Barrens. It serves as gruesome proof of execution demanded by the Shattered Hand, the covert rogue syndicate based in Orgrimmar. Grand Foreman Puzik Gallywix directed operations out of the Venture Company's tower north of the Sludge Fen. After word came that the Venture Co. were planning something on a grand scale, the Shattered Hand dispatched operatives to dismantle the facility entirely. Claiming Puzik Gallywix's head serves as absolute proof to Shenthul in Orgrimmar that the overseer was executed, securing the rogue's standing within the guild.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gallywix-s-head-6b3fe0e9f4e468a5ffa7/1-0000.mp3", duration = 39.444898, start = 0},
  },
}
P.transport["item:galvanized-horn"] = {
  hash = "b170b5",
  fullHash = "b170b5",
  text = "Galvanized Horn. A Galvanized Horn is a hardened biological growth harvested from the formidable chimaera matriarchs haunting the scorched crags of Kalimdor. Highly sought after by master armorers across both factions, this resilient specimen serves as a core material for specialized warrior armor. Chimaeras are savage, twin-headed beasts known for their ferocity, but the elder matriarchs that prowl the Charred Vale in the Stonetalon Mountains bear horns forged unusually hard by ash, flame, and survival. While standard fledglings yield brittle, blackened horns, the matriarch's horn possesses a naturally tempered strength akin to treated metal. Both the dwarven armorer Furen Longbeard in Stormwind and Orm Stonehoof in Thunder Bluff covet the horn, requiring it as a test of martial valor and as a critical ingredient in crafting exceptional mail armor.",
  ["1"] = {
    {file = "Audio/Transport/full_item_galvanized-horn-4495f9d70cf4aecd8657/1-0000.mp3", duration = 49.9461224, start = 0},
  },
}
P.transport["item:gargantuan-tumor"] = {
  hash = "a97c37",
  fullHash = "a97c37",
  text = "Gargantuan Tumor. The Gargantuan Tumor is a massive, diseased growth torn from the corrupted timberling Oakenscowl in Teldrassil. It serves as glaring proof of the unnatural sickness spreading through the creatures inhabiting Lake Al'Ameth. Near the southern bank of Lake Al'Ameth, a cavern shelters Oakenscowl, once a noble timberling elder who has fallen prey to vile affliction. The creature was visibly poisoned by an enormous growth that warped its behavior and seeped taint into surrounding wildlife. Severing this grotesque tumor is crucial not only to end the beast's tormented rampage, but to allow local researchers to inspect the blight and understand how such a foul malady took root in the boughs of the newly grown World Tree.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gargantuan-tumor-96da424af018be8abd44/1-0000.mp3", duration = 40.8032653, start = 0},
  },
}
P.transport["item:garrick-s-head"] = {
  hash = "ce1a0e",
  fullHash = "ce1a0e",
  text = "Garrick's Head. Garrick's Head is the severed head of Garrick Padfoot, a notorious cutthroat operating near the vineyards of Northshire Valley. It serves as gruesome proof of death to claim a bounty issued by the authorities at Northshire Abbey. For weeks, Garrick Padfoot and his gang of thugs harassed local farmers and merchants across Northshire Valley. Taking advantage of the Kingdom of Stormwind's stretched defenses, Garrick holed up in a shack near the Northshire vineyards, raiding passing trade. With local guards pinned down by encroaching kobolds and Defias bandits, Deputy Willem placed a bounty on Padfoot's head, seeking an enterprising adventurer to eliminate the outlaw and present undeniable proof of his demise.",
  ["1"] = {
    {file = "Audio/Transport/full_item_garrick-s-head-7faeee31048fe6bae07d/1-0000.mp3", duration = 40.3330612, start = 0},
  },
}
P.transport["item:gazlowe-s-ledger"] = {
  hash = "3557a0",
  fullHash = "3557a0",
  text = "Gazlowe's Ledger. Gazlowe's Ledger is a detailed record of trade goods and inventories kept by the goblin boss of Ratchet. It serves as an accounting book to cross-check cargo shipments arriving from Booty Bay against the harbor manifest. Overseeing a bustling trade port like Ratchet requires meticulous accounting. Gazlowe maintains this personal ledger to track imported crates, outbound cargo, and warehouse stores. When a long-awaited shipment from Booty Bay goes unaccounted for, Gazlowe uses the book to cross-reference his projected inventory against the maritime records kept down at the docks by Wharfmaster Dizzywig.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gazlowe-s-ledger-6369db43587b2585046c/1-0000.mp3", duration = 35.5265306, start = 0},
  },
}
P.transport["item:gem-of-anacondra"] = {
  hash = "30a6dd",
  fullHash = "30a6dd",
  text = "Gem of Anacondra. The Gem of Anacondra is one of four dream gems held by the corrupted serpent leaders within the Wailing Caverns. Carried by Lady Anacondra, it serves as tangible proof of her defeat and the curbing of the Nightmare's spread over the Barrens. When Naralex entered his deep slumber to bring water and life back to the arid Barrens, the Emerald Nightmare invaded his thoughts and warped his closest disciples. Lady Anacondra and her fellow conspirators abandoned their traditional ways to become the Druids of the Fang, twisting their noble restorative purpose into a toxic delusion. The Gem of Anacondra is one of the four dream gems carried by these serpentine leaders, focusing their corrupted bond with the Emerald Dream and anchoring the nightmare within the cave system.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gem-of-anacondra-f112e722378f62fc1e28/1-0000.mp3", duration = 43.0497959, start = 0},
  },
}
P.transport["item:gem-of-cobrahn"] = {
  hash = "ebf758",
  fullHash = "ebf758",
  text = "Gem of Cobrahn. The Gem of Cobrahn is a dream gem carried by Lord Cobrahn, one of the corrupt leaders of the Druids of the Fang within the Wailing Caverns. It serves as both a focus of his corrupted reverie and physical proof needed by Nara Wildmane to confirm his defeat. When the night elf druid Naralex entered the Emerald Dream to restore the barren plains of Kalimdor, his nightmare twisted both the Wailing Caverns and his disciples. Among them was Cobrahn, who abandoned the peaceful ways of the Cenarion Circle to take the shape of the serpent. Lord Cobrahn carries one of the four dream gems that anchor the leaders' hold over the subterranean waterways, using it to channel the twisted dreams that threaten to transform the Barrens into a venomous marsh.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gem-of-cobrahn-9d8e81008953ea69f323/1-0000.mp3", duration = 42.2661224, start = 0},
  },
}
P.transport["item:gem-of-pythas"] = {
  hash = "21b460",
  fullHash = "21b460",
  text = "Gem of Pythas. The Gem of Pythas is one of four corrupted dream gems carried by the leaders of the Druids of the Fang within the Wailing Caverns. Held by Lord Pythas, it fuels the nightmare twisting the subterranean oasis and threatening the Barrens. When Naralex entered the Emerald Dream to restore the arid Barrens, his noble vision was twisted into a living nightmare. His foremost followers fell with him, styling themselves the Druids of the Fang and seeking to remake the surface world into a venomous jungle. Lord Pythas carries this resonant stone, one of four dream gems anchoring the corruption within the caverns. The gem serves as a conduit of their dark design and proof to the druids of Thunder Bluff that Pythas's twisted trance has finally been broken.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gem-of-pythas-f3d2a4d33252462dc419/1-0000.mp3", duration = 41.5346939, start = 0},
  },
}
P.transport["item:gem-of-serpentis"] = {
  hash = "132e2c",
  fullHash = "132e2c",
  text = "Gem of Serpentis. The Gem of Serpentis is a dream gem carried by Lord Serpentis, one of the four leaders of the Druids of the Fang in the Wailing Caverns. It acts as a focal conduit for the twisted nightmare reshaping the cave network and threatening the Barrens. When Naralex's slumber inside the Wailing Caverns succumbed to the Emerald Nightmare, his most devoted followers were warped into the fanatical Druids of the Fang. Lord Serpentis is one of the cabal's four leaders. Like the other three, Serpentis carries an enchanted dream gem that anchors their collective will to the corrupted vision. Recovering this gem breaks Serpentis's hold over the cavern's ecosystem, striking directly at the leadership directing the corruption spreading across the Barrens.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gem-of-serpentis-eba2bee6cf5fd067d60d/1-0000.mp3", duration = 42.3183673, start = 0},
  },
}
P.transport["item:gerenzo-s-mechanical-arm"] = {
  hash = "105bf5",
  fullHash = "105bf5",
  text = "Gerenzo's Mechanical Arm. Gerenzo's Mechanical Arm is the grafted prosthetic limb taken from the rogue engineer Gerenzo Wrenchwhistle in the Stonetalon Mountains. It serves as unmistakable proof of his demise for goblin operatives seeking to clear out competition. Gerenzo Wrenchwhistle took self-modification to a grotesque extreme, grafting whirring gears and metal directly onto his failing body. Perched above Cragpool Lake, the renegade gnome replaced natural limbs with intricate machinery. When the goblin tinker Ziz Fizziks seeks Gerenzo's elimination to impress his superiors, this distinctive mechanical arm is the only trophy unique enough to serve as indisputable evidence of the engineer's death.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gerenzo-s-mechanical-arm-3d6ebeaf1e914cf0eec8/1-0000.mp3", duration = 39.6016327, start = 0},
  },
}
P.transport["item:ghost-hair-comb"] = {
  hash = "af2902",
  fullHash = "af2902",
  text = "Ghost Hair Comb. The Ghost Hair Comb is an eerie grooming tool entangled with the spectral strands of the spirit Blind Mary. Sent to the ghost by Madame Eva, the comb becomes an instrument of tragic realization before its gathered hair is spun into uncanny thread. Madame Eva of Darkshire sends the comb to the haunted spirit Blind Mary, who resides in a lonely dilapidated dwelling on the outskirts of Duskwood. When presented with the comb, the ghost recoils in sheer horror, suddenly confronted with the harrowing reality that she is no longer the lovely living woman she once was. In her grief and distress, Mary thrusts the comb away, leaving it tangled with strands of her own ghostly hair.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ghost-hair-comb-a767b1b2313775c4ce8b/1-0000.mp3", duration = 41.5346939, start = 0},
  },
}
P.transport["item:ghost-hair-thread"] = {
  hash = "5db5e9",
  fullHash = "5db5e9",
  text = "Ghost Hair Thread. Ghost Hair Thread is a rare, supernatural material spun by Madame Eva in Darkshire. Infused with potent occult properties, it is said to bind spiritual energies and even sew life into inanimate things. The hermit Abercrombie requests it to ward his dilapidated shack against restless ghosts. Spun by the fortune teller Madame Eva in Darkshire, Ghost Hair Thread is far more than an ordinary tailoring supply. According to Eva, the spectral thread possesses versatile occult properties, ranging from binding malevolent spirits to stitching vitality into inanimate objects. Its ethereal nature makes it a valuable asset for rituals and wards in the cursed realm of Duskwood.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ghost-hair-thread-ed6b62b8f61c4a12c2ab/1-0000.mp3", duration = 42.4228571, start = 0},
  },
}
P.transport["item:ghoul-fang"] = {
  hash = "d48d1d",
  fullHash = "d48d1d",
  text = "Ghoul Fang. Ghoul Fangs are gruesome trophies harvested from the undead prowling the blighted groves and cemeteries of Duskwood. In Darkshire, the seer Madame Eva uses them as essential components in crafting defensive talismans for travelers facing the encroaching darkness. The shadowed forest of Duskwood crawls with ravenous undead, from flesh eaters lurking near the graves to rotted corpses roaming the woods. Taking a fang from these monstrous creatures is both grim work and proof of survival against the ravenous dead that threaten Darkshire's borders. Madame Eva, the resident fortune teller and mystic in Darkshire, sees terrible omens swirling around travelers who dare step through Duskwood. She binds the latent necrotic essence of ghoul fangs alongside skeletal fingers and arachnid venom to enchant the Totem of Infliction, turning the dark forces of the forest into a protective charm against violent assault.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ghoul-fang-eb6b1349bb3d58ff655b/1-0000.mp3", duration = 52.0881633, start = 0},
  },
}
P.transport["item:ghoul-rib"] = {
  hash = "b47589",
  fullHash = "b47589",
  text = "Ghoul Rib. Ghoul Ribs are harvested from the undead prowling the haunted groves and cemeteries of Duskwood. The hermit Abercrombie claims to need them as materials to construct a grotesque effigy to ward off the flesh-eating horrors near his shack. The cursed forest of Duskwood crawls with violent undead, including ravenous ghouls such as Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones, and Plague Spreaders. Abercrombie, an eccentric recluse living isolated in a shack north of Raven Hill Cemetery, requests these sturdy, rotted bones from passing travelers. He claims that living outside the protection of the Night Watch in Darkshire leaves him vulnerable, and that assembling a terrifying effigy from ghoul ribs will serve as a scarecrow to frighten off prowling packs of the dead.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ghoul-rib-ab7bbcb0505ffc77dd64/1-0000.mp3", duration = 44.3297959, start = 0},
  },
}
P.transport["item:giant-crocolisk-skin"] = {
  hash = "ff9984",
  fullHash = "ff9984",
  text = "Giant Crocolisk Skin. Giant Crocolisk Skins are thick hides taken from the massive reptiles native to the marshes of the Wetlands. Prized by Menethil Harbor tradesmen for leatherworking, harvesting them is perilous work that has maimed more than one unwary hunter. The bogs and waterways of the Wetlands are home to enormous crocolisks whose hides are dense enough to resist the damp rot of the marshes. In Menethil Harbor, artisans like James Halloran rely on steady shipments of skins to craft rugged leather goods. However, taking a hide from a fully grown giant crocolisk requires braving deep waters and outmatching ferocious swamp predators, making every gathered pelt hard-won.",
  ["1"] = {
    {file = "Audio/Transport/full_item_giant-crocolisk-skin-c13e76faf5b3bd4bccf3/1-0000.mp3", duration = 38.5044898, start = 0},
  },
}
P.transport["item:gloom-weed"] = {
  hash = "484acf",
  fullHash = "484acf",
  text = "Gloom Weed. Gloom Weed is a sickly plant native to the blighted soil of Tirisfal Glades, commonly growing in the fields between Deathknell and Brill. It is best known as the wrong plant collected by Gordo, a lumbering Forsaken abomination who confuses it with the alchemy reagent doom weed. Sprouting amid the gloom and decay of Tirisfal Glades, Gloom Weed thrives in the fallow earth west of Brill and east of the Solliden Farmstead. Despite its morbid name, the plant is relatively harmless and lacks the potent alchemical kick prized by the Royal Apothecary Society. Its primary notoriety stems from the abomination Gordo, who wanders the roadway attempting to pull weeds with his massive, clumsy hands. Having misunderstood his master's commands, Gordo constantly gathers Gloom Weed and enlists gullible travelers to carry bunches of it back to Master Holland in the Brill graveyard, much to the apothecary's supreme annoyance.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gloom-weed-ef2997dc731bb1f0164d/1-0000.mp3", duration = 53.2897959, start = 0},
  },
}
P.transport["item:glowing-ember"] = {
  hash = "3f1598",
  fullHash = "3f1598",
  text = "Glowing Ember. A Glowing Ember is the lingering, elemental core recovered from a defeated Minor Manifestation of Fire atop the crags of Durotar. It serves as a vital ceremonial reagent in a shaman's trials, used to ignite the brazier at the Shrine of Eternal Flame. When a rising shaman drinks the fire sapta and faces the fiery spirits atop the ridge near Telf Joolam, they confront a Minor Manifestation of Fire. Upon the elemental's defeat, this smoldering remnant is all that remains of its physical form. Still pulsing with raw elemental heat, the ember carries the living spark of fire necessary to awaken the sacred brazier at the Shrine of Eternal Flame.",
  ["1"] = {
    {file = "Audio/Transport/full_item_glowing-ember-f6b6655acb605f134998/1-0000.mp3", duration = 38.8963265, start = 0},
  },
}
P.transport["item:glowing-fruit"] = {
  hash = "70b84a",
  fullHash = "70b84a",
  text = "Glowing Fruit. The Glowing Fruit is an exotic, luminescent specimen found growing amid strange fronds on the boughs of Teldrassil. Its unnatural radiance and bizarre interaction with the World Tree's soil make it an object of urgent botanical study for naturalists. Discovered hanging beneath unusual fronds on Teldrassil, this large, round fruit radiates an unmistakable light. Botanist Denalan at Lake Al'Ameth recognizes it as non-native to the World Tree, speculating its seeds arrived from distant lands across the sea. Whatever its origin, the fruit reacts strangely to the rich, enchanted soil of Teldrassil, demonstrating how vulnerable the nascent world bough is to foreign and unpredictable flora.",
  ["1"] = {
    {file = "Audio/Transport/full_item_glowing-fruit-23fb0e5a54cc1fe4a1c7/1-0000.mp3", duration = 42.004898, start = 0},
  },
}
P.transport["item:glowing-gem"] = {
  hash = "567e8d",
  fullHash = "567e8d",
  text = "Glowing Gem. The Glowing Gem is an enchanted stone recovered from the murloc camps along the waters of Ashenvale. Originally sought by the fallen scout Teronis, the stone is a vital component needed to reconstruct the magical rod crafted by Dartol. Discovered in the possession of the aggressive murlocs dwelling near Lake Falathim, the Glowing Gem is imbued with latent magical energy. The young night elf Teronis ventured out from Astranaar to track it down, aiming to piece together a tool capable of driving back the corruption seeping through Ashenvale's forests. Though Teronis met an untimely end at the lake, the stone itself survived intact among the shoreline scavengers.",
  ["1"] = {
    {file = "Audio/Transport/full_item_glowing-gem-c5fbb05335390c52f2f7/1-0000.mp3", duration = 37.1461224, start = 0},
  },
}
P.transport["item:glowing-soul-gem"] = {
  hash = "ab7f32",
  fullHash = "ab7f32",
  text = "Glowing Soul Gem. A Glowing Soul Gem is a dark ritual artifact carried by operatives of the Cult of the Dark Strand in northern Ashenvale. Imbued with shadowy sorcery, the stone traps the spirit of an unwitting victim to fuel the cult's sinister operations. Northeast of Maestra's Post, in the shadowed ruins of Ordil'Aran, members of the Cult of the Dark Strand wield dark sorcery under the watchful eyes of their shadowy masters. Among their ranks, operatives carry Glowing Soul Gems—vessels enchanted to trap and torment the souls of the dead. Rather than mere decorative trinkets, these stones act as conduits of magical energy, anchoring bound spirits to serve the cult's shadowy ends.",
  ["1"] = {
    {file = "Audio/Transport/full_item_glowing-soul-gem-75825b58c8f7224c9f34/1-0000.mp3", duration = 39.0530612, start = 0},
  },
}
P.transport["item:glutton-shackle"] = {
  hash = "ca8835",
  fullHash = "ca8835",
  text = "Glutton Shackle. Glutton Shackles are enchanted restraints worn by Moonrage Glutton worgen in Silverpine Forest. Crafted by the mad archmage Arugal, these bands channel magic to bolster his otherwise flawed sorcery and sustain his cursed lupine creations. To the trained mages of the Forsaken, the feral worgen infesting Silverpine are not merely savage monstrosities—they are evidence of gross arcane ineptitude. Dalar Dawnweaver, an accomplished arcanist stationed at the Sepulcher, holds nothing but contempt for Archmage Arugal, deeming him an incompetent hack unworthy of the Kirin Tor. Dawnweaver discovered that Arugal relied on enchanted relics to compensate for his fragile spells. The Glutton Shackles, worn by the heavy Moonrage Gluttons wandering northern Silverpine, act as magical anchors that reinforce the curse binding the beasts.",
  ["1"] = {
    {file = "Audio/Transport/full_item_glutton-shackle-4ab2a967962bc598343d/1-0000.mp3", duration = 49.5281633, start = 0},
  },
}
P.transport["item:glyph-of-azora"] = {
  hash = "aeb35e",
  fullHash = "aeb35e",
  text = "Glyph of Azora. A Glyph of Azora is an arcane tracking device crafted by the wizard Theocritus at the Tower of Azora. Bound to the scrying power of the Eye of Azora, these inscribed stones allow the mage to peer across distances and delve into the thoughts of his enemies. From his tower in Elwynn Forest, the wizard Theocritus works tirelessly to monitor hostile powers threatening the realm. While his crystal relic, the Eye of Azora, enables long-range visual scrying, it lacks the reach to pierce deeper into the minds and plans of adversaries. To overcome this limitation, Theocritus embeds miniature focuses known as Glyphs of Azora. Once affixed to a surface in a remote location, a glyph acts as an anchor for his magic, allowing him not only to read enemy intentions but also to project his voice across miles to communicate directly with field agents.",
  ["1"] = {
    {file = "Audio/Transport/full_item_glyph-of-azora-043d6442deee698c805d/1-0000.mp3", duration = 48.8228571, start = 0},
  },
}
P.transport["item:glyphic-letter"] = {
  hash = "ea8570",
  fullHash = "ea8570",
  text = "Glyphic Letter. The Glyphic Letter is an official missive bearing the arcane sigil of Khelden Bremen, the resident mage trainer in Northshire Abbey. Delivered to promising novitiates after early service to the garrison, it bids aspiring mages to report upstairs and face the rigorous realities of arcane study. Sealed with the personal insignia of the mage trainer Khelden Bremen, the Glyphic Letter is handed to apprentice spellcasters once they have proven their discipline in Northshire Valley. The letter acts as a formal invitation to step away from basic field duties and begin dedicated magical instruction within the abbey. Bremen uses the summons to gauge the student's resolve, ensuring anyone meddling with the arcane is fully prepared to confront dangerous forces, unyielding scrutiny, and the burdens that come with wielding raw magical power.",
  ["1"] = {
    {file = "Audio/Transport/full_item_glyphic-letter-130c42493d5b67a6072b/1-0000.mp3", duration = 49.2146939, start = 0},
  },
}
P.transport["item:glyphic-memorandum"] = {
  hash = "2f4273",
  fullHash = "2f4273",
  text = "Glyphic Memorandum. The Glyphic Memorandum is a written notice delivered to novice mages arriving in Coldridge Valley. Penned on behalf of the mage trainer Marryk Nurribit, it directs fledgling spellcasters indoors to begin their formal arcane instruction. Novice spellcasters setting out into the bitter frost of Coldridge Valley receive this brief missive after completing their initial tasks. Authored by the local mage trainer Marryk Nurribit, the memorandum summons young practitioners into the warmth of Anvilmar. Rather than stern academic dogma, Marryk's guidance is informal and blunt: learn your incantations, set aside coin for training and tavern ale, and steer well clear of the irradiated ruin of Gnomeregan.",
  ["1"] = {
    {file = "Audio/Transport/full_item_glyphic-memorandum-c4dfc344b5fc671df1d0/1-0000.mp3", duration = 41.4563265, start = 0},
  },
}
P.transport["item:glyphic-scroll"] = {
  hash = "6083cb",
  fullHash = "6083cb",
  text = "Glyphic Scroll. The Glyphic Scroll is a summons delivered to newly raised Forsaken magi in Deathknell. Bearing the seal of Isabella, the local arcane trainer, it calls fledgling spellcasters to the desecrated church to refine their craft in undeath. When a freshly awakened Forsaken mage returns from culling mindless Scourge in the graveyard of Deathknell, this sealed missive awaits them. Written under the mark of Isabella, the settlement's resident mage trainer, the scroll calls the recipient into the ruined parish sanctuary. For newly risen magi, it serves as an initial orientation into the discipline of the arcane under the Forsaken banner—reminding them that while death may have unburdened them of mortal weakness, the corrupting temptations of magical power remain as persistent as ever.",
  ["1"] = {
    {file = "Audio/Transport/full_item_glyphic-scroll-e33407ca3692de703052/1-0000.mp3", duration = 45.0612245, start = 0},
  },
}
P.transport["item:glyphic-tablet"] = {
  hash = "b3ff8e",
  fullHash = "b3ff8e",
  text = "Glyphic Tablet. The Glyphic Tablet is an inscribed slate handed to novice Darkspear troll mages upon beginning their trials in Durotar. Delivered through the overseer Gornek, it directs fledgling spellcasters to seek tutelage from the troll mage trainer, Mai'ah. In the Valley of Trials, new Darkspear troll initiates exhibiting an affinity for arcane power are presented with the Glyphic Tablet. Passed along by Gornek while young recruits handle early tasks around the red canyons, the tablet contains an invitation from Mai'ah, a seasoned troll mage posted outside the Den. For the Darkspear, whose arcane traditions diverge from the scholarly academies of humans or high elves, the tablet serves as a formal call to discipline. Mai'ah uses the meeting to offer both arcane instruction and a solemn warning: raw magic is corruptive, deceptive, and far more hazardous to a practitioner's mind than any enemy soldier.",
  ["1"] = {
    {file = "Audio/Transport/full_item_glyphic-tablet-5f037722806fbc138d61/1-0000.mp3", duration = 52.1404082, start = 0},
  },
}
P.transport["item:glyphs-of-summoning"] = {
  hash = "3601c9",
  fullHash = "3601c9",
  text = "Glyphs of Summoning. The Glyphs of Summoning are ritual inscriptions used by apprentice warlocks in Orgrimmar. Transcribed from the ancient Tablet of Verga, they allow a practitioner to draw a voidwalker from the Nether into a summoning circle and bind it to their service. In the subterranean depths of the Cleft of Shadow, the dark arts are studied far from the prying eyes of the Warchief's guards. For an aspiring warlock under the tutelage of Gan'rul Bloodeye, commanding a voidwalker marks a vital step in their craft. The Glyphs of Summoning, derived from the esoteric knowledge inscribed upon the Tablet of Verga, bridge the boundary between Azeroth and the Nether. Laid down within the summoning circle in Neeru Fireblade's tent, the glyphs tear open a threshold, pulling a creature of the Void into the mortal realm. The ritual demands that the warlock conquer the summoned entity in combat before Gan'rul imparts the final methods of binding.",
  ["1"] = {
    {file = "Audio/Transport/full_item_glyphs-of-summoning-6cb5c1eba27d03901d5b/1-0000.mp3", duration = 52.7934694, start = 0},
  },
}
P.transport["item:gnoam-sprecklesprocket"] = {
  hash = "405489",
  fullHash = "405489",
  text = "Gnoam Sprecklesprocket. The Gnoam Sprecklesprocket is a sophisticated power supply salvaged from Sneed's shredder deep within the Deadmines. Gnomish engineers seek this component to supercharge specialized drilling machines in an ambitious bid to reclaim their fallen home of Gnomeregan. Found in a goblin shredder operated within the Defias stronghold, the Gnoam Sprecklesprocket represents an exceptional feat of compact mechanical energy. Operating deep in the lumbering machine piloted by the goblin taskmaster Sneed, this specialized core delivers enough sustained energy to drive heavy industrial logging and cutting blades. Its stability and potent output make it an invaluable piece of salvage amidst the subterranean tunnels of Westfall. In Stormwind City, the gnomish inventor Shoni the Shilent singled out the Deadmines shredder as the key to a larger offensive. Gnomish forces seek to reclaim Gnomeregan from the trogg hordes that overran it, but the sealed underground approaches present a formidable barrier. By harnessing the Sprecklesprocket, Shoni intends to power heavy gyrodrillmatic excavationators capable of boring directly through the solid bedrock surrounding the lost techno-city, establishing an unexpected underground assault route.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gnoam-sprecklesprocket-1d9286ddbff4ff4e6e7d/1-0000.mp3", duration = 69.4334694, start = 0},
  },
}
P.transport["item:gnoll-paw"] = {
  hash = "b67029",
  fullHash = "b67029",
  text = "Gnoll Paw. Gnoll Paws are crude physical trophies harvested from Riverpaw gnolls roaming the grasslands of Westfall. Collected by The People's Militia, they serve as proof of a patrol's success in thinning the packs that threaten the local farmsteads. With the royal army absent and the crown seemingly blind to the plight of rural settlements, the defense of Westfall has fallen to ordinary citizens and volunteer forces. The People's Militia, operating out of Sentinel Hill, struggles constantly against outlaws, rogue mechanoids, and aggressive hyena-headed gnolls. To curb the gnoll menace, Captain Danuvin instituted bounties requiring physical evidence of slain beasts. Collecting severed paws is a grim necessity, ensuring that contracted adventurers truly scour the scrublands rather than loaf in the shadow of the watchtower. The Riverpaw gnolls in Westfall are more than just feral wild beasts foraging on the plains. Observers among the militia have noted troubling signs that these gnolls operate in close coordination with the Defias thieves based around the Deadmines. By terrorizing outlying farmsteads and preying on traveling supply wagons, the gnoll packs effectively screen the bandits from local resistance. Suppressing them by bringing in their paws helps keep the precarious overland routes between Sentinel Hill and Elwynn Forest open.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gnoll-paw-127e65238f868778861c/1-0000.mp3", duration = 77.0089796, start = 0},
  },
}
P.transport["item:gnomeregan-gumdrop"] = {
  hash = "8f0e19",
  fullHash = "8f0e19",
  text = "Gnomeregan Gumdrop. A Gnomeregan Gumdrop is a specialty seasonal sweet distributed during Hallow's End on behalf of the displaced gnomes. Adventurers fetch this confection to help the sick child Jesper in Stormwind's orphanage celebrate the holiday. While innkeepers across the Alliance dispense regional treats during Hallow's End, the exiled gnomes of Gnomeregan do not have a full capital inn of their own to operate. Instead, the inventive gnome Talvash del Kissel, residing in Ironforge's Mystic Ward, hands out Gnomeregan Gumdrops to travelers willing to play along with his festive tricks. Despite the radioactive disaster that drove his people from their subterranean kingdom, gnomes still proudly share their distinct confectionery with the wider Alliance. Because Jesper is sick and confined to the Stormwind orphanage in Cathedral Square, he cannot travel the continents to go trick-or-treating himself. A Gnomeregan Gumdrop is one of the four essential regional confections—alongside treats from Stormwind, Ironforge, and Darnassus—that kind-hearted travelers gather across the Alliance capitals to bring the festivities to him.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gnomeregan-gumdrop-b6ebc6b125f9fece8ee3/1-0000.mp3", duration = 64.6269388, start = 0},
  },
}
P.transport["item:gnomish-tools"] = {
  hash = "1fab50",
  fullHash = "1fab50",
  text = "Gnomish Tools. Gnomish Tools are intricate mechanical implements recovered from the sunken warships of Grand Admiral Daelin Proudmoore's fleet off the coast of Durotar. The Horde seeks these salvaged devices to study Alliance engineering and turn their enemies' technological advantages to their own benefit. When Grand Admiral Daelin Proudmoore led Kul Tiras and Alliance forces to the shores of Durotar, his fleet carried vast supplies of modern equipment, including sophisticated gear manufactured by their gnomish allies. Following the destruction of Proudmoore's fleet along the Scuttle Coast, east of Tiragarde Keep, these delicate mechanical kits sank beneath the waves. Today, waterproof toolboxes remain scattered among the rotting timbers and barnacle-encrusted hulls in the shallows. Gar'Thok, overseer of Razor Hill, tasked Horde scouts with securing these tools from the watery grave of Proudmoore's navy. The orcs recognize that humans and gnomes possess advanced technical craftsmanship, particularly in siege engines, shipwrighting, and clockwork mechanics. By collecting and dispatching these kits by caravan to the craftsmen and scholars in Orgrimmar, the Horde intends to dissect Alliance contraptions, learn how to counter their war machines, and adapt foreign innovations for their own survival.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gnomish-tools-29528bf18881e9f1e364/1-0000.mp3", duration = 73.4040816, start = 0},
  },
}
P.transport["item:gold-dust"] = {
  hash = "0a9485",
  fullHash = "0a9485",
  text = "Gold Dust. Gold Dust consists of fine flecks of precious metal sifted and hoarded by the kobolds infesting the mines of Elwynn Forest. While ordinary miners seek intact ore veins, local opportunists pay good coin to anyone willing to pry these gathered particles from the vermin. Beneath the soil of Elwynn Forest, kobolds scratch away at the subterranean tunnels of the Fargodeep and Jasperlode mines. Rather than properly refining the ore they uncover, the rat-like creatures often hoard coarse gold dust directly in their pockets and pouches. These small, glittering shavings represent the tedious labor of subterranean scavenging, easily overlooked by proper mining syndicates but intensely coveted by local peddlers and fences looking to turn a quiet profit without paying official smelting tariffs.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gold-dust-99b542b03a0783be9d00/1-0000.mp3", duration = 46.6546939, start = 0},
  },
}
P.transport["item:golm-fragment"] = {
  hash = "9b94ea",
  fullHash = "9b94ea",
  text = "Golm Fragment. The Golm Fragment is one of four missing pieces chipped from the Goaz Stone, an ancient relic uncovered at the Wetlands excavation site. Recovered by adventurers dodging ferocious raptors, it helps dwarven archaeologists piece together mysterious Titan inscriptions. Discovered at the excavation site in the southern Wetlands, the Golm Fragment is part of a monumental slab known as the Goaz Stone. Prospector Whelgar discovered the stone shortly before raptors drove the Explorers' League back, but found its inscription severed in four critical places. The Golm Fragment was abandoned amid the dirt and overturned crates when the dig was overrun, hidden away inside an ancient relic box until brave explorers could retrieve it.",
  ["1"] = {
    {file = "Audio/Transport/full_item_golm-fragment-5db8c295b09c9037caba/1-0000.mp3", duration = 39.2881633, start = 0},
  },
}
P.transport["item:gordon-s-crate"] = {
  hash = "13093d",
  fullHash = "13093d",
  text = "Gordon's Crate. Gordon's Crate is a heavy shipment of weapons packed in the Undercity for the Forsaken forces stationed in Silverpine Forest. It serves as an essential supply consignment meant to be ferried directly to the remote garrison at the Sepulcher. Maintaining the Forsaken grip on Silverpine Forest requires a steady logistical flow from the Undercity. Gordon's Crate holds armaments intended to bolster Deathguard Podrig's defenders at the Sepulcher, ensuring outpost sentries are not caught off guard by the worgen, wild beasts, or human remnants lurking in the woods. Because overland roads out of the capital are dangerous and slow, valuable shipments rely on the Undercity's bat handlers. The crate is handed to Michael Garrett, the bat master perched above the city's trade quarter, who secures passage atop a trained flying bat back to Karos Razok's roost in the Sepulcher.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gordon-s-crate-073a4bb55b217c0cc2e3/1-0000.mp3", duration = 49.1885714, start = 0},
  },
}
P.transport["item:grape-manifest"] = {
  hash = "be92f4",
  fullHash = "be92f4",
  text = "Grape Manifest. The Grape Manifest is a handwritten ledger tracking the harvest from Milly Osworth's vineyard in Northshire Valley. It documents the recovery of fresh fruit after local brigands overran the fields, destined for the cellars of Northshire Abbey. Northshire Abbey has long sustained itself on regional agriculture, including the lush vineyards tended by local farmers like Milly Osworth. When Defias bandits moved into the valley and seized the harvest, the abbey's stock of fresh fruit and fermentables was thrown into jeopardy. The Grape Manifest serves as official confirmation that the crates have been reclaimed from the fields. It details the quantity of saved grapes so the abbey's quartermasters can balance their stores and prepare barrels for fermentation. Brother Neals oversees Northshire's food and drink, maintaining a particular fondness for testing the abbey's vintage in the high quiet of the bell tower. For him, receiving the manifest is not merely administrative paperwork; it ensures that the monks and visiting recruits will not go thirsty. To the devout brothers of the abbey, every saved bushel is celebrated as both a logistical victory and a quiet blessing from the Holy Light.",
  ["1"] = {
    {file = "Audio/Transport/full_item_grape-manifest-c2c8decc40c4d0e27a20/1-0000.mp3", duration = 65.9853061, start = 0},
  },
}
P.transport["item:gray-bear-tongue"] = {
  hash = "efcb77",
  fullHash = "efcb77",
  text = "Gray Bear Tongue. A gray bear tongue is a raw reagent harvested from the wild bears roaming the Hillsbrad Foothills. It is sought after by the Royal Apothecary Society in Tarren Mill to serve as a biological component in their experimental toxins. The untamed wilderness surrounding Tarren Mill is rich in native fauna, including several varieties of sturdy gray bears. While natural predators pose a constant threat to travelers, the Forsaken see them as a harvestable source of raw alchemy components. Apothecary Lydon studies local wildlife to isolate potent organic agents, using the heavy muscular tissue and fluids of gray bear tongues as a base ingredient for concocting lethal solutions such as the Elixir of Suffering.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gray-bear-tongue-365ab3d6e224709399cf/1-0000.mp3", duration = 40.8293878, start = 0},
  },
}
P.transport["item:gregor-s-remains"] = {
  hash = "360c08",
  fullHash = "360c08",
  text = "Gregor's Remains. Gregor's Remains are the physical bones recovered from the Scourge-enslaved Gregor Agamand. Once part of the wealthiest dynasty in Tirisfal Glades, his remains are sought by a former mill worker eager to settle an old score from beyond the grave. Before the Third War, the Agamand family held immense wealth and vast tracts of land across northern Tirisfal Glades. When the Scourge invaded Lordaeron, the patriarchs chose pride over flight, fortifying their family mills and persuading their loyal laborers to make a desperate stand against the undead. The defense failed entirely. The estate was overrun, and those who stood their ground were butchered and raised into undeath. Gregor Agamand became another mindless thrall in the service of the Lich King, haunting the very mills his family once ruled. For survivors who broke free from the Lich King's grip to join the Forsaken, the memory of that fateful defense remains a bitter wound. Coleman Farthing, a former mill worker stationed in Brill, blames the hubris of the Agamands for trapping his soul in eternal rot. Collecting Gregor's remains offers Farthing a measure of personal retribution, closing the chapter on a master who led his household straight into damnation.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gregor-s-remains-ba29c61666966c795642/1-0000.mp3", duration = 71.7061224, start = 0},
  },
}
P.transport["item:grelin-s-report"] = {
  hash = "263d23",
  fullHash = "263d23",
  text = "Grelin's Report. Grelin's Report is a dispatch written by Grelin Whitebeard detailing the Frostmane troll situation in Coldridge Valley. Entrusted to an adventurer rather than a novice apprentice, it serves as the official link between the scouts guarding Anvilmar and Senir Whitebeard stationed in Kharanos. Written after observing the Frostmane trolls in Coldridge Valley, Grelin's Report concludes that they pose no large threat and can be dealt with by the Mountaineers already stationed there and mercenaries paid from Senate funds. Rather than trusting his fumbling apprentice with such vital intelligence, Grelin enlists a capable traveler to carry the document through the trogg-infested Coldridge Pass. The paper acts as an official pass through Mountaineer Thalos's blockade, proving the bearer travels on urgent business to the wider snowy expanse of Dun Morogh. When delivered to Senir Whitebeard at the Thunderbrew Distillery in Kharanos, the report provides critical field updates intended for Ironforge. Senir notes with amused resignation that his brother invoked King Magni Bronzebeard's name liberally throughout the text. Grelin claims the King's sanction for the action, and Senir expects that appeal to royal authority to ruffle some feathers in the Ironforge Senate.",
  ["1"] = {
    {file = "Audio/Transport/full_item_grelin-s-report-cf5810ea5d78c298afeb/1-0000.mp3", duration = 69.9820408, start = 0},
  },
}
P.transport["item:grelin-whitebeard-s-journal"] = {
  hash = "5d8487",
  fullHash = "5d8487",
  text = "Grelin Whitebeard's Journal. Grelin Whitebeard's Journal is a personal field notebook kept by the dwarf scout Grelin Whitebeard in Coldridge Valley. Containing critical notes on local Frostmane troll activity, the journal was stolen by the Frostmane brute Grik'nir the Cold and dragged into the troll cave in Coldridge Valley. While observing the aggressive movements of the Frostmane trolls near Coldridge Valley, Grelin Whitebeard diligently recorded his findings in this leatherbound notebook. The document contains his raw field observations regarding the strength, organization, and threat level posed by the indigenous winter trolls. However, during a confrontation or ambush, the journal was snatched away by Grik'nir the Cold—a heavily marked troll brute—forcing Grelin to recruit passing adventurers to delve into the troll cave and wrest it back before his report could be finalized.",
  ["1"] = {
    {file = "Audio/Transport/full_item_grelin-whitebeard-s-journal-3f7d5125cd941db1f7a7/1-0000.mp3", duration = 49.3714286, start = 0},
  },
}
P.transport["item:grell-earring"] = {
  hash = "bf2bef",
  fullHash = "bf2bef",
  text = "Grell Earring. Grell Earrings are crude baubles scavenged and worn by the feral creatures infesting the ruins of Bashal'Aran. Though unremarkable at a glance, their proximity to ancient relics allows sensitive spirits to trace the lingering magical seals holding them in torment. The Wild Grells and Vile Sprites lurking around the collapsed marble of Bashal'Aran hoard assorted trinkets, frequently fashioning earrings from scraps they scavenge among the ruins. To most mortals, these items are worthless refuse. However, to Asterion, an ancient night elf bound as a tormented phantom within the ruins, they serve as dowsing implements. By scrutinizing the resonant magical traces absorbed by these earrings, Asterion attempts to locate the ancient seal that imprisons his spectral form.",
  ["1"] = {
    {file = "Audio/Transport/full_item_grell-earring-919b5966b302f274b133/1-0000.mp3", duration = 46.08, start = 0},
  },
}
P.transport["item:grenka-s-claw"] = {
  hash = "e7c79f",
  fullHash = "e7c79f",
  text = "Grenka's Claw. Grenka's Claw is a physical trophy taken from the formidable harpy Grenka Bloodscreech in the depths of Roguefeather Den. Presented to Dorn Plainstalker at the Weathered Nook, it serves as undeniable proof that an aspiring adventurer has endured a grueling physical trial in the canyon heights. Within the winding caverns of Roguefeather Den, west of Freewind Post, harpies cache food and violently defend their territory against outsiders. To test the physical resilience of young champions, Dorn Plainstalker tasks them with invading the deep roosts and destroying the flock's food reserves. Such brazen provocation inevitably draws the fury of Grenka Bloodscreech. Severing and returning her wicked talon proves that a warrior can withstand wave after wave of enraged harpies and survive the vicious onslaught of their matriarch.",
  ["1"] = {
    {file = "Audio/Transport/full_item_grenka-s-claw-af10c656136954e70560/1-0000.mp3", duration = 45.2963265, start = 0},
  },
}
P.transport["item:grimtotem-satchel"] = {
  hash = "7a5a41",
  fullHash = "7a5a41",
  text = "Grimtotem Satchel. The Grimtotem Satchel is a leather pouch clutched by the fallen tauren Maur Grimtotem deep inside Ragefire Chasm. Even as troggs overwhelmed him in the subterranean cavern beneath Orgrimmar, Maur shielded this pack with his dying breath. Recovering it and returning it to Thunder Bluff reveals that Elder Crone Magatha Grimtotem had an active interest in whatever her clansman carried. Discovered beneath the broken body of Maur Grimtotem in the depths of Ragefire Chasm, this simple pack was held in a fierce, vice-like embrace. Maur fought desperately to protect whatever it contains while surrounded and slain by savage troggs. The sheer determination required to shield a satchel above one's own life suggests its contents are far more significant than ordinary trail rations or supplies.",
  ["1"] = {
    {file = "Audio/Transport/full_item_grimtotem-satchel-6e340d33b3bcdd1063b0/1-0000.mp3", duration = 43.6244898, start = 0},
  },
}
P.transport["item:grizzled-bear-heart"] = {
  hash = "8692a5",
  fullHash = "8692a5",
  text = "Grizzled Bear Heart. A Grizzled Bear Heart is a biological reagent harvested from the sturdy bears roaming Silverpine Forest. It serves as a vital component in the Royal Apothecary Society's grim research into the New Plague. The Royal Apothecary Society works ceaselessly to develop an engineered blight capable of exterminating both the Scourge and living humanity. In the woodlands of Silverpine Forest, Apothecary Renferrel discovered that a unique toxin derived from the heart of a grizzled bear, when combined with arachnid ichor, yields a remarkably lethal concoction. Couriers and Forsaken loyalists hunt down ferocious grizzled bears, giant grizzled bears, and the infamous beast Old Vicejaw to carve out these organs and deliver them directly to Master Apothecary Faranell deep within the Apothecarium of the Undercity.",
  ["1"] = {
    {file = "Audio/Transport/full_item_grizzled-bear-heart-706002ec0a292d7d3cdc/1-0000.mp3", duration = 47.0465306, start = 0},
  },
}
P.transport["item:grizzled-scalp"] = {
  hash = "a2d321",
  fullHash = "a2d321",
  text = "Grizzled Scalp. A Grizzled Scalp is the thick, furred hide taken from grizzled thistle bears roaming the southern forests of Darkshore. While seemingly an odd trophy, these pelts are sought by the eccentric gnome tinkerer Wizbang Cranktoggle to supply his hidden wilderness machinery.",
  ["1"] = {
    {file = "Audio/Transport/full_item_grizzled-scalp-4312a6c2b5b2742f7af5/1-0000.mp3", duration = 15.6212245, start = 0},
  },
}
P.transport["item:gryshka-s-letter"] = {
  hash = "8b54ca",
  fullHash = "8b54ca",
  text = "Gryshka's Letter. Gryshka's Letter is a personal note of thanks written by Innkeeper Gryshka of Orgrimmar and addressed to the butcher Zargh at the Crossroads. Sent after receiving a delivery of fresh meat, the letter serves as both a sign of gratitude and an excuse to teach young Horde couriers how to navigate the wind rider flight network. When Zargh ships a bundle of prepared steaks from the arid expanses of the Barrens to Orgrimmar's central tavern, Innkeeper Gryshka pens this note in return. Beyond expressing her satisfaction with the butcher's cuts, the letter reveals a fond—if rugged—appreciation for Zargh, recalling humorous misadventures such as the time he lost a finger while preparing meat. Gryshka concludes with affectionate amusement, remarking that he looks handsome even when bloodied by his trade. Carrying Gryshka's Letter provides travelers with a practical lesson in Horde logistics. To return the parchment to the Crossroads, adventurers are instructed to report to Doras, the wind rider master roosted atop Orgrimmar's plateau. By demonstrating that a traveler has already checked in with Devrak at the Crossroads, Doras introduces fledgling couriers to the wyvern flight paths that bind the settlements of Durotar and the Barrens together.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gryshka-s-letter-1032123ce6b63f61b40c/1-0000.mp3", duration = 68.884898, start = 0},
  },
}
P.transport["item:gunther-s-spellbook"] = {
  hash = "24ecfc",
  fullHash = "24ecfc",
  text = "Gunther's Spellbook. Gunther's Spellbook is a personal arcane tome belonging to Gunther Arcanus, a former Kirin Tor wizard dwelling in Tirisfal Glades. Imbued with an enchantment by Bethor Iceshard, the book serves as proof to Gunther that other mages have successfully broken free of the Lich King's control.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gunther-s-spellbook-d03489b0021b0015589a/1-0000.mp3", duration = 16.1959184, start = 0},
  },
}
P.transport["item:gyromechanic-gear"] = {
  hash = "92cdd9",
  fullHash = "92cdd9",
  text = "Gyromechanic Gear. A Gyromechanic Gear is a salvaged piece of precision engineering recovered from the fallout outside Gnomeregan. Gnomish inventors in Kharanos seek these specific gears to construct an experimental device capable of reversing leper gnome mutations. When radiation flooded Gnomeregan to purge the trogg invasion, it corrupted a vast portion of the surviving gnome population into mad, irradiated leper gnomes. Refusing to abandon their twisted kin, inventors Ozzie Togglevolt and Razzle Sprysprocket set to work drafting schematics for the Recombobulator—an ambitious contraption designed to undo the radiation's horrific effects. Building the prototype requires precision mechanisms capable of enduring volatile internal pressures, particularly Gyromechanic Gears and complementary Restabilization Cogs. Because local manufacturing collapsed with the fall of their capital, researchers are forced to scavenge these delicate parts directly from the hostile leper gnomes roaming Dun Morogh.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gyromechanic-gear-f97e7bd10a8eb9988993/1-0000.mp3", duration = 55.9020408, start = 0},
  },
}
P.transport["item:hallowed-letter"] = {
  hash = "0bc281",
  fullHash = "0bc281",
  text = "Hallowed Letter. The Hallowed Letter is a formal summons bearing the insignia of Priestess Anetta, delivered to promising young priests in Northshire Valley. It calls the bearer to Northshire Abbey to begin formal study and training in the Holy Light. Sealed with the personal mark of Priestess Anetta, the Hallowed Letter is presented to fledgling priests after their first trials against the kobold camps of Northshire Valley. Anetta recognizes the inner spark of the Holy Light within the novice and urges them not to linger, but to step inside the abbey walls to formally dedicate themselves. With dark forces still lingering across Azeroth in the wake of the Third War, the priesthood actively gathers those capable of healing, protecting, and offering spiritual guidance to an empire struggling to maintain order.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hallowed-letter-0a7dd81a8895799d0b6a/1-0000.mp3", duration = 43.8595918, start = 0},
  },
}
P.transport["item:hallowed-rune"] = {
  hash = "10a792",
  fullHash = "10a792",
  text = "Hallowed Rune. The Hallowed Rune is an inscribed stone passed to novice priests beginning their training in Coldridge Valley. Sent by the dwarven priest trainer Branstock Khalder, it calls aspiring wielders of the Holy Light into Anvilmar to begin their formal tutelage. When a fledgling priest demonstrates their resolve aiding the mountaineers and defenders of Coldridge Valley, Branstock Khalder sends forth the Hallowed Rune. Inscribed with teachings of the Holy Light, the stone serves as both an introduction and an invitation. Dwarven novices are directed to step away from minor skirmishes in the snow and report to Anvilmar, where Branstock prepares them to mend wounds and harness holy power against the trogg infestation threatening Dun Morogh.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hallowed-rune-2568c7e31198788fd6d9/1-0000.mp3", duration = 40.9861224, start = 0},
  },
}
P.transport["item:hallowed-scroll"] = {
  hash = "ac816f",
  fullHash = "ac816f",
  text = "Hallowed Scroll. The Hallowed Scroll is a formal summons delivered to newly awakened Forsaken priests in Deathknell. Bearing the personal seal of Dark Cleric Duesten, it directs fledglings to the ruined chapel to begin their re-education in faith, willpower, and shadow. Newly risen Forsaken priests find that their connection to the world has violently shifted. Delivered amidst the ongoing chaos of Deathknell's reclamation, the Hallowed Scroll directs nascent spellcasters to seek guidance within the settlement's ruined chapel. Marked with the seal of Dark Cleric Duesten, the parchment serves as both an introduction and an order to report for formal instruction, initiating the priest into the pragmatic philosophy that defines Forsaken priesthood. Upon answering the scroll's summons, priests are immediately disabused of old dogmas. Duesten makes it clear that traditional crutches—the veneration of the Holy Light, ancestral spirits, or demonic pacts—no longer serve the undead. Instead, the scroll marks the start of an inward discipline rooted strictly in individual willpower. The teachings initiated by this parchment emphasize surviving and ruling through sheer conviction, turning religious devotion into an instrument of self-determination and mastery.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hallowed-scroll-9e72917db7a8dd53823d/1-0000.mp3", duration = 72.1502041, start = 0},
  },
}
P.transport["item:hallowed-sigil"] = {
  hash = "88239a",
  fullHash = "88239a",
  text = "Hallowed Sigil. The Hallowed Sigil is an inscribed night elf token carried by young initiates within Shadowglen. Sent by the priest trainer Shanda, it serves as a formal summons directing prospective servants of Elune to the ancient boughs of Aldrassil. Novice night elf priests stepping into the sacred canopy of Shadowglen often receive the Hallowed Sigil from a woodland messenger. Engraved with holy markings, the token acts as a personal writ from Shanda, the resident priest trainer at Aldrassil. Carrying and reading the sigil directs an acolyte upward to the towering hollow of Aldrassil, formally introducing them to the Sisterhood of Elune and initiating their spiritual service to the Kaldorei as new travelers arrive across Teldrassil.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hallowed-sigil-718228e57af0d0d5860a/1-0000.mp3", duration = 41.6914286, start = 0},
  },
}
P.transport["item:hallowed-tablet"] = {
  hash = "404fb3",
  fullHash = "404fb3",
  text = "Hallowed Tablet. The Hallowed Tablet is an inscribed message delivered to young Darkspear troll priests training in the Valley of Trials. Sent by the spiritual elder Ken'jai, it bids novices to seek him out and begin learning how to commune with the spirits. When a promising troll priest takes their first steps in the harsh crimson canyons of the Valley of Trials, Gornek hands them the Hallowed Tablet. Rather than a formal bureaucratic writ, it serves as a personal invitation from Ken'jai, the resident priest trainer residing outside the Den. Ken'jai interprets the signs and whisperings of the spirits, sensing when young Darkspear with spiritual potential arrive in Durotar. The tablet instructs the initiate to read its words and present themselves for guidance on properly channeling spiritual authority.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hallowed-tablet-f277919bc43573f00d4c/1-0000.mp3", duration = 45.2179592, start = 0},
  },
}
P.transport["item:hand-of-dextren-ward"] = {
  hash = "6443d6",
  fullHash = "6443d6",
  text = "Hand of Dextren Ward. The Hand of Dextren Ward is a severed trophy taken from a condemned grave robber imprisoned within the Stormwind Stockade. Delivered to Darkshire, it serves as proof that frontier justice has finally been carried out against a man who desecrated the town's dead. Dextren Ward earned a death sentence from Lord Ebonlocke after he was caught digging up bodies in the Duskwood cemeteries and selling them to the necromancer Morbent Fel. Before the town could execute him, Stormwind intervened, hauling the criminal away to the Stockade. For the grieving families of Darkshire, the Hand of Dextren Ward is physical proof that the defiler has met the execution he deserved, bypassing the House of Nobles' unwanted leniency.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hand-of-dextren-ward-fd40fa5e55696acbb50f/1-0000.mp3", duration = 39.2881633, start = 0},
  },
}
P.transport["item:handful-of-oats-classic"] = {
  hash = "4d1197",
  fullHash = "4d1197",
  text = "Handful of Oats (Classic). Handfuls of Oats are simple grains salvaged from the abandoned farmsteads of Westfall. They serve as essential feed for working livestock like Old Blanchy, who struggle under the weight of refugee travel. Once the breadbasket of the Kingdom of Stormwind, Westfall's vast agrarian plots now lie overgrown or overrun by Defias bandits and rogue harvest golems. Despite the collapse of order, sacks of cultivated grain and oats remain abandoned near outbuildings, barns, and overgrown plots. For travelers and refugees stranded by broken wagons along the dusty roads, recovering handfuls of these leftover oats is one of the few ways to nourish weary draft horses.",
  ["1"] = {
    {file = "Audio/Transport/full_item_handful-of-oats-classic-af9263ca7b41af206c0f/1-0000.mp3", duration = 38.7395918, start = 0},
  },
}
P.transport["item:handful-of-stardust"] = {
  hash = "5b16f4",
  fullHash = "5b16f4",
  text = "Handful of Stardust. Handfuls of Stardust are shimmering, frosted coatings gathered from sparkling bushes in the southern wilderness of Ashenvale. Sourced from the ancient Ruins of Stardust, this powder possesses cooling natural properties prized by night elven healers treating intense fevers. Found clinging to the leafy shrubs within the ancient Ruins of Stardust south of Astranaar, stardust appears as a fine, luminous frost. While the ruins themselves are haunted by lingering elemental spirits, the vegetation that thrives among the broken stones absorbs a rare ambient luminescence. Traditional night elven medicine makes use of this frosted residue, processing it into poultices to draw out persistent, dangerous fevers when ordinary salves and moonwell waters fail to bring complete relief.",
  ["1"] = {
    {file = "Audio/Transport/full_item_handful-of-stardust-1651df6a9d1b1db8c340/1-0000.mp3", duration = 44.0163265, start = 0},
  },
}
P.transport["item:hardened-tortoise-shell"] = {
  hash = "b3a140",
  fullHash = "b3a140",
  text = "Hardened Tortoise Shell. Hardened Tortoise Shells are remarkably durable carapaces harvested from the sparkleshell tortoises wandering the Shimmering Flats. Coveted by gnomish racers at the Mirage Raceway, these rugged organic plates offer unmatched resistance against volatile and corrosive experimental fuels. The sun-scorched expanse of the Shimmering Flats is home to various breeds of sparkleshell tortoises, including snappers and borers, whose carapaces have evolved into exceptionally tough defenses against the harsh desert salt and wandering predators. Out on the salt flats, standard metal alloy fuel tanks frequently corrode or rupture under the strain of gnomish experimental chemistry. Mechanics like Wizzle Brassbolts prize these shells not for armor or shields, but as organic raw material tough enough to be retrofitted into makeshift, acid-resistant fuel tanks capable of containing volatile rocket propellants.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hardened-tortoise-shell-893535749202d3a86423/1-0000.mp3", duration = 53.3681633, start = 0},
  },
}
P.transport["item:hardened-tumor"] = {
  hash = "993a7e",
  fullHash = "993a7e",
  text = "Hardened Tumor. A Hardened Tumor is a rare biological anomaly harvested from the Vile Fin murlocs dwelling around Lake Lordamere. Noted originally in the research of Apothecary Berard, now a mindless servant of Arugal, this calcified growth serves as an unusual reagent in the Royal Apothecary Society's efforts to brew the New Plague. While studying the indigenous wildlife along the eastern borders of Silverpine Forest, Apothecary Berard cataloged an abnormal, calcified growth developing within the Vile Fin murlocs of Lake Lordamere. Such growths are exceedingly rare, appearing only in mature specimens along the shoreline and the Dawning Isles. What causes the Vile Fin murlocs to produce these hardened masses remains uncertain, but their dense, morbid tissue caught the immediate attention of the Royal Apothecary Society.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hardened-tumor-8a7873d2b5c260a6621d/1-0000.mp3", duration = 48.4832653, start = 0},
  },
}
P.transport["item:harpy-lieutenant-ring"] = {
  hash = "33a679",
  fullHash = "33a679",
  text = "Harpy Lieutenant Ring. Harpy Lieutenant Rings are crude ornaments worn by the Witchwing Slayers in the Dry Hills of the northern Barrens. Carried as emblems of command among the flock, they serve as proof of death for Darsok Swiftdagger at the Crossroads. Within the matriarchal hierarchy of the Witchwing harpies, rank is ruthlessly maintained. While the rank-and-file raiders harrying the Barrens fight with little coordination, the Witchwing Slayers serve as field lieutenants directing assaults against Horde travelers. To distinguish themselves and assert authority over their underlings, these veteran slayers carry distinctive rings. For Darsok Swiftdagger and the defenders stationed at the Crossroads, severing these rings from fallen harpies is the only sure way to confirm that the flock's middle leadership has been broken.",
  ["1"] = {
    {file = "Audio/Transport/full_item_harpy-lieutenant-ring-802cc61e1de944442e50/1-0000.mp3", duration = 43.4416327, start = 0},
  },
}
P.transport["item:head-of-arugal"] = {
  hash = "ead1e1",
  fullHash = "ead1e1",
  text = "Head of Arugal. The Head of Arugal is the grisly trophy taken from the mad archmage atop Shadowfang Keep. Brought to the Forsaken at the Sepulcher, it serves as undeniable proof that the master of the local worgen has fallen. Archmage Arugal has long cast a dark shadow across Silverpine Forest, commanding the lupine horrors from the ramparts of Shadowfang Keep. Claiming his severed head is the ultimate mandate given by Dalar Dawnweaver at the Sepulcher. To the Forsaken, the head is far more than a gruesome token; it signifies the removal of a potent spellcaster whose feral beasts impeded Lady Sylvanas's complete dominion over Silverpine. Presenting it to Dawnweaver confirms that the rogue archmage's foul sorcery has finally been severed from the land.",
  ["1"] = {
    {file = "Audio/Transport/full_item_head-of-arugal-c47d72ae630d3ce145d4/1-0000.mp3", duration = 42.24, start = 0},
  },
}
P.transport["item:head-of-bazil-thredd"] = {
  hash = "b448f2",
  fullHash = "b448f2",
  text = "Head of Bazil Thredd. The severed head of Bazil Thredd serves as definitive proof that the leader behind the Stockade uprising has been eliminated. Demanded by Warden Thelwater, this grim trophy marks an end to the Defias Brotherhood's organized control over Stormwind's subterranean prison. When riots erupted throughout the Stockade beneath Stormwind City, Bazil Thredd quickly established himself as the rebellion's mastermind. Entrenched in his cell block among loyal Defias inmates, Thredd directed the chaos from deep within the dungeon walls. Distrustful of outsiders and struggling to maintain order, Warden Thelwater demanded Thredd's head as unambiguous evidence of his demise and as a test of the adventurer's true allegiance to Stormwind.",
  ["1"] = {
    {file = "Audio/Transport/full_item_head-of-bazil-thredd-ccf47ec3bdd39a891bfa/1-0000.mp3", duration = 40.1763265, start = 0},
  },
}
P.transport["item:head-of-deepfury"] = {
  hash = "7febd6",
  fullHash = "7febd6",
  text = "Head of Deepfury. The severed head of Kam Deepfury serves as grim proof that the Dark Iron conspirator behind the sabotaged Thandol Span has met his end. Slain within the riots of the Stormwind Stockade, his death fulfills a personal vendetta for the dwarven defenders of Dun Modr. Kam Deepfury was arrested and locked away in the Stormwind Stockade for political reasons, spared from immediate execution by human diplomatic bureaucracy. To the Ironforge mountaineers stationed at Dun Modr, this restraint was unacceptable. Intelligence uncovered by Roggo revealed that Deepfury orchestrated the devastating attack on the Thandol Span—an assault that cost the lives of King Magni's soldiers and the kin of Longbraid the Grim. Bound by duty to remain at his post, Motley Garmason commissioned Alliance champions to infiltrate the rioting prison and claim Deepfury's head, ensuring true dwarven vengeance was delivered where human diplomacy faltered.",
  ["1"] = {
    {file = "Audio/Transport/full_item_head-of-deepfury-8b66e5fb6f46fa3df167/1-0000.mp3", duration = 55.1183673, start = 0},
  },
}
P.transport["item:head-of-gath-ilzogg"] = {
  hash = "2df750",
  fullHash = "2df750",
  text = "Head of Gath'Ilzogg. The severed head of Gath'Ilzogg serves as indisputable proof that the Blackrock warlord has been slain. Claiming it breaks the leadership behind the siege of Stonewatch Keep and brings desperate relief to the town of Lakeshire. Gath'Ilzogg orchestrated the brutal Blackrock assault that overran Stonewatch Keep, driving out its defenders and subjecting the surrounding valley to relentless raiding. With Lakeshire on the verge of ruin and Stormwind offering virtually no military reinforcements, Magistrate Solomon posted a bounty upon the warlord's head. Slaying Gath'Ilzogg within the fortified upper levels of Stonewatch and claiming his head shatters the local Blackrock leadership, marking the first real step toward reclaiming the keep for the kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_item_head-of-gath-ilzogg-b0b5a76f1435bd4f38ea/1-0000.mp3", duration = 42.5795918, start = 0},
  },
}
P.transport["item:head-of-grimson"] = {
  hash = "88543e",
  fullHash = "88543e",
  text = "Head of Grimson. The Head of Grimson is the severed trophy taken from Grimson the Pale, the corrupted overseer of the Deep Elem Mine in Silverpine Forest. Brought to Dalar Dawnweaver at the Sepulcher, it serves as physical proof that the mine's leadership has been eliminated. Securing the mine allows the Forsaken to seize valuable mineral wealth to fuel Varimathras's military campaigns. While Dalar Dawnweaver studies Archmage Arugal's shadowy enchantments from the safety of the Sepulcher, Forsaken scouts known as Darkstalkers identified a strategic threat brewing in the southeastern hills. Arugal's dark magic had seeped into the Deep Elem Mine, corrupting its workers and driving its overseer, Grimson the Pale, into madness. To secure the subterranean riches for Varimathras's forces, Dawnweaver dispatched champions to cut down Grimson and return with his severed head as undeniable confirmation of the mine's liberation from rogue magics.",
  ["1"] = {
    {file = "Audio/Transport/full_item_head-of-grimson-e7b0309384a01fb1f661/1-0000.mp3", duration = 54.3869388, start = 0},
  },
}
P.transport["item:head-of-kelris"] = {
  hash = "52b956",
  fullHash = "52b956",
  text = "Head of Kelris. The severed head of Twilight Lord Kelris serves as undeniable proof that the leader of the Twilight's Hammer within Blackfathom Deeps has fallen. Carried out from the corrupted temple ruins, it is sought by representatives of the Argent Dawn to confirm the end of his profane ritual sacrifices. Within the submerged depths of the sunken Temple of Elune, Twilight Lord Kelris orchestrated dark sacrifices to Aku'mai, a monstrous servant of an Old God. Claiming his head marks the end of his tyrannical leadership over the Twilight's Hammer cultists and their naga allies in the cavern. The grisly trophy must be carried back to surface civilizations to assure leaders that Kelris's bloody ceremonies have finally ceased. For months, Kelris was presumed dead or lost by the Argent Dawn, only for his sinister influence to resurface alongside Kalimdor's encroaching shadows. When presented to agents in Darnassus or Thunder Bluff, the head settles lingering bounties and confirms that his attempts to plunge the world back into primeval chaos have been thwarted.",
  ["1"] = {
    {file = "Audio/Transport/full_item_head-of-kelris-33960facf4adb6cd4db3/1-0000.mp3", duration = 60.3167347, start = 0},
  },
}
P.transport["item:head-of-targorr"] = {
  hash = "7cb2af",
  fullHash = "7cb2af",
  text = "Head of Targorr. The Head of Targorr is the grim proof demanded by Guard Berton in Lakeshire to confirm the death of Targorr the Dread. Once the supreme executioner for the Blackrock warlord Gath'Ilzogg in the Redridge Mountains, the captured orc was sentenced to death in the Stormwind Stockade before suspicious political meddling halted his execution. Targorr the Dread gained infamy across Redridge as the brutal executioner serving under the Blackrock clan warlord Gath'Ilzogg. Responsible for torturing and slaughtering defenders of the Kingdom of Stormwind, Targorr was eventually captured and condemned to death within the Stormwind Stockade. However, bureaucratic intervention from Stormwind nobles mysteriously suspended the sentence, leading local guardsmen like Berton to suspect foul play and corruption in the capital. Fearing that Targorr might be used as a political pawn or somehow orchestrate an escape, Guard Berton commissioned an outside champion to breach the volatile prison and finish what the courts delayed. Severing Targorr's head bypassed the paralyzed legal system entirely, delivering closure to the grieving families and besieged defenders of Lakeshire who suffered under the executioner's blades.",
  ["1"] = {
    {file = "Audio/Transport/full_item_head-of-targorr-d54185aa44e526dcfb87/1-0000.mp3", duration = 67.2653061, start = 0},
  },
}
P.transport["item:head-of-vancleef"] = {
  hash = "65431a",
  fullHash = "65431a",
  text = "Head of VanCleef. The severed head of Edwin VanCleef serves as grim, irrefutable proof that the leader of the Defias Brotherhood has fallen. Brought back from the depths of the Deadmines to Sentinel Hill, it represents the hard-won vengeance of the People's Militia. For months, Edwin VanCleef directed the Defias Brotherhood's terror from the deepest sanctum of the Deadmines, shielded by heavily armed outlaws, goblin engineers, and a massive war juggernaut. Words alone could never convince the battered settlers of Westfall that their nightmare was over. Gryan Stoutmantle, leader of the People's Militia, demanded undeniable physical proof before declaring the countryside safe. Severing the ringleader's head and bringing it out into the daylight offers the exhausted defenders tangible assurance that the grand architect of their ruin will never threaten Westfall again.",
  ["1"] = {
    {file = "Audio/Transport/full_item_head-of-vancleef-2f87608482efc1a6c6ce/1-0000.mp3", duration = 48.1697959, start = 0},
  },
}
P.transport["item:heart-of-isha-awak"] = {
  hash = "97ba0c",
  fullHash = "97ba0c",
  text = "Heart of Isha Awak. The Heart of Isha Awak is taken from the mighty thresher known as Isha Awak, the Deep Doom of the Merchant Coast. Sought by the tauren seer Mahren Skyseer, it serves as proof of overcoming one of the ocean's most formidable predators. Off the sun-drenched shores of the Merchant Coast south of Ratchet dwells Isha Awak, a massive sea beast revered and feared by sailors and coastal inhabitants alike. Known as the Deep Doom, the creature has claimed the lives of numerous human trespassers along the shoreline. For the mystic Mahren Skyseer, however, the beast represents an honorable predator rather than a mindless menace. She believes Isha Awak's fierce spirit resides directly within its heart, charging brave hunters to plunge into the waves, best the beast in its domain, and claim the pulsating organ as both trophy and spiritual offering.",
  ["1"] = {
    {file = "Audio/Transport/full_item_heart-of-isha-awak-e6cd5fba0a4b4e51297e/1-0000.mp3", duration = 51.8530612, start = 0},
  },
}
P.transport["item:heartswood"] = {
  hash = "cb5c02",
  fullHash = "cb5c02",
  text = "Heartswood. Heartswood is timber harvested from a sacred tree rooted within the Ruins of Ordil'Aran in northwestern Ashenvale. Born from the final resting place of two ancient lovers, its resonance with undying devotion makes it an essential lure for summoning a succubus. The Heartswood grows among the elven stones of the Ruins of Ordil'Aran in northwestern Ashenvale. According to legend, two lovers named Anathera and Latherion fell side by side during the catastrophic War of the Ancients thousands of years ago. On the very earth where they breathed their last, a peculiar tree took root, blossoming as an eternal testament to their devotion. Even millennia later, the wood cut from this tree hums with the memory of undying passion, making it an object of great curiosity for those who study emotional and spiritual bonds.",
  ["1"] = {
    {file = "Audio/Transport/full_item_heartswood-fb2e3ff259fcdab190ca/1-0000.mp3", duration = 44.9567347, start = 0},
  },
}
P.transport["item:heartswood-core"] = {
  hash = "17894f",
  fullHash = "17894f",
  text = "Heartswood Core. The Heartswood Core is an enchanted ritual focus crafted from the wood of an ancient tree. Provided by Gakin the Darkbinder in Stormwind City, it channels the magic required to pierce the Twisting Nether and summon a succubus into an arcane summoning circle. Within the dark crypts beneath the Slaughtered Lamb tavern in Stormwind's Mage Quarter, warlocks conduct rites far away from the prying eyes of the city watch. The Heartswood Core serves as an essential arcane conduit for initiating the ritual of binding. Fashioned from harvested heartswood, the core contains sufficient lingering magical resonance to pierce the veil between worlds. By focusing their dark arts through the wood at a consecrated summoning circle, an initiate can tear open a passage to the Twisting Nether, compelling a succubus across the planar barrier.",
  ["1"] = {
    {file = "Audio/Transport/full_item_heartswood-core-0fb016bc4b1c00890054/1-0000.mp3", duration = 47.2032653, start = 0},
  },
}
P.transport["item:heavy-leaden-collection-phial"] = {
  hash = "f3314a",
  fullHash = "f3314a",
  text = "Heavy Leaden Collection Phial. The Heavy Leaden Collection Phial is a shielded sampling vessel provided by Ozzie Togglevolt in Kharanos. It is designed to safely siphon and contain highly unstable irradiated discharge from the mutants deep inside Gnomeregan for ongoing decontamination research. The Heavy Leaden Collection Phial is a sampling vessel used to draw volatile residues from living, irradiated creatures in Gnomeregan. Containing this fallout is difficult, and collecting a suitable sample may take several attempts. Ozzie Togglevolt provides the phial as part of his research to reverse the horrific mutations afflicting leper gnomes. Earlier samples taken from surface troggs lacked the potency needed for effective chemical analysis. By using the leaden phial on virulent beasts like irradiated slimes and lurkers in the Hall of Gears, researchers hope to isolate the active elements of the city's toxic fallout and formulate an effective antidote.",
  ["1"] = {
    {file = "Audio/Transport/full_item_heavy-leaden-collection-phial-e649a0227654fdabbb0f/1-0000.mp3", duration = 52.7412245, start = 0},
  },
}
P.transport["item:hezrul-s-head"] = {
  hash = "7d528f",
  fullHash = "7d528f",
  text = "Hezrul's Head. Hezrul's Head is the grisly trophy taken from Hezrul Bloodmark, chieftain of the Kolkar centaur dwelling in the Barrens. Brought to Regthar Deathgate west of the Crossroads, it serves as undeniable proof that the central leadership of the local marauders has fallen. The Kolkar centaur maintain an aggressive hold on the crucial oases throughout the arid Barrens, constantly threatening Horde supply routes and fledgling settlements. Hezrul Bloodmark directs his clan from the Lushwater Oasis to the south. Regthar Deathgate, an orc veteran tasked with securing the territory west of the Crossroads, recognizes that while the Kolkar possess fierce rage, they lack formal discipline. By demanding Hezrul's severed head, Regthar seeks to fracture the clan's command structure, plunging their surviving fighters into disarray and blunting their coordinated assaults against the Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hezrul-s-head-e586752e0b86ef206d8f/1-0000.mp3", duration = 50.964898, start = 0},
  },
}
P.transport["item:high-potency-radioactive-fallout"] = {
  hash = "502ce5",
  fullHash = "502ce5",
  text = "High Potency Radioactive Fallout. High Potency Radioactive Fallout is a concentrated, volatile sample of the irradiated sludge poisoning the lower depths of Gnomeregan. Gathered in heavy leaden containers by order of gnome researchers, it is sought in the hope of reverse-engineering a cure for the afflicted leper gnomes. While minor radiation samples can be scraped from contaminated surface scavengers outside, the true heart of Gnomeregan's catastrophe demands something far more concentrated. Researchers stationed outside the fallen capital require raw, unadulterated radioactive fallout taken directly from living irradiated horrors, lurkers, and slimes creeping across the lowest tiers of the Hall of Gears. Because this viscous sludge is constantly decaying, it must be contained in a specialized leaden phial and returned quickly before the sample destabilizes entirely. The desperate pursuit of such lethal materials serves an urgent purpose. Ozzie Togglevolt and his colleagues believe that unlocking the secrets of the irradiated sludge is the only viable path toward developing a cure for the leper gnomes. Driven mad and deformed by the toxic venting ordered during the trogg invasion, these tragic survivors remain trapped in a living nightmare, making even the most dangerous gathering expeditions inside the ruins worth the hazard.",
  ["1"] = {
    {file = "Audio/Transport/full_item_high-potency-radioactive-fallout-22a4c9c236b26dc8c0f4/1-0000.mp3", duration = 73.0383673, start = 0},
  },
}
P.transport["item:highborne-relic-classic"] = {
  hash = "7b2432",
  fullHash = "7b2432",
  text = "Highborne Relic (Classic). Highborne Relics are ancient magical implements recovered from the restless spirits haunting the ruins of Ameth'Aran in Darkshore. Imbued with the arcane dabblings that shattered ancient Kalimdor, they are sought by night elf scholars who wish to see them destroyed before their dormant powers can cause further harm. Ten thousand years ago, the Highborne caste practiced reckless arcane magic, ultimately bringing ruin upon ancient Kalimdor. Today, their former estates lie in shattered ruin across Darkshore. Within the crumbling columns of Ameth'Aran, wailing and writhing apparitions wander the forest floor, endlessly clinging to the physical implements of their bygone sorcery. These relics remain persistent tether-points of arcane taint, clutched by ghosts who refuse to release the instruments of their own undoing. For modern night elf society, which largely renounced arcane magic after the Great Sundering, such artifacts represent a grave hazard. Scholars like Thundris Windweaver in Auberdine, acting upon scouting reports from the Sentinels, actively commission travelers to wrest these relics from the spectral hands of the cursed spirits. Once gathered, the relics are systematically destroyed to ensure that the ancient evils and catastrophic mistakes of the Highborne cannot be repeated.",
  ["1"] = {
    {file = "Audio/Transport/full_item_highborne-relic-classic-719cfd0f5a61bd265a56/1-0000.mp3", duration = 73.0383673, start = 0},
  },
}
P.transport["item:highperch-venom-sac"] = {
  hash = "4c89d7",
  fullHash = "4c89d7",
  text = "Highperch Venom Sac. Highperch Venom Sacs are harvested from the wild wyverns nesting upon the towering spires of Highperch in Thousand Needles. While orcs prize wyverns as aerial mounts, select apothecaries and traders value their potent stingers even more than the living beasts. The high spires of Thousand Needles house thriving prides of wild wyverns, particularly around the elevated crags of Highperch. These winged predators rely on powerful venom delivered through their barbed tails to paralyze and kill prey. While the Horde often domesticates these creatures as loyal wind riders, their venom sacs command a remarkably high price among alchemists, hunters, and opportunistic merchants across Kalimdor. Though native to the deep canyons of central Kalimdor, this venom draws interest far beyond them. In the port town of Theramore, the high elf Fiora Longears pays handsomely for fresh sacs collected from Highperch's broods. She seeks samples swollen with venom—typically found only on young wyverns or fertile females—fueling trade in dangerous reagents far from the beasts' natural desert habitat.",
  ["1"] = {
    {file = "Audio/Transport/full_item_highperch-venom-sac-11709f6529d498fe93b7/1-0000.mp3", duration = 62.0669388, start = 0},
  },
}
P.transport["item:highperch-wyvern-egg"] = {
  hash = "e9d223",
  fullHash = "e9d223",
  text = "Highperch Wyvern Egg. Highperch Wyvern Eggs are clutch eggs gathered from the nesting grounds atop the high mesas of Thousand Needles. They are sought after by aspiring Horde wind riders to raise and train new aerial mounts. The high plateau of Highperch in Thousand Needles provides a natural sanctuary for native wyverns to roost and raise their young. Accessible only via steep winding paths up the canyon walls, these nesting grounds are fiercely guarded by adult beasts. The eggs laid among these roosts are sturdy and warm, holding developing hatchlings capable of adapting to the harsh skies of Kalimdor. Across Kalimdor, the demand for trained wyverns continually outstrips supply as the Horde expands its courier and scouting networks. At Freewind Post, trainees like the tauren Elu seek out intact eggs directly from wild aeries. By raising the hatchlings from their shells, handlers hope to forge the deep bonds required to train trustworthy winged mounts for the Horde's wind riders.",
  ["1"] = {
    {file = "Audio/Transport/full_item_highperch-wyvern-egg-2e9557c118ee67b8a360/1-0000.mp3", duration = 56.3983673, start = 0},
  },
}
P.transport["item:hildelve-s-journal"] = {
  hash = "80ca8a",
  fullHash = "80ca8a",
  text = "Hildelve's Journal. Hildelve's Journal is the final record of dwarven pilot Hildelve, recovered from his remains in the frigid wilderness of Dun Morogh. Its bloodstained pages recount his fatal encounter with a ferocious bear and convey his dying wish for vengeance. When his steam tank broke down, dwarven pilot Hildelve left his partner Hammerfoot with the tanks and set out alone into the snow-swept crags of Dun Morogh in search of rumored chiron ore. According to the entries scrawled in his journal, he was stalked for days and then ambushed by a monstrous ice claw bear known as Mangeclaw. Though Hildelve fought bravely and managed to drive the beast off, he was left gravely mauled and stranded in the bitter cold. The journal details his agonizing final hours, concluding with a single, clear plea before the predator returned to finish him: that whoever discovered his body avenge his death by hunting down Mangeclaw.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hildelve-s-journal-90f6edc09ffb4c75f852/1-0000.mp3", duration = 52.5844898, start = 0},
  },
}
P.transport["item:hillsbrad-human-skull"] = {
  hash = "0d9986",
  fullHash = "0d9986",
  text = "Hillsbrad Human Skull. A gruesome war trophy harvested from slain human defenders and townsfolk across the Hillsbrad Foothills. These skulls are collected by Forsaken stationed at Tarren Mill as grim mementos of the relentless assault against the local human settlements. As conflict rages between the Forsaken of Tarren Mill and the human inhabitants of Southshore and surrounding settlements, severed skulls serve as physical proof of the slaughter. While Deathstalkers and soldiers carry out the systematic purge ordered by Darthalia during the Battle of Hillsbrad, other guards stuck on watch duty crave a piece of the carnage. Deathguard Samsa eagerly solicits these trophies from frontline fighters, taking twisted pleasure in amassing the remains of the very people the Forsaken once lived among in life.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hillsbrad-human-skull-b6585f0795be5f888bed/1-0000.mp3", duration = 44.2514286, start = 0},
  },
}
P.transport["item:hillsbrad-town-registry"] = {
  hash = "2ddaea",
  fullHash = "2ddaea",
  text = "Hillsbrad Town Registry. The Hillsbrad Town Registry is an official municipal ledger kept inside the town hall of the Hillsbrad Fields. It serves as an accounting of the settlement's surviving citizens, landowners, and civic records, making it a key strategic target during the Forsaken offensive against the human stronghold. Resting in the town hall near the podium of Magistrate Burnside, the Hillsbrad Town Registry documents the population, households, and administrative rights of Hillsbrad. As the Forsaken from Tarren Mill push to break human resistance in the foothills, Darthalia commands Horde champions to infiltrate the town hall, eliminate the council, and seize this ledger. Confiscating the registry strips Hillsbrad of its civic order and provides the Undercity with valuable intelligence on the surviving population and their assets.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hillsbrad-town-registry-611916c7a41b88377a9b/1-0000.mp3", duration = 45.3746939, start = 0},
  },
}
P.transport["item:hollow-vulture-bone"] = {
  hash = "58f904",
  fullHash = "58f904",
  text = "Hollow Vulture Bone. Hollow Vulture Bones are lightweight, durable skeletal remains harvested from the scavengers of the Shimmering Flats. At the Mirage Raceway, goblin mechanics prize them as specialized building materials to lighten their rocket cars without sacrificing structural integrity. Speed is everything out on the salt, and weight is the enemy of speed. While standard engineering leans heavily on iron and copper, the goblin pit crews at the Mirage Raceway turn to whatever the desert provides to gain an edge. Vulture bones are naturally hollow yet remarkably sturdy, providing the perfect strength-to-weight ratio for internal brackets, steering rigs, and minor structural supports. For chief tinkerers like Pozzik, harvesting bones from local scavengers is a practical and cheap shortcut to shaved seconds on the track.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hollow-vulture-bone-6179c93d1936200c4703/1-0000.mp3", duration = 44.4081633, start = 0},
  },
}
P.transport["item:honorary-picks"] = {
  hash = "c79f74",
  fullHash = "c79f74",
  text = "Honorary Picks. The Honorary Picks are a bundle of ceremonial tools crafted in Ironforge for young dwarven mining apprentices. Entrusted to travelers by way of the gryphon network, they are delivered to Brock Stoneseeker in Thelsamar to mark his students' readiness to work the rich ore veins of Loch Modan. In dwarven society, mining is far more than a trade; it is a cultural cornerstone that keeps the great forges burning and the kingdom supplied with iron and stone. The Honorary Picks represent formal recognition for novice prospectors learning under Brock Stoneseeker in Thelsamar. Sourced directly from Ironforge, these picks are presented to students who have proven their dedication and are ready to tackle the open ore deposits across Loch Modan. Transporting the picks serves a secondary purpose for the mountaineers and merchants of the Alliance: introducing couriers to the kingdom's gryphon network. Ferried from Ironforge's Great Forge directly to Gryth Thurden and flown across the mountains to Thorgrum Borrelson in Thelsamar, the shipment illustrates how closely tied the capital remains to its outlying outposts through swift aerial passage.",
  ["1"] = {
    {file = "Audio/Transport/full_item_honorary-picks-88c0c20d6978ca4094ac/1-0000.mp3", duration = 62.5632653, start = 0},
  },
}
P.transport["item:horn-of-arra-chea"] = {
  hash = "c1e971",
  fullHash = "c1e971",
  text = "Horn of Arra'chea. The Horn of Arra'chea is a hunting trophy taken from the legendary kodo Arra'chea, who wanders the plains of Mulgore. Claimed at the behest of High Chieftain Cairne Bloodhoof, the horn serves as definitive proof that an aspiring hunter has the discipline and tracking prowess to provide for the Shu'halo. Though passing the initial Rites of the Earthmother grants a youth their rightful place atop Thunder Bluff, High Chieftain Cairne Bloodhoof expects his people to continually prove their worth. For the tauren, identity is bound directly to the hunt and their enduring harmony with the land. Cairne tests young hunters by tasking them with tracking down Arra'chea, a massive, lone kodo bull roaming the grasslands below. Taking Arra'chea's horn proves mastery over the fundamental art of tracking prey across vast distances. Bringing the horn to the high rise of Thunder Bluff is more than a display of martial strength; it serves the survival of the entire community. In tauren culture, nothing of a slain beast is allowed to go to waste. Presenting the trophy alerts the High Chieftain to the fallen beast's location, allowing gathering parties to quickly depart down into the plains to harvest Arra'chea's thick hide and rich meat for the fledgling capital.",
  ["1"] = {
    {file = "Audio/Transport/full_item_horn-of-arra-chea-2ba8ff3f30b589358482/1-0000.mp3", duration = 67.84, start = 0},
  },
}
P.transport["item:horn-of-awakening"] = {
  hash = "e3cd7d",
  fullHash = "e3cd7d",
  text = "Horn of Awakening. The Horn of Awakening is a sounding instrument kept in a chest by Kerlonian Evershade in southern Darkshore. It is used to rouse the drowsy druid whenever he collapses into a slumber on the road to Ashenvale. Kerlonian Evershade, a Druid of the Claw recently awoken from centuries inside the Emerald Dream, finds himself persistently lethargic in the waking realm. Journeying south toward Maestra's Post, he entrusts this horn to travelers willing to escort him. Whenever exhaustion overtakes him along the perilous wilderness trail, a clear blast from the instrument jolts his senses, prodding him back to his feet before wild beasts or cultists can seize upon his slumber.",
  ["1"] = {
    {file = "Audio/Transport/full_item_horn-of-awakening-42a1750fb6e8149e9660/1-0000.mp3", duration = 38.8179592, start = 0},
  },
}
P.transport["item:horn-of-echeyakee"] = {
  hash = "24491d",
  fullHash = "24491d",
  text = "Horn of Echeyakee. The Horn of Echeyakee is a hunting instrument provided by Sergra Darkthorn at the Crossroads. Sounding it among the ancient kodo remains northeast of the settlement calls forth Whitemist, the legendary white predator of the Barrens. Given to initiates testing their prowess in the hunt, the horn's call echoes across the savannah to summon Echeyakee, whose name translates from Taur-ahe as 'Whitemist.' Known as the king of the savannah cats, Echeyakee is revered by tauren hunters as both mercy and death, striking so swiftly that his quarry feels neither terror nor suffering. The horn is meant to be sounded only at the great predator's lair, a sun-bleached nest of giant kodo bones tucked behind the hills northeast of the Crossroads.",
  ["1"] = {
    {file = "Audio/Transport/full_item_horn-of-echeyakee-cdb735c8bf1c7a26327b/1-0000.mp3", duration = 42.004898, start = 0},
  },
}
P.transport["item:huge-gnoll-claw"] = {
  hash = "dc5e58",
  fullHash = "dc5e58",
  text = "Huge Gnoll Claw. The Huge Gnoll Claw is an unmistakable trophy taken from Hogger, the massive gnoll prowling southwestern Elwynn Forest. Sized far beyond any normal gnoll talon, it serves as the official proof of demise required by the Stormwind authorities in Goldshire. For months, the brute Hogger has terrorized the southern woodlands of Forest's Edge, shrugging off patrols and overwhelming every effort by the local garrison to corral or subdue him. Outmatched and stretched thin across Elwynn, the Stormwind Army posted an open bounty on the beast's head. Marshal Dughan at Goldshire demands undeniable evidence before disbursing the reward funds, and the brute's oversized claw offers undisputed confirmation that the terror of the woods has finally fallen.",
  ["1"] = {
    {file = "Audio/Transport/full_item_huge-gnoll-claw-27e2856339a1e06b4c0e/1-0000.mp3", duration = 42.7363265, start = 0},
  },
}
P.transport["item:humbert-s-sword"] = {
  hash = "038614",
  fullHash = "038614",
  text = "Humbert's Sword. Humbert's Sword is the personal sidearm belonging to Deathguard Humbert of Tarren Mill. The weapon was looted from his camp by dwarven soldiers while he was scouting their stronghold at Dun Garok. Deathguard Humbert was dispatched by High Executor Darthalia to monitor the dwarven presence at Dun Garok from a concealed position. While he left his post unattended one morning to collect firewood to boil water, dwarven patrols stumbled across his campsite and plundered all of his gear, including his personal blade. With so many dwarves to search, Humbert relies on Horde agents to infiltrate the fortress and retrieve his lost weapon. Following the theft, Humbert's belongings were carried back behind the fortified barricades of Dun Garok. Because dwarven riflemen, mountaineers, and priests circulate supplies throughout the garrison, locating the specific thief requires searching among the defenders stationed within the stronghold's trenches and redoubts.",
  ["1"] = {
    {file = "Audio/Transport/full_item_humbert-s-sword-4e3eb635ff54a8eeb425/1-0000.mp3", duration = 52.9502041, start = 0},
  },
}
P.transport["item:hyacinth-mushroom"] = {
  hash = "347d8b",
  fullHash = "347d8b",
  text = "Hyacinth Mushroom. Hyacinth Mushrooms are distinctive fungi found sprouting at the roots of trees throughout Shadowglen on Teldrassil. Prized by local night elf herbalists for their medicinal properties, they also happen to be favored food and forage for the mischievous grell and grellkin. Hyacinth Mushrooms grow abundantly across Shadowglen, flourishing in the damp shadows at the bases of trees, mossy stones, and the sprawling roots of Aldrassil. While useful in woodland remedies, they have also caught the attention of the corrupted grell, who frequently hoard them. When young night elf sentinels or trainees are afflicted by local venomous fauna—such as the spiders of Shadowthread Cave—these mushrooms serve as a core component in soothing draughts and antivenoms concocted by forest healers.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hyacinth-mushroom-430abef8d433ce804888/1-0000.mp3", duration = 45.6097959, start = 0},
  },
}
P.transport["item:hypercapacitor-gizmo"] = {
  hash = "9e5c90",
  fullHash = "9e5c90",
  text = "Hypercapacitor Gizmo. The Hypercapacitor Gizmo is an eccentric piece of engineering recovered from the canyon floor of Thousand Needles. Once dangling from the neck of a caged beast in a ruined caravan, its true purpose remains a mystery even to the tinkerer who claims to own it. When centaur marauders ambushed a goblin caravan traveling through Thousand Needles, they plundered nearly everything in sight. The sole survivor, Wizlo Bearingshiner, managed to crawl his way to safety at Whitereach Post, leaving behind his best gizmo: the Hypercapacitor Gizmo. Strangely, the gadget wound up secured around the neck of a ferocious, enraged panther locked inside a transport cage. The raiding centaur feared the beast enough to leave the cage entirely alone amidst the burning wreckage, unwittingly preserving Wizlo's odd machine. While Wizlo proudly calls the device his best gizmo, he admits upon its recovery that he has no real idea what it actually does. Like many goblin contraptions, the Hypercapacitor Gizmo is a tangled mass of ambition and volatile parts, destined to keep its owner occupied with endless tinkering rather than serving any practical, understood function.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hypercapacitor-gizmo-a86b2a2e9b0cab8c598f/1-0000.mp3", duration = 67.1085714, start = 0},
  },
}
P.transport["item:ignition-key"] = {
  hash = "af6945",
  fullHash = "af6945",
  text = "Ignition Key. The Ignition Key is an essential control key carried by Supervisor Lugwizzle at the Venture Company's drilling operation in Sludge Fen. It is required to unlock the steering column and activate the controls of an advanced Venture Company shredder. When Sputtervalve of Ratchet dispatched an operative to steal a proprietary Venture Company shredder from Sludge Fen, things did not go smoothly. The undercover pilot, Wizzlecrank, managed to slip into the machine's cockpit only to find its movement column completely locked down. To keep suspicious foremen from catching on, he feigned mechanical troubles while awaiting an adventurer to retrieve the necessary Ignition Key. The key remains held under lock and key by Supervisor Lugwizzle high atop the central oil derrick, controlling access to the machine's state-of-the-art arm, speed, and rotation mechanisms.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ignition-key-57391efeb701ee11c618/1-0000.mp3", duration = 46.3412245, start = 0},
  },
}
P.transport["item:ilkrud-magthrull-s-tome"] = {
  hash = "af18cd",
  fullHash = "af18cd",
  text = "Ilkrud Magthrull's Tome. Ilkrud Magthrull's Tome is a grimoire recovered from a dangerous orc warlock residing within the corrupted depths of Ashenvale. Brought to Delgren the Purifier, its foul contents reveal the broader dark dealings surrounding the cultists operating out of the Tower of Althalaxx. Ilkrud Magthrull is a formidable orc warlock entrenched at the Fire Scar Shrine in southwestern Ashenvale, a site poisoned by lingering demonic influence. Surrounded by summoned minions, Magthrull recorded his foul rituals and shadowy communications within this personal tome. While the Argent Dawn paladin Delgren the Purifier had long known of the warlock's presence, the uncovered links between Magthrull and the dark cultists gathering at the Tower of Althalaxx made recovering the book an urgent priority.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ilkrud-magthrull-s-tome-15eea54ee7828e15d375/1-0000.mp3", duration = 45.1395918, start = 0},
  },
}
P.transport["item:incantations-from-the-nether"] = {
  hash = "bf5325",
  fullHash = "bf5325",
  text = "Incantations from the Nether. Incantations from the Nether is a grimoire of demonic magic held by the Searing Blade cultists lurking beneath Orgrimmar. Sylvanas Windrunner and her dreadlord lieutenant, Varimathras, seek to claim the tome to harness its fel knowledge for the Forsaken. Beneath the red stone streets of Orgrimmar, the Searing Blade—a subterranean sect tied to the Shadow Council—operates in the fiery tunnels of Ragefire Chasm. Among their darkest treasures is the Incantations from the Nether, a spellbook laden with demonic rites bestowed by agents of the Burning Legion. While the cultists use its vile secrets to plot treason within the Orcish capital, word of the text reached far across the sea to the royal quarters of Undercity.",
  ["1"] = {
    {file = "Audio/Transport/full_item_incantations-from-the-nether-f23562c68bb36da192f7/1-0000.mp3", duration = 42.004898, start = 0},
  },
}
P.transport["item:incendia-agave"] = {
  hash = "e96489",
  fullHash = "e96489",
  text = "Incendia Agave. Incendia Agave is a rare, spiky aquatic plant native to the Boiling Pool beneath Darkcloud Pinnacle in Thousand Needles. When enchanted by a skilled shaman, its unique properties allow it to kindle the sacred fire of life. Growing beneath and around the waters of the Boiling Pool in Thousand Needles, Incendia Agave thrives directly in the shadow of Darkcloud Pinnacle. Guarded naturally by wandering steam elementals, the plant is difficult to harvest and scarce across Kalimdor. Despite growing submerged in water, it contains potent natural elements that lend themselves directly to rituals of flame.",
  ["1"] = {
    {file = "Audio/Transport/full_item_incendia-agave-3191a4dc53071082dd68/1-0000.mp3", duration = 36.3363265, start = 0},
  },
}
P.transport["item:incendia-powder"] = {
  hash = "3170b2",
  fullHash = "3170b2",
  text = "Incendia Powder. Incendia Powder is an enchanted ritual catalyst refined to ignite sacred flames. Carried by Horde emissaries into Thousand Needles, the powder is specifically treated with shamanic incantations to invoke the slumbering spirit-beast Arikara atop Darkcloud Pinnacle. Incendia Powder is no mundane explosive or mundane flash powder; it is a purified, ritualistic substance carefully infused with shamanic magic. Enchanted and entrusted to travelers by Magatha Grimtotem on Thunder Bluff's Elder Rise, the mixture is designed to react solely with the dormant sacred fire of life atop the isolated spires of Darkcloud Pinnacle. Once scattered across the consecrated brazier where the dead are laid to rest, its alchemical and spiritual warding calls forth the vengeful winged serpent Arikara.",
  ["1"] = {
    {file = "Audio/Transport/full_item_incendia-powder-cc773aff11636c62f45d/1-0000.mp3", duration = 46.8114286, start = 0},
  },
}
P.transport["item:insane-scribbles"] = {
  hash = "d43965",
  fullHash = "d43965",
  text = "Insane Scribbles. Torn from the baffling Twilight Tome, these Insane Scribbles are a fragment of dark literature carried by cultists in Darkshore. Merely looking at the dancing text and distorted scrollwork induces severe dizziness and mental strain. Ancient protectors of the forest study such fragments to decipher the sinister motives of the Twilight's Hammer. Gazing upon the pages of the Twilight Tome proves profoundly hazardous to mortal sanity. The script writhes across the parchment, while graceful scrollwork warps into grotesque, unsettling imagery before the reader's eyes. Tearing loose even a single sheet—these Insane Scribbles—is an ordeal that leaves the bearer lightheaded and disoriented. Despite the chaotic incoherence of the script, the parchment hums with a primal, deeply ancient magic tied directly to dark powers long buried beneath Azeroth.",
  ["1"] = {
    {file = "Audio/Transport/full_item_insane-scribbles-cc5d9bd5c6019ac6a717/1-0000.mp3", duration = 48.1697959, start = 0},
  },
}
P.transport["item:inscribed-bark"] = {
  hash = "a5fd35",
  fullHash = "a5fd35",
  text = "Inscribed Bark. Inscribed Bark is a living parchment entrusted by the ancient Oracle Tree to carry word of Teldrassil's state to Arch Druid Fandral Staghelm. It serves as an official report on the boughs of the World Tree and the lingering threats troubling its woods. Carved from the sacred wood of the Oracle Tree, this inscribed bark acts as a direct communique between the ancient guardian and the leadership of the Cenarion Circle in Darnassus. After adventurers suppress the encroaching harpies in the glades, the Oracle Tree entrusts them with this token, reluctant to risk ordinary couriers through the tainted paths of the boughs. The inscribed message informs Arch Druid Fandral Staghelm of both recent victories and the deeper, unsettling blight that continues to grip Teldrassil.",
  ["1"] = {
    {file = "Audio/Transport/full_item_inscribed-bark-46de3eef25084788080a/1-0000.mp3", duration = 45.2179592, start = 0},
  },
}
P.transport["item:intact-raptor-horn"] = {
  hash = "1f8a46",
  fullHash = "1f8a46",
  text = "Intact Raptor Horn. An intact horn harvested from the predatory raptors stalking the savannas of the Barrens. Kept in pristine condition, it is coveted by an entrepreneurial goblin looking to tap into rumors of raptor intelligence. While common hunters value raptor parts for hides, talons, and trophies, unbroken horns are harder to come by in the field. In the port town of Ratchet, an eccentric goblin alchemist named Mebok Mizzyrix has formulated a wild theory regarding local wildlife: because the raptors of the Barrens display cunning beyond their kin elsewhere, he suspects their intellect resides directly within their headgear. By grinding whole horns down and brewing them into tonic concoctions, Mebok aims to bottle this perceived genius into commercial 'smart drinks.' Pristine horns cannot simply be chipped off any juvenile beast. To yield viable material for brewing, hunters must take them from particularly vicious predators, such as the Sunscale Scytheclaws that prowl the southern plains and the northern borders near Ashenvale. Notable legendary terrors of the veldt, such as Takk the Leaper and the elusive Ishamuhale, also bear horns stout enough to survive the clash of the hunt intact.",
  ["1"] = {
    {file = "Audio/Transport/full_item_intact-raptor-horn-bf94b8940805cae66370/1-0000.mp3", duration = 68.075102, start = 0},
  },
}
P.transport["item:intrepid-strongbox-key"] = {
  hash = "f23270",
  fullHash = "f23270",
  text = "Intrepid Strongbox Key. The Intrepid Strongbox Key is a rusted iron key once guarded jealously by Captain Halyndor, commander of the doomed Alliance vessel Intrepid. Even in undeath, the captain clutches it, keeping locked away the cursed artifact that brought ruin to his crew off the coast of the Wetlands. During the wreck of the Third Fleet off the stormy shores of the Wetlands, the warship Intrepid was cast into ruin, its crew twisted into restless, cursed spirits. Captain Halyndor obsessively watched over a mysterious item stowed inside the vessel's heavy strongbox. In death, his spectral figure continues to prowl the waterlogged deck, refusing to relinquish the rusted key that unlocks the hold's deepest, darkest cargo.",
  ["1"] = {
    {file = "Audio/Transport/full_item_intrepid-strongbox-key-cf87ac0b78c5cef50df1/1-0000.mp3", duration = 42.1616327, start = 0},
  },
}
P.transport["item:invisibility-liquor"] = {
  hash = "cd07bf",
  fullHash = "cd07bf",
  text = "Invisibility Liquor. Invisibility Liquor is a potent, alchemically infused brew crafted using rare Crystal Kelp Fronds found in Elwynn Forest. Designed to render its drinker unseen for a brief window, it serves as the linchpin in a clandestine plot allowing two star-crossed young lovers to bypass their feuding families. The ongoing feud between the Stonefields and the Maclures makes peaceful contact between their households nearly impossible. When young Tommy Joe Stonefield seeks to meet with Maybell Maclure away from the watchful eyes of their kin, conventional secrecy falls short. Invisibility Liquor provides an uncanny solution: an alcoholic draught that bends sight around the imbiber, granting just enough stealth to slip across disputed farmland undetected.",
  ["1"] = {
    {file = "Audio/Transport/full_item_invisibility-liquor-fb208197b0c4e4b547ed/1-0000.mp3", duration = 43.3632653, start = 0},
  },
}
P.transport["item:iron-pike"] = {
  hash = "386812",
  fullHash = "386812",
  text = "Iron Pike. Iron Pikes are sturdy construction materials originally shipped from Stormwind to aid in repairing the Everstill Bridge in Lakeshire. The shipment was ambushed and looted by Redridge gnolls, leaving the town short on essential rebuilding supplies. When Lakeshire faced recent attacks from the Blackrock orcs, the town's metal reserves were melted down to forge armor, blades, and ammunition for defense. In response to the shortage, local builders requested a resupply shipment of iron from Stormwind City. Before the materials could reach the town, a pack of Redridge gnolls hijacked the transport caravan along the road. The gnolls dragged crates of iron pikes and rivets north into the hills, halting critical repairs on the Everstill Bridge. Foreman Oslow, charged with overseeing the reconstruction of the Everstill Bridge, relies on adventurers to enter gnoll territory and reclaim the pilfered hardware. Without these heavy iron pikes to reinforce the stone and timber framework, Lakeshire remains partially severed from the northern roadway and vulnerable to further incursions.",
  ["1"] = {
    {file = "Audio/Transport/full_item_iron-pike-d48b992eacf88ffd4af7/1-0000.mp3", duration = 60.3167347, start = 0},
  },
}
P.transport["item:iron-pommel"] = {
  hash = "a217c5",
  fullHash = "a217c5",
  text = "Iron Pommel. The Iron Pommel is the final missing fragment of Dartol's Rod, a rod created by the long-dead wizard Dartol and sought by the night elves of Astranaar to slow the furbolg attacks on their people. Entrusted to the druids of the Dor'Danil Barrow Den for safekeeping, it was lost when their sanctuary was slaughtered and overrun by oozes. Dartol's Rod was divided and scattered across Ashenvale to protect its mystic power. The Iron Pommel was placed into the care of the night elf druids dwelling near the road winding south toward the Barrens. Tragedy struck the secluded enclave at the Dor'Danil Barrow Den when the circle was massacred, their tranquil shelter falling into ruined silence. The pommel vanished into the aftermath, swallowed by the grotesque, bubbling oozes that now shamble through the defiled glade.",
  ["1"] = {
    {file = "Audio/Transport/full_item_iron-pommel-c4a3271f0357c5d56453/1-0000.mp3", duration = 45.9232653, start = 0},
  },
}
P.transport["item:iron-rivet"] = {
  hash = "40b036",
  fullHash = "40b036",
  text = "Iron Rivet. Iron Rivets are sturdy construction fasteners manufactured in Stormwind to help rebuild the ruined Everstill Bridge in Lakeshire. After a supply caravan was ambushed and looted by Redridge gnolls, these heavy metal components ended up scattered across the gnoll camps in the northern hills. When Lakeshire faced repeated assaults from the Blackrock orcs, the town council was forced to melt down their structural iron reserves to forge urgent weapons, armor, and munitions. Once the immediate crisis subsided, Foreman Oslow requested fresh building supplies from Stormwind to mend the fractured Everstill Bridge. However, the supply caravan ferrying the shipment was ambushed by local Redridge gnolls before reaching the town. The pack beasts and wagons were dragged into the hills north of Lake Everstill, scattering essential construction materials like iron rivets and pikes among the gnoll packs. Without these heavy iron rivets, structural repairs on the Everstill Bridge cannot proceed safely. The stone and timber framework spanning the lake requires reinforced metal fasteners to withstand the weight of carts and travelers. Recovering the rivets directly from the gnoll camps is essential for restoring Lakeshire's vital link to the western valleys and securing the town's perimeter against further incursions.",
  ["1"] = {
    {file = "Audio/Transport/full_item_iron-rivet-bf442a77a028687d7676/1-0000.mp3", duration = 71.9934694, start = 0},
  },
}
P.transport["item:iron-shaft"] = {
  hash = "e7ccfe",
  fullHash = "e7ccfe",
  text = "Iron Shaft. The Iron Shaft is a metallic segment of Dartol's Rod, a relic Raene Wolfrunner's friend Teronis sought in hopes of slowing the furbolg assaults on Ashenvale. Recovered from a locked chest near the border of Felwood, it serves as a crucial component in restoring the relic for the defenders of Ashenvale. Dartol's Rod was the creation of Dartol, and its pieces were scattered across Ashenvale; one was even given to the druids of Dor'Danil for safekeeping. The Iron Shaft represents the sturdy metal core of the instrument, secured away inside a locked chest in a secluded glade near the northern border of Ashenvale, not far from the tainted realm of Felwood.",
  ["1"] = {
    {file = "Audio/Transport/full_item_iron-shaft-cc9b4d3a28582aef2c59/1-0000.mp3", duration = 37.2244898, start = 0},
  },
}
P.transport["item:ironband-s-progress-report"] = {
  hash = "b1a955",
  fullHash = "b1a955",
  text = "Ironband's Progress Report. Ironband's Progress Report is a written dispatch detailing the troubles facing Prospector Ironband's excavation site in eastern Loch Modan. It conveys both an account of slow digging hindered by aggressive troggs and an urgent plea for more blastpowder. Prospector Ironband's excavation in Loch Modan faces continuous disruption from local troggs. To keep the project moving forward, Ironband compiled this progress report to restate his desperate need for blastpowder. Carried first to Jern Hornhelm in Thelsamar and then forwarded to the Assembly of Explorers in Ironforge, the report documents the site's stalls while requesting heavy munitions. The dispatch quickly raises eyebrows among league leadership, as an ample supply of blastpowder was dispatched to Ironband weeks prior, leaving superiors wondering where the previous shipments vanished.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ironband-s-progress-report-d2893673d626b056c3ed/1-0000.mp3", duration = 48.1697959, start = 0},
  },
}
P.transport["item:ishamuhale-s-fang"] = {
  hash = "b87f14",
  fullHash = "b87f14",
  text = "Ishamuhale's Fang. Ishamuhale's Fang is a hunting trophy taken from Ishamuhale, the notorious sunscale raptor known as Speartooth in the Barrens. Brought to Jorn Skyseer at Camp Taurajo, the tooth serves as proof of besting one of Kalimdor's deadliest natural predators. Ishamuhale is feared across the central savanna as the fiercest sunscale raptor alive, an apex hunter said to kill purely out of predatory passion rather than mere hunger. Lured into the open with fresh zhevra meat beside a withered tree northwest of Ratchet, the beast offers no quarter. Severing its massive fang proves to the hunting instructors of the Horde that a traveler has conquered not just a beast, but the sheer savagery of the plains.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ishamuhale-s-fang-9c6a0cea06e3850fcb95/1-0000.mp3", duration = 41.8481633, start = 0},
  },
}
P.transport["item:ivar-s-head"] = {
  hash = "9bd09b",
  fullHash = "9bd09b",
  text = "Ivar's Head. Ivar's Head is the gruesome proof of the destruction of the ravenous ghoul Ivar the Foul in Silverpine Forest. It is sought by the Deathstalker Rane Yorick to ensure safe recovery for her wounded brother Quinn. While scouting northern Silverpine Forest on the orders of High Executor Hadrec, the Forsaken Deathstalkers Rane and Quinn Yorick were ambushed at an abandoned farmstead by a feral ghoul known as Ivar the Foul. Though the siblings managed to fend off the fiend, Quinn was severely mauled in the confrontation. Stranded at the ruined farm while her brother recovered, Rane could not safely leave Quinn unattended to complete their mission. Severing Ivar's head provides definitive proof that the beast will never terrorize the estate again, granting Quinn the necessary time to recuperate under Rane's watchful eye.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ivar-s-head-20d2effc66c4055752b1/1-0000.mp3", duration = 47.2816327, start = 0},
  },
}
P.transport["item:iverron-s-antidote-item"] = {
  hash = "9628db",
  fullHash = "9628db",
  text = "Iverron's Antidote (item). Iverron's Antidote is a delicate medicinal draught concocted by Dirania Silvershine in Shadowglen. Specially brewed to neutralize the lethal venom of the local Webwood spiders, the mixture is highly unstable and spoils rapidly once prepared. Crafted by Dirania Silvershine in Aldrassil, this antidote is formulated to counteract the potent venom afflicting the young night elf Iverron. Due to the volatile nature of its ingredients and herbal catalysts, the draught possesses an exceptionally short shelf life, remaining viable for only five minutes after brewing. Courier messengers must sprint north toward the Webwood cave without delay to deliver the concoction before it degrades into useless slurry.",
  ["1"] = {
    {file = "Audio/Transport/full_item_iverron-s-antidote-item-371e13326dbbb408c2e3/1-0000.mp3", duration = 41.5346939, start = 0},
  },
}
P.transport["item:jade-phial"] = {
  hash = "393548",
  fullHash = "393548",
  text = "Jade Phial. The Jade Phial is a specially crafted vessel provided by the night elf druid Corithras Moonrage in Dolanaar. It is designed to safely draw and transport sacred water from Teldrassil's moonwells to replenish the druids' central well in Darnassus. Teldrassil is dotted with moonwells that channel lunar and natural energies vital to night elf society and druidic worship. As part of maintaining this harmony, the central moonwell used by the druids in Darnassus must periodically be replenished from the outlying wells across the great bough. Corithras Moonrage entrusts young initiates with the Jade Phial, a receptacle carefully prepared to gather pure waters from the moonwell near Starbreeze Village without disturbing its delicate spiritual potency.",
  ["1"] = {
    {file = "Audio/Transport/full_item_jade-phial-f936f55fe1d8bd928765/1-0000.mp3", duration = 42.7363265, start = 0},
  },
}
P.transport["item:jennea-s-flask"] = {
  hash = "83450c",
  fullHash = "83450c",
  text = "Jennea's Flask. Jennea's Flask is an empty vessel given to aspiring mages by the wizard Jennea Cannon in the Mage Quarter of Stormwind. It is used to collect a water sample from Mirror Lake to study disturbances in the local ley lines. Following the cataclysmic magical struggles across Azeroth, the natural flow of arcane currents has torn loose from its ancient channels. In Stormwind, Jennea Cannon seeks to understand how deeply these mystical shifts have affected Elwynn Forest. She provides this simple glass flask to promising apprentices, sending them southwest of the capital's gates to draw fresh water from the base of the waterfall at Mirror Lake. Once filled, the container protects the delicate sample so it can be brought back to the Wizard's Sanctum intact for arcane analysis. The primary concern driving the use of the flask is public safety. If fluctuating ley lines begin to seep magical taint into Mirror Lake, the surrounding ecosystem and anyone drinking from its waters could suffer strange or harmful afflictions. Collecting a pristine sample in Jennea's flask allows the mages of Stormwind to detect invisible magical residue before tainted currents can spread undetected throughout the countryside.",
  ["1"] = {
    {file = "Audio/Transport/full_item_jennea-s-flask-27ff9b678bd7659c4f19/1-0000.mp3", duration = 68.3885714, start = 0},
  },
}
P.transport["item:jitters-completed-journal"] = {
  hash = "7d4861",
  fullHash = "7d4861",
  text = "Jitters' Completed Journal. Jitters' Completed Journal is a handwritten account detailing the grim tragedies of Duskwood, specifically the massacre at Sven Yorgen's farm. Fearing vengeance, the reclusive Jitters surrenders the finished text to clear his name and shed light on the sinister forces haunting the region.",
  ["1"] = {
    {file = "Audio/Transport/full_item_jitters-completed-journal-117892fb61661e4d726c/1-0000.mp3", duration = 15.882449, start = 0},
  },
}
P.transport["item:johaan-s-findings"] = {
  hash = "b6fbbf",
  fullHash = "b6fbbf",
  text = "Johaan's Findings. Johaan's Findings is a bundle of research documents penned by Apothecary Johaan in Brill. Entrusted to a courier heading south, these notes convey recent alchemical developments in Tirisfal Glades to Apothecary Renferrel at the Sepulcher. The Royal Apothecary Society operates under relentless pressure from Lady Sylvanas Windrunner to engineer a New Plague capable of destroying both the living and the Scourge. Because researchers are scattered across Lordaeron's contested ruins, maintaining a flow of data between outposts is vital. Apothecary Johaan compiles his local testing notes in Brill and dispatches them southward to Apothecary Renferrel, who directs society efforts from the Sepulcher in Silverpine Forest. These records represent one small piece of the Society's collective effort to hone their lethal brews.",
  ["1"] = {
    {file = "Audio/Transport/full_item_johaan-s-findings-1f92ec9ec02383a81c3e/1-0000.mp3", duration = 47.8563265, start = 0},
  },
}
P.transport["item:johaan-s-special-drink"] = {
  hash = "75930d",
  fullHash = "75930d",
  text = "Johaan's Special Drink. Johaan's Special Drink is a lethal concoction prepared by Apothecary Johaan in the village of Brill. Disguised as a common refreshment, the mixture serves as a field test for the Royal Apothecary Society's developing plague. Brewed in the brewing cauldrons of Brill, Johaan's Special Drink is far from a tavern beverage. Apothecary Johaan concocts the draft by refining various venomous components and local reagents into a single draught, tailored specifically to test virulence against living physiology. Handed over under the guise of slaking a captive's thirst, it represents the Forsaken apothecaries' ongoing ambition to engineer a weapon potent enough to fulfill Sylvanas Windrunner's designs for Azeroth.",
  ["1"] = {
    {file = "Audio/Transport/full_item_johaan-s-special-drink-d50bcbf7db746752967d/1-0000.mp3", duration = 40.7510204, start = 0},
  },
}
P.transport["item:jordan-s-ore-shipment"] = {
  hash = "4c58cc",
  fullHash = "4c58cc",
  text = "Jordan's Ore Shipment. Jordan's Ore Shipment is a crate of ore that Bailor Stonehand was to turn into his alloy for the smith Jordan Stilwell. Carried by caravan from the Wetlands, the delivery was intercepted and looted by Mo'grosh ogres in the northeastern hills of Loch Modan. Meant to be refined by the dwarf Bailor Stonehand into his special alloy, this ore was originally promised to Jordan Stilwell for his metalwork. While crossing south through the mountains from the Wetlands into Loch Modan, the supply caravan was violently ambushed by the Mo'grosh ogres. The shipment was dragged into the ogres' wilderness stronghold, leaving the surviving guards to perish from their wounds and halting Jordan's smithing project until an adventurer can pry it back from the brutes.",
  ["1"] = {
    {file = "Audio/Transport/full_item_jordan-s-ore-shipment-f6e40c2f3e13ac668e2e/1-0000.mp3", duration = 42.24, start = 0},
  },
}
P.transport["item:jordan-s-refined-ore-shipment"] = {
  hash = "3ef2f5",
  fullHash = "3ef2f5",
  text = "Jordan's Refined Ore Shipment. Jordan's Refined Ore Shipment is a crate of high-grade metal prepared specifically for the smith Jordan Stilwell. Acquired as part of a paladin's sacred trials, it provides the essential stock needed to forge a holy weapon of virtue. When Jordan Stilwell set out to forge a weapon worthy of a dedicated paladin, ordinary stock would not suffice. The blacksmith required an assortment of rare and exacting components: a Purified Kor Gem, sturdy Whitestone Oak lumber, his own lost smithing hammer, and a specialized shipment of refined ore. This consignment represents the metal foundation for that sacred labor, brought to Ironforge to complete the Test of Righteousness.",
  ["1"] = {
    {file = "Audio/Transport/full_item_jordan-s-refined-ore-shipment-487b91d14c6a5c0f0d76/1-0000.mp3", duration = 38.6612245, start = 0},
  },
}
P.transport["item:jordan-s-smithing-hammer"] = {
  hash = "10d6c8",
  fullHash = "10d6c8",
  text = "Jordan's Smithing Hammer. Jordan's Smithing Hammer is a cherished family heirloom passed down to the human blacksmith Jordan Stilwell by his father. Its recovery from the haunted halls of Shadowfang Keep is essential for forging a holy weapon consecrated to the Light. To an ordinary observer, Jordan's Smithing Hammer might seem like mere smith's iron, but to Jordan Stilwell, it represents both heritage and destiny. Inherited from his father, this tool is central to Jordan's identity as a forge master outside Ironforge. Having somehow wound up within the forsaken stone walls of Shadowfang Keep in Silverpine Forest, it must be reclaimed before Jordan can attempt his masterwork—a sacred weapon fit for a holy champion.",
  ["1"] = {
    {file = "Audio/Transport/full_item_jordan-s-smithing-hammer-57b60d6e2f90c02e1100/1-0000.mp3", duration = 40.1763265, start = 0},
  },
}
P.transport["item:kadrak-s-flag"] = {
  hash = "7d7829",
  fullHash = "7d7829",
  text = "Kadrak's Flag. Kadrak's Flag is an emblem of the Horde given by the scout Kadrak at the border between the Barrens and Ashenvale. It serves as an unmistakable warning to the night elves and dryads of Stonetalon Peak, planted directly in the Talon Den after the elimination of Keymaster Rynthariel. Tensions run high along the borders of Kalimdor, where Alliance messengers and sentinels routinely test the boundaries of Horde-held territories. When a decoded scroll reveals communications from the dryad Rynthariel, Keymaster of the Talon Den, Kadrak determines that killing her is not enough. He provides this crimson banner to be planted deep within the Den upon the peak of Stonetalon. By staking the Horde's colors inside one of the night elves' sacred mountain redoubts, Kadrak intends to send a clear message: incursions across the Barrens will be answered with bold retaliation on Alliance soil.",
  ["1"] = {
    {file = "Audio/Transport/full_item_kadrak-s-flag-40694c181b7fce908d0c/1-0000.mp3", duration = 48.0130612, start = 0},
  },
}
P.transport["item:keg-of-shindigger-stout"] = {
  hash = "dd3cb7",
  fullHash = "dd3cb7",
  text = "Keg of Shindigger Stout. A Keg of Shindigger Stout is a barrel of potent dwarven ale brewed and guarded by the riflemen and soldiers garrisoned within Dun Garok. Desired by the Royal Apothecary Society in Tarren Mill, it serves not as an evening drink, but as a deceitful delivery vehicle for newly synthesized plagues. Dun Garok stands as a formidable dwarven bastion in the southeastern Hillsbrad Foothills, fiercely maintained by the dwarves of Ironforge. Within its entrenched barracks and mess halls, the stout-hearted defenders share barrels of Shindigger Stout to weather the cold and the grinding siege against regional enemies. The brew is robust and plentiful, making it a staple of the garrison's day-to-day survival.",
  ["1"] = {
    {file = "Audio/Transport/full_item_keg-of-shindigger-stout-3eb11e9aa5ce9aca62b9/1-0000.mp3", duration = 40.0195918, start = 0},
  },
}
P.transport["item:ken-zigla-s-draught"] = {
  hash = "4b093c",
  fullHash = "4b093c",
  text = "Ken'zigla's Draught. Ken'zigla's Draught is a potent, foul-tasting medicinal tonic prepared by Ken'zigla in the Stonetalon Mountains. It is formulated to restore enough strength to critically wounded individuals so they can move without bleeding out. Prepared by Ken'zigla in the Stonetalon Mountains, this potent brew serves as an emergency restorative for those on the verge of death. The tonic is extremely strong and must be measured carefully; drinking more than half a dose at once risks causing the patient to bleed out as their circulation surges. Administering half provides enough raw vigor to move and flee imminent danger, while the remainder must wait until the body stabilizes after a full night's rest.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ken-zigla-s-draught-7d7c0f53e2e41be7ff2b/1-0000.mp3", duration = 37.2244898, start = 0},
  },
}
P.transport["item:khazgorm-s-journal"] = {
  hash = "06e34f",
  fullHash = "06e34f",
  text = "Khazgorm's Journal. Khazgorm's Journal is a personal field ledger kept by Prospector Khazgorm, the leader of the Ironforge dwarven excavation at Bael Modan in the southern Barrens. It details the intrusive activities of the Explorers' League upon lands claimed by the Stonespire tauren tribe. The journal belongs to Prospector Khazgorm, who directs the heavy machinery and blasting operations carving out the southern Barrens hillsides. Far from the idyllic search for knowledge professed by the Explorers' League, the notes reflect a relentless campaign of excavation that displaced the Stonespire tribe. Attempts by the tauren to reach a peaceful resolution were rebuffed, making the journal a prized prize of war for Gann Stonespire as he seeks to understand and dismantle the dwarf presence in his homeland.",
  ["1"] = {
    {file = "Audio/Transport/full_item_khazgorm-s-journal-b49d72c719241beb4294/1-0000.mp3", duration = 46.9681633, start = 0},
  },
}
P.transport["item:klaven-mortwake-s-journal"] = {
  hash = "b0d527",
  fullHash = "b0d527",
  text = "Klaven Mortwake's Journal. Klaven Mortwake's Journal is an intelligence report recovered by SI:7 operatives from the Defias tower in northeastern Westfall. Kept secured inside a chest shipped out of Duskwood, it details the Brotherhood's covert attempts to brew alchemical concoctions capable of reanimating the dead. Master Mathias Shaw, leader of Stormwind's intelligence service, prioritized the recovery of Mortwake's journal to piece together the Brotherhood's wider web of alliances. The notes confirm not only dark experiments in reanimation but also the illicit logistical support connecting Duskwood, the Venture Company, and the Defias. For rogue operatives in service to the crown, the recovery of this dark research marks the pivotal transition into mastering the art of poisons.",
  ["1"] = {
    {file = "Audio/Transport/full_item_klaven-mortwake-s-journal-ff186aedc1483da825d9/1-0000.mp3", duration = 43.6244898, start = 0},
  },
}
P.transport["item:kodo-horn"] = {
  hash = "fcc713",
  fullHash = "fcc713",
  text = "Kodo Horn. Kodo Horns are sturdy natural reagents taken from the beasts that roam the northern reaches of the Barrens. To the Cenarion druids, their dense composition provides the necessary strength and potency for experimental herbal mixtures, most notably in crafting curative salves to treat poisoned wildlife. While kodos are revered throughout the Barrens by the tauren for their endurance and strength, their horns carry practical medicinal value. Tonga Runetotem, working from the Crossroads, employs complete horns to reinforce the potency of his herbal remedies. Chips and fragments do not suffice for refining these salves; only intact horns gathered from the mature kodos wandering the arid plains hold enough strength to anchor the cure.",
  ["1"] = {
    {file = "Audio/Transport/full_item_kodo-horn-63d5efc64624793042a3/1-0000.mp3", duration = 42.8146939, start = 0},
  },
}
P.transport["item:kodo-liver"] = {
  hash = "5bac85",
  fullHash = "5bac85",
  text = "Kodo Liver. A Kodo Liver is a hefty organ harvested from the massive kodos roaming the plains of the Barrens. While hardly standard culinary fare, Brewmaster Drohn in Ratchet requires it as a vital ingredient for fermenting an unorthodox trogg ale learned from the wandering brewmaster Chen Stormstout. The great kodos of the Barrens are primarily hunted by the tauren and wandering predators for their tough hides and nourishing meat. However, a fresh kodo liver serves a much more eccentric purpose in the port town of Ratchet. Brewmaster Drohn uses the organ alongside thunderhawk saliva glands and lightning glands to recreate a potent brew Chen Stormstout taught him: trogg ale. Drohn claims this unusual blend possesses a formidable kick, providing adventurous travelers with a hearty concoction straight from the wilds of central Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_item_kodo-liver-aa58712feadfcbb07d16/1-0000.mp3", duration = 46.6546939, start = 0},
  },
}
P.transport["item:kodobane-s-head"] = {
  hash = "d64c8c",
  fullHash = "d64c8c",
  text = "Kodobane's Head. Kodobane's Head is the severed head of Barak Kodobane, a cunning Kolkar centaur chieftain. Taken as proof of his demise, it is brought to the orc warlord Regthar Deathgate to show that the centaur threat near the Forgotten Pools has been broken. The Kolkar centaur of the Barrens have historically been a fractured, disorganized nuisance, yet the rise of ambitious warlords threatens to unite their marauding bands into an army. Barak Kodobane established his encampment at the lush waters of the Forgotten Pools, cutting off vital oasis resources and raiding nearby paths. Regthar Deathgate, stationed in a bunker west of the Crossroads, demands his severed head as undeniable proof that this commander can no longer rally his brutal kin against the Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_item_kodobane-s-head-605dd6f9b108cab8aef5/1-0000.mp3", duration = 42.6579592, start = 0},
  },
}
P.transport["item:kravel-s-crate"] = {
  hash = "770592",
  fullHash = "770592",
  text = "Kravel's Crate. Kravel's Crate is a heavy package dispatched by Kravel Koalbeard from the Mirage Raceway in the Shimmering Flats. Destined for the Nesingwary expedition in Stranglethorn Vale, it contains specialized hunting ammunition designed to bring down the jungle's deadliest game. Handed out by the shrewd entrepreneur Kravel Koalbeard at the Mirage Raceway, Kravel's Crate represents an unfinished business transaction across continents. Ordered weeks prior by a wealthy dwarven patron, the shipment was delayed long enough for its buyer to depart Kalimdor entirely. Rather than lose out on the favor of a wealthy customer who already paid for forwarding, Kravel entrusts passing adventurers to haul the crate all the way to northern Stranglethorn Vale. Despite its nondescript appearance and the crust of salt dust it gathers in the Shimmering Flats, the crate carries lethal cargo: heavy, special-gauge ammunition tailored specifically for hunting rifles. When received at the expedition camp north of Grom'gol, the recipient notes that the potent rounds are prized by big-game hunters and vital for survival against the predators roaming the jungle canopy.",
  ["1"] = {
    {file = "Audio/Transport/full_item_kravel-s-crate-3b11c3796519f66f4025/1-0000.mp3", duration = 62.484898, start = 0},
  },
}
P.transport["item:kreenig-snarlsnout-s-tusk"] = {
  hash = "eaa334",
  fullHash = "eaa334",
  text = "Kreenig Snarlsnout's Tusk. Kreenig Snarlsnout's Tusk is a gruesome hunting trophy taken from the leader of the Razormane quilboar raiders in the northern Barrens. Severing the tusk serves as indisputable proof for Thork at the Crossroads that the menace targeting Horde supply lines has been put down. The supply caravans traveling west from Durotar into the Barrens face constant harassment, but recent attacks grew increasingly brazen under the orchestration of a fierce Razormane leader named Kreenig Snarlsnout. To cripple the quilboars' coordination, Thork—commander of the Crossroads watch—ordered Snarlsnout eliminated. Taking the chieftain's tusk not only offers concrete proof that the raider has fallen, but serves as a deliberate insult to the Razormane tribe, shattering their resolve and leaving their fighters without central direction.",
  ["1"] = {
    {file = "Audio/Transport/full_item_kreenig-snarlsnout-s-tusk-c2ddc5eb3a68b748d4d5/1-0000.mp3", duration = 47.8563265, start = 0},
  },
}
P.transport["item:kuz-s-skull"] = {
  hash = "be5541",
  fullHash = "be5541",
  text = "Kuz's Skull. Kuz's Skull is the severed head of Kuz, a prominent Razormane quilboar raider in the southern Barrens. Brought forward from Razorfen Kraul, Kuz helped orchestrate violent raids against Horde outposts before being targeted for death by a captive former kin. The plains of the southern Barrens crawl with the Razormane tribe, but their organized aggression stems from specific leaders sent directly out of Razorfen Kraul. Kuz, alongside Nak and their ruthless chieftain Lok Orcbane, coordinated brutal incursions against travelers and settlements like the Crossroads. However, their internal treachery proved their undoing. Having betrayed their fellow quilboar Mangletooth and left him to rot in a cage at Camp Taurajo, they made a vengeful enemy. Mangletooth bartered Kuz's location to Horde champions willing to sever the raider's head and end his raids for good.",
  ["1"] = {
    {file = "Audio/Transport/full_item_kuz-s-skull-03f895e49929abcd13bd/1-0000.mp3", duration = 50.4946939, start = 0},
  },
}
P.transport["item:laced-pumpkin"] = {
  hash = "00510a",
  fullHash = "00510a",
  text = "Laced Pumpkin. A Laced Pumpkin is an ordinary gourd treated with a lethal concoction developed by Apothecary Johaan in Brill. Handed to a starving, imprisoned Scarlet Crusader under the guise of sustenance, it serves as a live field test for the Forsaken's growing arsenal of alchemical weapons. To the untrained eye, the laced pumpkin appears to be ordinary produce salvaged from the blighted soil of Tirisfal Glades. Under the supervision of Apothecary Johaan in Brill, however, the vegetable is treated with experimental toxins designed to realize the full potential of undeath. The Royal Apothecary Society constantly seeks new weapons to repel both the Scourge in the north and living human forces advancing from the south, turning even simple harvest goods into vectors for infection and chemical death.",
  ["1"] = {
    {file = "Audio/Transport/full_item_laced-pumpkin-46584e1b0fb182862556/1-0000.mp3", duration = 45.035102, start = 0},
  },
}
P.transport["item:laird-s-response"] = {
  hash = "df0de1",
  fullHash = "df0de1",
  text = "Laird's Response. Laird's Response is a sealed dispatch penned by the fish curer Laird in the coastal port of Auberdine. Written for Nessa Shadowsong in Rut'theran Village, the letter details curious ecological differences between mainland marine life and the unusually large fish thriving along Teldrassil's shores. After reviewing catch reports from across the Veiled Sea, Laird of Auberdine noted a striking discrepancy: the fish hauled from Teldrassil's coast are remarkably larger and more plentiful than those taken along the mainland beaches of Darkshore. In this written response addressed to Nessa Shadowsong, Laird shares his working theory—that the unnatural presence and raw vitality of the newly planted World Tree may be warping and stimulating the surrounding marine life. Delivered by travelers returning across the waters, the letter prompts wonder and quiet curiosity among the fisherfolk of Rut'theran Village.",
  ["1"] = {
    {file = "Audio/Transport/full_item_laird-s-response-5a76e9a7162979118085/1-0000.mp3", duration = 50.4685714, start = 0},
  },
}
P.transport["item:lake-creeper-moss"] = {
  hash = "0052b0",
  fullHash = "0052b0",
  text = "Lake Creeper Moss. Lake Creeper Moss is an organic compound harvested from the aquatic creepers dwelling among the Dawning Isles in Lake Lordamere. It serves as a vital reagent sought by the Royal Apothecary Society for their efforts to engineer a lethal new plague. Grown along the hides of the vicious freshwater beasts that prowl the southern Dawning Isles of Lake Lordamere, Lake Creeper Moss carries unique properties shaped by Lordaeron's blighted waters. Apothecary Berard, before Arugal's curse claimed his mind, documented it in his journal, noting that the moss resembled trace materials on the fossils of creatures killed by an ancient plague in the lake. When recovered by Forsaken agents, samples are dispatched directly to the Apothecarium in the Undercity to fuel Master Apothecary Faranell's dark research.",
  ["1"] = {
    {file = "Audio/Transport/full_item_lake-creeper-moss-8e9b3a3bd6192cdcab8d/1-0000.mp3", duration = 45.3746939, start = 0},
  },
}
P.transport["item:lake-skulker-moss"] = {
  hash = "10f161",
  fullHash = "10f161",
  text = "Lake Skulker Moss. Lake Skulker Moss is a biological reagent gathered from the bog beasts inhabiting the northern reaches of Lake Lordamere. It was identified by Apothecary Berard, before Arugal's curse claimed his mind, as a key organic component for the Royal Apothecary Society's research into brewing a New Plague. Harvested from the mossy bodies of Lake Skulkers and Elder Lake Skulkers on the Dawning Isles, this damp aquatic moss possesses properties prized by Forsaken alchemists. Before Arugal's curse claimed his mind, Apothecary Berard meticulously cataloged the flora and fauna of eastern Silverpine Forest, concluding in his journal that both Lake Skulker and Lake Creeper mosses could serve as stabilizing or reactive agents. After Berard became a mindless servant of Arugal, his journal was recovered from Pyrewood Village for Apothecary Renferrel, who instructed Forsaken champions to gather moss samples alongside a rare tumor from local Vile Fin murlocs, delivering them directly to Master Apothecary Faranell in the Undercity.",
  ["1"] = {
    {file = "Audio/Transport/full_item_lake-skulker-moss-4d68cba8b2026fd40890/1-0000.mp3", duration = 62.3804082, start = 0},
  },
}
P.transport["item:large-candle"] = {
  hash = "96955a",
  fullHash = "96955a",
  text = "Large Candle. Large Candles are wax tapers prized and carried by kobolds delving into the mines of Elwynn Forest. Mounted atop their heads, these crude lights provide visibility in subterranean tunnels and serve as a reliable source of raw wax for human apothecaries. Kobolds tunneling beneath Elwynn Forest depend upon candle flame to navigate pitch-black subterranean shafts, affixing wax tapers directly to their heads. Kobold Miners, Tunnelers, and Geomancers defend their candles fiercely against interlopers. Despite their crude manufacture, the large candles carried deep inside Fargodeep Mine and Jasperlode Mine contain valuable wax that surface tradesmen cannot easily produce in bulk, turning an everyday monster tool into an alchemical commodity. William Pestle, an apothecary operative hailing from Stormwind City, gathers these oversized candles at the Lion's Pride Inn in Goldshire. Seeking rendered wax for the concoctions, balms, and ointments prepared by his family apothecary, Pestle employs passing adventurers to clear the infested mines and strip the candles from the subterranean invaders.",
  ["1"] = {
    {file = "Audio/Transport/full_item_large-candle-892b987ef88897657ebd/1-0000.mp3", duration = 66.4816327, start = 0},
  },
}
P.transport["item:large-soran-ruk-fragment"] = {
  hash = "5027e3",
  fullHash = "5027e3",
  text = "Large Soran'ruk Fragment. The Large Soran'ruk Fragment is a sizable remnant of an ancient artifact bound with demonic energy. Originally housing the spirit of a disgraced Burning Legion demon, this shard found its way into the hands of sinister spellcasters within the haunted walls of Shadowfang Keep. When demons of the Burning Legion fall out of favor with their dark masters, their spirits are sometimes condemned to imprisonment within enchanted orbs. These vessels are subsequently distributed among mages and warlocks aligned with the Legion, who draw upon the potent fel forces trapped within. Even when shattered into fragments, the lingering essence of the bound fiend still radiates power, making each piece a prize for ambitious practitioners of shadow magic. The orb of Soran'ruk was long ago cracked into two halves. While one portion was fractured further and dispersed among cultists elsewhere, the larger half was claimed by a sorcerer dwelling within the cursed stronghold of Shadowfang Keep. There, carried among the sinister Shadowfang Darksouls, the Large Soran'ruk Fragment channels demonic power until sought out by those hoping to reforge the ancient vessel.",
  ["1"] = {
    {file = "Audio/Transport/full_item_large-soran-ruk-fragment-893ec4b973cfdd8b13ee/1-0000.mp3", duration = 67.0302041, start = 0},
  },
}
P.transport["item:laughing-sister-s-hair"] = {
  hash = "e52c71",
  fullHash = "e52c71",
  text = "Laughing Sister's Hair. Laughing Sister's Hair consists of soft, magical locks harvested from dryads residing in the enchanted forests of Ashenvale. Highly sought after by skilled weavers, these strands possess innate mystical properties ideal for crafting fine robes. Harvested from the dryads known as laughing sisters near Raynewood Retreat in Ashenvale, this hair holds remarkable natural magic. While dryads are sacred woodland protectors linked to Cenarius and the night elves, craftsmen within the Horde value their hair purely as a potent crafting reagent. The troll tailor Kil'hala at the Crossroads spins these gathered locks into enchanted vestments for burgeoning practitioners of the arcane.",
  ["1"] = {
    {file = "Audio/Transport/full_item_laughing-sister-s-hair-d9d667da3b5bdbe6f437/1-0000.mp3", duration = 40.1763265, start = 0},
  },
}
P.transport["item:legacy-of-the-aspects"] = {
  hash = "21b767",
  fullHash = "21b767",
  text = "Legacy of the Aspects. Legacy of the Aspects is an ancient tome hidden deep within the Dor'Danil Barrow Den in southern Ashenvale. Retrieved during a Horde trial of the intellect, the volume contains essential lore concerning the Great Aspects that shaped ancient Azeroth. While earlier trials set forth by tauren elders test physical endurance and resolve, the pursuit of Legacy of the Aspects is designed to challenge the mind. Tasked by Braug Dimspirit at the entrance to the Talondeep Path in the Stonetalon Mountains, an aspirant must delve into the haunted barrow dens of Dor'Danil. Guarded by the restless spirits of fallen druids and the vicious creatures that slew them, the ancient text rests upon a stone pedestal. Claiming the volume is only the first step; the seeker must commit its contents to memory before relinquishing the book, as they are tested on its historical lessons.",
  ["1"] = {
    {file = "Audio/Transport/full_item_legacy-of-the-aspects-57fc25b60cf136dbc076/1-0000.mp3", duration = 48.7444898, start = 0},
  },
}
P.transport["item:letter-to-delgren"] = {
  hash = "32b064",
  fullHash = "32b064",
  text = "Letter to Delgren. The Letter to Delgren is an urgent missive penned by Balthule Shadowstrike near the Tower of Althalaxx in northern Darkshore. Addressed to his mentor, the paladin Delgren the Purifier, it details the sinister operations of the demonic Dark Strand cult. Delivering it carries vital intelligence southward to Maestra's Post in Ashenvale. As cultists of the Dark Strand gather around the ruins of the Tower of Althalaxx, the night elf Balthule Shadowstrike keeps watch over their escalating malice. Lacking the martial might to eradicate the cult alone, Balthule drafts this dispatch to request aid from his tutor in the Holy Light, Delgren the Purifier. Because the cult's foul rites threaten more than just Darkshore's coastline, the message must be carried the entire length of the region into western Ashenvale, where Delgren works in concert with night elf Sentinels to hunt down demonic and undead threats.",
  ["1"] = {
    {file = "Audio/Transport/full_item_letter-to-delgren-1100315c76393c624668/1-0000.mp3", duration = 52.6367347, start = 0},
  },
}
P.transport["item:letter-to-jin-zil"] = {
  hash = "f122d3",
  fullHash = "f122d3",
  text = "Letter to Jin'Zil. The Letter to Jin'Zil is a piece of correspondence penned by the orc Darsok Swiftdagger at the Crossroads. Entrusted to an adventurer after the defeat of Serena Bloodfeather, it bears word to the Darkspear witch doctor Jin'Zil in the Stonetalon Mountains that the northern Barrens have been purged of the Bloodfeather threat. Following the eradication of the harpy infestation at the Dry Hills and the slaying of Serena Bloodfeather, Darsok Swiftdagger drafts this missive to an old comrade. Recognizing that the harpies of the Barrens originally roosted within the peaks of Stonetalon Mountains, Darsok uses the dispatch to introduce a promising warrior to the wider frontier while notifying the witch doctor Jin'Zil that the harpy matron has fallen.",
  ["1"] = {
    {file = "Audio/Transport/full_item_letter-to-jin-zil-5422f82072b789d7254e/1-0000.mp3", duration = 41.3518367, start = 0},
  },
}
P.transport["item:letter-to-jorgen"] = {
  hash = "fa1e64",
  fullHash = "fa1e64",
  text = "Letter to Jorgen. The Letter to Jorgen is a confidential missive drafted to enlist an old contact in Stormwind City. It serves as an operative's introduction during the early stages of an inquiry into a high-level diplomatic disappearance. When a high-ranking diplomat bound for Theramore failed to arrive for scheduled talks with Lady Jaina Proudmoore, royal investigators scrambled to keep the incident quiet. While official agents began scouring the capital, alternative channels were quietly mobilized. This sealed letter was drafted to circumvent standard military bureaucracy, aimed specifically at Jorgen—a gruff veteran passing his days fishing beneath the colossal statues in the Valley of Heroes. The note calls upon old obligations, pulling an unwilling contact into a covert investigation touched by rumors of Defias conspiracy.",
  ["1"] = {
    {file = "Audio/Transport/full_item_letter-to-jorgen-e4e3ed4ea3c249e491c0/1-0000.mp3", duration = 45.0612245, start = 0},
  },
}
P.transport["item:lewis-note"] = {
  hash = "9d626e",
  fullHash = "9d626e",
  text = "Lewis' Note. Lewis' Note is an urgent supply requisition penned by Quartermaster Lewis at Sentinel Hill. Carried by courier via gryphon flight, it requests vital shipments of protective gear from a private armorer in Stormwind's Old Town. The People's Militia at Sentinel Hill operates on a shoestring budget, receiving little official support from the House of Nobles in Stormwind. Facing persistent skirmishes against the Defias Brotherhood, the garrison regularly burns through its meager stocks of gear. To keep the defenders outfitted, Quartermaster Lewis relies on private business arrangements rather than crown logistics. This requisition note bypasses official military channels entirely, tasking an Alliance courier to fly by gryphon to Old Town and present the order directly to Osric Strang, proprietor of the shop Limited Immunity.",
  ["1"] = {
    {file = "Audio/Transport/full_item_lewis-note-1303ad9764535961da50/1-0000.mp3", duration = 48.0914286, start = 0},
  },
}
P.transport["item:lightning-gland"] = {
  hash = "bd5867",
  fullHash = "bd5867",
  text = "Lightning Gland. Lightning Glands are harvested from stormhide beasts roaming the plains of the Barrens. Imbued with natural elemental charge, they are sought by Brewmaster Drohn in Ratchet to brew a fiery, potent trogg ale learned from the wandering pandaren Chen Stormstout. The savannas of the Barrens host a variety of elemental-touched predators, including the stormhides. Within their flesh lies the lightning gland, an organ pulsating with latent electrical energy. While hardly suitable for ordinary fare, these volatile glands are prized by eccentric brewers who appreciate a brew with a genuine sting. In the port town of Ratchet, Brewmaster Drohn continues the brewing traditions imparted to him by Chen Stormstout. To concoct a potent brew known as trogg ale, Drohn requires five lightning glands alongside a thunderhawk saliva gland and a fresh kodo liver. The resulting draught carries an unmistakable kick that adventurers find both invigorating and potent.",
  ["1"] = {
    {file = "Audio/Transport/full_item_lightning-gland-ae7ddc7727ac7c9ae64f/1-0000.mp3", duration = 56.1893878, start = 0},
  },
}
P.transport["item:logging-rope"] = {
  hash = "bf2313",
  fullHash = "bf2313",
  text = "Logging Rope. Logging Rope is heavy cordage vital to the Warsong clan's ongoing logging operations within Ashenvale. Shipments of this sturdy line were ambushed and stolen by local furbolg tribes who violently resist the Horde's expansion into the ancient forest. Maintaining the goblin-built machinery and lumber mills of the Warsong Lumber Camp requires massive quantities of durable logging line. Rather than reaching the loggers at their encampment, essential shipments were intercepted by the Foulweald and Thistlefur furbolg tribes. Driven mad by corruption and fiercely defensive of their ancestral woods, these furbolgs hoard the stolen ropes in their encampments across northern and central Ashenvale. Locke Okarr at Splintertree Post is tasked with recovering the misplaced logistical chain before the Warsong lumber camp grinds to a halt. Reclaiming the heavy rope directly from the furbolg den-mothers and warriors allows the Horde to secure fellable timber, bound logs, and rig saw machinery amidst constant guerrilla resistance from the native forest inhabitants.",
  ["1"] = {
    {file = "Audio/Transport/full_item_logging-rope-88741ae7884779b8f814/1-0000.mp3", duration = 59.8987755, start = 0},
  },
}
P.transport["item:lok-s-skull"] = {
  hash = "ced5ed",
  fullHash = "ced5ed",
  text = "Lok's Skull. Lok's Skull is the severed head of Lok Orcbane, a fierce Razormane warrior who led brutal quilboar raids against Horde supply routes in the southern Barrens. Sought after by the imprisoned quilboar Mangletooth as an act of vengeance, the skull serves as undeniable proof that the raiders' chieftain has fallen. Emerging from Razorfen Kraul into the southern Barrens, Lok Orcbane spearheaded aggressive Razormane quilboar assaults on Horde supply lines alongside his lieutenants Nak and Kuz. After betraying and abandoning Mangletooth to captivity in Camp Taurajo, Lok earned a grim reputation among orcish defenders who struggled to contain his ruthless raids. Claiming Lok's skull not only avenges the wronged captive who directs Horde champions to Lok's camp, but also shatters the core leadership driving the Razormane offensive.",
  ["1"] = {
    {file = "Audio/Transport/full_item_lok-s-skull-1b8dd49b32d018c1ab97/1-0000.mp3", duration = 46.1844898, start = 0},
  },
}
P.transport["item:lonebrow-s-journal"] = {
  hash = "a8c9c9",
  fullHash = "a8c9c9",
  text = "Lonebrow's Journal. Lonebrow's Journal is a weathered diary found clutched in the skeletal remains of the dwarven explorer Henrig Lonebrow at the base of the Great Lift. Its pages detail the final grim journey of Lonebrow through the Barrens and point toward dangers lurking within Razorfen Kraul. Henrig Lonebrow met an unfortunate end near the base of the Great Lift connecting the Barrens to Thousand Needles. Lying abandoned on a rocky ledge, his skeletal remains still grip this weathered journal. The diary serves as a testament to his final travels and directs whoever discovers it to bring word to the night elf druid Falfindel Waywarder at Thalanaar, the border outpost leading into Feralas. Lonebrow's notes shed critical light on the quilboar menace brewing in the southern barrens.",
  ["1"] = {
    {file = "Audio/Transport/full_item_lonebrow-s-journal-9a866fb28b7faef501d1/1-0000.mp3", duration = 44.9828571, start = 0},
  },
}
P.transport["item:lorgalis-manuscript"] = {
  hash = "ff946d",
  fullHash = "ff946d",
  text = "Lorgalis Manuscript. The Lorgalis Manuscript is an ancient text tied to the worship and lore of the Old Gods, preserved from the fallen night elven ruins beneath Ashenvale. Hidden within the sunken temple complex of Blackfathom Deeps, it holds secrets coveted by dark scholars seeking to awaken ancient, slumbering powers. The Lorgalis Manuscript rests at the bottom of Blackfathom Deeps, the sunken ruins where long-dead elves once dwelt before their city fell. Written by one Lorgalis, it speaks of the Old Gods who raged across Azeroth when the world was new and now lie chained and sleeping, and it praises Aku'mai, a servant of the Old Gods who dwells in the Deeps. Its lore is said to open mystical doorways and stir ancient entities that sleep deep beneath the world. Stored away in a pitted iron chest amidst the flooded corridors, it has drawn the attention of cultists and shadow scholars alike.",
  ["1"] = {
    {file = "Audio/Transport/full_item_lorgalis-manuscript-36b0730634231984bf14/1-0000.mp3", duration = 50.3379592, start = 0},
  },
}
P.transport["item:lunar-fungus"] = {
  hash = "a81f07",
  fullHash = "a81f07",
  text = "Lunar Fungus. Lunar Fungus is a potent medicinal growth harvested from fungal blooms deep within Darkshore's cavern systems. Druid initiates collect these mushrooms alongside common herbs to brew a restorative salve capable of treating diseased wildlife. Harvested from Lunar Fungal Blooms, this distinctive fungus thrives in dark, subterranean caverns across Darkshore. The Cenarion Circle values it for its amplifying effects; when blended with a soothing water base and common Earthroot, the fungus provides the necessary potency to create an effective counteragent against debilitating afflictions. Because it grows primarily in damp underground spaces frequented by territorial moonkin, obtaining it requires careful navigation of the untamed wilderness. In Auberdine, Alanndarian Nightsong directs young druids to harvest Lunar Fungus as part of their studies into nature's restorative arts. By witnessing how physical reagents like this fungus counteract virulent poisons in the local deer, initiates learn the underlying principles of herbal remedies before advancing to channel natural antidotes directly through shapeshifting and raw spiritual power.",
  ["1"] = {
    {file = "Audio/Transport/full_item_lunar-fungus-a2a1f3212504d157771c/1-0000.mp3", duration = 65.7502041, start = 0},
  },
}
P.transport["item:lurker-venom"] = {
  hash = "bc7012",
  fullHash = "bc7012",
  text = "Lurker Venom. Lurker Venom is a potent natural toxin harvested from the predatory spiders that prowl the rocky hills and woods of Loch Modan. Dwarven defenders require this caustic venom as a key ingredient to prepare an alchemical neutralizing compound against Dark Iron sabotage. The hills and crags surrounding Loch Modan crawl with predatory arachnids—ranging from common wood lurkers to the infamous matriarch Shanda the Spinner. While their bites pose a constant hazard to mountaineers and travelers, the explosives expert Ashlan Stonesmirk named their virulent poison as one ingredient of a disarming mixture, which Chief Engineer Hinderweir prepares. Combined with rare minerals and tears harvested from the loch's crocolisks, Lurker Venom forms a reactive solvent capable of disarming complex Dark Iron explosives.",
  ["1"] = {
    {file = "Audio/Transport/full_item_lurker-venom-2d372d310107544377f6/1-0000.mp3", duration = 47.124898, start = 0},
  },
}
P.transport["item:lydon-s-toxin"] = {
  hash = "ed00e1",
  fullHash = "ed00e1",
  text = "Lydon's Toxin. Lydon's Toxin is an alchemical concoction synthesized by Apothecary Lydon in Tarren Mill to disrupt the Venture Company's deforestation in the Stonetalon Mountains. Entrusted to Horde adventurers, it is delivered to Apothecary Zamah in Thunder Bluff so she can devise an effective delivery mechanism. Developed by Apothecary Lydon in the Hillsbrad Foothills, this virulent compound is designed to combat the invasive Venture Company loggers despoiling the Stonetalon Mountains. According to Lydon, the concoction produces lethal and potentially contagious results upon contact. However, before the substance can be unleashed against the goblins' operations around the Windshear Crag, it must be ferried across continents to Apothecary Zamah, the Royal Apothecary Society's representative in Thunder Bluff. Zamah requires the raw mixture to engineer a wide-dispersal apparatus—the Toxic Fogger—ensuring the brew wipes out the exploitative deforesters without needlessly endangering Horde assets.",
  ["1"] = {
    {file = "Audio/Transport/full_item_lydon-s-toxin-308f6f7ff0e06a8a9646/1-0000.mp3", duration = 56.2416327, start = 0},
  },
}
P.transport["item:macgrann-s-dried-meats"] = {
  hash = "88f572",
  fullHash = "88f572",
  text = "MacGrann's Dried Meats. MacGrann's Dried Meats are a month's worth of salted provisions prepared by the hunter Tundra MacGrann to survive the harsh Dun Morogh winter. Stored in a reinforced thorium meat locker, the entire cache was snatched by the ferocious yeti known as Old Icebeard. Life in the freezing crags of Dun Morogh demands careful planning. To prepare for the blizzards of the cold season, the dwarf hunter Tundra MacGrann spent weeks hunting game, salting the meat, and securing it inside a sturdy chest. Aware that scavenging bears and prowling predators routinely plague his homestead, MacGrann took no chances and locked his food supply away inside a thorium meat locker. Even with those precautions, he did not anticipate an intruder strong enough to carry away the entire chest rather than trying to pry it open on the spot. While MacGrann was away tracking deer, the notorious yeti Old Icebeard raided the hunter's camp and dragged the heavy chest back to his den in Chill Breeze Valley. Though the beast lacked the means to break through the solid thorium plating, MacGrann's injured leg left him unable to mount a swift rescue into the cavern. Without outside assistance to retrieve the cache before winter sets in, the stranded hunter faced starvation amidst the mountain snows.",
  ["1"] = {
    {file = "Audio/Transport/full_item_macgrann-s-dried-meats-ee18ef1c2f29988e5d89/1-0000.mp3", duration = 71.9934694, start = 0},
  },
}
P.transport["item:mackreel-s-moonshine"] = {
  hash = "c26d38",
  fullHash = "c26d38",
  text = "MacKreel's Moonshine. MacKreel's Moonshine is a potent dwarven liquor brewed by Foggy MacKreel, stationed on the broken Thandol Span north of the Wetlands. Strong enough to knock out a sentry on duty, it is prized as far north as Southshore, where Brewmeister Bilger accepts it as payment for debts. Brewed by the guard Foggy MacKreel on the Thandol Span, this moonshine carries an infamous reputation for potency. Even hardened dwarven sentries find themselves laid low by a night with the brew, waking with headaches akin to a brigade of siege engines rolling overhead. Despite its punishing kick, it is highly valued for warming up travelers against the damp chills of Lordaeron and Khaz Modan. Foggy MacKreel ran up an unsettled debt with Brewmeister Bilger, the tavern keeper and master brewer of Southshore. In order to clear his tab, Foggy traded a batch of his moonshine instead of coin. Bilger gladly accepts the liquor in place of gold, eager to add MacKreel's potent brew to his stock for the chilly coastal days of the Hillsbrad Foothills.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mackreel-s-moonshine-6acbc5cda16153d1c382/1-0000.mp3", duration = 59.5853061, start = 0},
  },
}
P.transport["item:maggot-eye-s-paw"] = {
  hash = "f941d4",
  fullHash = "f941d4",
  text = "Maggot Eye's Paw. Maggot Eye's Paw is the gruesome trophy taken from the gnoll chieftain Maggot Eye at Garren's Haunt. Carried back to Brill, it serves as physical proof of the beast's execution for grave-robbing on behalf of the Scourge. Maggot Eye earned the harsh wrath of the Forsaken by raiding graves and pillaging the countryside near Garren's Haunt, providing corpses to bolster the ranks of the Lich King's armies. In response, a formal death sentence and bounty were posted in the town of Brill. Because mere rumors of a death are never enough for military administrators like Executor Zygand, bounty hunters must sever the villain's paw and bring it back to town to collect their reward and close the bounty.",
  ["1"] = {
    {file = "Audio/Transport/full_item_maggot-eye-s-paw-60da361960d89cbb1850/1-0000.mp3", duration = 38.2432653, start = 0},
  },
}
P.transport["item:maggran-s-reserve-letter"] = {
  hash = "554a4f",
  fullHash = "554a4f",
  text = "Maggran's Reserve Letter. Maggran's Reserve Letter is an official dispatch written by Maggran Earthbinder at Sun Rock Retreat. Carried across Kalimdor to the Great Lift, it grants a stationed sentry long-awaited relief so he may return home to visit his family. Maintaining outposts across the rugged expanse of Kalimdor demands vigilance, but the leaders of the Horde recognize that prolonged watch duty takes a heavy toll on morale. Penned by Maggran Earthbinder in the high crags of Sun Rock Retreat, this simple missive serves as official orders notifying Grish Longrunner that a replacement warrior has been dispatched to take over his post at the Great Lift. For a lonely guard watching over the towering wooden winches far to the south, the letter promises something rare in troubled times: an honorable leave of absence to reunite with family.",
  ["1"] = {
    {file = "Audio/Transport/full_item_maggran-s-reserve-letter-a11f95a020e906b49e0b/1-0000.mp3", duration = 47.5167347, start = 0},
  },
}
P.transport["item:mangy-claw"] = {
  hash = "25cbab",
  fullHash = "25cbab",
  text = "Mangy Claw. The Mangy Claw is a severed claw taken from the great ice claw bear Mangeclaw in Dun Morogh. It serves as grim proof that the deadly beast responsible for killing a stranded dwarven pilot has finally been slain. When Pilot Hildelve's steam tank broke down in the frozen hills of Dun Morogh, he continued his search for ore on foot, only to face the mountain wilderness alone. As recorded in his recovered journal, Hildelve managed to fight off an initial attack by a monstrous ice claw bear named Mangeclaw, though he was savagely mauled in the struggle. The beast later returned to finish off the weakened pilot. Hildelve's final written entry pleaded for vengeance against the predator, a task fulfilled by taking the Mangy Claw from the fallen bear.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mangy-claw-8463d12913d2cdb0b9d7/1-0000.mp3", duration = 43.9379592, start = 0},
  },
}
P.transport["item:marshal-haggard-s-badge"] = {
  hash = "1d7e79",
  fullHash = "1d7e79",
  text = "Marshal Haggard's Badge. Marshal Haggard's Badge is a symbol of rank and authority once carried by Marshal Haggard during his service to the kingdom of Stormwind. After being stolen by the Defias bandit Dead-tooth Jack through trickery, the badge poses a dangerous threat as a tool for impersonating city officials. Though Marshal Haggard has long retired to his small farmstead in the hills of Elwynn Forest, his old Stormwind Marshal's badge still holds official weight. Under the cover of night, a Defias rogue named Dead-tooth Jack donned a Stormwind tabard and posed as Marshal Dughan, Goldshire's garrison commander. Tricked into believing his former peers required the insignia for official business, the aging Haggard handed it over without suspicion. Jack fled into the woods before the retired officer realized the ruse. In the hands of the Defias Brotherhood, such an emblem of Stormwind authority could allow outlaws to slip past checkpoints or sow confusion among local patrols.",
  ["1"] = {
    {file = "Audio/Transport/full_item_marshal-haggard-s-badge-9cf8c7e83c75f4a9ce49/1-0000.mp3", duration = 55.9804082, start = 0},
  },
}
P.transport["item:mary-s-looking-glass"] = {
  hash = "fbedfc",
  fullHash = "fbedfc",
  text = "Mary's Looking Glass. Mary's Looking Glass is a discarded hand mirror once treasured by Blind Mary before tragedy claimed her sight and life. Abandoned in the haunted groves of Duskwood, it was scavenged by a roving ghoul before being sought out to complete Viktori Prism'Antras's telescope. Before her terrible fate, Blind Mary treasured this polished looking glass. After her death and the loss of her eyes, looking upon her reflection became an agonizing reminder of what she had lost. She cast the mirror away behind her barn, leaving it to the encroaching gloom of Duskwood. There it fell into the clutching claws of an Insane Ghoul that wandered the ruined outskirts, carrying the trinket south into the crypts of Tranquil Gardens Cemetery. In Darkshire, the eccentric stargazer Viktori Prism'Antras dreamed of peering through Duskwood's eternal twilight toward the pristine heavens above. Building his telescope required specialized optical lenses and reflective glass. Learning of his need, Mary directed adventurers to hunt down the feral undead prowling the cemetery's ruined chapel, reclaiming the looking glass to serve as an optical reflector in his grand star-viewing machine.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mary-s-looking-glass-34b5a0a39c12e713f0f7/1-0000.mp3", duration = 67.2653061, start = 0},
  },
}
P.transport["item:mathystra-relic"] = {
  hash = "427f8f",
  fullHash = "427f8f",
  text = "Mathystra Relic. Mathystra Relics are ancient night elven artifacts scattered among the overgrown ruins of Mathystra in northern Darkshore. Though remnants of a fallen elven bastion, they retain dormant shards of magic that have drawn the interest of the Twilight's Hammer cult. Before the Great Sundering, Mathystra stood as a proud city and bastion of elven civilization along the Kalimdor coast. Today, its toppled columns and cracked stones sit half-swallowed by brush and sea mist, haunted by restless spirits and lurking beasts. Scattered across the ruins are ancient relics dating back to that golden age. Though worn by ten thousand years of neglect, these artifacts still hold faint traces of elven arcane craft, making them dangerous prizes if left unattended.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mathystra-relic-f8e97f62c160c51a2e75/1-0000.mp3", duration = 44.3297959, start = 0},
  },
}
P.transport["item:melenas-head"] = {
  hash = "b61229",
  fullHash = "b61229",
  text = "Melenas' Head. Melenas' Head is the severed bounty taken from Lord Melenas, a satyr commander encamped inside Fel Rock. Brought back as absolute proof of his demise, the trophy marks the quiet elimination of a lingering demonic threat on the boughs of Teldrassil. To the night elves guarding Shadowglen and the surrounding reaches of Teldrassil, the mere existence of satyrs upon their new World Tree is a bitter disgrace. Lord Melenas chose to make his lair inside the twisted caverns of Fel Rock, just north of the elven settlements, rallying aggressive grell warriors to his banner. Because the kaldorei prize discretion when handling corruptions so close to their heartlands, this bloody trophy serves as private proof that his scheming has been snuffed out before his influence could spread.",
  ["1"] = {
    {file = "Audio/Transport/full_item_melenas-head-d01795375c1901df153c/1-0000.mp3", duration = 43.4416327, start = 0},
  },
}
P.transport["item:menethil-statuette"] = {
  hash = "2c6af1",
  fullHash = "2c6af1",
  text = "Menethil Statuette. The Menethil Statuette is a rare silvery figurine portraying the late King Terenas Menethil II as a youthful paladin with an upraised warhammer. Lost in a shipwreck off the coast of the Wetlands, it is an exceptionally scarce memorial of Lordaeron's fallen sovereign. The statuette depicts King Terenas Menethil II in his early years, portrayed as a long-haired paladin lifting a hammer toward the heavens. Terenas was notoriously humble during his reign and disliked personal monuments, meaning few statues or likenesses were ever commissioned in his honor. Following the collapse of the Kingdom of Lordaeron to the Scourge, almost all such relics were obliterated, making this surviving effigy extraordinarily valuable to the Alliance. The statuette was cargo aboard the merchant vessel Blind Princess, bound for the Alliance harbor of Menethil. When the ship came under attack by aggressive Bluegill murlocs off the marshy coast, the cargo was scattered and the statuette ended up trapped in a half-buried barrel on the shore. With local threats like the Dragonmaw orcs hovering nearby, local defenders hurried to send the retrieved icon south to Stormwind City, where Highlord Bolvar Fordragon entrusted it to the Cathedral of Light.",
  ["1"] = {
    {file = "Audio/Transport/full_item_menethil-statuette-d7764cc59c5b5dd9e4d2/1-0000.mp3", duration = 70.8963265, start = 0},
  },
}
P.transport["item:merrin-s-letter"] = {
  hash = "84f9aa",
  fullHash = "84f9aa",
  text = "Merrin's Letter. Merrin's Letter is an urgent message written by Merrin Rockweaver, an archaeologist trapped at the dig site in the Wetlands. It recounts the catastrophic overrun of their archaeological expedition by vicious raptors and assures her loved ones of her immediate survival. While excavating enormous prehistoric fossils and relics at the Whelgar's Excavation site in the Wetlands, the dwarven expedition disturbed a nest of ferocious Mottled Raptors. The beasts swarmed the trenches, slaughtering several workers and cutting off the surviving researchers from escape. Penning this note amidst the chaos, Merrin Rockweaver wrote to inform her husband Tarrel back at Menethil Harbor that while the dig lies in ruins, she, Prospector Whelgar, and Ormer Ironbraid managed to survive behind barricaded shelter.",
  ["1"] = {
    {file = "Audio/Transport/full_item_merrin-s-letter-f64ec8ce553d6931e006/1-0000.mp3", duration = 47.2816327, start = 0},
  },
}
P.transport["item:middle-of-gelkak-s-key"] = {
  hash = "f2aa1b",
  fullHash = "f2aa1b",
  text = "Middle of Gelkak's Key. The Middle of Gelkak's Key is a broken metal fragment belonging to the shipwrecked gnome pirate Gelkak Gyromast. After his vessel went down off the coast of Darkshore, this central section was snatched away by scavengers among the local Greymist murlocs. When Gelkak Gyromast's ship was dragged beneath the waves by wild threshadons, the gnome pirate tumbled ashore with his most precious belongings shattered on the rocky shoals. Among the wreckage was a specialized winding key meant for his mechanical first mate. The key snapped into three distinct fragments during the catastrophe, scattering across the strand. While the tops and bottoms ended up carried off by coastal beasts, the middle section caught the eye of the Greymist murlocs prowling the Darkshore surf, who quickly hoarded the shiny metallic piece in their camps and wreckage holdings.",
  ["1"] = {
    {file = "Audio/Transport/full_item_middle-of-gelkak-s-key-35faee2b4997e5b1138a/1-0000.mp3", duration = 47.5428571, start = 0},
  },
}
P.transport["item:milly-s-harvest"] = {
  hash = "cb2e7d",
  fullHash = "cb2e7d",
  text = "Milly's Harvest. Milly's Harvest consists of crates and buckets of freshly picked grapes gathered by Milly Osworth in the Northshire Vineyards. When Defias bandits overran the fields, the harvest was abandoned, leaving the fruit at risk of being stolen by thieves or crushed beneath the boots of abbey guards. The fertile soil of the Northshire Valley produces grapes vital for local vintners and the abbey community. When harvesting season arrived, Milly Osworth worked the vines to collect the fresh fruit into storage buckets. Her work was violently interrupted when armed brigands bearing red masks pushed into the vineyards, forcing her to flee back to the abbey grounds with her crop left scattered between the rows. Though Stormwind guards watch the valley entrance, manpower shortages have left Northshire vulnerable. While the garrison promised to drive the Defias out, Milly feared that any drawn-out skirmish between armored guards and ruthless thieves would result in the complete destruction of her work. Retrieving the crates before they are trampled underfoot or carried off as provisions ensures that one of Northshire's few peaceful harvests is not lost.",
  ["1"] = {
    {file = "Audio/Transport/full_item_milly-s-harvest-ede19fc54ae3b2eb44e4/1-0000.mp3", duration = 61.8318367, start = 0},
  },
}
P.transport["item:miners-gear"] = {
  hash = "0b8f33",
  fullHash = "0b8f33",
  text = "Miners' Gear. Miners' Gear consists of sturdy dwarven picks, shovels, and excavation tools stored within the Silver Stream Mine. Following an infestation of vermin, the Miners' League tasked adventurers with retrieving these valuable implements before local guards launched an assault. When the Silver Stream Mine in northern Loch Modan ran out of ore, the Miners' League repurposed the quiet tunnels into a subterranean storage depot for mining equipment. Unfortunately, tunnel-dwelling kobolds quickly overrun the complex, making off with the stored goods and nesting among the crates. Fearing the valuable dwarven gear would either be wrecked in an all-out assault by the Mountaineers or ruined by the scavengers, the league relies on bold adventurers to venture inside and haul the crates back to safety.",
  ["1"] = {
    {file = "Audio/Transport/full_item_miners-gear-43889f1557f1c72a8088/1-0000.mp3", duration = 43.7812245, start = 0},
  },
}
P.transport["item:miners-union-card"] = {
  hash = "675638",
  fullHash = "675638",
  text = "Miners' Union Card. A Miners' Union Card is an identification credential once carried by laborers working the rich subterranean veins beneath Moonbrook. Following a catastrophic cave-in that sealed a wing of the tunnels, these tokens now remain on the restless skeletal corpses wandering the dark drifts. Long before the Defias Brotherhood took absolute control over Moonbrook, laborers toiled underground under the banner of the miners' guild, extracting valuable ore for the kingdom. That ended in disaster when a severe tunnel collapse crushed a major shaft, trapping and killing dozens of workers beneath tons of rock. Rather than finding a quiet grave, those who perished rose again as skeletal miners, excavators, and dynamiters. The union cards clutched in their bony pockets are the sole surviving proof of their identities, sought out by surviving colleagues in Stormwind hoping to bring closure to grieving families.",
  ["1"] = {
    {file = "Audio/Transport/full_item_miners-union-card-e10b0bede61f36be996e/1-0000.mp3", duration = 51.5395918, start = 0},
  },
}
P.transport["item:minshina-s-skull"] = {
  hash = "aeb21d",
  fullHash = "aeb21d",
  text = "Minshina's Skull. Minshina's Skull contains the bound soul of the Darkspear troll Minshina, brother of Master Gadrin. Trapped by the rogue witch doctor Zalazane on the Echo Isles, the skull serves as a grim vessel used to fuel dark ritual magics. When Zalazane seized control of the Echo Isles and drove out the Darkspear tribe, Minshina was among those captured and slain. Rather than letting his victim pass into death, the traitorous witch doctor bound Minshina's soul to his own severed skull. Placed within a foul circle of power on the southernmost isle, the skull became a tether of magical enslavement. Master Gadrin, guided by tormented visions of his brother calling to him in dreams, seeks out brave travelers to venture into the occupied islands, reclaim the relic, and shatter Zalazane's hold over his brother's spirit.",
  ["1"] = {
    {file = "Audio/Transport/full_item_minshina-s-skull-e3dcbb4cdcaedbe676de/1-0000.mp3", duration = 47.3077551, start = 0},
  },
}
P.transport["item:mirror-lake-water-sample"] = {
  hash = "15b884",
  fullHash = "15b884",
  text = "Mirror Lake Water Sample. The Mirror Lake Water Sample is a flask of fresh lake water collected from the base of the waterfall in Elwynn Forest. Gathered by novice mages on behalf of Jennea Cannon in the Mage Quarter of Stormwind, it is used to investigate whether altered arcane currents are seeping into local water supplies. Following catastrophic global conflicts that tore the world's mystic channels from their stable courses, the mages of the Wizard's Sanctum in Stormwind have grown deeply concerned about residual arcane disruption. Jennea Cannon tasks promising apprentices with filling a specially prepared flask at the base of the Mirror Lake waterfall, located just southwest of the Stormwind Gate. By analyzing this water sample, the mages seek to detect whether stray magical taints have seeped into the natural waterways relied upon by the surrounding populace.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mirror-lake-water-sample-60c9edf35c3dcff9245e/1-0000.mp3", duration = 47.4383673, start = 0},
  },
}
P.transport["item:mist-veil-s-lockbox"] = {
  hash = "f9ffc3",
  fullHash = "f9ffc3",
  text = "Mist Veil's Lockbox. Mist Veil's Lockbox is a sturdy strongbox resting in the submerged wreckage of the night elven vessel Mist Veil off the coast of Darkshore. It holds the captain's log and personal effects, which were lost when the ship was ambushed and sunk by coastal murlocs. The night elven vessel Mist Veil met its end while sailing the treacherous coastal waters toward Auberdine. Ambushed by hostile murlocs alongside its sister ship, the Silver Dawning, the vessel was overwhelmed and sent to the ocean floor. Its captain perished during the attack, leaving behind their logbook and prized personal belongings sealed inside this lockbox. Resting in the flooded hold, the chest remains a grim trophy surrounded by the very creatures responsible for the catastrophe. For the surviving sailors who managed to reach Auberdine, the loss of their vessel and commander remains an open wound. Gorbold Steelhand seeks the recovery of the Mist Veil's Lockbox so the captain's final effects can be properly honored and laid to rest. Braving the flooded ruins to salvage the chest offers some measure of solace to the grief-stricken survivors stranded on the mainland.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mist-veil-s-lockbox-a019db943cbac1b9e5b9/1-0000.mp3", duration = 63.8432653, start = 0},
  },
}
P.transport["item:mo-grosh-crystal"] = {
  hash = "bc4993",
  fullHash = "bc4993",
  text = "Mo'grosh Crystal. Mo'grosh Crystals are rare mineral formations mined and hoarded by the Mo'grosh ogres in northeastern Loch Modan. Prized for their unusual alchemical properties, they serve as a vital component in neutralizing Dark Iron demolition materials. Tucked away in the crags of northeastern Loch Modan, the Mo'grosh ogres excavate these distinctive crystals from their stronghold. Though the brute-strength ogres rarely specialize in delicate metallurgy, Mo'grosh Crystals are prized treasures among their clan, carried by common enforcers, mystic shamans, and their towering leaders alike. The crystals are relatively uncommon, making them a heavily guarded possession within the Mo'grosh Stronghold.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mo-grosh-crystal-4d96842a50d056afd9c4/1-0000.mp3", duration = 40.5681633, start = 0},
  },
}
P.transport["item:modr-fragment"] = {
  hash = "02a0cf",
  fullHash = "02a0cf",
  text = "Modr Fragment. The Modr Fragment is one of four missing pieces broken off from the ancient Goaz Stone, a relic unearthed in the Wetlands. Discovered amid relics and loose earth within the Whelgar Excavation Site, it bears ancient Titan script vital to assembling a forgotten prophecy. Before vicious raptors drove the Explorers' League from their dig in the Wetlands, Prospector Whelgar uncovered the Goaz Stone—a massive tablet inscribed with ancient Titan markings. Its translated text abruptly broke off across four distinct gaps, obscuring warnings of a divine plan and a doomed prophecy. The Modr Fragment is one of those four lost pieces, left behind among ancient relics and overturned soil when the diggers were forced to flee for their lives.",
  ["1"] = {
    {file = "Audio/Transport/full_item_modr-fragment-3806c4c8a96291afd735/1-0000.mp3", duration = 42.8930612, start = 0},
  },
}
P.transport["item:moldy-tome"] = {
  hash = "2b2d51",
  fullHash = "2b2d51",
  text = "Moldy Tome. The Moldy Tome is a water-damaged, salvaged remnant containing half of the original Tome of the Cabal. Lost in a shipwreck off the coast of Hillsbrad Foothills, it holds dark esoteric rituals coveted by warlocks seeking to master demonic summonings. The Tome of the Cabal was a singular, irreplaceable treatise on dark arts once held within the kingdom of Lordaeron. At some point in its murky history, the grimoire was ruthlessly vandalized and split in two. The portion now designated as the Moldy Tome was being transported south by ship toward Menethil Harbor and Ironforge. The vessel never reached its destination, succumbing to the treacherous waters west of Southshore. Swept ashore south of Azurelode Mine, the surviving half lay ruined by damp and surf amidst the scavenging murlocs that stalk the Hillsbrad coast.",
  ["1"] = {
    {file = "Audio/Transport/full_item_moldy-tome-24b28ab4269f2c7b0037/1-0000.mp3", duration = 48.7183673, start = 0},
  },
}
P.transport["item:moonpetal-lily"] = {
  hash = "970cfc",
  fullHash = "970cfc",
  text = "Moonpetal Lily. Moonpetal Lilies are large, luminous flora native to Teldrassil that flourish around freshwater pools. Renowned for their potent restorative qualities, their petals are prized as key ingredients in natural remedies and healing draughts. Moonpetal Lilies grow exclusively along the moist banks of freshwater pools and ponds, particularly favored along the northwestern side of Aldrassil in Shadowglen. Like much of the plant life flourishing atop the newly grown World Tree, they absorb the unique essence of Teldrassil's sheltered groves. Their broad petals are gentle and radiant, easily spotted hugging the tranquil water's edge where natural moisture allows them to thrive. Night elf healers and herbalists value the Moonpetal Lily for its extraordinary healing properties. When combined with other forest flora, such as Hyacinth Mushrooms, the lily acts as a powerful soothing and stabilizing agent. This restorative quality makes it an essential component when brewing antidotes to counteract lethal toxins, notably the virulent venom produced by the Webwood spiders lurking within Shadowthread Cave.",
  ["1"] = {
    {file = "Audio/Transport/full_item_moonpetal-lily-7c0b4d32ca8a81e45275/1-0000.mp3", duration = 64.1567347, start = 0},
  },
}
P.transport["item:moonstalker-fang"] = {
  hash = "4e8815",
  fullHash = "4e8815",
  text = "Moonstalker Fang. Moonstalker Fangs are sharp canine teeth taken from the predatory moonstalkers roaming the misty woods of Darkshore. They are gathered by travelers assisting Wizbang Cranktoggle with the maintenance of his automated sampling devices. Moonstalkers are stealthy saber cats that haunt the forest fringes of Darkshore, stalking prey between the shadowed pines. Their elongated fangs serve as formidable hunting weapons, capable of shearing flesh and bone. For the eccentric gnome tinkerer Wizbang Cranktoggle, however, the teeth serve a very different mechanical purpose. Stationed north of Auberdine near the bridge, his automated contraption known as Buzzbox 323 is calibrated specifically to crush these durable fangs to dust as part of his erratic ecological surveys.",
  ["1"] = {
    {file = "Audio/Transport/full_item_moonstalker-fang-28748bd57f14eed21cef/1-0000.mp3", duration = 44.9828571, start = 0},
  },
}
P.transport["item:moonwell-water-tube"] = {
  hash = "245ef6",
  fullHash = "245ef6",
  text = "Moonwell Water Tube. A vial filled with consecrated water drawn from the moonwell in Auberdine. Its potent, purifying nature magic is used to test and react with a mysterious red crystal embedded along Darkshore's eastern ridges. Drawn directly from the shimmering moonwell resting in Auberdine, the Moonwell Water Tube contains liquid steeped in the blessed energies of Elune. Moonwells serve night elf settlements as sacred reservoirs of restorative magic and purity, rendering even a small phial remarkably potent against corruption or unknown mystical phenomena.",
  ["1"] = {
    {file = "Audio/Transport/full_item_moonwell-water-tube-6893cb7bb94211156a8c/1-0000.mp3", duration = 32.3395918, start = 0},
  },
}
P.transport["item:mossy-tumor"] = {
  hash = "efcca1",
  fullHash = "efcca1",
  text = "Mossy Tumor. A mossy tumor is a foul, poisonous growth carved from the bark and flesh of corrupted timberlings on Teldrassil. Found primarily around Wellspring Lake, these growths serve as outward signs of an unnerving malevolence spreading through the newly grown World Tree. The timberlings of Teldrassil were created to nurture and tend the boughs of the great tree, but many have turned hostile and diseased. These mossy tumors are physical manifestations of this inner sickness. Heavily laden with toxins, the growths sprout across the bodies of Mire Beasts, Tramplers, and Elder Timberlings that prowl Wellspring Lake. Rellian Greenspyre and the keepers in Darnassus have tasked travelers with severing the tumors so they may be thoroughly burned, preventing their poison from taking deeper root in the island's soil.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mossy-tumor-4487c7cadb51da4bd218/1-0000.mp3", duration = 46.8897959, start = 0},
  },
}
P.transport["item:mountain-lion-blood"] = {
  hash = "48e7ae",
  fullHash = "48e7ae",
  text = "Mountain Lion Blood. Mountain Lion Blood is a reagent collected from the prowling predators of the Hillsbrad Foothills and the snowy slopes of Alterac. Apothecary Lydon of Tarren Mill seeks this fresh blood to formulate the Royal Apothecary Society's dreaded Elixir of Pain. The highlands and foothills flanking Hillsbrad and Alterac are prowled by feral and starving mountain lions. While ordinary hunters seek these predators for their pelts and claws, the Forsaken of the Royal Apothecary Society find value in what pumps through their veins. Fresh mountain lion blood possesses specific biological properties that Apothecary Lydon in Tarren Mill believes will serve as the base for a potent new toxic brew designed to bring misery to the living. Apothecary Lydon's experiments in Tarren Mill contribute directly to the Royal Apothecary Society's overarching mandate: perfecting the Forsaken's New Plague. By harvesting the blood of vigorous wild beasts, Lydon seeks to refine a concoction he calls the Elixir of Pain, testing how potent local organic compounds can be weaponized against the enemies of the Dark Lady.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mountain-lion-blood-f404398e7d847c89f259/1-0000.mp3", duration = 64.0783673, start = 0},
  },
}
P.transport["item:mudsnout-blossom"] = {
  hash = "879be6",
  fullHash = "879be6",
  text = "Mudsnout Blossom. Mudsnout Blossoms are pungent, toxic fungal growths found sprouting in Nethander Stead in the Hillsbrad Foothills. Guarded by local gnolls and harvested by the Royal Apothecary Society, these foul mushrooms are used in Apothecary Lydon's elixir research. Despite their floral name, Mudsnout Blossoms are actually large, foul-smelling mushrooms that flourish primarily in the soiled dirt of Nethander Stead, south of Tarren Mill. They grow amidst the camps of the local Mudsnout gnolls, who defend the territory fiercely. To living organisms, the spores and flesh of the mushroom act as a virulent poison, causing agony and rapid biological deterioration.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mudsnout-blossom-165d0f0e6db43ce1b090/1-0000.mp3", duration = 40.0195918, start = 0},
  },
}
P.transport["item:mudsnout-composite"] = {
  hash = "8a6e9a",
  fullHash = "8a6e9a",
  text = "Mudsnout Composite. Mudsnout Composite is an alchemical paste prepared by Apothecary Lydon in Tarren Mill from harvested Mudsnout Blossoms. It serves as an essential base ingredient carried to the Undercity for the Royal Apothecary Society's research into a new plague. Crafted in the field by Apothecary Lydon, this fine composite is derived directly from Mudsnout Blossoms gathered in the Hillsbrad Foothills. While noxious on its own, the mash requires a specialized colloid of decay—concocted by Master Apothecary Faranell himself—to activate its more lethal qualities. Once bound, the mixture forms a key chemical component in the development of the Dark Lady's Elixir of Agony.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mudsnout-composite-83918c4833912cb81111/1-0000.mp3", duration = 40.724898, start = 0},
  },
}
P.transport["item:mudsnout-mixture"] = {
  hash = "721b6c",
  fullHash = "721b6c",
  text = "Mudsnout Mixture. Mudsnout Mixture is a toxic alchemical base concocted by Master Apothecary Faranell in the Undercity. Created by blending a mudsnout composite with an alchemical colloid of decay, it serves as the foundation for the Royal Apothecary Society's deadly Elixir of Agony. When Apothecary Lydon in Tarren Mill seeks to craft a virulent new biological weapon, he sends a base composite of Mudsnout Blossoms, toxic mushrooms from the gnoll-held Nethander Stead, north to the Undercity. Impressed by the composite's potential, Master Apothecary Faranell introduces his own colloid of decay into the blend, producing the volatile Mudsnout Mixture. The solution stabilizes the mushroom compound while readying its virulent properties for further catalytic refinement back in the foothills.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mudsnout-mixture-44fdcc61efd188aab6a7/1-0000.mp3", duration = 45.9232653, start = 0},
  },
}
P.transport["item:murloc-head"] = {
  hash = "4e1b8a",
  fullHash = "4e1b8a",
  text = "Murloc Head. Murloc Heads are grim trophies severed from the amphibious creatures prowling the Western Strand in Hillsbrad Foothills. Lieutenant Farren Orinelle of Southshore requires them as physical proof of culled threats to satisfy his superior, Marshal Redpath. Southshore faces dangers from all directions, but the aggressive murlocs clustering along the Western Strand are an immediate menace to local fishermen and coastal travelers. Although Alliance adventurers frequently sweep the beaches to cull the creatures, Marshal Marcus Redpath demands undeniable verification before signing off on defensive reports. To humor the bureaucracy, Lieutenant Farren Orinelle relies on hired fighters to haul in cold, dripping murloc heads—an unpleasant task Farren himself finds entirely repulsive, especially given how thoroughly the sight has spoiled his appetite for Southshore's local seafood.",
  ["1"] = {
    {file = "Audio/Transport/full_item_murloc-head-095cc921a61cdd0dc9aa/1-0000.mp3", duration = 50.8865306, start = 0},
  },
}
P.transport["item:musquash-root"] = {
  hash = "790b89",
  fullHash = "790b89",
  text = "Musquash Root. Musquash Root is a rare botanical specimen found only in the damp soil beneath the massive waterfalls of the Stonewrought Dam in the Wetlands. It serves as a vital component in a concoction brewed by cultists hidden beneath Stormwind. Musquash Root thrives in the perpetually mist-soaked ground where the cascade of the Stonewrought Dam crashes into the Wetlands. Its secluded and damp habitat makes it exceedingly difficult to harvest. While ordinary herbalists rarely seek it out, certain practitioners of the darker arts value the root for its potent chemical and alchemical properties.",
  ["1"] = {
    {file = "Audio/Transport/full_item_musquash-root-60d69711892062b13e96/1-0000.mp3", duration = 33.4628571, start = 0},
  },
}
P.transport["item:mysterious-fossil"] = {
  hash = "ceabbd",
  fullHash = "ceabbd",
  text = "Mysterious Fossil. The Mysterious Fossil is an ancient specimen unearthed along the coast of Darkshore by Prospector Remtravel. Its curious characteristics have drawn the intense curiosity of the dwarven Explorers' League, prompting scholars to shuttle it across the sea to uncover its hidden secrets. While conducting fieldwork among the wild shores of Darkshore, Prospector Remtravel uncovered a fossil unlike the common petrified stone scattered across Kalimdor. Deeming it of monumental historical importance, Remtravel arranged for the specimen to be delivered to dwarven scholars rather than let it languish in the wilderness. When brought before Chief Archaeologist Greywhisker in Darnassus, the relic immediately stood out as an extraordinary find.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mysterious-fossil-77182ed84c097904647f/1-0000.mp3", duration = 38.6612245, start = 0},
  },
}
P.transport["item:nak-s-skull"] = {
  hash = "b31141",
  fullHash = "b31141",
  text = "Nak's Skull. Nak's Skull is a grisly hunting trophy severed from Nak, one of three prominent Razormane quilboar commanders directing warbands in the southern Barrens. Taken as proof of the raider's defeat, it is sought by the captive quilboar Mangletooth to avenge a bitter tribal betrayal. Emerging from Razorfen Kraul, the trio consisting of Nak, Kuz, and Lok Orcbane launched vicious raids targeting Horde settlements and roadways across the Barrens. Unknown to the defenders at the Crossroads, these warlords were orchestrating attacks far more cunning than typical tribal skirmishing. When the Razormane prisoner Mangletooth was abandoned to die in a cage at Camp Taurajo, his thirst for retribution turned against his former brethren. Demanding physical proof of Nak's demise, Mangletooth asks Horde adventurers to deliver the severed skull alongside those of his cohorts to break the back of the southern raiding parties.",
  ["1"] = {
    {file = "Audio/Transport/full_item_nak-s-skull-fb6cc6d7f97cd8532112/1-0000.mp3", duration = 53.6816327, start = 0},
  },
}
P.transport["item:nek-rosh-s-head"] = {
  hash = "e3ae1a",
  fullHash = "e3ae1a",
  text = "Nek'rosh's Head. Nek'rosh's Head is the gruesome proof of the downfall of Chieftain Nek'rosh, leader of the Dragonmaw clan in the Wetlands. Procured by Alliance adventurers, this trophy is delivered to Captain Stoutfist to confirm that the orcish threat menacing Menethil Harbor has been shattered. The Dragonmaw clan poses a persistent danger across the marshlands, massing forces and siege weapons against the Alliance port of Menethil Harbor. After burning their catapults, the defense of the port hinges on slaying Chieftain Nek'rosh himself. Severing his head provides undeniable proof to Captain Stoutfist and the Ironforge authorities that the warlord's grip over the Wetlands is broken.",
  ["1"] = {
    {file = "Audio/Transport/full_item_nek-rosh-s-head-f64e74a4a8a6fdcd3c67/1-0000.mp3", duration = 40.2546939, start = 0},
  },
}
P.transport["item:neru-fragment"] = {
  hash = "f8a4a1",
  fullHash = "f8a4a1",
  text = "Neru Fragment. The Neru Fragment is one of four ancient carved stone pieces belonging to the Goaz Stone, a relic discovered in the Whelgar's Excavation site within the Wetlands. Unearthed from the disturbed earth, it holds a segment of ancient Titan script detailing the primeval history of Azeroth. Discovered by the dwarven archaeological expedition led by Prospector Whelgar, the Goaz Stone broke apart into four distinct remnants: the Ados, Modr, Golm, and Neru fragments. When raptors overrun the dig site, work ground to a halt, leaving the Neru Fragment buried beneath loose soil amid the aggressive beasts. Recovering this fragment is crucial for reassembling the tablet, allowing dwarven scholars to decipher a forgotten record whose surviving words mention a divine plan and a doomed prophecy.",
  ["1"] = {
    {file = "Audio/Transport/full_item_neru-fragment-780b8527fff48d730c14/1-0000.mp3", duration = 45.844898, start = 0},
  },
}
P.transport["item:nessa-s-collection"] = {
  hash = "bd024f",
  fullHash = "bd024f",
  text = "Nessa's Collection. Nessa's Collection is a package of fish bones and scales gathered from the waters surrounding Rut'theran Village. Prepared for study by fish vendor Laird in Auberdine, it illustrates the unusually massive size of aquatic life thriving around the roots of Teldrassil. Nessa Shadowsong, a fisherwoman residing in Rut'theran Village at the base of Teldrassil, gathered this collection of fish bones and scales to compare the island's marine life with that of the Kalimdor mainland. The waters feeding into the Great Tree yield catches of staggering proportions, prompting Nessa to send physical proof across the sea to Laird, a fish merchant operating along the docks of Auberdine. Transferred by way of the village's hippogryph master, Vesprystus, the parcel serves as practical evidence of Teldrassil's burgeoning vitality. Upon inspecting the contents in Darkshore, Laird discovers that the specimens far outstrip their mainland counterparts. The collection contains jawbones nearly twice the size of fish native to the Darkshore coastline, along with individual scales as large as a clenched fist. For coastal night elves, the package provides a clear look at how drastically the waters around Teldrassil differ from the somber shores of northern Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_item_nessa-s-collection-99a701b1db29633e0e2c/1-0000.mp3", duration = 70.922449, start = 0},
  },
}
P.transport["item:nether-gem"] = {
  hash = "bdadbb",
  fullHash = "bdadbb",
  text = "Nether Gem. The Nether Gem is an enchanted arcane stone entrusted by the reclusive necromancer Gunther Arcanus. Imbued with magical power, it acts as a long-distance conduit allowing Gunther to manifest an arcane projection and communicate directly with his old associate, Bethor Iceshard, in the Undercity. Forged or enchanted by Gunther Arcanus on his solitary island in Brightwater Lake, the Nether Gem serves as a mystical link across Tirisfal Glades. Gunther, having broken free from the Lich King's control through his own sheer willpower, long avoided the fledgling Forsaken nation out of suspicion. After receiving his lost spellbook, he entrusts the gem to an emissary as a gesture of goodwill. Once brought to Bethor Iceshard atop the Magic Quarter in the Undercity, the stone channels Gunther's magical visage directly before the Mage Guild leader, opening the path for the solitary mage to align with Lady Sylvanas and the Forsaken.",
  ["1"] = {
    {file = "Audio/Transport/full_item_nether-gem-ba8c4dfdfd16ab52facd/1-0000.mp3", duration = 53.1330612, start = 0},
  },
}
P.transport["item:ng-5"] = {
  hash = "55b65c",
  fullHash = "55b65c",
  text = "NG-5. NG-5 is the shorthand designation for Nitromirglyceronium, a notoriously volatile chemical compound. Procured for the gnome tinkerer Gaxim Rustfizzle in the Stonetalon Mountains, it serves as the essential catalyst for his explosive engineering schemes. Known formally as Nitromirglyceronium, NG-5 is an exceptionally hazardous chemical solution handled only with extreme caution—or reckless gnomish enthusiasm. Gaxim Rustfizzle, an operative stationed in the Stonetalon Mountains, requires the substance as a critical ignition compound. According to Gaxim, NG-5 provides the exact reaction necessary to detonate entire wagons loaded with dynamite, orchestrating a massive explosion meant to serve as a chaotic distraction against his adversaries in the region.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ng-5-d0d39c5958326b893790/1-0000.mp3", duration = 43.7812245, start = 0},
  },
}
P.transport["item:nida-s-necklace"] = {
  hash = "d06ed0",
  fullHash = "d06ed0",
  text = "Hilary's Necklace. Hilary's Necklace is a cherished childhood keepsake lost beneath the surface of Lake Everstill in the Redridge Mountains. Given to young Hilary by her father, the trinket slipped into the murky waters while the children of Lakeshire were out fishing along the docks. While fishing along the shoreline of Lakeshire with her friend Shawn, young Hilary accidentally dropped her treasured necklace into Lake Everstill. The heirloom holds immense sentimental value, having been a gift from her father. Fear of the fierce beasts and aggressive murlocs inhabiting the depths keeps the local children safely on the docks, leaving the necklace sunken and buried in the silt of the lakebed until an adventurer is willing to dive into the murky water to recover it.",
  ["1"] = {
    {file = "Audio/Transport/full_item_nida-s-necklace-cf29dbc4f3381e13410f/1-0000.mp3", duration = 39.0530612, start = 0},
  },
}
P.transport["item:nightmare-shard"] = {
  hash = "493090",
  fullHash = "493090",
  text = "Nightmare Shard. The Nightmare Shard is a crystalline relic handed to couriers by Falla Sagewind after she examines a tainted glowing shard recovered from the Wailing Caverns. Containing the pure, disturbed essence of the Emerald Dream, it carries a troubling vision that prompts immediate warning and secrecy among senior druids in Darnassus and Thunder Bluff. When Falla Sagewind inspects the mysterious glowing shard unearthed deep within the Wailing Caverns, she realizes its energy is far darker than anticipated. Rather than mirroring the serene vitality of the Emerald Dream, the fragment reflects a twisting, unnatural affliction—a waking nightmare. Fearful of what its presence implies, she binds this tainted essence into the Nightmare Shard and commands that it be ferried straight to elder leaders of the Cenarion Circle without delay.",
  ["1"] = {
    {file = "Audio/Transport/full_item_nightmare-shard-aed8309a561611e4c03b/1-0000.mp3", duration = 46.8897959, start = 0},
  },
}
P.transport["item:nightsaber-fang"] = {
  hash = "b64154",
  fullHash = "b64154",
  text = "Nightsaber Fang. A sharp tooth harvested from the predatory nightsabers roaming the wild branches of Teldrassil. While a common trophy of the hunt, these fangs are also sought out as raw reagents by local woodland residents with questionable motives. Nightsabers are among the deadliest natural predators native to northern Kalimdor, revered by the night elves for their agility, ferocity, and deep spiritual connection to Elune. Across the great boughs of Teldrassil, these feline beasts hunt in the shadows beneath the canopy. Striking one down yields sharp fangs that serve as undeniable proof of a hunter's skill, though certain unsavory figures in the forest seek them out for less noble ritual purposes.",
  ["1"] = {
    {file = "Audio/Transport/full_item_nightsaber-fang-bd889ed3ebb73f1be1ba/1-0000.mp3", duration = 40.0195918, start = 0},
  },
}
P.transport["item:nissa-s-remains"] = {
  hash = "4db20f",
  fullHash = "4db20f",
  text = "Nissa's Remains. Nissa's Remains are the recovered earthly remnants of Nissa Agamand, a noblewoman of the once-wealthy Agamand dynasty in northern Tirisfal Glades. Slain and raised as mindless servants of the Scourge during the Third War, she and her family are now hunted down by former laborers seeking vengeance. Before the Third War, the Agamand family stood as the wealthiest and most influential dynasty in Tirisfal Glades, operating prosperous mills across the northern hills. When the Plague of Undeath crept across Lordaeron, the family patriarchs stubbornly refused to evacuate. Instead, they fortified their estates and convinced their retainers and laborers to stand their ground. That arrogance cost everyone their lives. The Agamands fell to the Scourge, rising not with their proud independence intact, but as shambling, mindless thralls bound to the Lich King's will. In the town of Brill, survivors who later broke free under Queen Sylvanas Windrunner have not forgotten the family's fatal pride. Coleman Farthing, a former laborer in the Agamand mills, holds a bitter grudge against his former masters for luring their workers into the jaws of undeath. He charges adventurers with putting down the risen Agamands and retrieving their physical remains, such as Nissa's. For Farthing and others among the Forsaken, burning or destroying these relics offers a grim sense of final closure and spiteful revenge.",
  ["1"] = {
    {file = "Audio/Transport/full_item_nissa-s-remains-a245ffe2e20380e7d02e/1-0000.mp3", duration = 81.7371429, start = 0},
  },
}
P.transport["item:nitroglycerin"] = {
  hash = "5188dc",
  fullHash = "5188dc",
  text = "Nitroglycerin. Nitroglycerin is a volatile chemical substance carried by dwarven soldiers and officers garrisoned at Bael Modan in the southern Barrens. It serves as an industrial explosive agent for their excavation operations, though it can also be turned against them. The Bael'dun dwarves tore into the ancestral lands of the Stonespire tauren using heavy mechanical drillers and volatile chemistry. To blast holes deep into the ground and tear apart the hills, dwarven personnel at the Bael Modan excavation site and its fortified keep keep stores of raw nitroglycerin close at hand. Both frontline soldiers and officers such as Lord Cyrik Blackforge carry vials of the volatile fluid on their persons to fuel the ongoing, destructive digging.",
  ["1"] = {
    {file = "Audio/Transport/full_item_nitroglycerin-41077db994dc915f9295/1-0000.mp3", duration = 41.2212245, start = 0},
  },
}
P.transport["item:nondescript-letter"] = {
  hash = "c4a86c",
  fullHash = "c4a86c",
  text = "Nondescript Letter. The Nondescript Letter is a sealed, unmarked missive entrusted to newly awakened Forsaken leaving Deathknell. Handed over by Calvin Montague under the guise of an errand, it directs the bearer down the road to Innkeeper Renee at the Gallows' End Tavern in Brill. Newly arisen Forsaken looking to venture beyond Deathknell are approached by Calvin Montague, a shifty rogue lingering near the village perimeter. Claiming to be weary from fighting mindless zombies and arachnids, Calvin asks travelers to carry a plain, unmarked envelope along the eastward road to Brill. Addressed casually to an innkeeper named Renee, the letter serves as an excuse to push travelers out of the valley and toward the Gallows' End Tavern, though Calvin's promises of rich compensation ring hollow from the start.",
  ["1"] = {
    {file = "Audio/Transport/full_item_nondescript-letter-82704e3ffc3decb17747/1-0000.mp3", duration = 44.2514286, start = 0},
  },
}
P.transport["item:nori-s-mug"] = {
  hash = "3a52ba",
  fullHash = "3a52ba",
  text = "Nori's Mug. Nori's Mug is the personal drinking vessel of Nori Pridedrift, used to deliver scalding mornbrew across the frigid drifts of Dun Morogh. After delivering a warm drink to stave off the biting alpine chill, travelers are tasked with returning the empty cup to its thrifty owner. In the freezing mountain passes of Dun Morogh, a piping hot tankard of mornbrew is one of the few comforts capable of cutting through the bitter cold. Nori Pridedrift entrusts his mug to travelers delivering a fresh, steaming pour to Durnan Furcutter in Anvilmar. Once drained, the sturdy vessel must make the trek back. As Nori notes, mugs do not grow on trees, and keeping track of hard-wearing dwarven dishware is essential business when hospitality meets snowy wilderness.",
  ["1"] = {
    {file = "Audio/Transport/full_item_nori-s-mug-910efce513cfdd6fb32b/1-0000.mp3", duration = 43.3632653, start = 0},
  },
}
P.transport["item:notched-rib"] = {
  hash = "e2e259",
  fullHash = "e2e259",
  text = "Notched Rib. A Notched Rib is a bone trophy harvested from the ranks of mindless undead wandering Tirisfal Glades. Deathguard Dillinger in Brill collects these scarred remains as proof of efforts to break the Scourge's foothold at the Agamand Mills. The Scourge forces massing across the northern fields of Tirisfal Glades consist of reanimated skeletons clad in ruined armor. Among their ranks, Cracked Skull Soldiers and Rattlecage Soldiers throw themselves against any living or free-willed being they encounter. Slicing through their brittle frames leaves their bone structure pitted and scored. To ensure that Forsaken scouts and volunteers actually cull these mindless intruders rather than merely observing them, the Deathguards demand tangible evidence. A notched, battle-marked rib serves as unmistakable proof that another of the Lich King's thralls has been shattered. The Agamand Mills represent a critical strategic position northwest of Brill. Should the Scourge firmly entrench themselves among the ruined farmsteads and windmills, they would possess a direct staging ground to launch assaults deep into the heart of Tirisfal. Deathguard Dillinger monitors the roads leading north, dispatching champions to crush the skeleton cohorts before they can consolidate. Piles of notched ribs returned to Brill demonstrate that the Forsaken lines are holding, slowly grinding down the Scourge vanguard bone by bone.",
  ["1"] = {
    {file = "Audio/Transport/full_item_notched-rib-380ae101b82d45c05109/1-0000.mp3", duration = 78.3673469, start = 0},
  },
}
P.transport["item:nugget-slug"] = {
  hash = "1134be",
  fullHash = "1134be",
  text = "Nugget Slug. Nugget slugs are specialized 17.5-gauge mechanical fasteners used in industrial engineering. Stockpiled in tool buckets by the Venture Company at the Sludge Fen, they are coveted by tinkerers attempting to repair volatile machinery. Nugget slugs are heavy-duty metallic fasteners manufactured for demanding industrial assemblies. Specifically sized at 17.5 gauge, these components are an essential part of the heavy equipment deployed across Venture Company extraction sites. While useless as ordinary trade goods, they are indispensable to tinkerers dealing with customized goblin hardware.",
  ["1"] = {
    {file = "Audio/Transport/full_item_nugget-slug-d4eee09e9cc501ed8616/1-0000.mp3", duration = 32.8881633, start = 0},
  },
}
P.transport["item:ogre-s-monocle"] = {
  hash = "d8cc2e",
  fullHash = "d8cc2e",
  text = "Ogre's Monocle. The Ogre's Monocle is an oversized eyeglass worn by Zzarc'Vul, an ogre dwelling in southern Duskwood's Vul'Gol Ogre Mound. Its immense glass lens provides the exact dimensions needed by Viktori Prism'Antras in Darkshire to assemble an elaborate stargazing telescope. While ogres are rarely renowned for refined scholarship, Zzarc'Vul somehow came into possession of an enormous monocle tailored to his massive stature. When the Darkshire resident Viktori Prism'Antras set out to build a stargazing instrument using blueprints drafted by the gnome engineer Cog, he found standard lenses far too small. Zzarc'Vul's eyewear proved to be the only piece of polished glass in the region with the curvature and size necessary to focus light through the completed device. Acquiring the monocle requires braving the Vul'Gol Ogre Mound in the shadow of southern Duskwood. Zzarc'Vul resides among his brute brethren, showing little inclination to voluntarily part with his distinctive accessory. Claiming the lens means defeating the brute on his own territory before returning the glass to Darkshire so Viktori can finally turn his gaze to the night skies.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ogre-s-monocle-0df801849b6b211b66cd/1-0000.mp3", duration = 66.4816327, start = 0},
  },
}
P.transport["item:okra"] = {
  hash = "c76a47",
  fullHash = "c76a47",
  text = "Okra. Okra is a cultivated vegetable that grows in the tilled plots of Westfall. Highly prized by local homesteaders, it serves as a crucial thickening agent in the region's hearty, improvisational stews. While much of Westfall lies fallow under the threat of Defias outlaws and rogue harvest golem attacks, stubborn farmers like the Saldeans still manage to coax hearty vegetables out of the soil. Okra grows low and green in the tilled dirt around Saldean's Farm. Despite the harsh conditions of the countryside, the crop persists, providing local homesteaders with essential bulk and nourishment when outside trade and supplies from Stormwind run completely dry. Okra is best known as the indispensable base for Salma Saldean's famous Westfall Stew. Combined with whatever meat can be hunted across the dusty plains—such as vulture flesh, goretusk snouts, and coastal murloc eyes—the sliced pods break down under heat to thicken thin broths into a filling, restorative meal. For the struggling settlers clinging to their homesteads, fresh pods of okra turn sparse, wild scavenging into a hot, hearty supper.",
  ["1"] = {
    {file = "Audio/Transport/full_item_okra-a7609da3f6837dfb2265/1-0000.mp3", duration = 64.8620408, start = 0},
  },
}
P.transport["item:ordanus-head"] = {
  hash = "35c401",
  fullHash = "35c401",
  text = "Ordanus' Head. Ordanus' Head is the grisly trophy taken from Keeper Ordanus at Raynewood Retreat in Ashenvale. Claimed on behalf of the blood elf magi Braelyn Firehand, it serves as undeniable proof that one of Cenarius's eldest sons has fallen to arcane vengeance. Keeper Ordanus was an ancient keeper of the grove, one of the elder scions of the forest god Cenarius. When Braelyn Firehand climbed the heights of Stonetalon Mountains on orders from her master, she sought to end the druids' stifling of magic at the peak and exact vengeance on Ordanus. However, the keeper was spirited away to the heart of Ashenvale before she could strike. Using arcane scrying to peer through the forest canopy, Firehand located his sanctuary in the boughs of Raynewood Retreat, demanding his severed head as proof that the wild demigod's arrogance had finally been answered.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ordanus-head-8295e5bd6cb567e1ade8/1-0000.mp3", duration = 48.9795918, start = 0},
  },
}
P.transport["item:orendil-s-cure"] = {
  hash = "1bb5bc",
  fullHash = "1bb5bc",
  text = "Orendil's Cure. Orendil's Cure is a medicinal draught concocted by the herbalist Orendil Broadleaf in northern Ashenvale. Created using the rare herb Bathran's Hair, it is meant to treat the mysterious, deathly sickness afflicting Relara Whitemoon in Astranaar. When young Relara Whitemoon fell deathly ill in Astranaar, conventional remedies proved useless against her ailment. Her desperate father, Pelturas Whitemoon, turned to Orendil Broadleaf, a hermit and master of natural medicine dwelling along the northern reaches of Ashenvale. Utilizing bundles of the rare plant Bathran's Hair harvested from the haunted ruins of Bathran's Haunt, Orendil brewed this tailored concoction. The arrival of the vial gives Pelturas hope where before he had little, though the cure only slows the disease, and Pelturas must turn to the further remedies Orendil suggested.",
  ["1"] = {
    {file = "Audio/Transport/full_item_orendil-s-cure-140e9853a9fd99b347df/1-0000.mp3", duration = 50.0767347, start = 0},
  },
}
P.transport["item:oslow-s-toolbox"] = {
  hash = "9eb2b8",
  fullHash = "9eb2b8",
  text = "Oslow's Toolbox. Oslow's Toolbox contains the vital construction tools needed by Foreman Oslow in Lakeshire. En route from Goldshire, the supplies were ferried across Lake Everstill only to be sunk by an orcish catapult bombardment. Maintaining the defenses and infrastructure of Lakeshire is a grueling challenge, particularly with the Blackrock orcs besieging the Redridge Mountains. Foreman Oslow ordered a vital set of construction tools brought in from Goldshire. Because the main bridge leading into Lakeshire had been destroyed by enemy action, the shipment had to be loaded into a rowboat to cross Lake Everstill. The crossing was abruptly cut short when Blackrock forces struck the vessel with a catapult blast, plunging the boat and Oslow's heavy chest straight down into the murloc-infested depths.",
  ["1"] = {
    {file = "Audio/Transport/full_item_oslow-s-toolbox-e4331f5baffe300a4163/1-0000.mp3", duration = 43.3632653, start = 0},
  },
}
P.transport["item:osric-s-crate"] = {
  hash = "d500de",
  fullHash = "d500de",
  text = "Osric's Crate. Osric's Crate is a heavy package of freshly crafted armor dispatched from Stormwind to the struggling defenders of Sentinel Hill. Carried aboard a gryphon across the kingdom's flight network, it provides vital equipment to help the People's Militia hold Westfall against outlaw gangs. Westfall suffers under the predations of the Defias Brotherhood and marauding gnolls, while the Stormwind army remains absent. The local defenders, organized as the People's Militia at Sentinel Hill, lack the formal support of the crown and must rely on piecemeal supplies. Osric's Crate contains a fresh batch of protective armor sent from the capital to Quartermaster Lewis, intended to be parceled out directly to volunteer militia fighters on the ground. Transporting gear overland from Stormwind through Elwynn Forest and across the Westfall border is slow and fraught with bandit ambushes. To bypass the roads, the crate is entrusted to an adventurer flying via Dungar Longdrink's gryphon roost in Stormwind's Trade District down to Thor at Sentinel Hill. This swift delivery demonstrates the crucial role gryphons play in keeping frontier garrisons supplied during wartime.",
  ["1"] = {
    {file = "Audio/Transport/full_item_osric-s-crate-93ebab0dc8c22466f19e/1-0000.mp3", duration = 66.56, start = 0},
  },
}
P.transport["item:package-of-empty-ooze-containers"] = {
  hash = "a700b0",
  fullHash = "a700b0",
  text = "Package of Empty Ooze Containers. This package is a kit of specialized, empty specimen jars supplied by the gnome researcher Laris Geardawdle in Ironforge. Intended for dangerous field sampling in the blighted forests of Felwood, it contains jars designed to safely hold tainted and cursed ooze extracts without dissolving. Containing a dozen empty jars—split between containers meant for cursed and tainted oozes—this kit was assembled by Laris Geardawdle for intrepid travelers heading out to Felwood. Because raw ooze specimens are notoriously caustic and prone to digesting ordinary luggage, sturdy, sealed glass is essential for transporting the acidic residues across continents back to the tinker's workbench in Ironforge. Geardawdle's interest in ooze is far from a simple eccentric hobby. Noticing that Forsaken researchers from the Royal Apothecary Society routinely harvest these bizarre organisms across Azeroth, he suspects oozes may hold profound secrets about the world's origin. Geardawdle theorizes that slimes might be primordial secretions connected to the planet's very creation, and he relies on field agents using this kit to collect the evidence he needs to win acclaim within the Explorers' League.",
  ["1"] = {
    {file = "Audio/Transport/full_item_package-of-empty-ooze-containers-a3ee42463c68fea4a1b8/1-0000.mp3", duration = 66.2465306, start = 0},
  },
}
P.transport["item:painted-gnoll-armband"] = {
  hash = "b715fa",
  fullHash = "b715fa",
  text = "Painted Gnoll Armband. Painted Gnoll Armbands are crude adornments worn by the Riverpaw gnolls prowling the outskirts of Elwynn Forest. Westbrook Garrison collects these marked bands as physical proof of bounties fulfilled against the encroaching packs. The Riverpaw pack marks its warriors and scavengers with rough armbands painted in crude tribal patterns. The painted bands are collected from the Riverpaw gnolls along the wilderness borders of Elwynn Forest. To the defenders of Stormwind, however, they represent a growing territorial menace encroaching near Stone Cairn Lake and the woods south of Westbrook Garrison. With the Stormwind Army stretched thin across the kingdom, Westbrook Garrison struggles to keep the western border secure against encroaching threats. Deputy Rainer placed a standing bounty on the invading packs, directing adventurers to slay Riverpaw outrunners and runts. The painted armbands serve as undeniable proof of the kill, allowing garrison deputies to tally bounties and thin the gnoll population encroaching on nearby farmlands.",
  ["1"] = {
    {file = "Audio/Transport/full_item_painted-gnoll-armband-201f2477a63a5d72d36f/1-0000.mp3", duration = 59.5069388, start = 0},
  },
}
P.transport["item:panther-cage-key"] = {
  hash = "6268e0",
  fullHash = "6268e0",
  text = "Panther Cage Key. The Panther Cage Key is a small metal key held by Wizlo Bearingshiner at Whitereach Post. It unlocks a reinforced cage holding an enraged, captive predator within the wreckage of an ambushed caravan in Thousand Needles. When a traveling caravan was attacked and ransacked by centaur raiders north of Whitereach Post, the goblin tinker Wizlo Bearingshiner barely escaped with his life. Amid the ruins of wagons and plundered cargo, the marauders left one thing entirely untouched: a sturdy cage housing a ferocious, rare panther. Around the predator's neck hung Wizlo's prized invention, a hypercapacitor gizmo. Unwilling to approach the snarling beast, the centaur gave the cage a wide berth, leaving Wizlo's key as the only way to open the door and retrieve the device.",
  ["1"] = {
    {file = "Audio/Transport/full_item_panther-cage-key-3bba72f4c7455e7013e0/1-0000.mp3", duration = 45.5314286, start = 0},
  },
}
P.transport["item:parker-s-lunch"] = {
  hash = "7b7796",
  fullHash = "7b7796",
  text = "Parker's Lunch. Parker's Lunch is a freshly prepared meal packed by Darcy in Lakeshire. Intended for Guard Parker on patrol, it offers a simple glimpse into the daily bonds and modest comforts of Redridge's defenders. While Redridge Mountains reels under attacks from gnolls and Blackrock orcs, the small gestures of daily life persist. Darcy, a waitress at the inn in Lakeshire, packs this wholesome meal for Guard Parker, who patrols the exposed road leading south toward Duskwood. Redridge's garrison is stretched thin and isolated from Stormwind's aid, leaving individual guards to maintain long, lonely watches. Delivering this bundle not only keeps a sentry fed, but also sparks an enduring, bashful courtship between the two townspeople.",
  ["1"] = {
    {file = "Audio/Transport/full_item_parker-s-lunch-bfd726154d14f7fd717d/1-0000.mp3", duration = 44.4865306, start = 0},
  },
}
P.transport["item:partially-filled-vessel"] = {
  hash = "b93b8c",
  fullHash = "b93b8c",
  text = "Partially Filled Vessel. The Partially Filled Vessel is an enchanted container used to transport blessed moonwell water across Teldrassil. Given to young night elf initiates by Tenaron Stormgrip in Aldrassil, it carries water drawn from Shadowglen toward the settlement of Dolanaar. Within the boughs of Aldrassil, initiates of the kaldorei collect blessed waters from the secluded moonwell of Shadowglen. Tenaron Stormgrip pours that pure sample into this specialized vessel, preparing it for travel across the World Tree. The vessel remains only partially filled because its journey has merely begun; more sacred waters from across Teldrassil must eventually be gathered to tend to the island's health. Carrying the vessel requires traveling south through the valley's gates and following the cobblestone roads west to Dolanaar. The journey marks a young adventurer's departure from the protected nursery of Shadowglen out into the broader wilds of Teldrassil. At Dolanaar's central moonwell, Corithras Moonrage takes custody of the vessel to direct the next phase of the ritual.",
  ["1"] = {
    {file = "Audio/Transport/full_item_partially-filled-vessel-0265860468fbd9452ae2/1-0000.mp3", duration = 58.0702041, start = 0},
  },
}
P.transport["item:pendant-of-shadow"] = {
  hash = "86df95",
  fullHash = "86df95",
  text = "Pendant of Shadow. The Pendant of Shadow is a dark talisman worn by the renegade warlock Morganth atop the Tower of Ilgalar in the Redridge Mountains. Brought to the mage Theocritus at the Tower of Azora, it serves as undeniable proof that the rogue spellcaster has been eliminated before his sinister ambitions could bear fruit. Held by the rogue warlock Morganth within his perch at the Tower of Ilgalar, the Pendant of Shadow is steeped in dark sorcery. Morganth sought to unravel the mysteries of the Scythe of Elune, an ancient relic of immense and volatile power. Fearing the havoc the warlock could unleash upon the Redridge Mountains and the kingdom of Stormwind, the mage Theocritus tasked adventurers with infiltrating Ilgalar, ending Morganth's plotting, and wresting the talisman from his grasp as proof of his demise.",
  ["1"] = {
    {file = "Audio/Transport/full_item_pendant-of-shadow-e9d71e9be1d76de7b6b3/1-0000.mp3", duration = 42.3183673, start = 0},
  },
}
P.transport["item:pendant-of-the-sea-lion"] = {
  hash = "f935dc",
  fullHash = "f935dc",
  text = "Pendant of the Sea Lion. The Pendant of the Sea Lion is a sacred druidic talisman representing the union of aquatic agility and endurance. Assembled at the Shrine of Remulos in Moonglade, it serves as proof that an initiate is ready to master their aquatic form. To claim the aquatic aspect of the sea lion, a druid must prove mastery over the water's greatest hazards. The pendant is created by recovering two distinct halves: one embodying the agility needed to slip past aquatic predators, and the other granting the endurance required to withstand prolonged submersion. Brought before the Shrine of Remulos in Moonglade, the two pieces are joined into a single whole. Once forged, the completed pendant is brought before elder mentors—such as Turak Runetotem on the towering rises of Thunder Bluff or Mathrengyl Bearwalker in Darnassus. The talisman provides undeniable proof of the initiate's trials under Dendrite Starblaze, permitting the elders to bestow the secrets of shifting into an aquatic form.",
  ["1"] = {
    {file = "Audio/Transport/full_item_pendant-of-the-sea-lion-008c0fa630ce85cd2b20/1-0000.mp3", duration = 57.6783673, start = 0},
  },
}
P.transport["item:perenolde-tiara"] = {
  hash = "97470b",
  fullHash = "97470b",
  text = "Perenolde Tiara. The Perenolde Tiara is an emerald-studded heirloom of Alterac's fallen royal house, originally fashioned by dwarven craftsmen of Ironforge. Lost amidst the destruction of the kingdom, it eventually fell into the greedy hands of an ogre wandering the ruins before drawing the interest of collectors in Stormwind. Before the mountainous realm of Alterac collapsed in infamy and rubble during the Second War, its ruling house was the Perenolde family. Among their treasures was this delicate tiara, commissioned from master jewelers in Ironforge and set with brilliant emeralds. When Alterac fell to ruin following King Aiden Perenolde's treachery, the crown jewel vanished into the chaotic devastation of the high crags. Rather than being buried forever beneath the snow, the tiara was unearthed by Grel'borg the Miser, an ogre mage who rummages through the ruins of Alterac searching for abandoned wealth. News of the surviving relic reached Count Remington Ridgewell, a wealthy noble in Stormwind eager to acquire famous relics for his family museum, prompting a search to prise the tiara from the ogre's grasping hands.",
  ["1"] = {
    {file = "Audio/Transport/full_item_perenolde-tiara-e501cecdbad34b9557af/1-0000.mp3", duration = 64.7053061, start = 0},
  },
}
P.transport["item:phial-of-scrying"] = {
  hash = "3da006",
  fullHash = "3da006",
  text = "Phial of Scrying. The Phial of Scrying is an enchanted vessel provided by the ancient of lore Onu in Darkshore. When used, it manifests a scrying bowl that allows distant communion across the corrupted woodlands. Entrusted to scouts investigating deep within Darkshore, the Phial of Scrying contains mystical waters that conjures a temporary scrying bowl upon the earth. This tool enables long-distance divination, allowing travelers venturing into perilous reaches like the Master's Glaive to commune directly with Onu without immediately journeying back to his grove.",
  ["1"] = {
    {file = "Audio/Transport/full_item_phial-of-scrying-34b10e240e41e7589073/1-0000.mp3", duration = 30.5632653, start = 0},
  },
}
P.transport["item:piece-of-krom-zar-s-banner"] = {
  hash = "fd6080",
  fullHash = "fd6080",
  text = "Piece of Krom'zar's Banner. A torn strip of cloth taken from the standards of Warlord Krom'zar, commander of the Kolkar retaliatory force. It serves as tangible proof to Regthar Deathgate that the centaur invasion from Desolace has been broken. Following the systematic defeat of Kolkar chieftains across the Barrens, a furious warband marched east from Desolace intent on revenge. Led by Warlord Krom'zar, these invaders assaulted the defensive bunkers west of the Crossroads. Slicing a remnant from the warlord's fallen battle standard provides undeniable proof to Regthar Deathgate that the assault was crushed and the southern trade routes preserved for the Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_item_piece-of-krom-zar-s-banner-edf7de426ffbdefeeef4/1-0000.mp3", duration = 36.6497959, start = 0},
  },
}
P.transport["item:plainstrider-beak"] = {
  hash = "051b1a",
  fullHash = "051b1a",
  text = "Plainstrider Beak. Plainstrider Beaks are harvested from the tall, flightless birds roaming the scrublands of the Barrens. Huntmasters at the Crossroads collect these beaks as physical proof that a hunter has culled local birds threatening the settlement's provisions. The vast savannahs surrounding the Crossroads are populated by various breeds of plainstrider, including greater, fleeting, and ornery varieties. While relatively simple prey compared to the fiercer beasts of central Kalimdor, their aggressive foraging makes them a constant pest around settlements. Sergra Darkthorn tasks arriving hunters with bringing back Plainstrider Beaks to confirm the flock has been culled away from essential supply lines and storehouses.",
  ["1"] = {
    {file = "Audio/Transport/full_item_plainstrider-beak-ba529bf2ab6b0f1aa855/1-0000.mp3", duration = 38.7395918, start = 0},
  },
}
P.transport["item:plainstrider-feather"] = {
  hash = "11a04d",
  fullHash = "11a04d",
  text = "Plainstrider Feather. Plucked from the swift birds roaming the plains of Mulgore, Plainstrider Feathers are essential materials gathered by young hunters on Red Cloud Mesa. The tauren of Camp Narache use them primarily for crafting clothing and tribal adornments, while honoring the creatures that provide for the village. On Red Cloud Mesa, young tauren learn early that survival relies on keen tracking and hunting. Plainstriders run wild across the grassy plateau, offering both sustenance and practical materials. Plucking their sturdy feathers allows the camp to craft traditional garments and gear. Presenting these feathers alongside fresh meat to Grull Hawkwind demonstrates respect for the tribe's needs and serves as the very first test toward being recognized by Chief Hawkwind and welcomed in Thunder Bluff.",
  ["1"] = {
    {file = "Audio/Transport/full_item_plainstrider-feather-86665d3bea5c5c4d155b/1-0000.mp3", duration = 45.0612245, start = 0},
  },
}
P.transport["item:plainstrider-kidney"] = {
  hash = "73d1be",
  fullHash = "73d1be",
  text = "Plainstrider Kidney. A harvested organ taken from the swift-footed plainstriders roaming the arid plains of the Barrens. Though unappetizing to most travelers, it serves as a bizarre yet essential component in exotic Kalimdor brewing traditions. The vast expanses of the Barrens are populated by tall, flightless birds known as plainstriders. While their feathers and meat are often claimed by hunters for tools and simple rations, Brewmaster Drohn in Ratchet seeks their internal organs for an entirely different purpose. According to the eccentric brewer, plainstrider kidneys are a necessary ingredient to replicate Chen Stormstout's legendary potent ale, imparting a unique kick passed down through an unconventional lineage of brewmasters.",
  ["1"] = {
    {file = "Audio/Transport/full_item_plainstrider-kidney-578aa467f3d22da2d0e8/1-0000.mp3", duration = 42.7363265, start = 0},
  },
}
P.transport["item:plainstrider-meat"] = {
  hash = "16c33a",
  fullHash = "16c33a",
  text = "Plainstrider Meat. Plainstrider Meat is freshly harvested game taken from the flightless birds that wander the plains of Mulgore. For the young tauren coming of age on Red Cloud Mesa, gathering this sustenance serves as both vital winter provisions and a core rite of passage. Tauren life is inextricably bound to the land, balancing respect for nature with the practical necessity of survival. On Red Cloud Mesa, the settlement of Camp Narache depends heavily on game hunted from the surrounding grasslands. Plainstrider meat provides essential food reserves for the village when stocks run lean, while the birds' plumage offers material for clothing and ceremonial adornments. Hunting plainstriders is one of the initial tests given to youth seeking to earn the tribe's respect. Grull Hawkwind directs hopeful hunters to stalk the swift birds across the mesa, gathering meat and feathers to prove their tracking skills and self-reliance before appearing before his father, Chief Hawkwind.",
  ["1"] = {
    {file = "Audio/Transport/full_item_plainstrider-meat-9d061389b238c8e99d6f/1-0000.mp3", duration = 54.2563265, start = 0},
  },
}
P.transport["item:plainstrider-scale"] = {
  hash = "02e1fe",
  fullHash = "02e1fe",
  text = "Plainstrider Scale. A tough scale harvested from the tallstriders roaming the sweeping plains of Mulgore. It serves as a vital component in a traditional remedy prepared by Maur Raincaller to counter a virulent infection. While plainstriders are best known for their soft feathers and lean meat, their powerful legs are covered in tough, protective scales. These scales are resilient against the harsh scrubland terrain and predator claws. Finding one intact and suitable for medicine requires patience, as only select plainstriders across Mulgore yield scales firm enough to be ground and prepared for folk remedies.",
  ["1"] = {
    {file = "Audio/Transport/full_item_plainstrider-scale-cff846ee1ddb747944b7/1-0000.mp3", duration = 33.3061224, start = 0},
  },
}
P.transport["item:plainstrider-talon"] = {
  hash = "9216bf",
  fullHash = "9216bf",
  text = "Plainstrider Talon. A Plainstrider Talon is a sharp claw harvested from the large, flightless plainstriders native to Mulgore. Tauren shamans use these talons alongside other natural reagents to craft sacred cleansing totems when the land's water sources are corrupted. The large, flightless plainstriders roam the open grasses of Mulgore, relying on powerful legs and sharp claws to defend against predators and forage through the tough prairie earth. To the tauren of Bloodhoof Village, every part of a hunted beast carries spiritual resonance. When goblin ventures tainted sacred sources like the Winterhoof Water Well, shaman Mull Thunderhorn sought plainstrider talons alongside prairie wolf paws. In tauren ritual crafting, gathering reagents from native predators and foragers allows the spiritual essence of the land to be channeled into totems capable of purging unnatural poisons.",
  ["1"] = {
    {file = "Audio/Transport/full_item_plainstrider-talon-b47fc39d00f9999b35b5/1-0000.mp3", duration = 48.3265306, start = 0},
  },
}
P.transport["item:podrig-s-order"] = {
  hash = "3e0d59",
  fullHash = "3e0d59",
  text = "Podrig's Order. Podrig's Order is a written military requisition penned by Deathguard Podrig at the Sepulcher. It requests a fresh shipment of weapons from Undercity merchant Gordon Wendham to keep Silverpine's Forsaken garrison properly armed. Silverpine Forest is a precarious frontier for the Forsaken, caught between encroaching Scourge, feral beasts, and other lurking threats. After an equipment inventory conducted by Deathguard Podrig on the orders of Executor Hadrec, the Sepulcher's stores were found mostly adequate but desperately low on replacement weapons. This official dispatch details the needed blades and arms to sustain the Deathguards holding the outpost. Because weapons cannot be forged easily amidst the damp crypts of Silverpine, the request is directed to Gordon Wendham, a weapon dealer located in the bustling Trade Quarter of the Undercity. To expedite the order, couriers carry the document directly to bat master Karos Razok, taking advantage of Forsaken flight paths to secure a swift resupply from the capital.",
  ["1"] = {
    {file = "Audio/Transport/full_item_podrig-s-order-8f324025516f5f936e0b/1-0000.mp3", duration = 58.4097959, start = 0},
  },
}
P.transport["item:pork-belly-pie"] = {
  hash = "c61b44",
  fullHash = "c61b44",
  text = "Pork Belly Pie. Pork Belly Pie is a savory, homemade dish baked by 'Auntie' Bernice Stonefield in Elwynn Forest. Despite the bitter, long-running feud between the Stonefield and Maclure families, young Billy Maclure cannot resist Auntie Bernice's cooking, demanding a pie as a bribe to reveal information about a lost family heirloom. The Stonefield and Maclure families have nursed a bitter rivalry for years, quarreling over land and pride in the heart of Elwynn Forest. Despite this hostility, young Billy Maclure harbors a glaring weakness: he loves Auntie Bernice's famous pork belly pie. When a valuable family necklace goes missing, Billy refuses to share what he knows until an adventurer delivers him a warm slice. Bernice bakes it with great reluctance—and a pointed wish that the greedy boy chokes on it—proving that culinary reputation can sometimes breach even the stubbornest family feuds.",
  ["1"] = {
    {file = "Audio/Transport/full_item_pork-belly-pie-1fd0a5d202d7808734cc/1-0000.mp3", duration = 50.4946939, start = 0},
  },
}
P.transport["item:powdered-azurite"] = {
  hash = "9c8f77",
  fullHash = "9c8f77",
  text = "Powdered Azurite. Powdered Azurite is a crushed mineral reagent harvested from the Azurelode Mine in Hillsbrad Foothills. It is sought by the master armorer Thun'grim Firegaze to temper and forge brutal armor for rising Horde warriors. Powdered Azurite is a refined dust derived from the mineral veins beneath Hillsbrad Foothills. The human workers of Azurelode Mine delve into the earth to extract this distinctive blue stone, pulverizing and packing it for trade and metallurgy. In the hands of a skilled smith, the dust acts as a crucial flux or additive when working dense metals, enhancing durability and lending unique resilience to finished armor. Though native to human-held tunnels across the Great Sea, Powdered Azurite is recognized by veteran Horde blacksmiths for its exceptional metallurgical properties. Thun'grim Firegaze, an aging orc armorer residing in the Barrens, demands small quantities of the powdered stone alongside refined iron and fiery reagents. Mixed into the smelt, the powder allows him to hammer out the heavy, punishing plating that characterizes his masterwork battle armor.",
  ["1"] = {
    {file = "Audio/Transport/full_item_powdered-azurite-b25e846e725b3f5bc007/1-0000.mp3", duration = 64, start = 0},
  },
}
P.transport["item:powers-of-the-void"] = {
  hash = "064427",
  fullHash = "064427",
  text = "Powers of the Void. Powers of the Void is a rare magical tome originally kept in a restricted wing of Northshire Abbey's library. After an errant novice stole it while defecting to the Defias Brotherhood, the warlock mentor Drusilla La Salle seeks its recovery to further her own study of dark magic. The Northshire Abbey archives hold far more than holy scripture and clerical records. Tucked away in a protected wing of the abbey's library was Powers of the Void, a scholarly work regarding shadow and nether energies, presumably penned by the archmage Khadgar. Given the dangerous nature of such research, abbey authorities kept the book heavily guarded and strictly off-limits to casual visitors. This kept it out of the hands of Northshire's local warlock mentor, Drusilla La Salle, who could not loiter near the restricted shelves without drawing unwanted suspicion from the priesthood. The tome finally left the abbey's walls not by Drusilla's hand, but through betrayal from within. A novice studying at Northshire abandoned his vows to join the Defias Brotherhood, looting several valuable volumes as he fled into the neighboring vineyards. Taking advantage of the thief's opportunism, Drusilla sends promising warlock initiates directly into the Defias bandit camp to seize the tome from their tents. Retrieving the text serves a double purpose: it places dark knowledge into the trainer's grasp and tests whether a novice possess the nerve required to bind otherworldly demons.",
  ["1"] = {
    {file = "Audio/Transport/full_item_powers-of-the-void-786a968596b5bf1557f2/1-0000.mp3", duration = 82.5208163, start = 0},
  },
}
P.transport["item:prairie-alpha-tooth"] = {
  hash = "7ac795",
  fullHash = "7ac795",
  text = "Prairie Alpha Tooth. A Prairie Alpha Tooth is taken from the fierce pack leaders roaming the plains around Thunder Bluff. In tauren tradition, these teeth serve as a potent offering to cleanse and honor the land's precious water sources. The water wells of Mulgore are vital lifelines for the tauren, and maintaining their spiritual purity demands rites of respect and sacrifice. To cleanse the Wildmane Well, Mull Thunderhorn of Bloodhoof Village requires teeth gathered from the prairie wolf alphas that stalk the shadow of Thunder Bluff. As apex predators of the rolling grassy plains, these alphas represent the raw strength of the wild. Offering their teeth honors the balance between hunter, prey, and the spirits of the earth.",
  ["1"] = {
    {file = "Audio/Transport/full_item_prairie-alpha-tooth-3cf5e758d2fe52b511c8/1-0000.mp3", duration = 39.0530612, start = 0},
  },
}
P.transport["item:prairie-wolf-heart"] = {
  hash = "a527bd",
  fullHash = "a527bd",
  text = "Prairie Wolf Heart. A Prairie Wolf Heart is a vital organ harvested from the wolves roaming the grasslands of Mulgore. It serves as an essential ingredient in an urgent folk remedy prepared by Maur Raincaller in Bloodhoof Village to counteract venomous infection. The wolves of the plains are fierce predators, hardy and persistent across the sweeping grasses of Mulgore. Their hearts are sought out by Maur Raincaller, a tauren residing in Bloodhoof Village who fell victim to the legendary plainstrider known as Mazzranache. Struck by the creature's virulent, fever-inducing venom, Maur relies on traditional plains medicine to halt the spreading poison. Alongside other potent reagents like cougar bone and bird gizzard, the vital essence of a freshly slain prairie wolf provides the cleansing properties needed to concoct a cure before delirium proves fatal.",
  ["1"] = {
    {file = "Audio/Transport/full_item_prairie-wolf-heart-677966e4778b4f918d55/1-0000.mp3", duration = 49.0579592, start = 0},
  },
}
P.transport["item:prairie-wolf-paw"] = {
  hash = "becf4d",
  fullHash = "becf4d",
  text = "Prairie Wolf Paw. Prairie Wolf Paws are harvested from the predators roaming the plains of Mulgore. Shamanic practitioners, such as Mull Thunderhorn in Bloodhoof Village, use them as organic components to bind the natural power of the land into cleansing totems. Prairie wolves stalk the rolling grasses across Mulgore, hunting in packs alongside prairie stalkers and their pack alphas. While dangerous to young hunters and local livestock, the creatures are deeply intertwined with the spiritual balance of the plains. Tauren shamans view the wolf's paws not merely as trophies, but as vital conduits of the earth's innate vitality. When goblin ventures tainted Mulgore's sacred water reserves, shaman Mull Thunderhorn required the physical aid of the land itself to counteract the pollution. Bound together with plainstrider talons, the wolf paws provide the raw spiritual resonance necessary to fashion cleansing totems, beginning the vital work of purifying the Winterhoof Water Well.",
  ["1"] = {
    {file = "Audio/Transport/full_item_prairie-wolf-paw-18ac099f943315cc58ce/1-0000.mp3", duration = 55.275102, start = 0},
  },
}
P.transport["item:pridewing-venom-sac"] = {
  hash = "5d6933",
  fullHash = "5d6933",
  text = "Pridewing Venom Sac. Pridewing Venom Sacs are harvested from the lethal wyverns nesting around Mirkfallon Lake in the Stonetalon Mountains. The night elves of Astranaar seek to stockpile and destroy these sacs after intelligence suggests Horde operatives harvest the potent poison for covert assassinations. The pridewings of Stonetalon are dangerous, airborne predators native to the peaks south of Ashenvale, particularly around Mirkfallon Lake. While wild wyverns are naturally venomous, Alliance intelligence out of Theramore suggests that Horde assassins have begun milking them for poison to coat blades used in covert raids against night elf settlements. To safeguard their kin and disrupt enemy supplies, the Sentinels in Astranaar hire scouts to hunt down the beasts and collect the venom glands before the Horde can secure them.",
  ["1"] = {
    {file = "Audio/Transport/full_item_pridewing-venom-sac-45aaca7abb2bdcbd15f5/1-0000.mp3", duration = 46.4195918, start = 0},
  },
}
P.transport["item:prismatic-punch-card"] = {
  hash = "e4196e",
  fullHash = "e4196e",
  text = "Prismatic Punch Card. The Prismatic Punch Card is the highest security clearance data card found within the fallen city of Gnomeregan. Upgraded sequentially through a series of Matrix Punchograph terminals, it holds data desperately sought by gnome refugees in Ironforge. When the gnomes fled the trogg invasion and toxic irradiation of Gnomeregan, massive troves of research and civic records were abandoned in the depths. To safeguard high-level systems, the gnomes utilized an escalating security protocol. Accessing the Matrix Punchograph 3005-D terminal in the lower Engineering Labs requires working through a progression of punch cards: starting from a basic White Punch Card and advancing through Yellow, Blue, and Red clearances at dedicated terminals before stamping the final Prismatic Punch Card. Its encoded clearance level is whimsically noted as pending the invention of an entirely new number.",
  ["1"] = {
    {file = "Audio/Transport/full_item_prismatic-punch-card-e7c51060f2075017f1e4/1-0000.mp3", duration = 47.9346939, start = 0},
  },
}
P.transport["item:pristine-spider-silk"] = {
  hash = "775d6f",
  fullHash = "775d6f",
  text = "Pristine Spider Silk. Pristine Spider Silk is an exceptionally fine thread gathered from the venomous arachnids of Duskwood. Mages of Stormwind commission this rare material to weave durable, enchanted robes worthy of recognized practitioners of the arcane arts. Not just any thread can hold the enchantments and wear demanded by a practicing mage. While ordinary spider silk is common enough among tailors, only the immaculate strands taken from carrion recluses and black widow hatchlings in the shadowed groves of Duskwood possess the necessary resilience. The mages of Stormwind's Wizard's Sanctum send their rising adepts into these perilous woods to harvest pristine spools, tasking local master tailor Wynne Larson with fashioning the material into a garment fit for an adept.",
  ["1"] = {
    {file = "Audio/Transport/full_item_pristine-spider-silk-b5de9760ce7ecbbcd29f/1-0000.mp3", duration = 44.4865306, start = 0},
  },
}
P.transport["item:prowler-claws"] = {
  hash = "1095ec",
  fullHash = "1095ec",
  text = "Prowler Claws. Prowler Claws are severed trophies collected from the savannah prowlers that stalk the sun-baked plains of the Barrens. Brought to Sergra Darkthorn at the Crossroads, they serve as tangible proof that a hunter can stalk and overpower Kalimdor's deadliest stealth predators. The tall grasses of the Barrens conceal Savannah Prowlers, large feline predators known for their patience, cunning, and lethal strikes. Hunting them is a vital proving ground for rising Horde warriors and scouts. Unlike herbivorous quarry like the plainstrider or the zhevra, prowlers actively ambush anything entering their hunting grounds. Taking their sharp, curved claws requires besting a creature that relies on absolute stealth and territorial aggression, proving to the camp's huntress that the stalker has become the prey. At the Crossroads, Sergra Darkthorn demands these claws to measure an initiate's readiness for greater trials. Bringing back a handful of claws demonstrates that a hunter has mastered tracking among the golden savannah grass and can withstand claws capable of tearing leather and flesh. Those who return with their prize show they possess the awareness needed to survive even deadlier beasts lurking across the plains.",
  ["1"] = {
    {file = "Audio/Transport/full_item_prowler-claws-38d7e4ab4a4ae2d883a8/1-0000.mp3", duration = 67.6832653, start = 0},
  },
}
P.transport["item:pure-hearts"] = {
  hash = "0f6173",
  fullHash = "0f6173",
  text = "Pure Hearts. Pure Hearts are ritual reagents provided to Forsaken warlocks by Carendin Halgar in the Undercity. They are used to lure and manifest a succubus across the Twisting Nether so the practitioner can defeat and bind the demon. Demonology relies on exploiting base desires and spiritual vulnerabilities. To summon a succubus into the Magic Quarter of the Undercity, Carendin Halgar provides warlocks with Pure Hearts. When placed upon the summoning circle, these untainted spiritual essences act as potent bait, drawing the seductive demon across the Twisting Nether into the mortal realm. Once the demon manifests, the warlock must resist her enthralling mind-charms and strike her down in combat. Overcoming the succubus asserts mystical dominance, banishing her back to the Twisting Nether until Carendin teaches the warlock the spell to summon her forth at will.",
  ["1"] = {
    {file = "Audio/Transport/full_item_pure-hearts-f79d6e448c9b140014d4/1-0000.mp3", duration = 48.7444898, start = 0},
  },
}
P.transport["item:purified-kor-gem"] = {
  hash = "6fadbf",
  fullHash = "6fadbf",
  text = "Purified Kor Gem. A Purified Kor Gem is a rare, consecrated crystal required by the weaponsmith Jordan Stilwell outside Ironforge. Once tainted by dark energies, it must be reclaimed from the depths of Kalimdor and cleansed by elven magic before it can be forged into a holy arm of the Light. The stone begins its journey as a Corrupted Kor Gem in the possession of the vile naga lurking within Blackfathom Deeps, deep beneath the coast of Ashenvale. To cleanse the stone of its aquatic, shadowy taint, a paladin must seek out the night elf Thundris Windweaver in Auberdine. Drawing upon arcane and natural arts, Thundris purges the corruption from the stone, transforming it into the radiant Purified Kor Gem. Only in this pristine state is it fit to serve as a conduit for holy power. Outside Ironforge in the snowy crags of Dun Morogh, the human weaponsmith Jordan Stilwell requires the gem as a key component for forging a masterwork weapon. Having long possessed designs for an armament worthy of the Silver Hand, Stilwell lacked the exotic materials to realize his plans. The Purified Kor Gem, alongside Whitestone Oak Lumber and rare ore, provides the spiritual core necessary to channel the paladin's righteous wrath.",
  ["1"] = {
    {file = "Audio/Transport/full_item_purified-kor-gem-8bca26e65257d36d34bb/1-0000.mp3", duration = 72.3853061, start = 0},
  },
}
P.transport["item:putrid-claw"] = {
  hash = "5af7c7",
  fullHash = "5af7c7",
  text = "Putrid Claw. Putrid Claws are the decaying hands severed from mindless undead prowling the woods west of Brill. Deathguard Dillinger collects them as definitive proof that the encroaching Scourge threat near the old bridge is being held at bay. Even in their own homeland, the Forsaken are not entirely safe from the Lich King's reach. Pockets of mindless Scourge—rotting dead and ravaged corpses—regularly wander across the eastern borders into Tirisfal Glades, clustering along roads and near the old bridge west of Brill. To ensure the safety of travelers and garrison supply lines, the Deathguards place bounties on these wandering horrors. A severed putrid claw serves as unmistakable, physical evidence that one more shambling corpse has been put down for good.",
  ["1"] = {
    {file = "Audio/Transport/full_item_putrid-claw-5259d033c16726f8554a/1-0000.mp3", duration = 42.5795918, start = 0},
  },
}
P.transport["item:pyrewood-shackle"] = {
  hash = "a20967",
  fullHash = "a20967",
  text = "Pyrewood Shackle. Pyrewood Shackles are enchanted restraints worn by the beleaguered inhabitants of Pyrewood Village in southern Silverpine Forest. Imbued with the strange magic of Archmage Arugal, these bands are linked to the eerie curse that transforms ordinary townsfolk into ravenous worgen once night falls. The cursed village of Pyrewood holds an unsettling secret: by day, its residents carry on ordinary lives appearing as typical humans, but the setting sun twists them into feral Moonrage worgen. Archmage Arugal bound these villagers in enchanted shackles as part of his twisted experiments with worgen sorcery. Dalar Dawnweaver, an arcane researcher stationed at the Sepulcher for the Forsaken, studies these shackles to decode the enchantments driving this dual existence. By gathering and analyzing the lingering energy on the bands, Dawnweaver seeks a deeper understanding of Arugal's magic in hopes of unraveling the mad archmage's hold over the region.",
  ["1"] = {
    {file = "Audio/Transport/full_item_pyrewood-shackle-367bfbb46ed2ef3bf97f/1-0000.mp3", duration = 53.9428571, start = 0},
  },
}
P.transport["item:quinn-s-potion"] = {
  hash = "b49fe8",
  fullHash = "b49fe8",
  text = "Quinn's Potion. Quinn's Potion is a restorative draught concocted by Apothecary Renferrel in the Sepulcher. It is brewed to stabilize and revitalize the wounded Deathstalker Quinn Yorick following a disastrous scouting patrol in Silverpine Forest. After Deathstalker Quinn Yorick was severely battered and incapacitated near the Ivar Patch, word reached the Royal Apothecary Society at the Sepulcher. Apothecary Renferrel hastily compounded this specialized draught to facilitate Quinn's recovery. While Renferrel rarely lets minor field casualties distract him from his grander, more sinister research for Lady Sylvanas, he provided the restorative to get the injured scout back on his feet and capable of travel.",
  ["1"] = {
    {file = "Audio/Transport/full_item_quinn-s-potion-8ebe7db3b5401d840f80/1-0000.mp3", duration = 41.6914286, start = 0},
  },
}
P.transport["item:ran-bloodtooth-s-skull"] = {
  hash = "8a4aec",
  fullHash = "8a4aec",
  text = "Ran Bloodtooth's Skull. Ran Bloodtooth's Skull is a grisly trophy taken from the chieftain of the corrupted furbolgs in Ashenvale. Brought back to the night elves of Astranaar, it serves as tangible proof that a ferocious threat to the woodland realm has been ended. The forests of Ashenvale have suffered immensely from demonic taint and wilderness corruption, driving once-peaceful furbolg tribes into murderous madness. Among the fiercest of these hostile chieftains was Ran Bloodtooth. Recovering his skull provides the night elf Sentinels with definite proof that the brute has fallen, breaking his hold over the local furbolgs and offering a small measure of respite to the beleaguered town of Astranaar.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ran-bloodtooth-s-skull-6010a92deab881065fd5/1-0000.mp3", duration = 36.9632653, start = 0},
  },
}
P.transport["item:raptor-head"] = {
  hash = "5e5aa6",
  fullHash = "5e5aa6",
  text = "Raptor Head. A severed raptor head serves as bloody proof of a beast slain in the Barrens. Gazrog of the Crossroads demands these macabre trophies to purge the local packs after an improbable theft of guard payroll. Life in the arid plains of the Barrens is harsh enough without local wildlife raiding settlement towers. When a chest containing guard payroll vanished from the Crossroads watchtower, the defenders caught an improbable culprit red-handed: a wild raptor. Perplexed and furious, Gazrog placed an immediate bounty on the cunning reptiles prowling the savannah. Bringing severed raptor heads back to the outpost proves that these predatory pests are being culled before they can pilfer any more Horde supplies.",
  ["1"] = {
    {file = "Audio/Transport/full_item_raptor-head-473c223622b5d3b9d483/1-0000.mp3", duration = 38.7395918, start = 0},
  },
}
P.transport["item:rare-earth"] = {
  hash = "7c105d",
  fullHash = "7c105d",
  text = "Rare Earth. Rare Earth is a specialized package of mineral-rich soil procured from Darnassus for botanic experiments on Teldrassil. It is sent via courier from Dolanaar to the herbalist researcher Denalan at his lakeside camp near Lake Al'Ameth. Teldrassil's newly grown ecosystem requires careful observation and nurturing, prompting herbalists across the island to study how various plants respond to foreign or enriched soils. This particular parcel of rare earth was requisitioned directly from Darnassus by Denalan, an eccentric botanist stationed along the eastern shore of Lake Al'Ameth. After languishing in transit and turning up late in Dolanaar, herbalist Syral Bladeleaf entrusts travelers passing south to deliver the perishable soil to Denalan before its potency fades.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rare-earth-4cbdcbbf15a398191215/1-0000.mp3", duration = 45.6097959, start = 0},
  },
}
P.transport["item:rattlecage-skull"] = {
  hash = "6e4f70",
  fullHash = "6e4f70",
  text = "Rattlecage Skull. Rattlecage Skulls are the shattered remnants of mindless undead roaming the ruined outskirts of Deathknell. Novice Forsaken warlocks must gather these calcified trophies for Venya Marthand to demonstrate their emerging will and qualify for the dark arts of summoning. Within the sunless bounds of Deathknell, newly raised Forsaken with an affinity for dark magic are guided by Venya Marthand. To prove that a fledgling practitioner has the fortitude to bend extraplanar creatures to their command, Venya tasks them with subduing the lingering Rattlecage Skeletons near the ruined smithy. Striking down these lesser undead and retrieving their severed skulls serves as both a practical test of discipline and a ritual foundation before learning to breach the void and enslave a first demonic minion.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rattlecage-skull-14743e55e888fd6a34aa/1-0000.mp3", duration = 43.755102, start = 0},
  },
}
P.transport["item:raven-claw-talisman"] = {
  hash = "bec683",
  fullHash = "bec683",
  text = "Raven Claw Talisman. The Raven Claw Talisman is a sacred night elf relic tied to the Druids of the Talon. Kept deep within Ban'ethil Barrow Den on Teldrassil, it is one of the four essential Relics of Wakening required to safely guide slumbering druids back from the Emerald Dream. The Raven Claw Talisman is preserved within a designated chest inside Ban'ethil Barrow Den, the subterranean sanctuary where Teldrassil's Druids of the Talon entered their deep meditative slumbers. Druidic hibernation is a delicate spiritual threshold. If a druid's link to the waking world is shattered without the proper ceremonial focus, their spirit risks being stranded within the Emerald Dream indefinitely. Alongside the Black Feather Quill, the Sapphire of Sky, and the Rune of Nesting, the talisman is required by Athridas Bearmantle in Dolanaar to conduct the ritual of awakening and bring the slumberers back safely. When corrupted Gnarlpine furbolgs overran Ban'ethil Barrow Den, the sacred chests and the sleeping druids fell into immediate peril. The furbolg desecration severed the sanctum from outside aid and put the relics in danger of being lost or destroyed. Athridas Bearmantle tasks defenders of Teldrassil with braving the winding earthen corridors of the den to secure the Raven Claw Talisman before the displaced druids are lost to the Dream forever.",
  ["1"] = {
    {file = "Audio/Transport/full_item_raven-claw-talisman-81f120c74dfa1c554976/1-0000.mp3", duration = 78.8897959, start = 0},
  },
}
P.transport["item:razorflank-s-medallion"] = {
  hash = "67b2c8",
  fullHash = "67b2c8",
  text = "Razorflank's Medallion. Razorflank's Medallion is a personal token carried by Charlga Razorflank, the crone ruling over Razorfen Kraul. Recovered from the heart of the quilboar stronghold, it serves as undeniable proof that the matriarch has been brought down. Carried by Charlga Razorflank herself, this medallion represents the authority of the crone who leads the Razorfen quilboar. When Falfindel Waywarder at Thalanaar learns of the fates of fallen explorers like Heralath and the dwarf Lonebrow, he tasks Alliance adventurers with striking directly at the quilboar leader. Presenting the crone's medallion confirms her death, reassuring the night elf sentinels guarding the borders of Feralas that the gathered forces within the Kraul have lost their leader.",
  ["1"] = {
    {file = "Audio/Transport/full_item_razorflank-s-medallion-03aa35d344d98cecc476/1-0000.mp3", duration = 40.8032653, start = 0},
  },
}
P.transport["item:reagent-pouch-shaman"] = {
  hash = "dfaf8e",
  fullHash = "dfaf8e",
  text = "Reagent Pouch (shaman). A reagent pouch carried by Burning Blade cultists lurking in the crags of Durotar. Shaman seeking to communing with fire require these gathered spell components to distill their initial fire sapta. To forge a fire sapta and attune a young shaman to the spirits of flame, specific ritual catalysts are vital. Cultists of the Burning Blade carry small satchels stocked with reagents tailored for demonic fire conjurations. The hermit Telf Joolam uses these gathered powders and oils, combined with the fire tar of Razormane quilboar, to craft the draught needed to grant sight into the realm of fire. Though the Burning Blade perverts flame for destruction and fel sorcery, the physical elements within their pouches remain bound to the primal nature of heat and combustion. Shamanic philosophy maintains that all elemental forces exist in tension: fire is both creator and destroyer. By taking the cultists' stolen tools, a shaman reclaims the elemental medium to awaken genuine communion with the spirits.",
  ["1"] = {
    {file = "Audio/Transport/full_item_reagent-pouch-shaman-de728f16dc63144c1be6/1-0000.mp3", duration = 56.9469388, start = 0},
  },
}
P.transport["item:reconstructed-tome"] = {
  hash = "c2ab42",
  fullHash = "c2ab42",
  text = "Reconstructed Tome. The Reconstructed Tome is a pieced-together grimoire of dark cabal lore, compiled for warlocks seeking to expand their mastery of demonic servants. It contains the arcane knowledge and rituals necessary to summon and bind a predatory felhunter from the Twisting Nether. Recovered in fragments and painstakingly pieced back together, the Reconstructed Tome represents an elusive collection of cabal teachings known formally as the Tome of the Cabal. Warlocks of both the Alliance and the Horde go to great lengths to restore its frayed leaves, consulting occult scholars eager for a mere glimpse of its esoteric contents before surrendering the completed manuscript.",
  ["1"] = {
    {file = "Audio/Transport/full_item_reconstructed-tome-ac3cb94601c35d2693ac/1-0000.mp3", duration = 38.4, start = 0},
  },
}
P.transport["item:recruitment-letter"] = {
  hash = "9e2bea",
  fullHash = "9e2bea",
  text = "Recruitment Letter. The Recruitment Letter is an official dispatch handed to promising adventurers departing Durotar for duty in the Barrens. Issued by scout Takrin Pathseeker, it directs able-bodied volunteers to report to the border outpost overseen by Kargal Battlescar. As young warriors and scouts prove themselves around Razor Hill, the Horde's gaze turns west toward the vast, untamed expanse of the Barrens. Takrin Pathseeker identifies promising recruits who appear strong enough to handle frontline service and provides them with this letter. Crossing the Southfury River bridge marks a rite of passage: leaving the sheltered red dirt of Durotar behind to join the ranks of the Horde standing guard against quilboar, centaur, and Alliance scouts. The letter's intended recipient is Kargal Battlescar, the grizzled veteran managing the outpost just across the river. Kargal evaluates each conscript before formally signing off on their enlistment. Yet holding this letter is only the first step; frontier outposts are perpetually stretched thin, and any signed recruit is swiftly redirected further west to the strategic hub of the Crossroads.",
  ["1"] = {
    {file = "Audio/Transport/full_item_recruitment-letter-90f09711800df8123efc/1-0000.mp3", duration = 64.3134694, start = 0},
  },
}
P.transport["item:red-burlap-bandana"] = {
  hash = "7397ee",
  fullHash = "7397ee",
  text = "Red Burlap Bandana. Red Burlap Bandanas are the crude, dyed cloth masks worn by low-ranking highwaymen and cutpurses of the Defias Brotherhood. In Northshire Valley, Deputy Willem collects these pieces of cloth as proof of slain thieves encroaching near the abbey vineyards. Worn across the lower face, the red burlap bandana serves as the identifying badge of the Defias Brotherhood's rank-and-file. Made from cheap, rough fabric and soaked in red dye, the cloth conceals a thief's features while signaling allegiance to the growing rebellion. In Northshire, young recruits and common thugs carry these scarves into the eastern orchards, unaware that the local guards use the striking red fabric as a grim bounty marker.",
  ["1"] = {
    {file = "Audio/Transport/full_item_red-burlap-bandana-83db018a029fff8a046e/1-0000.mp3", duration = 40.5681633, start = 0},
  },
}
P.transport["item:red-leather-bandana"] = {
  hash = "b36a61",
  fullHash = "b36a61",
  text = "Red Leather Bandana. A signature piece of attire worn by members of the Defias Brotherhood across Westfall. Crafted from dyed crimson leather, it serves as both a practical face covering and an unmistakable symbol of defiance against the Crown of Stormwind. Across the dusty fields and abandoned farms of Westfall, these crimson bandanas conceal the faces of highwaymen, looters, and rebellious laborers. To the People's Militia stationed at Sentinel Hill, the headwear is more than simple cloth—it is concrete proof of allegiance to Edwin VanCleef's rogue fraternity. Scout Galiaan collects these bandanas from passing adventurers to monitor the shifting movements and dwindling numbers of the brotherhood throughout the region.",
  ["1"] = {
    {file = "Audio/Transport/full_item_red-leather-bandana-f4fabc9de7f2112b6900/1-0000.mp3", duration = 39.6016327, start = 0},
  },
}
P.transport["item:red-linen-bandana"] = {
  hash = "1a35ac",
  fullHash = "1a35ac",
  text = "Red Linen Bandana. A red linen bandana is the distinctive facial mask worn by members of the Defias Brotherhood across Elwynn Forest. Beyond concealing a bandit's identity, the cloth is woven from quality linen that resourceful locals often repurpose into useful garments. While lower-ranking initiates and common thugs in Northshire Valley make do with coarse burlap face masks, full-fledged Defias operatives throughout Elwynn Forest wear woven red linen bandanas. The bright crimson fabric serves as both a uniform and a statement of allegiance to Edwin VanCleef's rogue fraternity, disguising faces while signaling insurrection against the crown of Stormwind. Despite their violent associations, the bandanas are cut from respectable yardage. Pragmatic settlers like Sara Timberlain at the Eastvale Logging Camp routinely ask travelers to collect them from outlaw encampments. With a bit of washing and needlework, the contraband cloth is transformed into sturdy clothing and bandages for the working folk of the forest.",
  ["1"] = {
    {file = "Audio/Transport/full_item_red-linen-bandana-4e3867ed36924dfd3c9f/1-0000.mp3", duration = 55.4318367, start = 0},
  },
}
P.transport["item:red-wool-bandana"] = {
  hash = "c999ad",
  fullHash = "c999ad",
  text = "Red Wool Bandana. Red Wool Bandanas are makeshift symbols fashioned by imprisoned Defias cutthroats inside the Stormwind Stockade. Torn from jailhouse wool blankets, they serve as defiant emblems of brotherhood even behind bars. Even locked deep within the high stone walls of the Stormwind Stockade, members of the Defias Brotherhood refuse to surrender their identity. Using scraps torn from prison wool blankets, inmates secretly craft red bandanas to wear as identifying colors. To the guards, these scarves are contraband that spark fatal mutinies; to the prisoners, they are a statement that their brotherhood and rebellion endure, even in chains. The bandanas gained a bitter notoriety after fourteen-year-old prison guard Mac Raskol caught inmates shredding blankets to make them. When he attempted to discipline the prisoners, the Defias convicts stabbed him in the back. In the wake of his death, his grieving grandmother Nikova seeks out adventurers to venture into the rioting dungeon, cull the rioters, and retrieve the crimson cloth as proof of vengeance.",
  ["1"] = {
    {file = "Audio/Transport/full_item_red-wool-bandana-3b67decdc9fd0221a4c3/1-0000.mp3", duration = 58.644898, start = 0},
  },
}
P.transport["item:remaining-drops-of-purest-water"] = {
  hash = "7c9ba7",
  fullHash = "7c9ba7",
  text = "Remaining Drops of Purest Water. The Remaining Drops of Purest Water are the final residue of a specialized draught prepared by the water seer Brine. Shaman carrying these potent drops travel across kingdoms to cleanse a sacred water shrine corrupted by the Scourge's undead plague. Forged through ritual gathering across Kalimdor and Lordaeron, this concentrated elixir retains the purest essence of clean water, prepared by the hermit Brine in the Barrens. While part of the draught is consumed to grant shaman vision of distant elements, the remaining drops are safeguarded for a far more perilous task. Carried to the plague-choked shores of Silverpine Forest near the Sepulcher, the drops serve as the vital purifying catalyst atop the Brazier of Everfount. Consumed in ritual flames alongside the bracers of a fallen, tainted elemental, this pure water cuts through the necrotic corruption, calling forth an untainted spirit of water to commune with the shaman and complete their communion with the element.",
  ["1"] = {
    {file = "Audio/Transport/full_item_remaining-drops-of-purest-water-8e8a642b9c682e028539/1-0000.mp3", duration = 55.6669388, start = 0},
  },
}
P.transport["item:remedy-of-arugal"] = {
  hash = "1f04a8",
  fullHash = "1f04a8",
  text = "Remedy of Arugal. The Remedy of Arugal is an incantation penned by the mage Arugal during his early experiments with worgen magic. Left behind in a dilapidated farmhouse in Silverpine Forest, the spell is sought by Dalar Dawnweaver to unravel the sorcerer's dark work. Before seizing Shadowfang Keep, Archmage Arugal took refuge at an abandoned wheat farm north of the river bridge in Silverpine Forest. There, amidst forgotten farm tools and rotting floorboards, he documented his strange arts in a set of dusty spellbooks. The scroll titled the Remedy of Arugal is among these notes, outlining early methods and magical formulations he devised while dabbling in the dangerous transmutations that cursed the local populace. Dalar Dawnweaver, an accomplished Forsaken spellcaster operating from the Sepulcher, holds little respect for Arugal's pedigree, dismissing the former Dalaran wizard's intellect as fragile and transparent. Even so, Dawnweaver recognizes the urgent need to understand the exact mechanics behind the worgen curse. By recovering the Remedy of Arugal, Forsaken agents provide Dawnweaver with the foundational arcana required to counter Arugal's spreading menace and secure Silverpine for Lady Sylvanas.",
  ["1"] = {
    {file = "Audio/Transport/full_item_remedy-of-arugal-ec63e62d47bf1a428dc0/1-0000.mp3", duration = 69.4334694, start = 0},
  },
}
P.transport["item:rendered-spores"] = {
  hash = "c9ae19",
  fullHash = "c9ae19",
  text = "Rendered Spores. Rendered Spores are a volatile emulsion prepared from fungal samples gathered across the Barrens. Created by Apothecary Helbrim at the Crossroads, the mixture decays rapidly unless swiftly delivered to Apothecary Zamah beneath Thunder Bluff for stabilizing. After acquiring strange fungal spores from mushrooms near the damp oases of the Barrens, Apothecary Helbrim processes them into an active chemical emulsion known as Rendered Spores. The delicate extraction suspends the potent compounds of the fungal growths in a liquid medium, but the solution is chemically unstable. It maintains its vital potency for only forty-five minutes before breaking down and becoming completely useless for scientific study. Because Helbrim lacks the necessary facilities or time at his remote outpost to complete the refining process, the emulsion must be rushed directly to his Forsaken colleague, Apothecary Zamah. Hidden away in the subterranean Pools of Vision beneath Spirit Rise in Thunder Bluff, Zamah possesses the specialized equipment and reagents needed to reseal and finish processing the spores for the Royal Apothecary Society.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rendered-spores-f666336a636390a1bbfc/1-0000.mp3", duration = 62.72, start = 0},
  },
}
P.transport["item:renferrel-s-findings"] = {
  hash = "76fea2",
  fullHash = "76fea2",
  text = "Renferrel's Findings. Renferrel's Findings is a collection of research notes compiled by Apothecary Renferrel in Silverpine Forest. Entrusted to Horde couriers, these documents carry vital data southward to Apothecary Lydon in Tarren Mill to assist in brewing the Forsaken's New Plague. The Royal Apothecary Society labours tirelessly under direct orders from the Dark Lady, Lady Sylvanas Windrunner, to engineer a New Plague. Achieving this breakthrough requires constant collaboration among researchers scattered across Lordaeron. Stationed at the Sepulcher in Silverpine Forest, Apothecary Renferrel compiles these findings to document his progress and experiments, sending the gathered intelligence south to Tarren Mill so fellow researchers can build upon his results. Carrying these papers across the border from Silverpine into the Hillsbrad Foothills represents a vital link in the Forsaken's alchemical network. In Tarren Mill, Apothecary Lydon eagerly awaits Renferrel's notes to cross-reference and advance his own concoctions against the living and the Scourge. Without reliable couriers running the contested roads of Hillsbrad, the Society's decentralized research would quickly stall.",
  ["1"] = {
    {file = "Audio/Transport/full_item_renferrel-s-findings-f95d8e72f357d1feb604/1-0000.mp3", duration = 65.3583673, start = 0},
  },
}
P.transport["item:report-on-the-defias-brotherhood"] = {
  hash = "d4a66f",
  fullHash = "d4a66f",
  text = "Report on the Defias Brotherhood. The Report on the Defias Brotherhood is an official document compiled by City Architect Baros Alexston, detailing the activities and threat posed by Edwin VanCleef's conspirators. Intended to inform the royal court, it is entrusted to the adventurer who uncovered the Deadmines plot for personal delivery to Stormwind Keep. Following the long investigation into the unrest plaguing Westfall and the surrounding territories, City Architect Baros Alexston prepared this formal report to alert the leadership of Stormwind to the full scope of the Defias threat. Rather than sending a standard royal messenger, Alexston entrusted the document to the very hero who untangled the conspiracy. Delivered directly to Stormwind Keep, the report is meant to accompany a personal audience detailing Edwin VanCleef's schemes and the danger they pose to the kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_item_report-on-the-defias-brotherhood-d05d40b4ec84c1097faa/1-0000.mp3", duration = 48.3004082, start = 0},
  },
}
P.transport["item:resonite-crystal"] = {
  hash = "d4faf2",
  fullHash = "d4faf2",
  text = "Resonite Crystal. Resonite Crystals are rare mineral samples mined by kobolds inside Boulderslide Cavern in the Stonetalon Mountains. Their frantic digging has drawn the concern of Mor'rogal at Sun Rock Retreat.",
  ["1"] = {
    {file = "Audio/Transport/full_item_resonite-crystal-47bc0ed6ac91d71dd76c/1-0000.mp3", duration = 11.5461224, start = 0},
  },
}
P.transport["item:restabilization-cog"] = {
  hash = "66a179",
  fullHash = "66a179",
  text = "Restabilization Cog. Restabilization Cogs are precision mechanical components salvaged from the leper gnomes wandering outside the irradiated ruins of Gnomeregan. In Kharanos, gnomish tinkerers require these intact parts to construct the Recombobulator, an ambitious machine intended to reverse leper mutation. When radiation flooded Gnomeregan in a disastrous attempt to wipe out the invading troggs, countless gnomes were twisted into sick, hostile leper gnomes. Despite their madness, these afflicted exiles still carry intricate gnomish machinery and salvageable fittings. Tinkers Ozzie Togglevolt and Razzle Sprysprocket believe the horrific transformation can be systematically undone. To finish their prototype Recombobulation Device, they rely on adventurers to recover vital parts directly from the afflicted outside Gnomeregan's gates, including intact Restabilization Cogs to balance the machine's inner combustion systems.",
  ["1"] = {
    {file = "Audio/Transport/full_item_restabilization-cog-5f3b08f17b8cd711831c/1-0000.mp3", duration = 50.4163265, start = 0},
  },
}
P.transport["item:ring-of-zoram"] = {
  hash = "c999e7",
  fullHash = "c999e7",
  text = "Ring of Zoram. The Ring of Zoram is an ancient Kaldorei heirloom dating back to the glory days of the sunken city of Zoram before the Great Sundering. Once worn by the city's rulers and the key to the ancient lock of a sunken statuette, it recently fell into the hands of the encroaching coastal naga. Before the Well of Eternity collapsed and the oceans swallowed the western reaches of Kalimdor, Zoram was a coastal jewel of the night elven empire. The Ring of Zoram belonged to the rulers of the city, and a strange code is written upon its inner band in the language of the night elves. When the Great Sundering shattered the continent ten thousand years ago, the ring sank along with the city, lost beneath the crashing tides of what is now the Zoram Strand. For millennia, the ring remained buried beneath silt and ruins until the naga began scouring the coastline of Ashenvale. Ruuzel, a naga leader dwelling on an islet off the northern strand, uncovered the artifact among the sunken debris. Scholars like the night elf Talen seek the ring not merely for its antiquity, but because it functions as the only key capable of unlocking other relics salvaged from the depths, including sealed ancient statuettes recovered from the sea floor.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ring-of-zoram-4139ad5bcdadad7a4150/1-0000.mp3", duration = 67.7616327, start = 0},
  },
}
P.transport["item:robo-mechanical-guts"] = {
  hash = "ffc96f",
  fullHash = "ffc96f",
  text = "Robo-Mechanical Guts. Robo-Mechanical Guts are salvagable gearworks, conduits, and machine innards harvested from the malfunctioning constructs roaming the ruins of Gnomeregan. Gnomish engineers in Stormwind require these specific components to repair heavy tunneling vehicles meant to aid in the reclamation of Gnomeregan in Dun Morogh. When High Tinker Gelbin Mekkatorque and the surviving gnomes evacuated Gnomeregan, thousands of automated mechanisms, clockwork sentries, and industrial robots were abandoned inside. In the city's radioactive aftermath, these machines continue to roam the corridors autonomously. In Stormwind City, the tinker Shoni seeks to assemble a fleet of gyrodrillmatic excavationators to pierce the defenses of Gnomeregan and reclaim the lost city. Lacking fresh raw materials, she tasks bold adventurers with braving the contaminated halls of Gnomeregan to carve out functional robot viscera—springs, wires, and gyro-components—to refit the excavation machinery.",
  ["1"] = {
    {file = "Audio/Transport/full_item_robo-mechanical-guts-75e640fcc59f46c35499/1-0000.mp3", duration = 55.7714286, start = 0},
  },
}
P.transport["item:rocket-car-parts"] = {
  hash = "bf7c74",
  fullHash = "bf7c74",
  text = "Rocket Car Parts. Rocket Car Parts are the scattered, twisted metal remains of high-speed collisions across the Shimmering Flats in Thousand Needles. Constantly generated by reckless gnome and goblin racers pushing experimental speeders past their limits, these salvaged scraps are harvested by opportunists looking to turn racetrack accidents into quick coin. The Mirage Raceway in the Shimmering Flats is the staging ground for an unending, combustible rivalry between goblin and gnome engineering. In their pursuit of unmatched land speed, racers regularly suffer catastrophic breakdowns, explosive misfires, and high-velocity crashes that scatter metal across the salt flats. These discarded remnants—ranging from bent cylinders and burnt gears to crushed sheet metal—do not stay abandoned for long. Scavengers and merchants, most notably the opportunistic dwarf Kravel Koalbeard, hire passing adventurers to comb the blinding white expanse and collect the debris. Because both racing teams are perpetually desperate for spare machinery to patch together their next prototype, scavenged wreckage can easily be resold directly back to the very teams that wrecked it.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rocket-car-parts-71953aa69602e2dbabf0/1-0000.mp3", duration = 66.4032653, start = 0},
  },
}
P.transport["item:rod-of-channeling"] = {
  hash = "003880",
  fullHash = "003880",
  text = "Rod of Channeling. A Rod of Channeling is an arcane focus carried by spellcasters of the Dragonmaw clan in the Wetlands. Warlocks seeking to master the summoning of a felhunter must gather several of these rods for Strahad Farsan's acolytes to safely anchor the ritual circle in Ratchet. When a warlock seeks to bind a predator as volatile as a felhunter, raw willpower is rarely enough. Strahad Farsan requires three matched rods to allow his acolytes to channel their magic in concert, stabilizing the summoning circle while the practitioner undertakes the binding. The Dragonmaw clan's darkcasters, including the bonewarders and shadowwarders haunting the Angerfang Encampment and surrounding ruins in the Wetlands, carry these implements for their own fell workings. Though typically worn and nicked from combat, the rods remain potent focuses capable of directing chaotic nether energy.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rod-of-channeling-26f4223605c871e39f42/1-0000.mp3", duration = 49.5804082, start = 0},
  },
}
P.transport["item:rot-blossom"] = {
  hash = "c60364",
  fullHash = "c60364",
  text = "Rot Blossom. Rot Blossoms are foul, necrotic flora found growing among the desecrated graves of Duskwood. Fed by the blighted soil and undead remains, they are sought after for their potent, unwholesome alchemical properties. Duskwood's unnatural corruption breeds bizarre and disturbing plant life, none more unsettling than the Rot Blossom. Rooted in the defiled earth of graveyards such as the Tranquil Gardens Cemetery, these morbid blooms thrive in proximity to death. Local rumors claim they can even take root within the cracked skulls of the walking dead, particularly Skeletal Horrors and Skeletal Fiends that stalk the barrows. To the locals in Darkshire, harvesting them is both a grim chore and a dangerous necessity, as disturbing their soil means braving the unrested dead. Despite their repulsive nature, Rot Blossoms serve a specialized purpose in local concoctions. The blooms contain dark essences required to brew Zombie Juice, a foul draft tied to Duskwood's macabre survival efforts. Those dispatched to gather the blossoms often find themselves inadvertently aiding the Night Watch, culling the restless skeletons that wander the haunted gravesites in the process.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rot-blossom-8218408897d227d48f0f/1-0000.mp3", duration = 68.3885714, start = 0},
  },
}
P.transport["item:rot-hide-ichor"] = {
  hash = "1d63ed",
  fullHash = "1d63ed",
  text = "Rot Hide Ichor. Rot Hide Ichor is a foul bodily fluid harvested from the undead Rot Hide gnolls infesting Fenris Isle in Lordamere Lake. Apothecary Renferrel collects samples of the substance at the Sepulcher to uncover the origin of the gnolls' corruption and devise a strategy against them. The Rot Hide gnolls of Fenris Isle are not ordinary wild beasts; they are visibly decomposed and twisted by unnatural blight. Rather than normal blood, their veins pump a noxious ichor that sustains their animated flesh. The Royal Apothecary Society suspects that this fluid holds the secret to how the pack was corrupted and who commands them from within the ruined keep of Fenris Isle. Apothecary Renferrel gathers vials of this ichor to analyze its properties at the Sepulcher. By isolating the chemical and magical components fueling the gnolls, the Forsaken hope to pinpoint vulnerabilities before committing troops to a full-scale assault across Lordamere Lake.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rot-hide-ichor-106d325270cb2831c459/1-0000.mp3", duration = 53.1330612, start = 0},
  },
}
P.transport["item:rough-quartz"] = {
  hash = "f6eb7d",
  fullHash = "f6eb7d",
  text = "Rough Quartz. Rough Quartz is a humble elemental stone gifted to novice shaman by a Minor Manifestation of Earth. Though small and unrefined, it serves as the vital spiritual core needed to craft a shaman's first Earth Totem. To the untrained eye, rough quartz appears to be nothing more than an ordinary desert pebble. Yet to a shaman communing with the spirits in Durotar or Mulgore, it is an elemental gift offered directly by a Minor Manifestation of Earth. The stone represents endurance, patience, and unwavering strength. When presented to an elder such as Canaga Earthcaller in the Valley of Trials, the quartz is bound into the carved wood of an Earth Totem, acting as the spiritual focus that links the fledgling shaman directly to the living soil of Azeroth.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rough-quartz-213c01b44c970a15c4de/1-0000.mp3", duration = 41.6914286, start = 0},
  },
}
P.transport["item:rumbleshot-s-ammo"] = {
  hash = "4022b9",
  fullHash = "4022b9",
  text = "Rumbleshot's Ammo. Rumbleshot's Ammo is a mislaid crate of munitions bound for the gunsmith Hegnar Rumbleshot in Dun Morogh. Lost when a frightened courier fled from hungry wendigos, the heavy crate sits abandoned in the snow near the Grizzled Den. Hegnar Rumbleshot operates a roadside arms shop along the mountain path leading down from Coldridge Pass toward Anvilmar. With Ironforge riflemen, mountaineers, and dwarven mortar teams constantly drilling in the snowy heights, his supplies burn away almost as fast as powder catches flame. This particular shipment of shot was dispatched by Loslor from Kharanos, but never reached the shelves. The courier tasked with transporting it pitched camp too close to the predatory wendigos of the Grizzled Den, panicked when attacked, and fled for his life, leaving the heavy supply crate sitting deep within the beast's hunting grounds.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rumbleshot-s-ammo-d250d65ac6b76499a20f/1-0000.mp3", duration = 49.1102041, start = 0},
  },
}
P.transport["item:rune-inscribed-parchment"] = {
  hash = "a79091",
  fullHash = "a79091",
  text = "Rune-Inscribed Parchment. A written missive delivered to aspiring orc shamans in the Valley of Trials. Penned by the trainer Shikrik and handed out by Gornek, it calls initiates to embrace their role as spiritual leaders and conduits for the elemental spirits. Within the sun-baked canyon of the Valley of Trials, new orc shamans begin their training under the watchful gaze of veteran overseers. While performing initial trials for Gornek, an initiate is handed this rune-covered document. Sent directly by Shikrik, the local shamanic instructor, the parchment serves as a formal summons into the deeper mysteries of elemental communion. Orcish culture regards the shaman not merely as a battlefield spellcaster, but as an essential mediator between the living and the ancestors. This brief writ marks the transition from simple brute strength to the disciplined path of ancestral reverence.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rune-inscribed-parchment-270bd04df548337a76c5/1-0000.mp3", duration = 49.684898, start = 0},
  },
}
P.transport["item:rune-inscribed-pendant"] = {
  hash = "29446a",
  fullHash = "29446a",
  text = "Rune-Inscribed Pendant. The Rune-Inscribed Pendant is a magical trinket recovered from Dalaran supply shipments destined for Ambermill. Prized by the Kirin Tor, these pendants serve as conduits for channeling potent arcane energies. Discovered among crates of cartographic supplies bound for the Dalaran enclave at Ambermill, this pendant bears intricate arcane inscriptions. High-ranking wizards of the Kirin Tor frequently employ such artifacts to focus and amplify their spellcasting. The presence of numerous channeled pendants moving into the region immediately draws the suspicion of the Forsaken at the Sepulcher, signaling an impending project of immense magical power.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rune-inscribed-pendant-ecb724296b89bfb1c6cf/1-0000.mp3", duration = 37.3812245, start = 0},
  },
}
P.transport["item:rune-inscribed-tablet"] = {
  hash = "c5d1ab",
  fullHash = "c5d1ab",
  text = "Rune-Inscribed Tablet. A Rune-Inscribed Tablet is a stone message delivered to young Darkspear troll shamans in the Valley of Trials. Handed over by Gornek, it directs promising mystics to begin formal communion with the elements under the tutelage of the orc trainer Shikrik. Carved with elemental runes, this tablet serves as a formal invitation for burgeoning troll shamans taking their first steps in Durotar. When an initiate demonstrates their mettle in the Valley of Trials, the overseer Gornek presents the stone, sent by the troll shaman Ishi-yo to direct the initiate to the shaman trainer Shikrik. For the Darkspear trolls—who hold deep spiritual traditions of their own—the tablet marks the beginning of their shared path with the orcs, bridging ancient troll mysticism with the revitalized shamanic heritage championed by Warchief Thrall.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rune-inscribed-tablet-416833d8c2a895d2b14e/1-0000.mp3", duration = 47.4644898, start = 0},
  },
}
P.transport["item:rune-of-nesting"] = {
  hash = "580ce3",
  fullHash = "580ce3",
  text = "Rune of Nesting. The Rune of Nesting is one of the four sacred Relics of Wakening kept within the Ban'ethil Barrow Den on Teldrassil. It is an essential component in the delicate druidic ritual required to safely summon sleeping Druids of the Talon back from the Emerald Dream. Night elf druids undergo deep, cyclical hibernations within underground barrow dens to commune with nature through the Emerald Dream. Waking from this profound trance is not simply a matter of stirring; it requires a precise ritual guided by sacred instruments. The Rune of Nesting, kept safely within the Chest of Nesting deep in the winding chambers of the Ban'ethil Barrow Den, anchors this process. Alongside the Raven Claw Talisman, the Black Feather Quill, and the Sapphire of Sky, the rune serves as a conduit to call the Druids of the Talon back to the waking world. When corrupted Gnarlpine furbolgs overran the Ban'ethil Barrow Den, the barrow's slumbering defenders were placed in immediate peril. Without access to their relics, the druids risked being trapped within the Emerald Dream indefinitely while invaders desecrated their sanctuary. Recovering the Rune of Nesting and its companion artifacts allows Athridas Bearmantle in Dolanaar to prepare the ritual necessary to safely awaken the endangered druids.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rune-of-nesting-fcce36e754cc4a28ab5a/1-0000.mp3", duration = 73.9004082, start = 0},
  },
}
P.transport["item:runes-of-summoning"] = {
  hash = "b74133",
  fullHash = "b74133",
  text = "Runes of Summoning. The Runes of Summoning are a ritual item provided by the warlock trainer Carendin Halgar in the Magic Quarter of the Undercity. They are used to call forth an unbound voidwalker into a summoning circle so that an aspiring warlock may bend it to their will. Within the dark recesses of the Undercity's Magic Quarter, Forsaken practitioners of the dark arts study the manipulation of the Nether. Carendin Halgar entrusts the Runes of Summoning only to warlocks who have prepared themselves to take command of a voidwalker. By casting the runes within the active summoning circle below Halgar's station, the practitioner tears through the fabric of the Void, drawing forth a creature that must be overpowered and bound into servitude.",
  ["1"] = {
    {file = "Audio/Transport/full_item_runes-of-summoning-d8b84f93f5a822b1588d/1-0000.mp3", duration = 40.0195918, start = 0},
  },
}
P.transport["item:sack-of-murloc-heads"] = {
  hash = "91b691",
  fullHash = "91b691",
  text = "Sack of Murloc Heads. The Sack of Murloc Heads is a gruesome bundle collected along the beaches of the Hillsbrad Foothills. Assembled as proof of military action against local shore pests, it is pawned off by Lieutenant Farren Orinelle onto passing adventurers for delivery to Marshal Redpath in Southshore. Southshore stands under constant siege from Syndicate outlaws, Forsaken skirmishers, and wild murlocs crowding the coast. To secure funding and favor from town leadership, local officers must demonstrate that coastal threats are actively being culled. Lieutenant Farren Orinelle gathers proof in the form of severed heads, but the distasteful nature of the cargo—and his own squeamishness—prompts him to hand the dripping sack off to travelers rather than deliver the grisly evidence to Marshal Redpath himself.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sack-of-murloc-heads-09f38df5d5c19593614e/1-0000.mp3", duration = 43.7028571, start = 0},
  },
}
P.transport["item:sack-of-supplies"] = {
  hash = "c4eb8b",
  fullHash = "c4eb8b",
  text = "Sack of Supplies. These supply sacks belong to a caravan shipment intended for the goblin engineer Rezlak outside Orgrimmar. Transported across Durotar, the goods were intercepted by the Dustwind harpies roosting in the crags of Razorwind Canyon. Rezlak, an engineer contracted out of Ratchet by Gazlowe, relies on regular caravans through Durotar to supply his construction efforts for the Horde. Durotar's wilderness, however, is far from tame. When a promised shipment passed near the canyon road south of Orgrimmar, it was ambushed and pillaged by the local Dustwind harpies. The vicious creatures hauled the cargo deep into their roosts within Razorwind Canyon, scattering the sacks among the dirt and scree alongside harpy nesting sites.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sack-of-supplies-1ef1d5747fa62febaef3/1-0000.mp3", duration = 41.9265306, start = 0},
  },
}
P.transport["item:salty-scorpid-venom"] = {
  hash = "63b9a2",
  fullHash = "63b9a2",
  text = "Salty Scorpid Venom. Salty Scorpid Venom is a caustic fluid harvested from the scorpids stalking the Shimmering Flats in Thousand Needles. Packed with natural salts from the desert floor, it is prized by gnomish rocket racers attempting to engineer volatile, ultra-hot fuel. The scorpids crawling the arid expanse of the Shimmering Flats have adapted to an intensely mineral-rich environment. Over generations, the venom of beasts like the Scorpid Reavers and Scorpid Terrors has absorbed enormous quantities of local salt. Rather than brewing antidotes or standard poisons, gnomish tinkers like Fizzle Brassbolts prize this caustic compound as a prospective additive for high-combustion engine fuel. Out at the Mirage Raceway, the engineering competition between gnomes and goblins drives inventors to test increasingly dangerous materials in their rocket cars. Fizzle Brassbolts believes boiling down the salted venom, treating it with specialized catalysts, and mixing it into propellant tanks will deliver the blazing heat necessary to outrun goblin racers on the salt pans.",
  ["1"] = {
    {file = "Audio/Transport/full_item_salty-scorpid-venom-30e485f7958289ec3eb9/1-0000.mp3", duration = 59.115102, start = 0},
  },
}
P.transport["item:samophlange-item"] = {
  hash = "45f3f3",
  fullHash = "45f3f3",
  text = "Samophlange (item). The samophlange is an enigmatic mechanical component recovered from the deep interior of an automated control console in the Barrens. Despite its complex appearance, its precise function remains an engineering mystery even to the goblin mechanics who sought it. Tucked away behind a labyrinth of superfluous wiring and hollow tubing within a Barrens control console lies the samophlange. It takes some rooting through deliberately confounding machinery just to unseat it from its housing. To the untrained eye, it appears to be an essential nexus of clockwork and steam-driven technology. To goblin tinkerers, it is an irresistible mechanical puzzle intended for shipment to the Tinkers' Union in Undermine—though its fragile build means it rarely survives casual handling long enough to be understood.",
  ["1"] = {
    {file = "Audio/Transport/full_item_samophlange-item-c499a45ac5f0e0b8bcf4/1-0000.mp3", duration = 43.284898, start = 0},
  },
}
P.transport["item:samophlange-manual"] = {
  hash = "82a86d",
  fullHash = "82a86d",
  text = "Samophlange Manual. The Samophlange Manual is a technical operating guide detailing the inner workings of the elusive samophlange. Kept under tight lock and key by the Venture Company, its scattered pages hold the instructions needed by goblin engineers to repair and operate the bizarre contraption. Engineering schematics and operating handbooks are guarded like gold among goblin enterprises, and the Samophlange Manual is no exception. While working within the Venture Company, an ambitious overseer named Boss Copperplug jealously hoarded knowledge regarding the device, distributing only scattered pages to his most loyal subordinates to retain control over the machinery. When the device fell out of Venture Company clutches, repairing it proved impossible without assembling the torn, distributed documentation from the overseer and his crew at the Boulder Lode Mine. After breaking ties with the Venture Company, the goblin engineer Rilli Greasygob took up residence in Orgrimmar with hopes of mastering the samophlange's construction. Lacking Copperplug's favor during his former employment, Rilli relies on enterprising travelers to retrieve the handbook's cover and loose leaves. Reconstructing the handbook offers goblin tinkerers working alongside the Horde a rare window into proprietary Venture Company engineering.",
  ["1"] = {
    {file = "Audio/Transport/full_item_samophlange-manual-54180a264755c7d3ce38/1-0000.mp3", duration = 71.68, start = 0},
  },
}
P.transport["item:sample-ichor"] = {
  hash = "57bce5",
  fullHash = "57bce5",
  text = "Sample Ichor. This vial contains a refined extract of the foul fluid that sustains the rot hide gnolls of Silverpine Forest. Distilled down to its base components by Apothecary Renferrel, the substance carries lingering traces of both necromancy and warlock sorcery. The Rot Hide gnolls that prowl Silverpine Forest are no ordinary beasts. After recovering samples from the creatures and their lingering remnants, Apothecary Renferrel of the Royal Apothecary Society reduced the vile liquid into its constituent elements. His chemical breakdown revealed that the ichor was artificially manufactured through a convergence of dark schools: necromantic rites woven together with warlock magics. Because the craft behind it borders on arcane disciplines outside simple alchemy, Renferrel packaged this sample and dispatched it to the Undercity for Bethor Iceshard to examine with divination.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sample-ichor-907bef982e83036abbe3/1-0000.mp3", duration = 50.8865306, start = 0},
  },
}
P.transport["item:sample-of-zanzil-s-altered-mixture"] = {
  hash = "faf854",
  fullHash = "faf854",
  text = "Sample of Zanzil's Altered Mixture. This vial contains a potent specimen of a concoction brewed by the witch doctor Zanzil, recovered during a covert infiltration in the Barrens. Carried by an operative suffering from its debilitating effects, the sample is sent across the sea to Tarren Mill in hopes of unlocking both an antidote and the lethal secrets of poisoncraft. After infiltrating the Venture Company's tower near the Sludge Fen and looting the cache of Zanzil's mixture from Gallywix's lockbox, an operative ends up afflicted by Zanzil's foul touch. Shenthul orders the stricken agent across the Great Sea with a sample of the brew in hand. Finding a cure means locating Serge Hinott, an apothecary stationed at Tarren Mill in Hillsbrad Foothills, who possesses the rare expertise required to isolate the toxin and decipher its components.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sample-of-zanzil-s-altered-mixture-25ae1e049dfc53d35bdd/1-0000.mp3", duration = 47.9346939, start = 0},
  },
}
P.transport["item:sample-snapjaw-shell"] = {
  hash = "a8648a",
  fullHash = "a8648a",
  text = "Sample Snapjaw Shell. A Sample Snapjaw Shell is a durable tortoise carapace harvested from the freshwater oases of the Barrens. Remarkable for its lingering vitality, it is sent across the Great Sea to aid druidic research into rejuvenating the blighted woodlands of Silverpine Forest. The snapping turtles that dwell in the lush, anomaly-tinged oases of the Barrens possess shells of surprising vigor. Unlike common shell matter, a fresh Sample Snapjaw Shell retains a faint inner radiance and an energetic pulse long after being separated from the creature. To the tauren druids observing the land's rapid ecological shifts, these carapaces embody the resilient, adaptive spark of Kalimdor's wilderness, suggesting that nature can flourish even amidst harsh arid surroundings. Recognizing the latent vitality within the shell, tauren naturalists dispatch couriers across the sea to deliver specimens to Mura Runetotem at the Sepulcher. Stationed within the blighted expanses of Silverpine Forest, Mura seeks to aid the Forsaken by finding ways to heal the afflicted northlands. By examining the enduring life-force preserved inside the snapjaw's armor, she hopes to isolate secrets that can revitalize an ailing forest and encourage new growth in dying soil.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sample-snapjaw-shell-8e8d1f4ad4ee33f9a167/1-0000.mp3", duration = 76.1469388, start = 0},
  },
}
P.transport["item:samuel-s-remains"] = {
  hash = "50d48b",
  fullHash = "50d48b",
  text = "Samuel's Remains. Samuel's Remains are the recovered earthly remnants of Samuel Fipps, a former resident of Tirisfal Glades who fell to the Scourge. Gathered by adventurers near Deathknell, they are laid to rest beside his wife Marla to fulfill her dying wish. Before the plague of undeath swept across Lordaeron, Samuel Fipps lived peacefully with his wife, Marla. When the contagion struck, Samuel succumbed and was bound into mindless service to the Scourge. Marla escaped undeath only to be struck down by the very husband she loved. Despite this brutal end, her final wish was not vengeance, but eternity together: she pleaded to be interred beside Samuel once his cursed form was put to rest. Novice Elreth in Deathknell enlists newly awoken Forsaken to track down Samuel's wandering form northeast of the settlement, recover his bones, and bury them in the front row of the local cemetery.",
  ["1"] = {
    {file = "Audio/Transport/full_item_samuel-s-remains-c6a7cafe077cb189e83a/1-0000.mp3", duration = 52.4016327, start = 0},
  },
}
P.transport["item:sapphire-of-aku-mai"] = {
  hash = "7cc9cc",
  fullHash = "7cc9cc",
  text = "Sapphire of Aku'Mai. Sapphires of Aku'Mai are glowing, water-infused mineral clusters growing along the subterranean tunnels of Blackfathom Deeps. The encroaching naga have begun harvesting these gems, prompting the Earthen Ring to seek them out before their potent arcane power can be exploited. Discovered within the watery cavern entrances of Blackfathom Deeps along Ashenvale's Zoram Strand, Sapphires of Aku'Mai are crystalline formations rich in elemental energy. The spirits of water cling tightly to them, making them exceptional catalysts for magical workings. When scouts reported that the subterranean naga had begun actively quarrying these clusters from the cavern walls, the Shaman Je'neu Sancrea sought adventuring assistance to confiscate them. Left in the serpent peoples' clutches, the stones could easily fuel devastating arcane rites.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sapphire-of-aku-mai-c96e0a0124057b24f633/1-0000.mp3", duration = 47.8563265, start = 0},
  },
}
P.transport["item:sapphire-of-sky"] = {
  hash = "46cc3f",
  fullHash = "46cc3f",
  text = "Sapphire of Sky. The Sapphire of Sky is one of four sacred Relics of Wakening kept by the night elves within Ban'ethil Barrow Den. It is an essential focus used to safely summon sleeping Druids of the Talon back from the Emerald Dream. Deep within the roots of Teldrassil, Druids of the Talon commune with the wilds while resting in hibernation within Ban'ethil Barrow Den. Awakening from such deep trance-states into the waking world is a fragile, perilous process. To safeguard the transition, the druids rely on four consecrated artifacts known as the Relics of Wakening: the Black Feather Quill, the Raven Claw Talisman, the Rune of Nesting, and the Sapphire of Sky. Without this resonant gem, the harmony required to call sleeping spirits back from the Emerald Dream remains incomplete, leaving them vulnerable to eternal entrapment. When corrupted Gnarlpine furbolgs overran the barrow den, the sacred artifacts were left behind in their ornate repositories. The Sapphire of Sky resides secured inside the Chest of the Sky amidst the winding subterranean corridors. With the druids still slumbering as the furbolgs rampage around them, retrieving this jewel alongside its companion relics is an urgent matter for Athridas Bearmantle in Dolanaar before the sleepers are permanently lost.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sapphire-of-sky-d3e1789e469376222400/1-0000.mp3", duration = 74.7885714, start = 0},
  },
}
P.transport["item:sara-balloo-s-plea"] = {
  hash = "14787d",
  fullHash = "14787d",
  text = "Sara Balloo's Plea. Sara Balloo's Plea is a handwritten missive penned by a grieving widow in Ironforge. Unable to face the monarch directly in her sorrow, she entrusts this letter to a trusted champion of the Alliance to carry before King Magni Bronzebeard. Written in the shadow of deep personal tragedy, Sara Balloo's Plea represents a humble appeal directly to Ironforge's throne. Rather than braving the High Seat herself in her grief-stricken condition, Sara seeks an adventurer who has demonstrated loyalty and valor to the Alliance to deliver her words. The message asks for the attention of King Magni Bronzebeard, drawing the sovereign's gaze toward the private mourning and sacrifices made by ordinary dwarven families serving the kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sara-balloo-s-plea-b4d4b56df174c7437868/1-0000.mp3", duration = 41.0644898, start = 0},
  },
}
P.transport["item:sarilus-foulborne-s-head"] = {
  hash = "805513",
  fullHash = "805513",
  text = "Sarilus Foulborne's Head. Sarilus Foulborne's Head is a gruesome trophy claimed from an undead sorcerer who defiled the waters of northern Kalimdor. Carried back across the border from the Barrens into Ashenvale, it serves as undeniable proof that the meddling mage has met his end at the hands of the Sentinels. Perched high atop Dreadmist Peak in the northern Barrens, the Forsaken spellcaster Sarilus Foulborne drew the wrath of the night elves by corrupting and binding swarms of water elementals. From her post at Silverwind Refuge, Sentinel Velene Starstrike recognized his foul handiwork and dispatched champions across the frontier into Horde territory to end his reckless experiments. Severing the mage's head was the only proof Starstrike would accept to verify that his mocking grin was wiped away forever, securing a measure of peace for the troubled waters of Ashenvale.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sarilus-foulborne-s-head-cd5bbf5327c753a12413/1-0000.mp3", duration = 48.0130612, start = 0},
  },
}
P.transport["item:sarkoth-s-mangled-claw"] = {
  hash = "2d727c",
  fullHash = "2d727c",
  text = "Sarkoth's Mangled Claw. Sarkoth's Mangled Claw is the severed pincer of Sarkoth, a monstrous scorpid stalking the southern bluffs of the Valley of Trials. Heavily scarred by the badly wounded troll Hana'zua, the trophy serves as both proof of the beast's death and a final consolation for a wounded hunter's pride. While hunting in the Valley of Trials, a young Darkspear troll named Hana'zua engaged a massive scorpid known as Sarkoth. Before Sarkoth's venomous stinger pierced his chest and left him bleeding under a nearby tree, Hana'zua landed a crushing blow against the creature's massive pincer. Severing this battered limb offers undeniable proof that the monstrous scorpid has been slain. For Hana'zua, holding the mangled claw confirms that his desperate strike left a lasting mark, providing a fleeting spark of warrior's honor as venom courses through his veins.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sarkoth-s-mangled-claw-31288a7594c6518e1a26/1-0000.mp3", duration = 49.4497959, start = 0},
  },
}
P.transport["item:sarltooth-s-talon"] = {
  hash = "ee2e5c",
  fullHash = "ee2e5c",
  text = "Sarltooth's Talon. Sarltooth's Talon is a severed claw taken from the alpha raptor lurking above Whelgar's Excavation Site in the Wetlands. It serves as tangible proof for the dwarf Ormer Ironbraid that the vicious beast responsible for overrunning the archaeological dig has been slain. When raptors overran Whelgar's Excavation Site and butchered the dwarven expedition, Ormer Ironbraid watched from the ridge above, unable to prevent the slaughter. He singled out one massive, menacing raptor—Sarltooth—as the likely pack leader behind the assault. Seeking retribution for his fallen kin, Ormer demanded the beast's death and requested one of its vicious talons as proof of the deed. Severing this claw marks the end of Sarltooth's reign of terror over the ancient dwarven ruins.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sarltooth-s-talon-0f039c2db787b21c0699/1-0000.mp3", duration = 43.284898, start = 0},
  },
}
P.transport["item:sathrah-s-sacrifice"] = {
  hash = "a34694",
  fullHash = "a34694",
  text = "Sathrah's Sacrifice. Sathrah's Sacrifice consists of the silvery spinnerets taken from Lady Sathrah, a mighty spider dwelling in Teldrassil. Entrusted to adventurers by Priestess A'moora, this offering is presented at the fountain of the Temple of the Moon to cleanse the creature's corruption and lay her spirit to rest. Lady Sathrah was once a venerable creature of Teldrassil who fell prey to the creeping madness and corruption afflicting the boughs of the great tree. Tasked by the Sisterhood of Elune, adventurers retrieve her silvery spinnerets not as mere trophies, but as a consecrated offering. By bathing these remains within the sacred fountain of the Temple of the Moon, the foul taint that poisoned Sathrah's mind is washed away. The rite frees her troubled soul, allowing her spirit to manifest peacefully within the sanctuary and granting her the promise of rebirth under Elune's grace.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sathrah-s-sacrifice-9e9476b948f34b912fae/1-0000.mp3", duration = 48.4832653, start = 0},
  },
}
P.transport["item:satyr-horns"] = {
  hash = "d41e79",
  fullHash = "d41e79",
  text = "Satyr Horns. Satyr Horns are grim trophies harvested from the corrupted satyrs that plague the ancient woods of Ashenvale. Coveted both by grieving forest dwellers seeking retribution and opportunistic merchants trading out of Ratchet, they serve as undeniable proof that another servant of the Burning Legion has fallen. The curled horns of Ashenvale's satyrs are stark symbols of demonic corruption taken root in the sacred forest. For the dryad Illiyana at the Shrine of Aessina, gathering these severed horns is a matter of grief and vengeance for her lost sister Anilia. To outside traders like the traveling goblin Pixel resting at Splintertree Post, however, the horns represent raw opportunity. Demand for satyr horns has surged in the neutral port of Ratchet, transforming these macabre remnants of slain demons into lucrative trade goods for anyone daring enough to hunt their bearers. Satyr Horns cannot be bought from ordinary suppliers; they must be cut directly from the beasts lurking in the dark corners of the woodland. The satyrs maintain strongholds across Ashenvale, most notoriously in the corrupted groves of Xavian, the shadowed hollows of Satyrnaar, and the ruins of Night Run. Clearing these enclaves rids the land of lingering demonic taint while keeping both grieving guardians and eager merchants supplied with proof of the cull.",
  ["1"] = {
    {file = "Audio/Transport/full_item_satyr-horns-7c78404ec912c15849a0/1-0000.mp3", duration = 76.9567347, start = 0},
  },
}
P.transport["item:savannah-lion-tusk"] = {
  hash = "9fc013",
  fullHash = "9fc013",
  text = "Savannah Lion Tusk. Savannah Lion Tusks are hefty fangs taken from the predatory big cats roaming the arid plains of the Barrens. While common hunting trophies for travelers, they serve an exotic purpose as a brewing ingredient for Chen Stormstout's legendary potent ale. The great cats of the Barrens—from prowlers and huntresses to majestic prides ruled by patriarchs and beasts like Humar the Pridelord—are armed with sharp, heavy tusks. While most who fell these predators take their teeth as simple proof of prowess, Brewmaster Drohn in Ratchet seeks them out for a far more spirited craft. Drohn uses the tusks alongside plainstrider kidneys and thunder lizard horns to recreate Chen Stormstout's famous namesake brew, imparting a legendary kick that few mortal gullets can easily withstand.",
  ["1"] = {
    {file = "Audio/Transport/full_item_savannah-lion-tusk-131bc4e51f9b8cd4a505/1-0000.mp3", duration = 44.2514286, start = 0},
  },
}
P.transport["item:scaber-stalk"] = {
  hash = "fb85af",
  fullHash = "fb85af",
  text = "Scaber Stalk. Scaber Stalks are rare mushrooms that flourish in the damp, secluded cavern hidden behind Cliffspring Falls in Darkshore. Prized by herbalists and alchemists for their unusual properties, they are sought by Barithras Moonshade for his concoctions. Scaber Stalks are obscure mushrooms found deep within the cavern nestled behind Cliffspring Falls, situated along the northeastern mountains of Darkshore. Unlike ordinary forest flora, these pale stalks thrive strictly in the secluded dampness of the subterranean cave network. Their remote and hazardous habitat makes gathering them exceedingly rare, leading alchemists like Barithras Moonshade in Auberdine to commission daring scouts willing to brave the dark.",
  ["1"] = {
    {file = "Audio/Transport/full_item_scaber-stalk-0d6414f902745eb38c67/1-0000.mp3", duration = 40.2546939, start = 0},
  },
}
P.transport["item:scale-of-old-murk-eye"] = {
  hash = "0c52d9",
  fullHash = "0c52d9",
  text = "Scale of Old Murk-Eye. The Scale of Old Murk-Eye is taken from the infamous murloc leader who terrorizes the coastline of Westfall. Severed from the beast's hide, it serves as undeniable proof of his demise for Captain Grayson, the ghost who haunts the Westfall Lighthouse. The coast of Westfall is perilous enough between hidden shoals and relentless storms, but the presence of Old Murk-Eye elevated the danger from navigational hazard to outright massacre. According to Captain Grayson, the ghost bound to the Westfall Lighthouse, this particular murloc possessed a cunning beyond his feral kin, rallying weaker-minded murlocs to raid the shore. Murk-Eye scared off the keeper's family, leaving the beacon dark the night Grayson's ship smashed against the rocks, and when the family returned to relight the flame he raided again and slaughtered them. Taking a scale from the creature is the only way to satisfy the vengeful spirit and prove that the shore has been cleansed of its fiercest predator.",
  ["1"] = {
    {file = "Audio/Transport/full_item_scale-of-old-murk-eye-60b78f7d132de524acae/1-0000.mp3", duration = 54.8832653, start = 0},
  },
}
P.transport["item:scarlet-armband"] = {
  hash = "83ccd6",
  fullHash = "83ccd6",
  text = "Scarlet Armband. Scarlet Armbands are insignia worn by members of the Scarlet Crusade, marking their fanatic allegiance to the eradication of all undead. In Deathknell, Executor Arren demands them as proof that fledgling Forsaken have struck back against the zealots encroaching on their territory. Worn on the sleeves of Scarlet Initiates and fresh converts alike, the Scarlet Armband is the unmistakable mark of the Scarlet Crusade. To the newly risen Forsaken emerging from Deathknell, these strips of red cloth represent a lethal threat right on their doorstep. The Crusade makes no distinction between the mindless minions of the Scourge and the free-willed subjects of the Dark Lady; in their eyes, any walking corpse must be put to the torch. Executor Arren uses the collection of these armbands as a grim rite of passage, confirming the deaths of enemy scouts southeast of the settlement and proving that new Forsaken can defend their fledgling nation.",
  ["1"] = {
    {file = "Audio/Transport/full_item_scarlet-armband-e726329dc12dfb306163/1-0000.mp3", duration = 52.8718367, start = 0},
  },
}
P.transport["item:scarlet-crusade-documents"] = {
  hash = "bf5231",
  fullHash = "bf5231",
  text = "Scarlet Crusade Documents. These intercepted papers were carried by a Scarlet Crusade messenger at the Crusade's camp near Deathknell. Containing orders for the Crusade's field commanders across Tirisfal Glades, they provide the Forsaken with the exact military intelligence needed to target the Crusade's regional leadership. The courier Meven Korgal carried these documents at the Crusade's encampment southeast of Deathknell. Issued by order of the Highlord, the directives are addressed to the captains of the Crusade's Tirisfal Regional Command: Captain Perrine is to further fortify the southwest tower and gather information on the undead in Brill, Captain Vachon to crush undead movement near the northern tower, and Captain Melrose to watch the borders of the Plaguelands. The documents reveal the names, posts, and orders of Scarlet field officers stationed across Tirisfal Glades, turning an otherwise routine courier run into a catastrophic intelligence breach for the zealots. Executor Arren swiftly recognized that local forces in Deathknell could not exploit the full breadth of the intelligence. Instead, the captured dossier serves as a newly awakened Forsaken's passport out of Deathknell. Carried northeast past Cold Hearth Manor into Brill, the documents are handed directly to Executor Zygand outside the Brill Town Hall. With these orders in hand, the Forsaken military leadership plans swift decapitation strikes against Scarlet commanders entrenched across the Glades.",
  ["1"] = {
    {file = "Audio/Transport/full_item_scarlet-crusade-documents-c80f933599dc160f3187/1-0000.mp3", duration = 81.5020408, start = 0},
  },
}
P.transport["item:scarlet-insignia-ring"] = {
  hash = "59c524",
  fullHash = "59c524",
  text = "Scarlet Insignia Ring. A Scarlet Insignia Ring is a signet band worn by members of the Scarlet Crusade garrisoned throughout Tirisfal Glades. For the Forsaken defenders of Brill, these rings serve as gruesome proof that another zealot has been eliminated from Lordaeron's soil. Every fighting member of the Scarlet Crusade in Tirisfal Glades—from fresh neophytes and zealous friars to seasoned captains like Melrache and Perrine—carries an insignia ring. Marked with the Crusade's fiery sigil, the rings identify brother and sister within an organization consumed by paranoia. To outsiders and enemies, however, these trinkets serve entirely different purposes: they are unmistakable identifiers of Lordaeron's most fanatical human remnant. Under the direct mandate of Varimathras, Lady Sylvanas's dreadlord lieutenant, Deathguard Burgess in Brill actively collects these rings. The Forsaken consider the Scarlet Crusade an intolerable pestilence crawling across their newly claimed homeland. For Forsaken recruits, bringing stacks of these rings back to Brill is treated as undeniable proof of demise and a direct affirmation of loyalty to the throne of the Undercity.",
  ["1"] = {
    {file = "Audio/Transport/full_item_scarlet-insignia-ring-b07688c1420586b9d541/1-0000.mp3", duration = 67.3436735, start = 0},
  },
}
P.transport["item:scavenged-goods"] = {
  hash = "2c50f6",
  fullHash = "2c50f6",
  text = "Scavenged Goods. Scavenged Goods are miscellaneous pieces of discarded gear and supplies packed into equipment boxes around Deathknell. Newly risen Forsaken recover them to ensure the endless stream of fresh recruits can be armed and clothed. When new Forsaken pull themselves out of the earth in Deathknell's graveyard, they awaken with little more than rotting burial shrouds. Surrounding settlements and kingdoms offer no aid to the undead, leaving them entirely dependent on what they can salvage. Deathguard Saltain coordinates the collection of discarded weapons, tools, and garments cached in supply crates across the village, distributing them directly to the next batch of risen recruits.",
  ["1"] = {
    {file = "Audio/Transport/full_item_scavenged-goods-4288b0e6b630bde5ba43/1-0000.mp3", duration = 38.0081633, start = 0},
  },
}
P.transport["item:scavenger-paw"] = {
  hash = "196d78",
  fullHash = "196d78",
  text = "Scavenger Paw. Scavenger Paws are severed limbs gathered from the young and ragged wolves roaming the hills of Deathknell. Newly awakened Forsaken collect them for local caretakers to stitch together into crude, protective gear. Resources are scarce for the newly returned in Deathknell. With the Scourge and the Scarlet Crusade pressing against Tirisfal, every scrap of hide and bone is put to practical use. Novice Elreth, assistant to Shadow Priest Sarvis, collects paws from the local scavenger wolves alongside bat wings to fashion serviceable garments and armor for disoriented Forsaken stepping fresh from their graves.",
  ["1"] = {
    {file = "Audio/Transport/full_item_scavenger-paw-d55efd82f10f156734df/1-0000.mp3", duration = 35.2130612, start = 0},
  },
}
P.transport["item:scorched-spider-fang"] = {
  hash = "252d46",
  fullHash = "252d46",
  text = "Scorched Spider Fang. Scorched Spider Fangs are specialized crafting materials harvested from predatory arachnids lurking in the sodden caverns of the Wetlands. The dwarven armorer Furen Longbeard requires a substantial bulk of these heat-tempered fangs to forge resilient fire-hardened mail for seasoned warriors. Forging armor capable of turning blades and resisting violent trauma requires more than standard iron. In Stormwind's busy district, the skilled blacksmith Furen Longbeard uses obscure metallurgical techniques that blend beast parts with rare reagents. Furen demands fifty scorched fangs from the giant arachnids of the marshlands, utilizing their dense, venomous, and naturally toughened composition to reinforce mail links during the tempering process. These fangs are harvested directly from the lethal arachnids inhabiting the sunken valleys and burrows of the Wetlands, notably Cave Stalkers and Leech Stalkers. Despite the damp, rotting environment of the marsh, these predators possess peculiarly hardened, scorched mandibles. Gathering them in the quantities Furen demands requires venturing into deep hollows and clearing out entire swarms of monstrous vermin.",
  ["1"] = {
    {file = "Audio/Transport/full_item_scorched-spider-fang-b74a9e9bcc27d1721873/1-0000.mp3", duration = 65.5673469, start = 0},
  },
}
P.transport["item:scroll-of-messaging"] = {
  hash = "66fb43",
  fullHash = "66fb43",
  text = "Scroll of Messaging. The Scroll of Messaging is an enchanted parchment carrying a specific magical sending spell. Acquired for the gnome engineer Gaxim Rustfizzle in the Stonetalon Mountains, it serves an unusual purpose: providing the magical trigger needed to detonate remote explosives. While ostensibly an arcane script meant for long-distance communication, Gaxim Rustfizzle has a far more disruptive application in mind for the Scroll of Messaging. By combining its transmission incantation with volatile NG-5 charges, the gnome plans to create a remotely detonated explosive. The resulting blast is intended to trigger a massive distraction at the Venture Company's logging operation in Stonetalon, granting operatives a window to slip past guards and pilfer proprietary engineering schematics and confidential correspondence.",
  ["1"] = {
    {file = "Audio/Transport/full_item_scroll-of-messaging-988d5ec9f5512968723a/1-0000.mp3", duration = 47.124898, start = 0},
  },
}
P.transport["item:sea-creature-bones"] = {
  hash = "dc3fcb",
  fullHash = "dc3fcb",
  text = "Sea Creature Bones. Sea Creature Bones are skeletal samples gathered from the massive marine carcasses washing ashore along the mist-shrouded coast of Darkshore. Sent directly to the Temple of the Moon in Darnassus, these remains are central to an ongoing investigation into what is driving these great beasts to strand themselves upon the beaches. The fog-blanketed beaches of Darkshore have recently witnessed an alarming surge of massive sea creatures—including giant threshers far larger than those native to the local shallows—flinging themselves onto the shallows until they perish. The sight is viewed as an ominous portent by the night elves. Gwennyth Bly'Leggonde, an investigator dispatched by the Temple of the Moon to Auberdine, collects bone specimens from these beached leviathans to ship by hippogryph to Darnassus for close examination. Recovering these bones is fraught with danger, as the immense carcasses inevitably attract local scavengers. The coastal Greymist murlocs frequently swarm the dead and dying leviathans, feeding on the remains and defending the feeding grounds aggressively. Although the murlocs are far too weak to hunt such colossal creatures on their own, their opportunistic presence along Mist's Edge forces investigators and adventurers to fight through the scavenging packs to secure viable bone fragments for study.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sea-creature-bones-94af468023ab6e3c6e03/1-0000.mp3", duration = 74.6318367, start = 0},
  },
}
P.transport["item:sea-turtle-remains"] = {
  hash = "408710",
  fullHash = "408710",
  text = "Sea Turtle Remains. Sea Turtle Remains are skeletal samples salvaged from the carcasses of giant sea turtles along the coast of Darkshore. They serve as vital specimens for night elf researchers in Auberdine investigating an alarming surge of marine strandings. Giant sea creatures have begun beaching themselves all along Darkshore's mist-shrouded shores, while others lie submerged just off the coast near sunken wrecks. Gwennyth Bly'Leggonde, stationed in Auberdine, oversees the collection of skeletal fragments and tissue from these corpses. The Temple of the Moon in Darnassus urgently requests these samples, concerned by theories that the beasts may be fleeing an unnatural disturbance in the waters surrounding the newly grown world tree, Teldrassil. Recovering these remains is perilous work. Coastal tribes of murlocs routinely congregate around the massive carcasses, picking the bones clean and nesting beside them. Scholars require fresh bone fragments and tissue before the scavengers destroy any surviving evidence that might explain the creatures' fatal migration.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sea-turtle-remains-63ee3b282ae90fed8b9d/1-0000.mp3", duration = 59.1934694, start = 0},
  },
}
P.transport["item:sealed-description-of-thredd-s-visitor"] = {
  hash = "38aa21",
  fullHash = "38aa21",
  text = "Sealed Description of Thredd's Visitor. The Sealed Description of Thredd's Visitor is a confidential report penned by Warden Thelwater regarding an enigmatic man who visited the imprisoned Defias leader, Bazil Thredd, inside the Stormwind Stockade. Its contents help track down a covert operative moving unseen through Stormwind's political and criminal spheres. For years inside the Stockade, prisoner Bazil Thredd sat in his cell with no visitors. That routine shifted when an uncommunicative man began stopping by once or twice a week with completely valid identification papers. Taking note of these unusual arrivals, Warden Thelwater composed a physical account of the man, who carried identification marking him as 'Maelik'. The warden sealed the profile to prevent any meddling eyes from reading it before proper investigators could act.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sealed-description-of-thredd-s-visitor-2538917a802a2715436e/1-0000.mp3", duration = 45.2963265, start = 0},
  },
}
P.transport["item:sealed-envelope"] = {
  hash = "d849d1",
  fullHash = "d849d1",
  text = "Sealed Envelope. This tightly sealed packet contains confidential Venture Company technical documents and stolen schematics. Assembled by the exiled goblin engineer Fizziks, it holds proprietary designs meant for delivery to Sputtervalve in Ratchet. When the goblin engineer Fizziks was abruptly ejected from the Venture Company's logging operations in the Stonetalon Mountains, he did not leave empty-handed. Stuffing internal manuals, operating procedures, and technical specifications into this envelope, he managed to smuggle out company secrets under the noses of his former overseers. Most prized among these stolen records are the technical schematics for the Super Reaper 6000, a devastating piece of industrial clear-cutting machinery. Rather than keeping the dangerous trade secrets buried, Fizziks sends the packet south to Sputtervalve, an engineer residing in the neutral goblin port of Ratchet. While business rivals in the Steamwheedle Cartel have little personal love or trust for Fizziks, the engineering value of the designs inside the envelope is undeniable. The documents provide a clear window into Venture Company mechanical ingenuity and give independent engineers a chance to exploit the Venture Company's advanced logging technologies.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sealed-envelope-ae08b6a1a5ca4fd47251/1-0000.mp3", duration = 68.5453061, start = 0},
  },
}
P.transport["item:sealed-note-to-elling"] = {
  hash = "9935d2",
  fullHash = "9935d2",
  text = "Sealed Note to Elling. The Sealed Note to Elling is a confidential dispatch penned by the Stormwind fisherman Jorgen. Intended for Elling Trias, the proprietor of Trias' Cheese, it serves as an early link in the discreet investigation surrounding a vanished diplomat. Carrying a sealed note through the bustling avenues of Stormwind might seem mundane, but Jorgen's strict instructions make the stakes clear: deliver the parchment into Elling Trias's hands and keep silent. While Trias outwardly presents himself as a mild-mannered cheese merchant in the Trade District, this clandestine message directs the investigation of the missing diplomat straight to his counter, hinting at networks far deeper than dairy trade.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sealed-note-to-elling-02874a080d2389990f16/1-0000.mp3", duration = 38.7395918, start = 0},
  },
}
P.transport["item:sealed-note-to-watcher-backus"] = {
  hash = "9d1f01",
  fullHash = "9d1f01",
  text = "Sealed Note to Watcher Backus. The Sealed Note to Watcher Backus is a confidential dispatch written by master cheese merchant and informant Elling Trias. Addressed to a member of the Night Watch patrolling the road outside Darkshire, it calls in a personal favor to gather intelligence on Defias activity in Duskwood. When Jorgen's sealed note drags him into the hunt for the missing diplomat, cheese monger Elling Trias grudgingly agrees to put his own contacts to work. He pens this wax-sealed missive to Watcher Backus, a Night Watch guard stationed in Duskwood. Trias sends an adventurer south through the gloomy forest to deliver it by hand, using his longstanding rapport with Backus to secure any reports of Defias presence wandering near Darkshire.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sealed-note-to-watcher-backus-360bd3d71e5da00fdf8a/1-0000.mp3", duration = 43.1281633, start = 0},
  },
}
P.transport["item:searing-collar"] = {
  hash = "80ece1",
  fullHash = "80ece1",
  text = "Searing Collar. Searing Collars are ritual torcs worn by members of the Burning Blade cult hiding within Skull Rock in Durotar. Heated to burn the wearer's flesh, they are used by the cultists to attune themselves to demonic powers. Within the shadowy cavern of Skull Rock, just east of Orgrimmar, the Burning Blade gathers to perform dark rituals. Cultists, neophytes, and thugs of the cult don Searing Collars around their necks, willingly subjecting themselves to scorching heat that brands and sears their skin. The hermit Margoz studies these cruel devices, theorizing that the burning sensation and dark enchantments bound to the metal serve to attune the wearers directly to demonic energies. Investigating the collars reveals that they are a significant conduit of demonic corruption creeping into orc society right under the Horde's nose.",
  ["1"] = {
    {file = "Audio/Transport/full_item_searing-collar-6fb0be7e10b6b488da82/1-0000.mp3", duration = 48.1697959, start = 0},
  },
}
P.transport["item:searing-coral"] = {
  hash = "bec5c4",
  fullHash = "bec5c4",
  text = "Searing Coral. Searing Coral is a rare, resilient mineral substance harvested from living iron corals off the coast of the Wetlands. Prized by tinkerers and smiths, it possesses remarkable thermal properties that allow it to be smelted and forged into protective armor. Searing Coral grows exclusively in the chilly ocean waters along the coast south of Menethil Harbor in the Wetlands. Despite thriving in cold saltwater, this unique marine organism yields a mineral-rich material capable of enduring extreme heat. Harvesters brave the Wetlands' treacherous surf and coastal predators to pry the hardened formations loose. While traditionally outside standard dwarven metallurgy, Searing Coral caught the attention of inquisitive minds in Ironforge. Gnome craftsmen such as Klockmort Spannerspan adapt the techniques of veteran armorsmith Furen Longbeard, smelting and hammering the coral directly into metal alloys to produce lightweight, exceptionally durable armor for aspiring warriors.",
  ["1"] = {
    {file = "Audio/Transport/full_item_searing-coral-3ba55ffdee020e6ed01d/1-0000.mp3", duration = 56.7902041, start = 0},
  },
}
P.transport["item:secure-crate"] = {
  hash = "931d63",
  fullHash = "931d63",
  text = "Secure Crate. The Secure Crate is a tightly packed parcel filled with potions, alchemical reagents, and other miscellaneous goods destined for the Eastern Kingdoms. Entrusted to travelers in the Barrens, it must be carried to the bustling port of Ratchet to catch the outgoing tide. Trade routes between Kalimdor and the Eastern Kingdoms rely on a fragile chain of couriers, desert caravans, and goblin merchant vessels. When land caravans across the Barrens miss their scheduled departures, fragile shipments like this Secure Crate must be hauled by independent travelers down to the coast. Inside are alchemical goods, potions, and various reagents earmarked for associates across the Great Sea. Given the delicate and valuable nature of the contents, the crate is firmly sealed to ensure it survives both the arid trails of the Barrens and the salty spray of oceanic transit. The destination of the crate's land leg is the dock at Ratchet, overseen by Wharfmaster Dizzywig. Ratchet's harbor serves as the primary neutral funnel through which supplies cross the sea toward destinations like Blackwater Cove. Operating under the ledger of the Steamwheedle Cartel, Dizzywig ensures that small parcels and heavy freight alike are properly manifested and loaded aboard the next departing vessel, providing a vital commercial link between the Old World and the frontier.",
  ["1"] = {
    {file = "Audio/Transport/full_item_secure-crate-cb607f745dd6a29c495c/1-0000.mp3", duration = 76.1730612, start = 0},
  },
}
P.transport["item:senir-s-report"] = {
  hash = "bd256b",
  fullHash = "bd256b",
  text = "Senir's Report. Senir's Report is a dispatched document penned by Mountaineer Senir Whitebeard detailing the Frostmane troll threat in Dun Morogh. It carries findings commissioned under royal directive and is destined for Senator Barin Redstone in Ironforge. Drafted after scouting missions against the Frostmane trolls nestled in the crags of Dun Morogh, this field report contains mountaineer observations intended for the dwarf Senate. Senir Whitebeard, stationed out in the cold foothills, penned the document and enclosed his brother Grelin's report on Coldridge Valley, which states that Grelin acted under a sanction from King Magni Bronzebeard. Senir tasks adventurers with hauling the findings straight to Senator Barin Redstone in the High Seat of Ironforge—cautiously advising couriers to omit just how much outside help he required to compile it.",
  ["1"] = {
    {file = "Audio/Transport/full_item_senir-s-report-3735a094282ccd0bc25c/1-0000.mp3", duration = 46.4195918, start = 0},
  },
}
P.transport["item:serena-s-head"] = {
  hash = "dcbb56",
  fullHash = "dcbb56",
  text = "Serena's Head. Serena's Head is the grisly trophy taken from the matriarch of the Dry Hills harpies in the northern Barrens. Darsok Swiftdagger of the Crossroads demanded it as proof of her demise, intending to display it upon Horde supply wagons as a harsh deterrent against further aerial raids. The Witchwing harpies of the Dry Hills have long plagued trade moving through the northern Barrens, but under Serena Bloodfeather their assaults turned particularly vicious. Her raids against Horde supply lines were driven by personal vengeance for her sister, who fell to the beastmaster Rexxar. To permanently break the morale of the flock, the orc rogue Darsok Swiftdagger ordered Serena hunted down. Rather than letting her death go unnoticed, he sought her severed head so it could be mounted upon the next outbound caravan—serving as a stark, bloody warning to any harpy watching from the crags above.",
  ["1"] = {
    {file = "Audio/Transport/full_item_serena-s-head-fd1ffc29678e9e871da9/1-0000.mp3", duration = 50.0767347, start = 0},
  },
}
P.transport["item:serpentbloom"] = {
  hash = "5cd3d2",
  fullHash = "5cd3d2",
  text = "Serpentbloom. Serpentbloom is a rare, subterranean herb found growing only in the dark depths of the Wailing Caverns. Its potent natural properties have drawn the keen interest of the Forsaken's Royal Apothecary Society. Serpentbloom grows exclusively within the damp, shadowy tunnels of the Wailing Caverns beneath the Barrens. Rooted in an ecosystem warped by unrestrained Emerald Dream energies, the plant thrives far from sunlight and often harbors venomous serpents nesting among its stems. Because the cave system is overrun with hostile beasts and corrupted druids, few who venture inside ever return with viable specimens. Operating from the Pools of Vision beneath Thunder Bluff, Apothecary Zamah collects Serpentbloom on behalf of the Royal Apothecary Society of Undercity. The Forsaken continuously seek out virulent, strange, and chemically potent vegetation across Kalimdor to fuel their research for the Dark Lady. Zamah believes that harvesting Serpentbloom in significant quantities could yield valuable breakthroughs for Forsaken alchemy.",
  ["1"] = {
    {file = "Audio/Transport/full_item_serpentbloom-2f08018057f637e01ca4/1-0000.mp3", duration = 59.2718367, start = 0},
  },
}
P.transport["item:sethir-s-journal"] = {
  hash = "873920",
  fullHash = "873920",
  text = "Sethir's Journal. Sethir's Journal is a personal record carried by the elusive satyr Sethir the Ancient in Teldrassil. Recovered through stealth, its contents confirm the alarming spread of corruption from mainland Kalimdor onto the World Tree.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sethir-s-journal-56495a59f77541349b27/1-0000.mp3", duration = 12.5910204, start = 0},
  },
}
P.transport["item:sevren-s-orders"] = {
  hash = "0b2f3c",
  fullHash = "0b2f3c",
  text = "Sevren's Orders. Sevren's Orders are written dispatches penned by Magistrate Sevren of Brill. They direct a proven Forsaken agent to report to Bethor Iceshard, a formidable mage stationed in the Undercity's Magic Quarter. As the Forsaken solidify their grip on the ruins of Lordaeron, skilled agents who have proven their worth against the Scourge in Tirisfal Glades are summoned south to the capital. Issued by Magistrate Sevren, these written orders serve as official introduction and credentials to Bethor Iceshard, one of the Dark Lady's foremost practitioners of the arcane in the Magic Quarter. While Sevren knows little beyond the fact that the assignment involves reaching out to an errant lich, the summons carries the absolute authority of the Undercity's high mages.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sevren-s-orders-ae2aebb7b0c9127b83c8/1-0000.mp3", duration = 41.1428571, start = 0},
  },
}
P.transport["item:shadowhide-pendant"] = {
  hash = "ddd5c7",
  fullHash = "ddd5c7",
  text = "Shadowhide Pendant. Shadowhide Pendants are crude ornamental charms carried by the Shadowhide gnolls roaming the Redridge Mountains. Collected as legal proof of bounty enforcement, they signify that local defenders have enacted Lakeshire's law against gnolls collaborating with the rogue mage Morganth. Carried by warriors, brutes, and spellcasters of the Shadowhide clan, these pendants serve as crude personal totems or rank insignias. Deep in the hills of Redridge, the clan has rallied under Lieutenant Fangore and fallen under the sway of Morganth, a rogue wielder of the Arcane. To the townspeople of Lakeshire, these charms are not mere primitive jewelry; they are identifying marks of an organized menace harassing settlements across the region on behalf of an enemy of the Crown. Under the authority of Magistrate Solomon and the laws of Stormwind, actively aiding a known criminal of the realm carries a sentence of death. Lacking sufficient royal reinforcements, Bailiff Conacher in the Lakeshire Town Hall relies on independent adventurers to uphold the peace. Presenting ten Shadowhide Pendants provides tangible proof that gnolls obeying Morganth's orders have faced frontier justice.",
  ["1"] = {
    {file = "Audio/Transport/full_item_shadowhide-pendant-80ebd200a1e441114d68/1-0000.mp3", duration = 65.8285714, start = 0},
  },
}
P.transport["item:shaman-voodoo-charm"] = {
  hash = "62176d",
  fullHash = "62176d",
  text = "Shaman Voodoo Charm. The Shaman Voodoo Charm is a dark ritual trinket carried by Gnarlpine furbolg shamans deep within the Ban'ethil Barrow Den. Emanating a vile aura, this charm channels an unnatural magic capable of severing a slumbering druid's spirit from their physical flesh. The Gnarlpine tribe of Teldrassil has fallen into madness and corruption, but within the Ban'ethil Barrow Den, their shamans wield powers far beyond ordinary wilderness sorcery. Utilizing these strange voodoo charms, the shamans discovered a way to rip a sleeping druid's consciousness away from the mortal realm and trap it helplessly within the Emerald Dream. By severing the soul from the vessel, the furbolgs are able to animate the empty physical form, turning venerable night elf protectors into mindless guardians that slaughter anyone venturing into the barrows.",
  ["1"] = {
    {file = "Audio/Transport/full_item_shaman-voodoo-charm-adbbe46f1fdaa25d532a/1-0000.mp3", duration = 48.64, start = 0},
  },
}
P.transport["item:shard-of-water"] = {
  hash = "8c7fdb",
  fullHash = "8c7fdb",
  text = "Shard of Water. The Shard of Water is an elemental remnant gathered during a shaman's communion with the spirits of water. Delivered to Islen Waterseer along the Barrens coast, it serves as tangible proof that an initiate has understood water's life-giving nature and conquered its corruption. For shamans seeking mastery over the elements, communing with water demands a deep understanding of balance, life, and preservation. In the trials of the Call of Water, shamans are directed to confront corruption seeped into natural springs—even journeying across the sea to blighted lands like Silverpine Forest. The Shard of Water is granted upon purifying these corrupted waters. Returning this crystal token to Islen Waterseer on the rocky shores of the Barrens proves the initiate's worth, providing the final key needed to forge their Water Totem.",
  ["1"] = {
    {file = "Audio/Transport/full_item_shard-of-water-708d8895059981fe674d/1-0000.mp3", duration = 45.7665306, start = 0},
  },
}
P.transport["item:shaw-s-report"] = {
  hash = "791780",
  fullHash = "791780",
  text = "Shaw's Report. Shaw's Report is a confidential dispatch written by Master Mathias Shaw of SI:7 for Gryan Stoutmantle in Westfall. It outlines the intelligence agency's knowledge regarding the Stonemasons Guild, its leader Edwin VanCleef, and their grievance with the crown following the rebuilding of Stormwind.",
  ["1"] = {
    {file = "Audio/Transport/full_item_shaw-s-report-07dd0308b5f99d838a27/1-0000.mp3", duration = 16.6661224, start = 0},
  },
}
P.transport["item:shimmering-frond"] = {
  hash = "1adbd3",
  fullHash = "1adbd3",
  text = "Shimmering Frond. A Shimmering Frond is a specimen harvested from a strange, glowing plant growing within the Oracle Glade of Teldrassil. Its unusual luminescence and twisting aura reveal it to be an exotic species entirely alien to the boughs of the World Tree. While wandering the verdant canopies around the Oracle Glade, travelers may come across strange vegetation boasting a pulsing, radiant aura. The fronds plucked from this plant catch the filtered woodland light in unnatural ways, shimmering with vibrant vitality. Denalan, a botanist tending to his planters by Lake Al'Ameth, recognizes the foliage immediately as a species native to the distant Swamp of Sorrows in the Eastern Kingdoms. How seeds from a marsh so far across the Great Sea managed to take root and flourish upon the newly raised Teldrassil remains an intriguing mystery, prompting Denalan to sprout and study specimens in his own soil.",
  ["1"] = {
    {file = "Audio/Transport/full_item_shimmering-frond-896d2933841cde12b3c2/1-0000.mp3", duration = 52.1665306, start = 0},
  },
}
P.transport["item:shimmerweed"] = {
  hash = "f11bcf",
  fullHash = "f11bcf",
  text = "Shimmerweed. Shimmerweed is a distinct herb cultivated by the Frostmane trolls on Shimmer Ridge in the snowy heights of Dun Morogh. While the trolls harvest it for their own tribal rituals, local dwarven brewers covet its sharp, unique flavor for experimental ales. High above the lowlands of Dun Morogh, the Frostmane trolls tend patches of shimmerweed along the icy crags of Shimmer Ridge. The trolls harvest and store the plant in woven baskets scattered throughout their camps, relying on it to fuel their sacred and enigmatic rituals. Outside of troll society, few mountaineers pay the weed much mind, though its potent properties have drawn the gaze of inventive outsiders. In nearby Brewnall Village, brewmaster Rejold Barleybrew has taken a keen interest in the herb. Believing that brewing is in his blood, Rejold seeks to craft the ultimate dwarven stout and suspects that the pungent, unmistakable flavor of shimmerweed might be the missing piece. He frequently hires adventurous travelers to slip into the Frostmane encampments, dodge the hostile trolls, and haul back bushels to dump into his fermenting vats.",
  ["1"] = {
    {file = "Audio/Transport/full_item_shimmerweed-896faa88a2d408a04413/1-0000.mp3", duration = 65.9069388, start = 0},
  },
}
P.transport["item:shindrell-s-note"] = {
  hash = "0a8107",
  fullHash = "0a8107",
  text = "Shindrell's Note. Shindrell's Note is a written missive detailing recent observations of corruption around Astranaar and the Ashenvale coastline. Penned by the night elf Sentinel Shindrell Swiftfire, it serves as an intelligence report dispatched east across the forest to the druid Kayneth Stillwind. As unrest spreads throughout Ashenvale, night elf sentinels and druids coordinate to monitor the woodland's borders. Penned by Sentinel Shindrell Swiftfire in Astranaar, this report details troubling disturbances spotted along the western coast and through the central canopies. It is addressed to Kayneth Stillwind, a druid stationed at the shrine of Forest Song within the Nightsong Woods to the east. By dispatching couriers with her firsthand observations, Shindrell aids Kayneth's investigation into the subtle corruption creeping through the sacred groves.",
  ["1"] = {
    {file = "Audio/Transport/full_item_shindrell-s-note-fa056814a8ffd837a5db/1-0000.mp3", duration = 48.1697959, start = 0},
  },
}
P.transport["item:shipment-of-boots"] = {
  hash = "007c53",
  fullHash = "007c53",
  text = "Shipment of Boots. A crate of footwear dispatched from Booty Bay by the merchant Drizzlik, intended for Gazlowe's trade network in Ratchet. It was intercepted off the coast by Southsea Freebooters and stashed away in their encampment south of the port. Running a goblin trade port requires endless supplies, and Gazlowe arranged for a fresh delivery of boots from Drizzlik, a purveyor of apparel based out of Booty Bay. The consignment never reached Ratchet's docks. Southsea Freebooters prowling the Merchant Coast ambushed the transport vessel, carrying the crates off to their beach encampments south of the harbor. The pirates scattered the stolen freight throughout their tents and shanties, leaving Gazlowe without his expected wares until adventurous mercenaries could be hired to scour the shoreline.",
  ["1"] = {
    {file = "Audio/Transport/full_item_shipment-of-boots-1743fc3d97968072e4f4/1-0000.mp3", duration = 44.2514286, start = 0},
  },
}
P.transport["item:shipment-of-iron"] = {
  hash = "5c05bb",
  fullHash = "5c05bb",
  text = "Shipment of Iron. A crate of raw metal stored at the human smithy in Hillsbrad Fields. It serves as vital stock for local armament production, making it a priority target for Forsaken forces seeking to cut off the supply lines arming the Hillsbrad townsfolk. In the ongoing struggle across the Hillsbrad Foothills, the human peasantry has mounted surprisingly stiff resistance against Tarren Mill. Much of this fighting capability stems directly from the smithy at the southwestern edge of the Hillsbrad Fields, where Blacksmith Verringtan and his apprentices work round the clock churning out weapons and armor from heavy shipments of iron. To break the farmers' resolve, Forsaken commanders ordered the forge extinguished, its smiths eliminated, and its stockpiled metal seized for the Horde war effort.",
  ["1"] = {
    {file = "Audio/Transport/full_item_shipment-of-iron-7a6910b62edefd8970f4/1-0000.mp3", duration = 44.564898, start = 0},
  },
}
P.transport["item:shipping-schedule"] = {
  hash = "6e0ab3",
  fullHash = "6e0ab3",
  text = "Shipping Schedule. The Shipping Schedule is a logistical document held by the Defias Brotherhood's dockmaster at Jerod's Landing. It outlines illicit cargo shipments flowing through Elwynn Forest between Redridge and Westfall, drawing the close attention of Stormwind's intelligence agency. South of Goldshire on the Elwynn bank of the Nazferiti River, the Defias Brotherhood seized control of Jerod's Landing to serve as a hub for their river traffic. Through this covert dock, the Brotherhood moves large quantities of contraband between Redridge and Westfall, slipping through waterways right under the nose of the Stormwind Guard. The Shipping Schedule records these clandestine movements, kept under close guard on the dockmaster's person. Master Mathias Shaw, leader of SI:7, commissioned the theft of the schedule to map Defias supply chains and test fledgling operatives. Infiltrating the dock house and lifting the document from the dockmaster's pockets serves both as actionable intelligence for the crown and as an initiation trial. If the operative is caught, SI:7 disavows all connection, leaving no trail back to the barracks in Stormwind.",
  ["1"] = {
    {file = "Audio/Transport/full_item_shipping-schedule-37b27b43d748ad6936ca/1-0000.mp3", duration = 65.4367347, start = 0},
  },
}
P.transport["item:sida-s-bag"] = {
  hash = "1f5ecf",
  fullHash = "1f5ecf",
  text = "Sida's Bag. Sida's Bag is the personal satchel of Sida, a resident of Menethil Harbor. Swallowed whole by a creeping ooze during her excursion to Ironbeard's Tomb, the bag and its mysterious contents require a thorough hunt through the acidic slimes of the Wetlands to recover. While paying her regular weekly visit to Ironbeard's Tomb near Dun Modr, Sida found herself ambushed by the dreadful, dripping oozes that infest the area. Panicking in the face of the encroaching sludge, she flung her personal satchel directly at one of the creatures. Rather than driving the beast off, the ooze simply absorbed the bag into its gelatinous body. The distraction bought Sida enough precious moments to flee with her life back to the safety of Menethil Harbor, leaving her possessions trapped inside an unknown slime. Because the undulating oozes prowling Ironbeard's Tomb—ranging from crimson to monstrous varieties—look largely identical, finding the bag requires cutting down the marsh slimes until the swallowed satchel emerges intact. Despite soaking within acidic digestive muck, the durable sack preserves its contents. Once returned to Sida, she eagerly reclaims her belongings and discards the ruined, slime-coated exterior, offering the washed-out container to whoever braved the marsh on her behalf.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sida-s-bag-0a0240e862c64d4f7622/1-0000.mp3", duration = 73.195102, start = 0},
  },
}
P.transport["item:signed-recruitment-letter"] = {
  hash = "87c9c1",
  fullHash = "87c9c1",
  text = "Signed Recruitment Letter. The Signed Recruitment Letter is an official dispatch issued by Kargal Battlescar at the Far Watch Post. Bearing Kargal's mark, it transfers new recruits deeper into the arid interior of the Barrens to report for duty at the Crossroads. Standing as the eastern threshold of the Barrens, the Far Watch Post evaluates newcomers crossing over the Southfury River from Durotar. Once a conscript proves their readiness to Kargal Battlescar, he stamps and signs this letter of introduction. It serves as military orders directing recruits west down the road to the Crossroads, where Sergra Darkthorn coordinates logistical operations and territorial defense across the dry plains. While the letter is an official document of the Horde, Kargal does not hide his personal contempt for the officer awaiting the recruit. He views Sergra Darkthorn as an abrasive shaman who talks circles around soldiers, openly questioning Warchief Thrall's high opinion of her. Despite his misgivings, the dispatch must be delivered directly into Sergra's hands before any further assignments in the Crossroads are granted.",
  ["1"] = {
    {file = "Audio/Transport/full_item_signed-recruitment-letter-2ffa35324d3e41cdfb02/1-0000.mp3", duration = 58.4097959, start = 0},
  },
}
P.transport["item:silithid-egg-the-barrens"] = {
  hash = "77e8e4",
  fullHash = "77e8e4",
  text = "Silithid Egg (The Barrens). Silithid Eggs are the developing brood of the insectoid creatures nesting in the southern Barrens. Found buried within earth mounds around the Field of Giants, these clutches are gathered by Horde researchers seeking to uncover the origins and intelligence of the encroaching swarm. In the arid basin of the Field of Giants, bizarre insect-like beings have begun churning the earth into towering mounds. Deep within these nests lie their eggs, buried beneath hardened soil and watched over by territorial broods. The Horde knows remarkably little about the silithid, but scouts stationed at the Crossroads have noted signs of coordinated behavior and uncanny intellect far exceeding ordinary wild beasts. Gathering unhatched eggs offers scholars in Orgrimmar their best chance to study the lifecycle and nature of this emerging menace. Reaching the eggs requires prying into silithid mounds with specialized digging claws. Disturbing these clutches is perilous work; the silithid react fiercely to intrusions near their subterranean nurseries, swarming any who threaten their unhatched young. For researchers like the troll Korran, securing intact, unbroken specimens is critical for analysis before the swarm spreads further across Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_item_silithid-egg-the-barrens-e48e2eed5d6c079c6040/1-0000.mp3", duration = 69.5902041, start = 0},
  },
}
P.transport["item:silixiz-s-tower-key"] = {
  hash = "f85e4c",
  fullHash = "f85e4c",
  text = "Silixiz's Tower Key. Silixiz's Tower Key is a small key carried by Foreman Silixiz outside the Venture Company tower near the Sludge Fen. Horde operatives belonging to the Shattered Hand are tasked with lifting it directly from the foreman's pockets as part of an undercover sabotage assignment. The Venture Company operation north of the Sludge Fen runs under tight security, centered on an isolated lookout tower supervised by Grand Foreman Puzik Gallywix. Outside the compound patrolled by goblin mercenaries, Foreman Silixiz carries the tower key that the Shattered Hand operative is instructed to steal and keep. For the rogue network of the Shattered Hand operating out of Orgrimmar, obtaining this key is not a matter of blunt force; field operatives must slip into the compound undetected and pick the foreman's pockets cleanly, proving their mastery of stealth before climbing into the toxic upper levels.",
  ["1"] = {
    {file = "Audio/Transport/full_item_silixiz-s-tower-key-602a4b01516bebe46427/1-0000.mp3", duration = 48.7967347, start = 0},
  },
}
P.transport["item:silver-dawning-s-lockbox"] = {
  hash = "ac7f19",
  fullHash = "ac7f19",
  text = "Silver Dawning's Lockbox. The Silver Dawning's Lockbox is a sturdy chest resting within the sunken wreckage of the vessel Silver Dawning off the coast of Darkshore. It holds the personal effects and ship log of the vessel's fallen captain, lost during an ambush by coastal murlocs. The ship Silver Dawning was en route across the sea toward the port of Auberdine when disaster struck. Coastal murlocs swarmed the vessel, driving it down into the dark surf north of the harbor. The captain perished in the assault, leaving the wreckage submerged beneath the waves as a grim monument claimed by the creatures. Inside the flooded hull remains the captain's personal lockbox, holding the ship's log and private belongings. Recovering these effects offers a final measure of peace to the surviving crew members ashore.",
  ["1"] = {
    {file = "Audio/Transport/full_item_silver-dawning-s-lockbox-e58229bd2757bd33612c/1-0000.mp3", duration = 43.8595918, start = 0},
  },
}
P.transport["item:silvery-spinnerets"] = {
  hash = "1a9155",
  fullHash = "1a9155",
  text = "Silvery Spinnerets. Silvery Spinnerets are harvested from the great spider Lady Sathrah in northern Teldrassil. Once used to weave webs that captured healing evening dew for the Temple of the Moon, they are sought by the Priestesses of Elune to honor the fallen creature's soul through a sacred ritual of rebirth. Lady Sathrah was once counted among the favored creatures of Elune, renowned for spinning shimmering webs through the moonlight near Wellspring Lake. Her silver silk gathered the evening mist, forming healing dews prized by the Sisterhood of Elune in Darnassus. Unfortunately, the corruption creeping through the boughs of Teldrassil did not spare her. Falling into violent madness, Sathrah became a danger to her own brood and the surrounding forest. Priestess A'moora asks travelers to end the spider's suffering and recover her spinnerets as an act of mercy, bringing closure to a revered resident of the great boughs.",
  ["1"] = {
    {file = "Audio/Transport/full_item_silvery-spinnerets-aca75cd53ae79b7684ef/1-0000.mp3", duration = 51.3044898, start = 0},
  },
}
P.transport["item:simple-memorandum"] = {
  hash = "d62a32",
  fullHash = "d62a32",
  text = "Simple Memorandum. The Simple Memorandum is an official notice delivered to novice gnome warriors training in Coldridge Valley. A terse gnomish directive, it instructs fledglings to report to the warrior trainer Thran Khorman in Anvilmar to prepare for the war to take back Gnomeregan. Novice adventurers in Coldridge Valley frequently find themselves entrusted with letters of introduction as they demonstrate their mettle against the local wildlife and trogg threats. For young gnome fighters, this memorandum serves as a formal order to report to Thran Khorman, the resident warrior trainer within Anvilmar. Dwarven veterans recognize that while gnomes may rely on intellect and contraptions, retaking Gnomeregan will demand pure physical resolve and martial discipline. The memorandum directs the bearer to put aside preliminary tasks and seek personalized instruction in the art of war.",
  ["1"] = {
    {file = "Audio/Transport/full_item_simple-memorandum-2651c10f4a6ef6626985/1-0000.mp3", duration = 49.2146939, start = 0},
  },
}
P.transport["item:simple-rune"] = {
  hash = "aa5b15",
  fullHash = "aa5b15",
  text = "Simple Rune. A Simple Rune is an inscribed stone token passed to fledgling dwarven warriors training in Coldridge Valley. It serves as a summons from the warrior trainer Thran Khorman, directing recruits to seek instruction inside Anvilmar. Carved with basic martial marks, the Simple Rune is handed to promising recruits who have begun clearing out the threats around Coldridge Valley. Rather than a magical charm, it acts as a formal calling stone from Thran Khorman, the resident warrior trainer at Anvilmar. Upon reading its inscribed guidance, a young fighter is expected to report directly to Thran to learn basic combat techniques and hear practical advice on surviving Dun Morogh's hostile wilds.",
  ["1"] = {
    {file = "Audio/Transport/full_item_simple-rune-c03494fa05e991808bde/1-0000.mp3", duration = 40.0979592, start = 0},
  },
}
P.transport["item:simple-sigil"] = {
  hash = "269ea1",
  fullHash = "269ea1",
  text = "Simple Sigil. A Simple Sigil is a modest training token presented to novice night elf warriors in Shadowglen. Carried as a summons from the warrior trainer Alyissia, it marks a young fighter's formal introduction into the martial defense of Teldrassil. Within the sheltered boughs of Shadowglen, young night elves are guided by Conservator Ilthalaine to find their calling. For fledgling warriors, Ilthalaine delivers a Simple Sigil sent by a runner from the warrior trainer Alyissia. Bearing an inscription that directs the recruit to report for instruction, this token represents the start of disciplined martial training amidst troubling times for the World Tree. When brought to Alyissia, the sigil opens a dialogue on the pressing state of the kaldorei. The recent growth of Teldrassil, the creeping corruption tainting forest beasts, and the rediscovery of distant lands like Feralas have stretched night elven protectors thin. The sigil is not an artifact of power, but a practical credential welcoming the recruit into the fold of guardians tasked with shielding their people from emerging threats.",
  ["1"] = {
    {file = "Audio/Transport/full_item_simple-sigil-744f618f595e05cd6462/1-0000.mp3", duration = 62.72, start = 0},
  },
}
P.transport["item:simple-tablet"] = {
  hash = "f30f8a",
  fullHash = "f30f8a",
  text = "Simple Tablet. The Simple Tablet is a written missive handed to novice troll warriors arriving in the Valley of Trials. Delivered by Gornek, it directs the fledgling combatant to present themselves to Frang, the local warrior trainer. Within the harsh red bounds of the Valley of Trials, new recruits are quickly set to work. For young trolls seeking the path of the warrior, Gornek passes along this simple slate or parchment. Written by the troll Tar'sere and addressed to Frang, the master-at-arms resting near the Den, it serves as an official introduction to martial training in Durotar. It urges the recruit to step forward, present themselves, and prove their willingness to swing weapons under the banner of the Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_item_simple-tablet-908be1a6c30adbea55ce/1-0000.mp3", duration = 39.5232653, start = 0},
  },
}
P.transport["item:singed-scale"] = {
  hash = "49541d",
  fullHash = "49541d",
  text = "Singed Scale. Singed Scales are the charred, shock-hardened plates harvested from the electrified thunder lizards of Durotar. Procuring them serves as a rite of passage for young Horde warriors striving to master defensive battle arts. To the veterans of the Horde, a true warrior is not measured solely by the blood drawn by their axe, but by the blows they can absorb to shield their allies. In the arid canyon of Thunder Ridge in western Durotar, lightning hides and thunder lizards crackle with volatile storm energies. Hunting these beasts requires a warrior to endure relentless electrical shocks and crushing physical strikes. The blackened, scorched scales torn from their hides offer undeniable proof of a fighter's ability to weather punishing assaults and stand firm where lesser soldiers would fall. At the Far Watch Post on the border between Durotar and the Barrens, the veteran warrior Uzzek demands five of these scales from initiates before imparting his knowledge. In Uzzek's eyes, an initiate must possess inherent physical toughness before they can comprehend the subtle discipline of stances and tactical defense. Presenting the scales demonstrates that a warrior has the fortitude needed to combine thick hide, heavy armor, and calculated footwork into an unyielding wall against the enemies of the Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_item_singed-scale-4621f7735bb64da76f58/1-0000.mp3", duration = 72.5159184, start = 0},
  },
}
P.transport["item:skeleton-finger"] = {
  hash = "4afdcc",
  fullHash = "4afdcc",
  text = "Skeleton Finger. A severed, bony digit scavenged from the walking dead prowling the cursed groves and cemeteries of Duskwood. Madame Eva of Darkshire collects these macabre remnants alongside ghoul fangs and spider venom to craft protective talismans. The cursed woods of Duskwood are overrun by the restless remains of the dead, ranging from skeletal raiders and warriors to necrotic mages and fiends. While ordinary travelers avoid touching the foul remains of the risen dead, fortune tellers and mystics value their cold essence. Madame Eva, the resident seer of Darkshire, gathers these bony fingers to bind their lingering necrotic energies into a ward of retaliatory magic known as the Totem of Infliction.",
  ["1"] = {
    {file = "Audio/Transport/full_item_skeleton-finger-abd889237035d3129f3f/1-0000.mp3", duration = 40.0979592, start = 0},
  },
}
P.transport["item:skin-of-sweet-rum"] = {
  hash = "f7d966",
  fullHash = "f7d966",
  text = "Skin of Sweet Rum. A Skin of Sweet Rum is a specialized liquor sourced from the Lion's Pride Inn in Goldshire. It is sought after by Barkeep Daniels in Lakeshire, who is desperate to keep his tavern stocked while Blackrock orcs cut off Redridge from regular trade routes. In the war-weary town of Lakeshire, tavern supplies are running dangerously low. The Blackrock orc invasion has choked the supply roads leading into the Redridge Mountains, leaving Barkeep Daniels scrambling to quench the thirst of beleaguered town guards and refugees. To restock his depleted shelves, Daniels sends travelers across the kingdom to gather regional specialties, including a waterskin filled with the distinctive sweet rum brewed and served in Goldshire's Lion's Pride Inn.",
  ["1"] = {
    {file = "Audio/Transport/full_item_skin-of-sweet-rum-62bd661856de150bddcc/1-0000.mp3", duration = 41.5346939, start = 0},
  },
}
P.transport["item:skittering-blood"] = {
  hash = "71127f",
  fullHash = "71127f",
  text = "Skittering Blood. Skittering Blood is an alchemical reagent harvested from the arachnids dwelling within the Skittering Dark of Silverpine Forest. It serves as a vital toxic ingredient for the Royal Apothecary Society's research into a New Plague designed to eradicate both Scourge and humanity. Harvested from Skitterweb lurkers, strikers, and their broodmother Krethis the Shadowspinner, this venomous hemolymph possesses virulent properties prized by Forsaken alchemists. Apothecary Renferrel discovered that when refined alongside toxins extracted from grizzled bear hearts, the blood forms the base of an exceptionally lethal elixir. The compounds within the fluid demonstrate severe contaminating agents, making it an ideal biological catalyst for the Apothecarium's chemical experiments. Under the direction of Master Apothecary Faranell in the Undercity, the Royal Apothecary Society gathers reagents like Skittering Blood to engineer a devastating New Plague. Faced with overwhelming Scourge hordes and hostile human remnants, the Forsaken pursue biological warfare as an equalizer. Faranell analyzes the blood's toxic potency to devise a contagion potent enough to snuff out unlife and living flesh alike.",
  ["1"] = {
    {file = "Audio/Transport/full_item_skittering-blood-c090013b9db60e09cd71/1-0000.mp3", duration = 71.3404082, start = 0},
  },
}
P.transport["item:sleepers-key"] = {
  hash = "15ed9b",
  fullHash = "15ed9b",
  text = "Sleepers' Key. The Sleepers' Key is one of three enchanted keys crafted by night elf druids to seal their sacred vault within the Talon Den atop Stonetalon Peak. Kept safe inside a hidden cache opened with the Gatekeeper's Key, it is one of the three keys needed to open the druids' hoard. Carved into the heights of Stonetalon Peak, the Talon Den serves as a redoubt and sanctum for the druids of Kalimdor. Aware that their sacred relics and potent treasures might draw unwanted attention, the night elf keepers devised an intricate system of locks and hidden caches to protect their hoard. The Sleepers' Key is one third of that protective ward. Placed within a secluded cache in the den's depths, it can only be retrieved using the Gatekeeper's Key hidden near the threshold. Alongside the Claw Key and the Barrow Key, the Sleepers' Key must be set into the stone locks of the Talon Den Hoard to disperse the ward and reveal the ancient items held within.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sleepers-key-c6f2aff8278be9b94024/1-0000.mp3", duration = 53.4987755, start = 0},
  },
}
P.transport["item:smoky-iron-ingot"] = {
  hash = "b967b4",
  fullHash = "b967b4",
  text = "Smoky Iron Ingot. Smoky Iron Ingots are roughly processed metal bars smelted by the kobolds of the Windshear dig sites in the Stonetalon Mountains. Orcish armorers prize these ingots as raw material for forging sturdy mail gear fit for Horde warriors. Within the soot-stained tunnels of the Windshear Crag in the Stonetalon Mountains, kobolds excavate deep into the rocky earth, pulling unrefined ore from the slopes and smelting it over crude, smoking fires. The resulting Smoky Iron Ingots are far from pristine—thick with residue and charcoal—yet dense enough to retain substantial tensile strength. The near-blind orc armorer Thun'grim Firegaze, working out of a rugged camp overlooking the Barrens, specifically requests these ingots when crafting armor for proven warriors of the Horde. Combined with refined iron bars, powdered azurite, and volatile phlogiston, the smoky metal serves as a resilient core for crafting Brutal Hauberks.",
  ["1"] = {
    {file = "Audio/Transport/full_item_smoky-iron-ingot-c96b7c48418461a6b1b8/1-0000.mp3", duration = 56.0065306, start = 0},
  },
}
P.transport["item:smoldering-embers"] = {
  hash = "18c1d5",
  fullHash = "18c1d5",
  text = "Smoldering Embers. Smoldering Embers are the glowing, heat-baked remnants retrieved from the raging fire elementals of the Charred Vale. Night elf Sentinels track these cinders as physical proof that the fiery terrors overrunning the devastated woodland are being subdued. The Venture Company's relentless clear-cutting and industrial devastation tore through the Charred Vale, setting the forest ablaze and unleashing destructive fury from deep within the earth. In their wake, elementals of living fire—Burning Ravagers, Burning Destroyers, and wandering Rogue Flame Spirits—surged across the scorched basin. These Smoldering Embers are the lingering, ash-covered cores left behind when an elemental is extinguished, serving as proof that the rampant fires of the vale are being systematically suppressed.",
  ["1"] = {
    {file = "Audio/Transport/full_item_smoldering-embers-85051a037fab1cc1821d/1-0000.mp3", duration = 43.1281633, start = 0},
  },
}
P.transport["item:snellig-s-snuffbox"] = {
  hash = "24ec9b",
  fullHash = "24ec9b",
  text = "Snellig's Snuffbox. Snellig's Snuffbox is a personal keepsake recovered from the restless undead First Mate Snellig among the wreckage of the Lost Fleet. Bringing this trinket back to First Mate Fitzsimmons in Menethil Harbor serves as proof that his cursed former crewmate has finally been put to rest. When the Third Fleet of Kul Tiras ran aground along the northern shores of the Wetlands, its sailors and officers did not find peaceful deaths. Bound by a mysterious and dark power tied to a hidden treasure aboard the ships, the drowned crew rose again as tortured spirits and skeletal undead. Among them was First Mate Snellig, who still haunts the rotting hold of the wreck closest to the coastline. Even in death, he clung to his snuffbox—a small, mundane reminder of his mortal life at sea. For the sole living survivor of the disaster, First Mate Fitzsimmons, recovering this small possession provides tangible proof that at least one of his lost shipmates has been released from an eternity of torment.",
  ["1"] = {
    {file = "Audio/Transport/full_item_snellig-s-snuffbox-b9cb51b1ea378988261a/1-0000.mp3", duration = 56.0065306, start = 0},
  },
}
P.transport["item:snufflenose-command-stick"] = {
  hash = "fd0330",
  fullHash = "fd0330",
  text = "Snufflenose Command Stick. The Snufflenose Command Stick is a training rod provided by the goblin entrepreneur Mebok Mizzyrix in Ratchet. It is used to direct trained snufflenose gophers to locate and unearth valuable blueleaf tubers buried deep within Razorfen Kraul. Blueleaf tubers are coveted delicacies across Azeroth, but finding them is nearly impossible without specialized help. Buried in the thorny underground depths of Razorfen Kraul, the roots are entirely hidden from sight. To exploit this lucrative market without braving the quilboar dens himself, the Ratchet merchant Mebok Mizzyrix conditioned keen-scented snufflenose gophers to dig up the tubers. The Snufflenose Command Stick is the tool adventurers use to direct these trained critters, prodding them to sniff out and expose root nodes from up to fifty paces away.",
  ["1"] = {
    {file = "Audio/Transport/full_item_snufflenose-command-stick-c3cfcf22766ebcf8787c/1-0000.mp3", duration = 45.9232653, start = 0},
  },
}
P.transport["item:snufflenose-owner-s-manual"] = {
  hash = "75b8ce",
  fullHash = "75b8ce",
  text = "Snufflenose Owner's Manual. The Snufflenose Owner's Manual is an instructional booklet from Marwig Rustbolt of Snuff Inc., kept beside the goblin entrepreneur Mebok Mizzyrix in Ratchet. It outlines how to deploy and direct a trained Snufflenose Gopher to locate rare Blueleaf Tubers buried in Razorfen Kraul. Written by Marwig Rustbolt, owner of Snuff Inc., this short guide details how to work with the company's trained snufflenose gophers. These beasts possess a keen sense of smell capable of detecting subterranean Blueleaf Tubers from fifty paces away. The manual instructs prospectors to release a gopher using a ventilated crate and guide its rooting instincts with a command stick, directing the creature through the hostile thorns and quilboar tunnels of Razorfen Kraul to secure the prized culinary delicacies.",
  ["1"] = {
    {file = "Audio/Transport/full_item_snufflenose-owner-s-manual-afd9f7662838e20e5c91/1-0000.mp3", duration = 45.1395918, start = 0},
  },
}
P.transport["item:sodium-nitrate"] = {
  hash = "3a3b5b",
  fullHash = "3a3b5b",
  text = "Sodium Nitrate. Sodium Nitrate is a volatile chemical reagent carried by the dwarven excavators and garrison stationed at Bael Modan in the southern Barrens. Though imported by the Ironforge expedition to blast through ancient stone, the exiled tauren Gann Stonespire seeks to reclaim it to assemble an explosive charge against the invaders. The Bael'dun expedition tore into the ancestral lands of the Stonespire tribe armed with heavy earthmovers and blasting reagents. To crack open the stubborn rockbeds of the southern Barrens, the dwarves relied on volatile chemical compounds. Sodium Nitrate forms a crucial stabilizing and oxidizing agent in high-grade explosives, carried routinely by Bael'dun riflemen, soldiers, and officers inside the excavation works and nearby fortress.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sodium-nitrate-a72f9c7c0f63811740a9/1-0000.mp3", duration = 44.2514286, start = 0},
  },
}
P.transport["item:solomon-s-plea-to-darkshire"] = {
  hash = "5fc5ba",
  fullHash = "5fc5ba",
  text = "Solomon's Plea to Darkshire. Solomon's Plea to Darkshire is an urgent missive penned by Magistrate Solomon of Lakeshire addressed to Lord Ello Ebonlocke. In the face of mounting Blackrock orc and gnoll threats, the letter begs the leadership of Darkshire to send their elite militia, the Night Watch, to bolster Lakeshire's strained defenses. Lakeshire stands on the brink of being overwhelmed by invading Blackrock orcs, gnolls, and murlocs, with virtually no official reinforcements arriving from Stormwind. In desperation, Magistrate Solomon drafted this formal plea to Mayor Ello Ebonlocke of Darkshire, petitioning him to dispatch members of the Night Watch northward into Redridge. The document reflects the severe breakdown of central military support across southern Azeroth, forcing individual human settlements to look to one another for mutual survival.",
  ["1"] = {
    {file = "Audio/Transport/full_item_solomon-s-plea-to-darkshire-c0f7e1b0409181a120df/1-0000.mp3", duration = 46.3412245, start = 0},
  },
}
P.transport["item:solomon-s-plea-to-westfall"] = {
  hash = "220397",
  fullHash = "220397",
  text = "Solomon's Plea to Westfall. Solomon's Plea to Westfall is an urgent written appeal penned by Magistrate Solomon of Lakeshire. Desperate for reinforcements against the Blackrock orcs and gnolls, Solomon sends this dispatch to Gryan Stoutmantle in Westfall hoping the newly formed People's Militia can lend aid while Stormwind's royal army fails to respond. As the threat of the Blackrock clan and hostile gnolls looms large over Redridge, Magistrate Solomon finds himself dangerously isolated in Lakeshire. The royal army from Stormwind has inexplicably failed to arrive in force to defend the region's borders. Unable to wait for official support from the kingdom's capital, Solomon pens this plea in a desperate bid to recruit assistance from outside the regular military structure. Having caught word of a volunteer defense force coalescing across Elwynn to the west, he turns directly to the People's Militia. The message is addressed directly to Gryan Stoutmantle, a veteran warrior organizing the frontier defense of Westfall. Solomon hopes Stoutmantle can spare fighters to reinforce Lakeshire until Stormwind's crown finally sends regular reserves. Entrusted to an adventurer acting as courier, the document reflects the fracturing administrative coordination across Stormwind's outlying territories, where local magistrates are left to negotiate mutual aid agreements on their own initiative.",
  ["1"] = {
    {file = "Audio/Transport/full_item_solomon-s-plea-to-westfall-a3a85c41a7e19bdc957f/1-0000.mp3", duration = 77.3485714, start = 0},
  },
}
P.transport["item:soran-ruk-fragment"] = {
  hash = "9aac0d",
  fullHash = "9aac0d",
  text = "Soran'ruk Fragment. A Soran'ruk Fragment is a shattered shard of a demonic prison orb once bound to the spirit of a disgraced servant of the Burning Legion. Though split and dispersed among cultists deep beneath Ashenvale, each shard still radiates residual fel energy. When demons of the Burning Legion fall out of favor with their masters, their spirits are sometimes condemned to imprisonment inside specialized orbs and distributed to fel spellcasters as conduits of raw power. The orb of Soran'ruk met this fate, yet somewhere in its history, it was cracked apart. One half was broken into smaller shards and fell into the hands of the Twilight's Hammer cultists lurking within the submerged ruins of Blackfathom Deeps, who draw upon the lingering demonic essence for their own dark workings.",
  ["1"] = {
    {file = "Audio/Transport/full_item_soran-ruk-fragment-7e9f314fafe02aadedcd/1-0000.mp3", duration = 45.3746939, start = 0},
  },
}
P.transport["item:southsea-treasure"] = {
  hash = "663433",
  fullHash = "663433",
  text = "Southsea Treasure. The Southsea Treasure is a valuable hoard kept deep within the hold of the Southsea Freebooter vessel, the Tide Razor. Sought by Wrenix the Wretched in Ratchet, retrieving it tests the lockpicking and infiltration skills of fledgling thieves. Anchored along the Merchant Coast south of Ratchet, the pirate vessel Tide Razor serves as a forward base and training ground for the Southsea Freebooters. Stashed deep in its lowest hold lies a coveted stash of plunder known as the Southsea Treasure. Wrenix the Wretched, a goblin scoundrel operating out of Ratchet, considers it the ultimate test for aspiring pickpockets. According to Wrenix, the last five operatives sent to filch the chest returned in pieces, owing to the alert pirates aboard and a surprisingly ferocious guardian guarding the hold.",
  ["1"] = {
    {file = "Audio/Transport/full_item_southsea-treasure-02f4718b59c94b7047e3/1-0000.mp3", duration = 44.4081633, start = 0},
  },
}
P.transport["item:spectral-comb"] = {
  hash = "819814",
  fullHash = "819814",
  text = "Spectral Comb. The Spectral Comb is an ethereal grooming tool used to interact with the restless dead of Duskwood. Fashioned to pass through intangible forms, it is brought to the sorrowful spirit Blind Mary to harvest strands of ghost hair. Normal implements cannot touch or groom a spirit, making gathering ethereal materials nearly impossible for mortal craftsmen. The Spectral Comb is specially suited to interact with ghostly forms, gliding through otherwise intangible tresses. It is carried south of Darkshire to the ruined farmstead where the weeping ghost Blind Mary wails in isolation. Finding solace in the familiar act of grooming her ruined hair, Mary willingly uses the comb, leaving behind the spectral fibers needed to weave Ghost Hair Thread.",
  ["1"] = {
    {file = "Audio/Transport/full_item_spectral-comb-c1f8c0394694cb4d3b82/1-0000.mp3", duration = 42.8930612, start = 0},
  },
}
P.transport["item:spells-of-shadow"] = {
  hash = "c111a2",
  fullHash = "c111a2",
  text = "Spells of Shadow. Spells of Shadow is a dark grimoire carried by the Searing Blade cultists lurking beneath Orgrimmar in Ragefire Chasm. Filled with fel magic granted by the Burning Legion, it is targeted for recovery by the Forsaken leadership in the Undercity. Hidden deep in the molten caverns of Ragefire Chasm, members of the Searing Blade—a splinter cult tied to the Shadow Council—wield dark rites granted by demon masters of the Burning Legion. Among their most guarded treasures is the Spells of Shadow, a text containing insidious shadow and fel sorcery. Cultists and warlocks of the sect keep this book close at hand as they plot beneath the very feet of the Horde in Durotar. Word of the Searing Blade's demonic gifts reached the royal quarters of the Undercity. Lady Sylvanas Windrunner and her dreadlord lieutenant, Varimathras, determined that such powerful relics were wasted on cultists with lesser vision. Varimathras tasks Horde adventurers with venturing into the chasm to seize the Spells of Shadow alongside its companion tome, Incantations from the Nether, directing their power toward the Forsaken cause against the Scourge and the Lich King.",
  ["1"] = {
    {file = "Audio/Transport/full_item_spells-of-shadow-92f68fba229a9c172854/1-0000.mp3", duration = 65.2538776, start = 0},
  },
}
P.transport["item:spotted-sunfish"] = {
  hash = "5196bf",
  fullHash = "5196bf",
  text = "Spotted Sunfish. Spotted Sunfish are freshwater fish native to Lake Everstill in the Redridge Mountains. Renowned locally for their flavor, they are a staple commodity for Lakeshire's docks, though the growing murloc infestation makes procuring them hazardous. Lake Everstill has long been celebrated for its spotted sunfish, which fetch a dependable price among local merchants and visitors alike. Dockmaster Baren keeps a steady trade in them at the Lakeshire piers, supplying food and commerce to a town under strain. However, the aggressive murloc tribes prowling the shallows have disrupted routine fishing, often stockpiling catches of their own that adventurers must recover by force.",
  ["1"] = {
    {file = "Audio/Transport/full_item_spotted-sunfish-4db947142290903b9145/1-0000.mp3", duration = 38.6612245, start = 0},
  },
}
P.transport["item:stalker-claws"] = {
  hash = "16dc7c",
  fullHash = "16dc7c",
  text = "Stalker Claws. Stalker Claws are the talons harvested from the prairie stalkers roaming the rolling plains of Mulgore. Tauren shamans use them as vital components in carving traditional cleansing totems to purify tainted water wells. The grassy steppes of Mulgore are home to deadly natural predators, among them the stealthy prairie stalkers. These beasts survive through raw instinct and lethal precision, an essential balance within the Earth Mother's design. Mull Thunderhorn, seeking to heal the blighted land, requires these claws not out of malice toward the animals, but because the pure, natural ferocity with which they hunt holds the spiritual resonance necessary to counteract artificial corruption. When goblin ventures began drilling and mining across central Kalimdor, chemical poisons seeped deep into the subterranean waters feeding the ancestral tauren wells. The Thunderhorn Water Well in particular fell prey to vile taint. By binding Stalker Claws and Cougar Claws into a Thunderhorn Cleansing Totem, tribal shamans create a spiritual conduit capable of scouring the muck and unnatural sludge out of the earth's natural springs.",
  ["1"] = {
    {file = "Audio/Transport/full_item_stalker-claws-b5dfe739fab32e9be809/1-0000.mp3", duration = 65.4367347, start = 0},
  },
}
P.transport["item:steelgrill-s-tools"] = {
  hash = "a225f2",
  fullHash = "a225f2",
  text = "Steelgrill's Tools. Steelgrill's Tools are a specialized set of mechanic implements requisitioned for Beldin Steelgrill, the master technician of Steelgrill's Depot. Renowned for pushing siege engines—and his own equipment—to their limits, Beldin frequently breaks gear and relies on shipments from nearby Kharanos to keep his workshop running. Beldin Steelgrill is widely regarded as one of the finest siege engine technicians in Dun Morogh, but his aggressive repair style is infamous among local merchants. Working tirelessly on armored tanks and mechanical contraptions, Beldin tends to destroy delicate equipment almost as fast as it can be forged. Between snapping arclight spanners and stripping fang-ratchets, the mechanic is constantly placing fresh orders in Kharanos to keep his repair benches stocked. This particular delivery of tools is vital for keeping Ironforge's war machines operational. At his depot northeast of Kharanos, Beldin is actively servicing combat vehicles for seasoned drivers like Pilot Stonegear. Without freshly supplied wrenches and ratchets, critical siege engines would sit half-assembled in the snow, leaving both the depot and local defenses stalled.",
  ["1"] = {
    {file = "Audio/Transport/full_item_steelgrill-s-tools-afc49af0f95c810e2108/1-0000.mp3", duration = 66.3771429, start = 0},
  },
}
P.transport["item:steelsnap-s-rib"] = {
  hash = "807d55",
  fullHash = "807d55",
  text = "Steelsnap's Rib. Steelsnap's Rib is a grim trophy taken from the carcass of the ferocious hyena Steelsnap in Thousand Needles. Brought back to Thunder Bluff, it serves as physical proof that a creature deemed outside the Earthmother's blessing has been put down. Most tauren hunts are undertaken for sustenance, for honor, or to seek harmony with nature. Steelsnap, however, represents a different kind of quarry. Roaming the canyon floor of Thousand Needles south of Camp E'thok, this vicious alpha hyena terrorizes peaceful wildlife and rallies packs of lesser predators to senseless bloodshed. When the hunt master Melor Stonehoof on Hunter Rise marks Steelsnap for death, he demands a heavy bone—Steelsnap's rib—as undeniable confirmation that the tyrant has been slain and the canyon cleansed of its blight.",
  ["1"] = {
    {file = "Audio/Transport/full_item_steelsnap-s-rib-cb1463aab42eeb37642e/1-0000.mp3", duration = 46.4979592, start = 0},
  },
}
P.transport["item:stolen-silver"] = {
  hash = "666ff0",
  fullHash = "666ff0",
  text = "Stolen Silver. The Stolen Silver is a recovered strongbox of Horde coin meant for the Crossroads guard garrison. It was bizarrely carried off into the wilderness by the ferocious raptors of the Barrens, leading to disbelief among the outpost's overseers. The vast wilds of the Barrens present constant threats to supply lines, but few expected the local Sunscale raptors to target strongboxes of metal currency. When a shipment of silver meant as payroll for the Crossroads garrison was stolen from the guard tower, the raptors dragged the lockbox back to their communal nests at the Raptor Grounds south of Ratchet. To overseers like Gazrog, the theft reveals an unsettling degree of cunning in the predators, who apparently value shiny trinkets or possess intelligence far beyond that of ordinary wild beasts.",
  ["1"] = {
    {file = "Audio/Transport/full_item_stolen-silver-bf941d9ad591a1e19a66/1-0000.mp3", duration = 43.4416327, start = 0},
  },
}
P.transport["item:stone-of-relu"] = {
  hash = "66328f",
  fullHash = "66328f",
  text = "Stone of Relu. The Stone of Relu is an ancient archaeological relic recovered from the Wetlands. Believed by Archaeologist Flagongut to be the key to unlocking latent powers within primordial fossils, it was briefly lost when local raptors ambushed the scholar on the road. Discovered during Explorers' League operations, the Stone of Relu is believed to hold the deciphering power needed to unlock prehistoric fossils gathered from Kalimdor and the Eastern Kingdoms. Archaeologist Flagongut identified the artifact as the catalyst required to unleash secrets within both his own Wetlands specimens and the fossil unearthed by Prospector Remtravel in Darkshore. While Flagongut was traveling along the Wetland roads to rendezvous with Prospector Whelgar, a pack of mottled raptors ambushed him. During the scramble, the relic was lost and swallowed by one of the ravenous beasts, forcing the League to enlist adventurers to hunt the marsh raptors and cut the ancient stone from their gullets.",
  ["1"] = {
    {file = "Audio/Transport/full_item_stone-of-relu-898de18241b60a5435d2/1-0000.mp3", duration = 53.76, start = 0},
  },
}
P.transport["item:stonetalon-sap"] = {
  hash = "aa3b0c",
  fullHash = "aa3b0c",
  text = "Stonetalon Sap. Stonetalon Sap is a sticky, potent substance harvested directly from the lumbering sap beasts that roam the craggy heights of the Stonetalon Mountains. It serves as a key reagent for the Darkspear witch doctor Jin'Zil, who uses its raw woodland properties to concoct a spiteful brew.",
  ["1"] = {
    {file = "Audio/Transport/full_item_stonetalon-sap-cdaddda65ca12b354c65/1-0000.mp3", duration = 16.9273469, start = 0},
  },
}
P.transport["item:stormpike-banner"] = {
  hash = "f665e3",
  fullHash = "f665e3",
  text = "Stormpike Banner. The Stormpike Banner is a military standard hidden deep within the treacherous Icewing Cavern in Alterac Valley. Alliance recruits must brave wild harpies to recover it as an initiation trial, proving they are worthy to wear the Stormpike insignia. To officially join the ranks of the Stormpike expedition in Alterac Valley, prospective recruits must prove their mettle before they ever clash with the Frostwolf orcs. Lieutenant Haggerdin sends newly arrived Alliance soldiers into the Icewing Caverns, situated southwest of Dun Baldar. Planted deep inside this frozen subterranean den, the Stormpike Banner serves as a testing ground: anyone brave enough to brave the native harpies, seize the standard, and bring it back alive earns the rank and insignia of an initiate in the Stormpike Guard.",
  ["1"] = {
    {file = "Audio/Transport/full_item_stormpike-banner-6187fa386773da7f6f48/1-0000.mp3", duration = 45.1395918, start = 0},
  },
}
P.transport["item:stormpike-s-request"] = {
  hash = "739e30",
  fullHash = "739e30",
  text = "Stormpike's Request. Stormpike's Request is a written commission dispatched by Mountaineer Stormpike from the hills of Loch Modan to Stormwind City. The letter petitions master armorsmith Furen Longbeard to craft a custom shield of unmatched dwarven quality. While stationed far to the north in Loch Modan, Mountaineer Stormpike requires a sturdy new shield to weather the dangers of the dwarven frontier. Rather than trusting an ordinary smith, he insists on commissioning Furen Longbeard, an armorsmith whose legendary craftsmanship he holds in the highest regard. Because Furen now resides far to the south among the humans of Stormwind's Dwarven District—lured away from Ironforge by what Stormpike assumes must be a king's ransom—the mountaineer relies on traveling adventurers to deliver his formal request across the kingdoms. Delivering the letter into the bustling Dwarven District of Stormwind places the order directly into Furen Longbeard's capable hands. As a proud and established dwarven clan known across Khaz Modan for both martial grit and substantial wealth, a Stormpike commission carries weight. Pleased to receive word and business from his ancestral northern homelands, Furen agrees to fulfill the order and set to work hammering out the mountaineer's shield.",
  ["1"] = {
    {file = "Audio/Transport/full_item_stormpike-s-request-919ef07d79cc30e322dd/1-0000.mp3", duration = 69.9820408, start = 0},
  },
}
P.transport["item:stormwind-armor-marker"] = {
  hash = "d75f58",
  fullHash = "d75f58",
  text = "Stormwind Armor Marker. A Stormwind Armor Marker is an official military requisition token issued to adventurers who have aided the realm. It can be redeemed with sanctioned artisans, such as Sara Timberlain at the Eastvale Logging Camp, in exchange for freshly crafted gear. Maintaining law and order across Elwynn Forest stretches the resources of the realm thin. Rather than distributing standard gear directly from military outposts, commanders sometimes issue official tokens known as armor markers. These requisition slips verify that the bearer has performed valorous service for Stormwind and authorize local contracted craftsmen to supply them with tailored armor. One key destination for these markers is the Eastvale Logging Camp, situated on the eastern frontier of Elwynn. There, artisans like Sara Timberlain operate under commission from the Stormwind Army, turning local materials into protective cloth and leather garments. Presenting a marker grants recruits custom-fitted defense to aid them in safeguarding the surrounding woodlands.",
  ["1"] = {
    {file = "Audio/Transport/full_item_stormwind-armor-marker-4041a23c7e89bb8cd5c1/1-0000.mp3", duration = 58.2269388, start = 0},
  },
}
P.transport["item:stoutmantle-s-response-to-solomon"] = {
  hash = "f16fa5",
  fullHash = "f16fa5",
  text = "Stoutmantle's Response to Solomon. Stoutmantle's Response to Solomon is a written dispatch carried from Sentinel Hill to Lakeshire. In it, Gryan Stoutmantle grimly informs Magistrate Solomon that the embattled People's Militia cannot spare a single soldier to defend Redridge Mountains. Facing relentless pressure from Blackrock orcs and gnolls, Magistrate Solomon of Lakeshire reached out to Sentinel Hill hoping Westfall's local forces could send reinforcements. Gryan Stoutmantle's written reply brings bitter news. Mourning Lakeshire's losses, Stoutmantle explains that Westfall is plagued with its own war. The People's Militia was formed out of desperation precisely because the Crown withdrew its garrison, leaving farmers and volunteers to battle the Defias Brotherhood alone. Stoutmantle explains that his own forces are bleeding and stretched thin, unable to sacrifice men to bail out another abandoned frontier.",
  ["1"] = {
    {file = "Audio/Transport/full_item_stoutmantle-s-response-to-solomon-0f8a0d34b0d9d24ad91a/1-0000.mp3", duration = 50.4946939, start = 0},
  },
}
P.transport["item:strange-smelling-powder"] = {
  hash = "eaea58",
  fullHash = "eaea58",
  text = "Strange Smelling Powder. Strange Smelling Powder is an enigmatic residue uncovered during investigations into suspicious sabotage around Loch Modan. Feared to be an unstable demolition agent, it prompts Chief Engineer Hinderweir to send an urgent courier north to seek out a demolition expert. Discovered amid signs of sabotage threatening Loch Modan's infrastructure, this peculiar powder immediately raised alarm for Chief Engineer Hinderweir. Its pungent odor and fine consistency suggest an engineered demolition compound rather than standard mining blast powder. Unsure of the mixture's chemical nature or origin, Hinderweir refuses to tamper with it himself, knowing that even a slight spark could trigger disaster.",
  ["1"] = {
    {file = "Audio/Transport/full_item_strange-smelling-powder-da01ef3cbc123e173b11/1-0000.mp3", duration = 39.3665306, start = 0},
  },
}
P.transport["item:strangely-marked-box"] = {
  hash = "77e86f",
  fullHash = "77e86f",
  text = "Strangely Marked Box. A Strangely Marked Box is a piece of cargo discovered inside the harnesses strapped to dead sea turtles along the Darkshore coastline. Its mysterious exterior bears the runic script of the serpentine naga, offering night elf scholars proof that these sea creatures did not strand themselves by accident. While several giant sea turtles and sea creatures simply wash ashore along Darkshore's mist-veiled beaches, others tell a far more ominous tale. Scattered carcasses bear the splintered remnants of riding harnesses and abandoned carriages bound straight to their shells. Within the ruins of these buckled contraptions lie sealed containers covered in foreign, sinuous runes. Scavenging Greymist murlocs frequently take up residence in the hollow ribcages and broken wagons, picking at the carrion and guarding whatever remnants were left behind.",
  ["1"] = {
    {file = "Audio/Transport/full_item_strangely-marked-box-2f75de056eafd195c2d1/1-0000.mp3", duration = 46.9681633, start = 0},
  },
}
P.transport["item:strigid-owl-feather"] = {
  hash = "1a16db",
  fullHash = "1a16db",
  text = "Strigid Owl Feather. Strigid Owl Feathers are gathered from the wild strigid owls nesting within the boughs of Teldrassil. While natural forest plumage, they are sought after by questionable figures seeking raw materials for their covert dealings.",
  ["1"] = {
    {file = "Audio/Transport/full_item_strigid-owl-feather-69f55a1c20288c8b0541/1-0000.mp3", duration = 12.5910204, start = 0},
  },
}
P.transport["item:sturdy-dragonmaw-shinbone"] = {
  hash = "1813a4",
  fullHash = "1813a4",
  text = "Sturdy Dragonmaw Shinbone. Sturdy Dragonmaw Shinbones are durable skeletal trophies gathered from the renegade Dragonmaw orcs in the Wetlands. Required by armor crafter Velora Nitely in the Undercity, they serve as reinforcement struts for bespoke warrior armor. When forging brutal leg guards for frontline warriors, smiths require raw components that can endure severe punishment. In the Undercity, Velora Nitely prizes the skeletal density of the renegade Dragonmaw orcs entrenched at the Angerfang Encampment in the central Wetlands. Dragonmaw orcs are known for their thick, sturdy frames, making their shins well suited to serve as structural bracers. However, not every collected bone can withstand the strain; warriors must test each piece with their bare hands, discarding those that snap under pressure.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sturdy-dragonmaw-shinbone-3e40b1270191017ef375/1-0000.mp3", duration = 44.0946939, start = 0},
  },
}
P.transport["item:sully-balloo-s-letter"] = {
  hash = "48ed9d",
  fullHash = "48ed9d",
  text = "Sully Balloo's Letter. Sully Balloo's Letter is a waterlogged, tender missive recovered from the sunken remains of a dwarven soldier beneath the Thandol Span. Addressed to his wife Sara in Ironforge, it represents the quiet personal tragedies lingering beneath the grand conflicts of Khaz Modan. Beneath the massive stone pillars of the Thandol Span, connecting the Wetlands to the Arathi Highlands, lies the skeletal remains of a dwarf pinned deep under the rushing water. Clutched in his grasp is a fragile, waterlogged envelope containing this letter. Written with painstaking care in his final days or hours, it begins with the poignant words, 'My dear Sara....' Though the parchment has suffered from prolonged submersion, the ink still holds the enduring love of a dwarven defender who never made it back home to the city of Ironforge.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sully-balloo-s-letter-891499732870cc2544c8/1-0000.mp3", duration = 46.0277551, start = 0},
  },
}
P.transport["item:sunscorched-shell"] = {
  hash = "48dd98",
  fullHash = "48dd98",
  text = "Sunscorched Shell. Sunscorched Shells are the sturdy remnants of wyvern eggs gathered beneath the roosts of Highperch in Thousand Needles. Hardened by the harsh desert heat, they are prized by skilled armorcrafters who can render them into a protective lacquer for mail links. Perched high upon the mesa needles of southern Kalimdor, Highperch wyverns lay eggs that endure relentless desert sun and searing winds. The discarded shell fragments accumulate beneath their roosts, baked to remarkable hardness by the arid climate. While seemingly little more than brittle refuse to a casual wanderer, these sunscorched remains possess natural structural resilience that makes them an intriguing reagent for specialized artisans. In Darnassus, the armorer Mathiel studies crafting methods pioneered by his colleague, the dwarf smith Furen Longbeard. Intrigued by Furen's discoveries, Mathiel uses these shells to create a fine lacquer capable of reinforcing mail armor. When properly processed and applied, the mineral-rich coating bonds to metallic links, adding substantial resilience without overburdening the wearer.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sunscorched-shell-052664585a13db2253d0/1-0000.mp3", duration = 64.8097959, start = 0},
  },
}
P.transport["item:super-reaper-6000-blueprints"] = {
  hash = "0a4e24",
  fullHash = "0a4e24",
  text = "Super Reaper 6000 Blueprints. The Super Reaper 6000 Blueprints are the technical schematics for an enormous mechanized woodcutter deployed by the Venture Company in Stonetalon Mountains. Designed under the supervision of the gnome engineer Gerenzo Wrenchwhistle, the plans are heavily coveted by his disgruntled goblin rivals. The Venture Company's relentless clear-cutting operation in Windshear Crag relies on massive mechanized lumber harvesters known as Super Reapers. To the utter dismay of traditional goblin engineers, the company placed a gnome named Gerenzo in charge of designing the Super Reaper 6000 model. These blueprints contain the schematics for the contraption, carried by Venture Co. operators working the machinery across the crag. When the goblin engineer Ziz Fizziks was ousted from the operation, he was quickly hired by Sputtervalve to steal the designs. However, deciphering Gerenzo's dense, eccentric gnomish technical notations proves to be almost as difficult as taking the blueprints by force.",
  ["1"] = {
    {file = "Audio/Transport/full_item_super-reaper-6000-blueprints-9e0e511c34346d7fb45d/1-0000.mp3", duration = 56.7902041, start = 0},
  },
}
P.transport["item:supplies-for-sven"] = {
  hash = "6c82ed",
  fullHash = "6c82ed",
  text = "Supplies for Sven. Supplies for Sven is a bundle of vital provisions packaged in Darkshire and destined for Sven Yorgen's secluded camp. Surrounded by the horrors of Duskwood, Sven and his small band rely on sympathetic townspeople like the Carevin family to sustain their vigil against the shadows. Carrying survival gear and basic necessities through Duskwood is no simple chore. Sven Yorgen and his handful of followers camp in the northwestern wilderness of the woods, far from the safety of Darkshire. Their numbers are so depleted and their watch so demanding that they cannot spare a single fighter to make the trek into town. This parcel represents a lifeline sent by the Carevin family, ensuring that the isolated camp has the food, bandages, and materials needed to hold their ground.",
  ["1"] = {
    {file = "Audio/Transport/full_item_supplies-for-sven-213b29d887687316fcf5/1-0000.mp3", duration = 45.0612245, start = 0},
  },
}
P.transport["item:surena-s-choker"] = {
  hash = "5214de",
  fullHash = "5214de",
  text = "Surena's Choker. Surena's Choker is an enchanted bloodstone necklace gifted by Gakin the Darkbinder to his former apprentice, Surena Caledon. After Surena betrayed Gakin and fled to join the Defias Brotherhood, the warlock master sent aspiring acolytes to reclaim the piece by force. Gakin the Darkbinder, operating quietly from beneath the Slaughtered Lamb in Stormwind, took Surena Caledon on as a promising student in the dark arts. Taken by her youthful charm and magical aptitude, Gakin presented her with a valuable bloodstone choker to aid her studies. However, Surena abandoned her training and absconded with Erlan Drudgemoor, a rogue aligned with the Defias Brotherhood. Unwilling to let such a potent artifact remain in the hands of a traitor, Gakin task initiates seeking mastery over the void to track Surena down to the Brackwell Pumpkin Patch, reclaim the necklace, and demonstrate where true loyalty lies.",
  ["1"] = {
    {file = "Audio/Transport/full_item_surena-s-choker-ea513dfb81b840301d82/1-0000.mp3", duration = 53.524898, start = 0},
  },
}
P.transport["item:swoop-gizzard"] = {
  hash = "5f018a",
  fullHash = "5f018a",
  text = "Swoop Gizzard. A swoop gizzard is an organ harvested from the predatory birds soaring over Mulgore. Highly sought after for traditional folk remedies, it serves as a crucial ingredient for cleansing deadly toxins. Swoops are predatory avian hunters native to the plains and mesas of Mulgore, known for their keen eyesight and scavenging nature. While their feathers and meat serve everyday uses for the tauren, their internal organs—particularly the gizzard—are prized by herbalists and healers. When combined with other potent animal remnants like cougar bones and wolf hearts, the dense muscular organ aids in neutralizing venomous animal bites and halting festering systemic infections. In Bloodhoof Village, the medicine worker Maur Raincaller fell prey to the legendary plainstrider Mazzranache, suffering a vicious, venomous wound to his shoulder. Falling into delirium from the creeping poison, Maur relies on a swoop gizzard alongside a prairie wolf heart, a flatland cougar femur, and a plainstrider scale to concoct a curative poultice capable of expelling the beast's lethal venom.",
  ["1"] = {
    {file = "Audio/Transport/full_item_swoop-gizzard-96eab0b234f26e327a28/1-0000.mp3", duration = 63.3469388, start = 0},
  },
}
P.transport["item:tablet-of-verga"] = {
  hash = "adf207",
  fullHash = "adf207",
  text = "Tablet of Verga. The Tablet of Verga is an arcane stone inscribed with demonic runes essential for binding dark entities. Stolen by the sinister Burning Blade cult, it was taken deep into their lair within Skull Rock. Recovering the artifact allows dark practitioners in Orgrimmar to decipher the rituals needed to bind a voidwalker. The Tablet of Verga holds specific ritual runes required to summon and bend creatures of the Nether to a master's will. When the Burning Blade cult managed to steal the tablet, they concealed it within a hidden chest inside Skull Rock, just east of Orgrimmar. For the warlocks working discreetly in the shadows of the Cleft of Shadow, regaining the relic is crucial—not only to study its ancient markings for summoning a voidwalker, but also to deny the fanatical cultists their own dark advantage.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tablet-of-verga-66077fe044f62dfacc84/1-0000.mp3", duration = 46.8897959, start = 0},
  },
}
P.transport["item:tainted-heart"] = {
  hash = "6f762b",
  fullHash = "6f762b",
  text = "Tainted Heart. The Tainted Heart is a blighted floral core extracted from the corrupt flora of Teldrassil. Given to adventurers by the botanist Denalan, it requires magical and nutritive cleansing to rid it of lingering foul energies. Teldrassil's natural balance suffers from an unnatural malady, warping its native plants and beasts. After stripping away foul moss that clung to a blighted growth, Denalan presents this lingering core: the Tainted Heart. Though freed of its outer rot, darkness still permeates the tissue. Denalan seeks to discover whether specially prepared, nutrient-rich earth can counteract the lingering taint and restore life to what was corrupted.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tainted-heart-f3a8aed78a28fe5ac4ca/1-0000.mp3", duration = 40.6465306, start = 0},
  },
}
P.transport["item:tainted-keg"] = {
  hash = "bceff1",
  fullHash = "bceff1",
  text = "Tainted Keg. The Tainted Keg is a barrel of stolen dwarven stout laced with a lethal Forsaken brew concocted by Apothecary Lydon. Delivered under the guise of refreshments to imprisoned human farmers in Tarren Mill, it serves as a gruesome field test for the Royal Apothecary Society's developing poisons. The keg began its existence as a barrel of Shindigger Stout, plundered from the dwarven riflemen entrenched at Dun Garok. Rather than drinking it, Apothecary Lydon contaminated the hearty ale with his newly refined Elixir of Agony. By lacing an ordinary beverage, the Forsaken crafted an insidious vector designed to slip past suspicion, turning a familiar comforts of the living into a swift death sentence.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tainted-keg-5f49d342c77669531651/1-0000.mp3", duration = 40.3330612, start = 0},
  },
}
P.transport["item:tainted-letter"] = {
  hash = "9556f5",
  fullHash = "9556f5",
  text = "Tainted Letter. The Tainted Letter is a discreetly delivered summons bearing the seal of Drusilla La Salle, a warlock trainer lurking on the outskirts of Northshire Abbey. It directs aspiring human practitioners of the dark arts to report to her for specialized tutelage away from watchful eyes. While priests, paladins, and standard soldiers train openly across the manicured lawns of Northshire Abbey, practitioners of fel magic must operate with far greater discretion. Handed to initiates returning from the nearby kobold camps, this letter carries the personal insignia of Drusilla La Salle. Bearing subtle traces of dark artifice, the missive instructs novice warlocks to seek out their mentor discreetly near the abbey's grounds before the local town guards and clerics become suspicious of their forbidden path. Meeting Drusilla reveals the necessity for such secretive measures. Warlocks are viewed with deep distrust by the mundane populace of Elwynn, forcing mentors to linger on the fringes and avoid prying sentries. Drusilla uses the delivered letter to initiate a critical lesson in discipline: arcane and nether magic invite relentless corruption, requiring practitioners to temper their surging ambition with patient self-control while communing with denizens of the Twisting Nether.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tainted-letter-b1a15fdaf06072777e14/1-0000.mp3", duration = 75.8334694, start = 0},
  },
}
P.transport["item:tainted-memorandum"] = {
  hash = "f12611",
  fullHash = "f12611",
  text = "Tainted Memorandum. The Tainted Memorandum is a discreet note handed to novice gnome warlocks starting out in Coldridge Valley. Penned by the warlock trainer Alamar Grimm, it urges the reader to cast aside traditional paths and seek out the true power offered by the dark arts. In the chilly dwarven outpost of Anvilmar, practitioners of fel magic are neither celebrated nor widely trusted. For young gnomes dabbling in forbidden arts, the Tainted Memorandum serves as an invitation from Alamar Grimm. The message rejects reliance on the Holy Light or mundane martial steel, pointing instead to the fall of Gnomeregan as proof that conventional methods and tinkering have failed their people. To Grimm, relying on dwarven charity is a dead end; gnomes must seize undeniable power and summon unquestioning minions if they ever hope to secure their own future.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tainted-memorandum-ec6a4707d756243af832/1-0000.mp3", duration = 48.3265306, start = 0},
  },
}
P.transport["item:talisman-of-corruption"] = {
  hash = "9914c1",
  fullHash = "9914c1",
  text = "Talisman of Corruption. The Talisman of Corruption is a vile demonic trinket used by the satyr Xabraxxis to poison the minds of Darkshore's Blackwood furbolgs. Carried within the satyr's personal pouch, it serves as a magical conduit that binds the tribe to fel madness. The night elves of Auberdine have long struggled to understand why the Blackwood furbolgs turned so aggressively upon their former allies. Thundris Windweaver discovered that the tribe's downfall was not a natural descent, but deliberate sabotage orchestrated by the satyrs. Using talismans like this one, demonic agents project corrupting sorcery across the wilderness, tainting food supplies and twisting peaceful forest spirits into frenzied beasts. By channeling fell magics directly through these devices, the satyrs hold an unbroken grip over the minds and wills of the local tribes.",
  ["1"] = {
    {file = "Audio/Transport/full_item_talisman-of-corruption-914380d1a566a7fc7571/1-0000.mp3", duration = 49.3714286, start = 0},
  },
}
P.transport["item:tallonkai-s-jewel"] = {
  hash = "189612",
  fullHash = "189612",
  text = "Tallonkai's Jewel. Tallonkai's Jewel is a luminous emerald stolen from an enchanted druidic talisman on Teldrassil. Prized by the furbolg mystic Ferocitas the Dream Eater, it serves as the crucial centerpiece required to mend the Emerald Dreamcatcher. Tallonkai Swiftroot was given the Emerald Dreamcatcher by Gaerolas Talvethen, warden of the druids in the Ban'ethil Barrow Den, as a potent focus that siphons energy from the Emerald Dream. When his talisman was damaged, the central radiant emerald was pried loose and carried off into the wilds of eastern Teldrassil. The jewel fell into the paws of Ferocitas the Dream Eater, a corrupted Gnarlpine leader who fashioned the gleaming stone into a personal necklace. While the green stone cast an eerie glow in the forest gloom, its true harmonious resonance was entirely useless to the furbolg, serving merely as a trophy until retrieved.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tallonkai-s-jewel-b5e6fbbb24f826b6e094/1-0000.mp3", duration = 50.5730612, start = 0},
  },
}
P.transport["item:taming-rod"] = {
  hash = "0a1c81",
  fullHash = "0a1c81",
  text = "Taming Rod. A Taming Rod is an instructional tool entrusted to novice hunters by their trainers. Infused with simple binding magic, it allows a student to temporarily pacify and command local wildlife to master the fundamentals of beast handling. Novice hunters cannot immediately exert the mental force required to bind a wild creature to their will permanently. To bridge that gap, veteran trainers issue specialized Taming Rods. In places like Razor Hill, mentors such as Thotar give aspiring orc and troll hunters these enchanted implements to subdue regional predators—such as dire mottled boars and armored scorpids. The rod temporarily pacifies the beast, allowing the handler to practice issuing commands and fighting alongside an animal companion without the danger of an unbreakable primal bond forming prematurely. The control granted by a Taming Rod is fleeting, typically lasting only a short while before the magic fades. Each rod is attuned to specific types of wild beasts, serving as a stepping stone through successive trials. Once a novice has proved they can command various wild temperaments—from docile foragers to aggressive venomous hunters—the rod is returned to the trainer. Having demonstrated proper technique, the student is finally taught the innate art of taming, calling, and dismissing lifelong companions without needing an artifact.",
  ["1"] = {
    {file = "Audio/Transport/full_item_taming-rod-7ec0222ef2b794e76ff7/1-0000.mp3", duration = 80.0391837, start = 0},
  },
}
P.transport["item:tattered-manuscript"] = {
  hash = "676165",
  fullHash = "676165",
  text = "Tattered Manuscript. The Tattered Manuscript consists of loose, vandalized pages torn from the singular copy of the Tome of the Cabal. Hidden away in the dusty depths of southern Kalimdor, this battered portion of the text holds arcane secrets vital to warlocks seeking mastery over felhunters. The Tome of the Cabal was once an intact, unique volume safeguarded within the fallen kingdom of Lordaeron. At some point, an unknown defiler ripped almost half of the treatise directly from its binding. While the surviving spine and remainder of the book—now known as the Moldy Tome—were shipped south toward Khaz Modan and lost at sea, these torn parchment leaves drifted far across the Great Sea into Kalimdor, ultimately falling into the hands of the Galak centaur inside Splithoof Hold. Kept within a battered chest deep within the labyrinthine caverns of Splithoof Hold, the manuscript survived the harsh arid winds of Thousand Needles. Despite its fragile, tattered state, practitioners of the dark arts—both Alliance warlocks working with Krom Stoutarm in Ironforge and Horde practitioners aiding Jorah Annison in the Undercity—brave the aggressive centaur to reunite these lost leaves with the Moldy Tome. Once combined, the completed treatise contains the dark rituals necessary to summon and bind a demonic felhunter.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tattered-manuscript-a15a2903a0a19999ff03/1-0000.mp3", duration = 76.4865306, start = 0},
  },
}
P.transport["item:tazan-s-satchel"] = {
  hash = "148a71",
  fullHash = "148a71",
  text = "Tazan's Satchel. Tazan's Satchel is a locked pouch carried by the troll Tazan, who operates alongside pirates near Ratchet. It holds secret information coveted by the Shattered Hand, the covert guild of rogues based beneath Orgrimmar. Within the sun-baked wastes of the Barrens, a troll named Tazan carries on illicit dealings with the pirates encamped along the coast near Ratchet. These under-the-table arrangements drew the keen eyes of Therzok, a guild master of the Shattered Hand situated in the subterranean gloom of the Cleft of Shadow. Seeking to build covert power away from Warchief Thrall's cautious diplomacy, the Shattered Hand marked Tazan for elimination to seize the valuable intelligence bound within his satchel.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tazan-s-satchel-cbc2325769378192d5ad/1-0000.mp3", duration = 40.1763265, start = 0},
  },
}
P.transport["item:tear-of-the-moons"] = {
  hash = "8c2258",
  fullHash = "8c2258",
  text = "Tear of the Moons. The Tear of the Moons is a mysterious, radiant crystal unearthed by dwarven excavators at Bael Modan in the southern Barrens. Though prized by the dwarven expedition, it carries a volatile and corruptive power that led directly to obsession, exile, and bloodshed. Discovered during the initial excavations of Bael Modan, the crystal was celebrated as the dig site's first major triumph. Its strange radiance captivated the miners, but none more intensely than Feegly. Claiming the relic gifted him profound strength, Feegly fell under its sway. Fearing the artifact's dark influence—and alarmed by Feegly's increasingly unstable behavior toward his comrades—expedition commander General Twinbraid declared the stone cursed. Twinbraid confiscated the relic, sealed it securely inside his personal strongbox within Bael'dun Keep, and cast Feegly out into the Barrens wasteland.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tear-of-the-moons-1678716e1d41883981a0/1-0000.mp3", duration = 50.0767347, start = 0},
  },
}
P.transport["item:tear-of-tilloa"] = {
  hash = "ac9692",
  fullHash = "ac9692",
  text = "Tear of Tilloa. The Tear of Tilloa is a delicate, pale blossom found in the shadows of Duskwood. Desired for its potent alchemical properties, it grows quietly in the overgrown grounds of the Mistmantle estate near Darkshire. Growing amidst the encroaching blighted woods outside Darkshire, the Tear of Tilloa takes root within the estate grounds of Stalvan Mistmantle. Though Duskwood's soil has turned hostile to wholesome vegetation, this small white flower persists among the shadowed plots. Its scarce growth and secluded location make it an object of interest for those seeking rare reagents not easily discovered in lawful markets.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tear-of-tilloa-680bd236a229e9824f3e/1-0000.mp3", duration = 36.2579592, start = 0},
  },
}
P.transport["item:techbot-s-memory-core"] = {
  hash = "7a1ad7",
  fullHash = "7a1ad7",
  text = "Techbot's Memory Core. Techbot's Memory Core is the polarized central repository of Tinkmaster Overspark's mechanical assistant, Techbot. Recovered from the malfunctioning automaton within the corrupted depths of Gnomeregan, it contains the critical data Overspark hopes to use to reverse the machine's reversed, negatronic behavior. Before the catastrophe that forced the gnomes into exile, Techbot served Tinkmaster Overspark and his fellow inventors as an indispensable assistant, packed with gizmos and encyclopedic data. When Gnomeregan fell, an errant electrical discharge jolted the automaton, inverting its positronic brain into a hostile negatronic state. Driven mad by the reversal, Techbot now wanders the tainted halls of the city attacking anyone in sight. Recovering its memory core is Overspark's only hope for analyzing the malfunction and restoring his prized creation to its senses.",
  ["1"] = {
    {file = "Audio/Transport/full_item_techbot-s-memory-core-0c4bcdfa97d0460b46a9/1-0000.mp3", duration = 52.5583673, start = 0},
  },
}
P.transport["item:telescopic-lens"] = {
  hash = "ddbf7a",
  fullHash = "ddbf7a",
  text = "Telescopic Lens. The Telescopic Lens is a precision optical component imported by Gazlowe to complete the construction of the Ratchet observatory. Intercepted along the coast by Southsea pirates, the fragile glass must be recovered from their encampment south of town before the port's grand telescope can scan the skies. Ratchet is known primarily as a port of ruthless commerce, but its chief engineer and overseer, Gazlowe, harbors grander mechanical ambitions. Prominently perched over the harbor, his observatory was built to house a powerful telescope to monitor maritime traffic and astronomical phenomena. While the larger lens arrived safely via an overland caravan from Durotar, the vital smaller lens was routed by sea—making it easy prey for the Southsea Freebooters who plague the merchant lanes off the Barrens coastline. When the Freebooters raided the transport ship, they hauled off anything of value, packing the delicate optics into a crate marked 'Fragile - Do Not Drop.' Unable to appreciate the fine craftsmanship or simply unsure how to pawn it, the buccaneers left the lens stashed amidst the clutter of their beachside camp south of Ratchet. Gazlowe relies on daring adventurers to brave the cutthroats, secure the unblemished glass, and finally bring his observation deck into focus.",
  ["1"] = {
    {file = "Audio/Transport/full_item_telescopic-lens-79632df9be1eb94eafb6/1-0000.mp3", duration = 74.7885714, start = 0},
  },
}
P.transport["item:teronis-journal"] = {
  hash = "112cc4",
  fullHash = "112cc4",
  text = "Teronis' Journal. Teronis' Journal is a field notebook recovered from the remains of a night elf scout in Ashenvale. Found alongside the slain investigator, it documents his search for a mysterious gem and serves as vital evidence for the Sentinels in Astranaar. A longtime friend of Raene Wolfrunner aiding the Sentinels, Teronis ventured into the wilds of Ashenvale seeking a gem for a rod he believed could slow the furbolg attacks on his people. His mission ended abruptly when he fell in the field, surrounded by aggressive creatures near the shore. Recovered from his personal effects, this journal remains in remarkably good condition despite the violence of his demise. It outlines his findings regarding a radiant gem that once formed part of that rod, providing Astranaar's defenders with the vital trail needed to see his unfinished mission through.",
  ["1"] = {
    {file = "Audio/Transport/full_item_teronis-journal-09626225db20cadf4f4e/1-0000.mp3", duration = 48.6661224, start = 0},
  },
}
P.transport["item:tharil-zun-s-head"] = {
  hash = "d0310a",
  fullHash = "d0310a",
  text = "Tharil'zun's Head. This grizzly trophy is the severed head of Tharil'zun, leader of the Blackrock orc Outrunners occupying Stonewatch. Marshal Marris demands it as irrefutable proof that the commander terrorizing the Redridge approaches has been slain. The Blackrock orcs entrenched within Stonewatch Keep have exerted ruthless pressure on Lakeshire, raiding farms and ambushing travelers along the roads. At the vanguard of these raiding parties were the Blackrock Outrunners, orchestrated by Tharil'zun. Because the garrison in Lakeshire cannot afford to act on rumors or partial victories, Marshal Marris demands concrete proof of the leader's demise. Bringing him Tharil'zun's severed head demonstrates that the coordinated ambushes from the keep have suffered a major blow.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tharil-zun-s-head-2007a27d81f5d7815bc8/1-0000.mp3", duration = 42.3444898, start = 0},
  },
}
P.transport["item:tharnariun-s-hope"] = {
  hash = "0a95c1",
  fullHash = "0a95c1",
  text = "Tharnariun's Hope. Tharnariun's Hope is a specialized trap crafted by the night elf Tharnariun Treetender in Darkshore. Designed to pacify diseased wildlife rather than harm it, the device projects a calming light intended to tame rabid thistle bears so they can be examined for a cure. As a mysterious affliction spreads through Darkshore, the local thistle bears have grown increasingly frenzied and violent. Rather than sanctioning a cull of the afflicted wildlife, the druid Tharnariun Treetender crafted this unique trap in the hope of studying and curing the illness. When laid upon the ground, Tharnariun's Hope emits a soothing radiance. Any rabid thistle bear that steps across the trap's light has its frenzy temporarily broken, rendering the beast docile enough to follow an adventurer back to Tharnariun's camp for treatment.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tharnariun-s-hope-0620cae1f77fef59a138/1-0000.mp3", duration = 47.124898, start = 0},
  },
}
P.transport["item:the-book-of-ur"] = {
  hash = "263c6f",
  fullHash = "263c6f",
  text = "The Book of Ur. The Book of Ur is a scholarly magical treatise penned by the late Dalaran wizard Ur, detailing his research into strange extradimensional entities. Left behind in Shadowfang Keep, it fell into the hands of Archmage Arugal before drawing the keen interest of Forsaken researchers in the Undercity. Before Dalaran fell to the Scourge, Ur was renowned among the Kirin Tor for his esoteric investigations into other planes of existence and otherworldly creatures. Despite his fascination with extraplanar magic, Ur was guided by caution and ethical restraint, choosing to record his discoveries rather than recklessly breach the veil between worlds. Tragically, when the Scourge assaulted the violet city, his magical prowess and moral hesitations were not enough to save him.",
  ["1"] = {
    {file = "Audio/Transport/full_item_the-book-of-ur-1bca964884142b2140a9/1-0000.mp3", duration = 44.564898, start = 0},
  },
}
P.transport["item:the-collector-s-schedule"] = {
  hash = "1793a0",
  fullHash = "1793a0",
  text = "The Collector's Schedule. The Collector's Schedule is a handwritten itinerary detailing dates and times for illicit gold shipments extracted from the mines of Elwynn Forest. Recovered from local gnolls, the document reveals that an elusive figure known only as 'The Collector' is coordinating the operation from near the Brackwell Pumpkin Patch. The schedule provides alarming evidence of organized activity right under the nose of Stormwind's garrison. Although the kingdom has not formally operated Elwynn's mines for months due to banditry and creature incursions, ore is still being systematically extracted and moved. The note lists specific days and times when someone titled 'The Collector' receives shipments, pointing toward a camp near the Brackwell Pumpkin Patch in eastern Elwynn Forest. When presented with the document, Marshal Dughan recognizes the name of the Collector, though the true mastermind paying for the stolen gold remains hidden.",
  ["1"] = {
    {file = "Audio/Transport/full_item_the-collector-s-schedule-3c398111e782961df488/1-0000.mp3", duration = 53.0285714, start = 0},
  },
}
P.transport["item:the-embalmer-s-heart"] = {
  hash = "1ca236",
  fullHash = "1ca236",
  text = "The Embalmer's Heart. The Embalmer's Heart is an unholy relic beating within the undead corpse of Eliza, buried deep in Duskwood. Once belonging to a grief-stricken alchemist known as the Embalmer, it was transplanted through dark magic to revive his deceased wife, becoming the primary anchor of his twisted power. According to the folklore of Darkshire, the Embalmer was once a gentle alchemist whose mind shattered upon the passing of his beloved wife, Eliza. Desperate to reclaim her from the grave, he turned to foul sorceries and cut out his own heart, placing it inside Eliza's lifeless chest. While the unholy transfusion successfully stirred her corpse back to unlife, the resurrection twisted her into a ravenous creature consumed by an insatiable hunger for living human flesh, forcing the horror-stricken alchemist to inter her once more within the earth.",
  ["1"] = {
    {file = "Audio/Transport/full_item_the-embalmer-s-heart-f79902dd1fe7e0b09fec/1-0000.mp3", duration = 47.2032653, start = 0},
  },
}
P.transport["item:the-general-s-response"] = {
  hash = "116a1d",
  fullHash = "116a1d",
  text = "The General's Response. The General's Response is an official military dispatch written by General Marcus Jonathan, commander of the Stormwind city guard. Intended for Magistrate Solomon in Lakeshire, the missive acknowledges Redridge's plea for aid while revealing that the capital cannot—or will not—immediately send royal reinforcements. When Magistrate Solomon reaches out to Stormwind City desperately seeking troops to fend off the gathering Blackrock orc clans and Gnoll warbands in Redridge, he sends his plea straight to the high command. General Marcus Jonathan's written response delivers cold comfort: while the plea has been forwarded upward to the throne, no soldiers are currently dispatched. Caught between protocol and politics, the General orders the letter delivered back to Lakeshire, leaving Solomon troubled and suspicious that a deeper sickness paralyzes the capital's leadership.",
  ["1"] = {
    {file = "Audio/Transport/full_item_the-general-s-response-5bae0b290c2b10cdfee1/1-0000.mp3", duration = 48.64, start = 0},
  },
}
P.transport["item:the-lich-s-spellbook"] = {
  hash = "cefe10",
  fullHash = "cefe10",
  text = "The Lich's Spellbook. The Lich's Spellbook is a volume of necromantic lore kept within a chest on the island in Brightwater Lake. Recovered for Bethor Iceshard in the Undercity, the tome reveals the true identity and immense magical power of a reclusive undead lich dwelling just north of the Forsaken capital. On an isolated island in Brightwater Lake stands an enigmatic lich surrounded by skeletal guardians. Though free-willed, this sorcerer distrusts the outside world, mistaking all other undead for thralls of the Scourge and ordering his minions to destroy any who approach. Bethor Iceshard, seeking gifted necromancers to bolster the Forsaken ranks beneath Queen Sylvanas Windrunner, tasked an emissary with infiltrating the island camp to retrieve the lich's spellbook. Through its study, Bethor hoped to discern the master's magical aptitude and uncover who he was before death took Lordaeron.",
  ["1"] = {
    {file = "Audio/Transport/full_item_the-lich-s-spellbook-e3141590ae7379f37574/1-0000.mp3", duration = 50.7297959, start = 0},
  },
}
P.transport["item:the-state-of-lakeshire"] = {
  hash = "edbb7f",
  fullHash = "edbb7f",
  text = "The State of Lakeshire. The State of Lakeshire is an urgent written report penned by Magistrate Solomon detailing the desperate military crisis gripping the town of Lakeshire. Intended directly for General Marcus Jonathan in Stormwind, the document pleads for the capital to deploy royal army reinforcements before the Redridge settlement falls. Penned by Magistrate Solomon amid relentless attacks on Redridge, 'The State of Lakeshire' outlines the dire circumstances threatening the township. Besieged by hostile Blackrock orcs and gnolls, Lakeshire lacks the local manpower to hold its borders indefinitely. Entrusted to trusted couriers traveling the road west to Elwynn Forest, this dispatch carries Solomon's formal request for the Stormwind Army to intervene and preserve the eastern reach of the kingdom. Upon delivery to General Marcus Jonathan at Stormwind's gates, the general acknowledges Solomon's noble standing and the gravity of the report. However, Jonathan cannot mobilize the army unilaterally. Military deployments require the explicit consent of the crown, forcing Lakeshire's urgent plea to wait upon high-level council with the young King and the regent Bolvar Fordragon.",
  ["1"] = {
    {file = "Audio/Transport/full_item_the-state-of-lakeshire-0645da79e6a99d7d7593/1-0000.mp3", duration = 65.4367347, start = 0},
  },
}
P.transport["item:theramore-medal"] = {
  hash = "ba5563",
  fullHash = "ba5563",
  text = "Theramore Medal. A Theramore Medal is a military insignia carried by the Alliance garrison stationed at Northwatch Hold. Emblazoned with the mark of Theramore, these tokens serve as identifying proof of service among the marines and officers defending the outpost along the Merchant Coast. Carried by marines, marksmen, commandos, and officers serving out of Northwatch Hold, these stamped medals signify military allegiance to Lady Jaina Proudmoore's realm of Theramore. To the human soldiers perched on the cliffs overlooking the Barrens, they represent legitimate service and sovereign authority in a hostile frontier. To outsiders, however, the medals are trophies of an overzealous foreign garrison that treats every approaching vessel along the coast as a mortal threat. Northwatch Hold's gun batteries pose a deadly hazard to maritime traffic navigating the Merchant Coast, frequently bombarding privateers and merchantmen alike. In response to lost vessels, Ratchet privateer Captain Thalo'thas Brightsun seeks these medals as proof that Northwatch's trigger-happy ranks have paid in blood for sinking his ships.",
  ["1"] = {
    {file = "Audio/Transport/full_item_theramore-medal-a679bd5baece08b275dd/1-0000.mp3", duration = 61.5967347, start = 0},
  },
}
P.transport["item:thick-bear-fur"] = {
  hash = "75f6a9",
  fullHash = "75f6a9",
  text = "Thick Bear Fur. Thick Bear Fur is a prized pelt gathered from the cold-hardened bears roaming the snowdrifts of Dun Morogh. Coveted for its heat retention, it is commonly used by traveling scouts and soldiers to craft insulation and warm bedding against the bitter alpine freeze. The bears prowling the ridges of Dun Morogh endure some of the harshest snowfields in the Eastern Kingdoms. Their thick, resilient coats provide vital protection from blizzards, making the pelt an invaluable resource for locals and travelers alike. Rather than being discarded as scrap, these heavy pelts are regularly harvested by hunters and used to line clothes, insulate drafty outposts, and pad cold sleeping rolls. When Pilot Bellowfiz began outfitting his siege tank, Jetsteam, at Steelgrill's Depot, he faced the harsh prospect of spending a full month in the field on a long mission for the Siege Brigade. Because cold iron offers little comfort in high-altitude snowbanks, he commissioned local scouts to gather thick bear furs from the snow fields south of the Grizzled Den to fashion warm bedding for his cabin quarters.",
  ["1"] = {
    {file = "Audio/Transport/full_item_thick-bear-fur-1b0fa6b4e149d26de013/1-0000.mp3", duration = 62.5110204, start = 0},
  },
}
P.transport["item:thistlenettle-s-badge"] = {
  hash = "5cb806",
  fullHash = "5cb806",
  text = "Thistlenettle's Badge. Thistlenettle's Badge is an official insignia of the dwarven Explorers' League, once carried proudly by Foreman Thistlenettle into the depths of the Deadmines. Following a catastrophic cave-in and an invasion of thieves, the token is all that remains to confirm the foreman's tragic fate to his surviving brother in Stormwind. Before the Defias Brotherhood locked down Moonbrook and the cavernous tunnels beneath it, dwarven prospectors affiliated with Ironforge's Explorers' League delved into the old gold mines of Westfall. Foreman Thistlenettle and his crew worked deep underground until a sudden tunnel collapse separated the team. While his brother Wilder managed to escape to Stormwind City, the foreman and several laborers remained trapped in the subterranean dark.",
  ["1"] = {
    {file = "Audio/Transport/full_item_thistlenettle-s-badge-78d9dbfb7f515a1430a4/1-0000.mp3", duration = 44.4081633, start = 0},
  },
}
P.transport["item:thresher-eye"] = {
  hash = "099f75",
  fullHash = "099f75",
  text = "Thresher Eye. Thresher Eyes are organic harvesting samples taken from the threshers prowling the coastal waters of Darkshore. They are sought by the eccentric gnome engineer Wizbang Cranktoggle to service his automated field devices known as Buzzboxes. Off the misty shores of Darkshore, aquatic predators known as Darkshore Threshers hunt along the surf and outer shallows. While dangerous to local fishermen and travelers, these beasts possess large ocular organs that have drawn the peculiar interest of Wizbang Cranktoggle. Stationed nearby and deeply fond of crawler wine, the gnomish engineer demands these eyes as essential components to repair Buzzbox 411, one of his far-speaking communication machines, positioned on the beach north of Auberdine. Wizbang never fully elaborates on how slimy sea-creature eyes repair delicate mechanical apparatuses, whether functioning as crude optical lenses, chemical agents, or esoteric biological gears. Regardless of the questionable engineering logic, feeding three of these harvested eyes into Buzzbox 411's maintenance hatch successfully restores the machine's comms link, allowing Wizbang to dispense rewards through static-choked transmissions.",
  ["1"] = {
    {file = "Audio/Transport/full_item_thresher-eye-748470af26581f353335/1-0000.mp3", duration = 65.5934694, start = 0},
  },
}
P.transport["item:thule-s-head"] = {
  hash = "cef04d",
  fullHash = "cef04d",
  text = "Thule's Head. Thule's Head is the grisly proof demanded by the Forsaken to confirm the demise of Thule Ravenclaw, commander of the Scourge forces on Fenris Isle. Bringing this macabre trophy back to High Executor Hadrec at the Sepulcher solidifies the Forsaken's hold on Silverpine Forest. Fenris Isle serves as the primary bastion of the Lich King's Scourge within Silverpine Forest. From deep inside Fenris Keep, the necromancer Thule Ravenclaw directs his legions of rot hides and undead minions, directly threatening Forsaken outposts like the Sepulcher. High Executor Hadrec requires absolute certainty that this dark commander has fallen, refusing to accept any testimony short of Thule's severed head. The violent release of dark magic upon Ravenclaw's death was felt across the woods, but his head remains the physical proof Hadrec requires to declare Fenris Isle broken.",
  ["1"] = {
    {file = "Audio/Transport/full_item_thule-s-head-b4b404d208f3751f683d/1-0000.mp3", duration = 50.4163265, start = 0},
  },
}
P.transport["item:thunder-lizard-blood"] = {
  hash = "f0148c",
  fullHash = "f0148c",
  text = "Thunder Lizard Blood. Thunder Lizard Blood is a vital fluid taken from the massive thunder lizards wandering the southern Barrens. It serves as martial proof of survival against some of Kalimdor's most crushing terrestrial beasts. Thunder lizards, known across the plains as Stormsnouts, Stormhides, and Thunderheads, are colossal beasts whose heavy strides shake the earth. Hunting them is an exercise in perilous footing, as their crushing weight easily flattens unwary stalkers. Bringing back their blood demonstrates not just hunting prowess, but the sheer endurance needed to survive a bout beneath their thundering feet.",
  ["1"] = {
    {file = "Audio/Transport/full_item_thunder-lizard-blood-9ce301e25bf3e8aeb77b/1-0000.mp3", duration = 32.4963265, start = 0},
  },
}
P.transport["item:thunder-lizard-horn"] = {
  hash = "3c9ba4",
  fullHash = "3c9ba4",
  text = "Thunder Lizard Horn. A thunder lizard horn is a hardy trophy harvested from the massive, lightning-attuned thunder lizards wandering the Barrens. Brewmaster Drohn in Ratchet seeks this unusual reagent to recreate a legendary beverage originally concocted by Chen Stormstout. Thunder lizards roam the arid flats of the Barrens, crackling with raw, localized lightning that arcs from their crested bodies. While hunters occasionally seek their thick hides, Brewmaster Drohn in Ratchet values their horns for a very different purpose. Handed down from a mentor who learned it from the wandering pandaren Brewmaster Chen Stormstout, the recipe for Stormstout ale calls for unusual, potent local ingredients. The horn of a thunder lizard provides the electrifying kick that gives the legendary draught its fiery, unforgettable bite.",
  ["1"] = {
    {file = "Audio/Transport/full_item_thunder-lizard-horn-1566e405a40dfb962c4c/1-0000.mp3", duration = 46.5763265, start = 0},
  },
}
P.transport["item:thunderhawk-saliva-gland"] = {
  hash = "c05370",
  fullHash = "c05370",
  text = "Thunderhawk Saliva Gland. A Thunderhawk Saliva Gland is a potent biological reagent harvested from the greater thunderhawks that soar over the Barrens. Brewmaster Drohn in Ratchet prizes it as an essential ingredient for recreating Chen Stormstout's fiery Trogg Ale. The arid savannas of the Barrens are home to thunderhawks—winged serpents renowned for harnessing the storm itself. Among their population, the older and more dangerous greater thunderhawks produce a saliva gland charged with raw, natural potency. While ordinary travelers steer clear of these deadly beasts, skilled brewmasters recognize the organ's rare properties as an extraordinary base for exotic concoctions. Following the legendary wandering brewmaster Chen Stormstout's travels through Kalimdor, Brewmaster Drohn settled outside Ratchet to master the pandaren's remarkable fermentation techniques. Drohn requires a fresh thunderhawk saliva gland alongside stormhide lightning glands and kodo liver to brew Trogg Ale, a fiery spirit with an unmistakable kick intended to fortify hardy adventurers.",
  ["1"] = {
    {file = "Audio/Transport/full_item_thunderhawk-saliva-gland-0639cd9b3e756b873faa/1-0000.mp3", duration = 59.6636735, start = 0},
  },
}
P.transport["item:thunderhawk-wings"] = {
  hash = "1c8016",
  fullHash = "1c8016",
  text = "Thunderhawk Wings. Thunderhawk Wings are feathered trophies taken from the fierce wind serpents soaring above the central and southern Barrens. Presented to Jorn Skyseer at Camp Taurajo, they serve as definitive proof of a hunter's strength, cunning, and endurance in tracking down one of the savanna's most majestic predators. Wind serpents, known to local hunters as thunderhawks, are formidable winged reptiles capable of striking swiftly from above. For the hunters stationed at Camp Taurajo, harvesting a pair of intact Thunderhawk Wings is far more than collecting biological scraps; it represents the culmination of grueling hunting trials in the Barrens. By tracking the aerial predators across the open plains and claiming their wings in combat, an initiate proves their readiness to walk the lifelong path of an accomplished hunter.",
  ["1"] = {
    {file = "Audio/Transport/full_item_thunderhawk-wings-8a6ecef1dfd3294750a1/1-0000.mp3", duration = 44.4865306, start = 0},
  },
}
P.transport["item:thunderhorn-cleansing-totem"] = {
  hash = "044c7d",
  fullHash = "044c7d",
  text = "Thunderhorn Cleansing Totem. The Thunderhorn Cleansing Totem is a consecrated ritual implement crafted by Mull Thunderhorn in Bloodhoof Village. It is imbued with ancestral magic to purify the corrupted waters of the Thunderhorn Water Well. Across the rolling plains of Mulgore, the lifeblood of the earth is being fouled by unseen corruption. The ancestral wells dug by the tauren tribes provide vital nourishment to the herds and hunting grounds, but foul agents have tainted the water. Entrusted by the elder Mull Thunderhorn, adventurers carry this prepared totem north of Bloodhoof Village to drive out the pollution settling over the Thunderhorn clan's sacred spring. Through ritual invocation, the totem calms the disturbed spirits of the water and cleanses the ancestral site.",
  ["1"] = {
    {file = "Audio/Transport/full_item_thunderhorn-cleansing-totem-64d429caddae20af4522/1-0000.mp3", duration = 42.8146939, start = 0},
  },
}
P.transport["item:thurman-s-remains"] = {
  hash = "654118",
  fullHash = "654118",
  text = "Thurman's Remains. Thurman's Remains are the corporeal remnants of Thurman Agamand, recovered from the family's ruined mills in northern Tirisfal Glades. Once a wealthy mill owner who persuaded his workers to stand against the Scourge, Thurman succumbed to the Plague and wanders his former estate as an undead thrall. Before the Third War, the Agamand family stood as the most prosperous landowners in Tirisfal Glades, operating extensive mills and employing dozens of local workers. When the Scourge swept across Lordaeron, Thurman Agamand and his kin fortified their estate rather than fleeing. Convinced that their wealth and fortified mills could weather the onslaught, they persuaded their loyal laborers to take up arms beside them. The defense failed utterly. The Agamands and their workers were slaughtered and transformed into mindless servants of the Lich King. Today, Coleman Farthing—a former employee risen as Forsaken—demands the destruction of his former masters, seeking Thurman's remains as proof that the foolish patriarch has paid for dooming his household.",
  ["1"] = {
    {file = "Audio/Transport/full_item_thurman-s-remains-8e1a3371488968718559/1-0000.mp3", duration = 60.7085714, start = 0},
  },
}
P.transport["item:thurman-s-sewing-kit"] = {
  hash = "49eac6",
  fullHash = "49eac6",
  text = "Thurman's Sewing Kit. Thurman's Sewing Kit is a small pouch containing the needles and shears required by an apprentice tailor in Stormwind City. Belonging to Thurman Schneider, it was conveniently left behind at his family's canal home in an attempt to dodge a long day of tedious tailoring work. The sewing kit holds the everyday tools of an apprentice tailor: needles, shears, and thread. It belongs to young Thurman Schneider, who studies tailoring at Larson Clothiers deep in Stormwind's Mage Quarter near the Mage Tower. Knowing her son cannot perform his duties without his equipment, his mother, Rema Schneider, asks sympathetic passersby along the Canals to carry it to the shop. Thurman's reaction upon receiving it reveals that leaving his shears and needles behind was no accident, but rather a failed plot to skip out on stitching garments in favor of leisure.",
  ["1"] = {
    {file = "Audio/Transport/full_item_thurman-s-sewing-kit-4e36797522ad5bdf7b98/1-0000.mp3", duration = 48.9012245, start = 0},
  },
}
P.transport["item:timberling-seed"] = {
  hash = "290efc",
  fullHash = "290efc",
  text = "Timberling Seed. Timberling Seeds are botanical kernels harvested from the agitated plant elementals inhabiting Teldrassil. Naturalists and druids study these seeds to understand why the forest's plant life has grown unusually aggressive. The timberlings of Teldrassil are nature elementals whose temperament reflects the balance of the World Tree. Recently, these creatures have turned hostile and angry, troubling the night elves who tend the boughs. Herbalists like Denalan at Lake Al'Ameth believe the issue lies rooted in the soil, collecting seeds from wild timberlings in hopes that nurturing them under controlled, purified conditions might sprout docile offspring.",
  ["1"] = {
    {file = "Audio/Transport/full_item_timberling-seed-cea631a9768ecd9102a8/1-0000.mp3", duration = 36.4146939, start = 0},
  },
}
P.transport["item:timberling-sprout"] = {
  hash = "4d749c",
  fullHash = "4d749c",
  text = "Timberling Sprout. Timberling Sprouts are young, nascent plant elementals taking root near the shores of Lake Al'Ameth in Teldrassil. Even in their earliest growth, these sprouts show signs of corruption, prompting night elf wardens to pull them before they mature into aggressive timberlings. Timberlings are plant spirits closely tied to the natural vitality of Teldrassil, but the seedlings sprouting along Lake Al'Ameth have worried the local night elves. Rather than emerging healthy and in harmony with the wild, they sprout already tainted and aggressive. Because these infant sprouts appear beyond cleansing or natural healing, caretakers at Lake Al'Ameth must gather and destroy them to prevent an uncontrolled spread of hostile timberlings across the fragile boughs of the newly planted World Tree.",
  ["1"] = {
    {file = "Audio/Transport/full_item_timberling-sprout-d2ac471bc76869279877/1-0000.mp3", duration = 44.1730612, start = 0},
  },
}
P.transport["item:tirisfal-pumpkin"] = {
  hash = "5c9c72",
  fullHash = "5c9c72",
  text = "Tirisfal Pumpkin. Tirisfal Pumpkins grow in the tilled plots of the Solliden Farmstead, tended by surviving living humans struggling to survive in the blighted glades. The Forsaken routinely raid these fields to supply the Royal Apothecary Society with organic matter for their ongoing chemical concoctions. Despite the corruption settling over Lordaeron, crops still somehow sprout in the fields west of Brill. At the Solliden Farmstead, living human farmers cling to their soil, cultivating massive orange squash under the watchful guard of the nearby Scarlet Crusade. For these mortals, the harvest is vital sustenance. For the nearby Forsaken of Brill, however, the pumpkins represent both a spiteful target of sabotage and a bounty of raw organic reagents needed by Apothecary Johaan. Deathguard Simmer directs young Forsaken out into the contested fields to pilfer the pumpkins directly from beneath the farmers' noses. Rather than feeding the dead, these vegetables find their way into the boiling cauldrons of the Royal Apothecary Society. The apothecaries frequently test how natural flora reacts to their plagues and experimental mixtures, turning Lordaeron's remaining agriculture against the living.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tirisfal-pumpkin-9a3c724c4498f8b93817/1-0000.mp3", duration = 68.3363265, start = 0},
  },
}
P.transport["item:token-of-thievery"] = {
  hash = "b5f389",
  fullHash = "b5f389",
  text = "Token of Thievery. The Token of Thievery is a proof of skill recovered by novice rogues during their training in the Redridge Mountains. Placed inside a locked footlocker at the orc-threatened Alther's Mill, it serves as the final test set by the seasoned thief Lucius to demonstrate mastery over lockpicking. Not every scoundrel possesses an innate knack for working tumblers and slipping catches unnoticed. In Lakeshire, the roguish instructor Lucius puts promising operatives through their paces by testing their wits and tools in the field. Rather than keeping his trials confined to quiet alleys, Lucius stashes the Token of Thievery inside a sturdy lockbox hidden among the ruins of Alther's Mill, directly in the path of encroaching Blackrock orcs. Retrieving the token proves that an initiate can pick a secure mechanism under the pressure of mortal danger, earning them their formal Certificate of Thievery.",
  ["1"] = {
    {file = "Audio/Transport/full_item_token-of-thievery-67fd7eaeab9e570cbe97/1-0000.mp3", duration = 50.7036735, start = 0},
  },
}
P.transport["item:tome-of-the-cabal-quest-item"] = {
  hash = "9eeb24",
  fullHash = "9eeb24",
  text = "Tome of the Cabal (quest item). The Tome of the Cabal is a grimoire entrusted to warlocks by Strahad Farsan on the bluffs overlooking Ratchet. It holds the perilous incantations necessary to pull a ravenous felhunter across the Twisting Nether and bind it to the summoner's will. Felhunters are vicious, mana-devouring beasts native to the chaotic expanse of the Twisting Nether. Subduing one is a rite of passage for seasoned warlocks, and the rituals required to tear open a pathway for such a beast are contained within the pages of the Tome of the Cabal. Strahad Farsan, an experienced conjurer operating out of Ratchet, provides the tome only after an aspirant has proven capable of gathering the rare and hazardous components needed to fuel its magics. Summoning from the tome is far from a solo endeavor. Strahad establishes a primary summoning circle within his sanctum, while his acolytes employ rods of channeling to construct a greater protective boundary. The warlock must then recite the tome's exact incantations to drag the felhunter into our world, immediately battling and subduing the ravenous demon to cement their dominion over it.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tome-of-the-cabal-quest-item-62376cde608cac1d3850/1-0000.mp3", duration = 64.3918367, start = 0},
  },
}
P.transport["item:top-of-gelkak-s-key"] = {
  hash = "0b94d5",
  fullHash = "0b94d5",
  text = "Top of Gelkak's Key. The Top of Gelkak's Key is one of three shattered fragments of a mechanical key belonging to the shipwrecked gnome Gelkak Gyromast. After his vessel was lost off the coast of Darkshore, this jagged brass section was snatched up by a giant foreststrider roaming the nearby woods. When Gelkak Gyromast's ship was attacked and sunk by ravenous threshadons off the coast of Darkshore, the gnome washed ashore clutching the winding key meant for his mechanical first mate. The impact against the coastal rocks broke the instrument into three pieces. Before the dizzy pirate could gather his wits, the indigenous beasts scavenged the wreckage, with a giant foreststrider making off with this ornate upper portion into the misty forest.",
  ["1"] = {
    {file = "Audio/Transport/full_item_top-of-gelkak-s-key-bc50e7edfb05d1d0237b/1-0000.mp3", duration = 41.8481633, start = 0},
  },
}
P.transport["item:torch-of-the-dormant-flame"] = {
  hash = "1f21bb",
  fullHash = "1f21bb",
  text = "Torch of the Dormant Flame. The Torch of the Dormant Flame is a ritual implement carried by young Horde shaman during their communion with fire in Durotar. Awaiting the defeat of a flame manifestation atop the mountain, it serves as a vessel meant to capture primal elemental fire upon the Shrine of the Dormant Flame. A shaman seeking the favor of fire is entrusted with the unlit Torch of the Dormant Flame before ascending the peaks above Durotar. After drinking a spirit-revealing fire sapta, the shaman sees and challenges a Minor Manifestation of Fire upon the mountaintop. Slaying this elemental spirit yields a glowing ember, which is deposited into the weathered brazier of the Shrine of the Dormant Flame. Touching the head of the dormant torch to the resulting white-hot conflagration awakens the wood, transforming it into a burning emblem of elemental mastery.",
  ["1"] = {
    {file = "Audio/Transport/full_item_torch-of-the-dormant-flame-4f354cb16e3eee781a62/1-0000.mp3", duration = 48.0130612, start = 0},
  },
}
P.transport["item:torn-fin-eye"] = {
  hash = "b166c0",
  fullHash = "b166c0",
  text = "Torn Fin Eye. Torn Fin Eyes are ocular organs harvested from the Torn Fin murlocs prowling the shores of Hillsbrad Foothills. They serve as a crucial reactive ingredient for the Royal Apothecary Society's grim alchemical research into new plagues. The Royal Apothecary Society rarely lets any vile biological component go to waste in their quest to develop the Forsaken's New Plague. Torn Fin Eyes, harvested from the salt-crusted murlocs prowling the Western Strand of Hillsbrad Foothills, possess specialized organic properties needed to activate volatile alchemical compounds. When combined with Daggerspine naga scales, restorative troll elixirs, and gnoll-derived sludge, the optic tissues help stabilize and trigger toxic mixtures formulated to sow death across enemy territories.",
  ["1"] = {
    {file = "Audio/Transport/full_item_torn-fin-eye-cfb02a36c44612a66f70/1-0000.mp3", duration = 44.4865306, start = 0},
  },
}
P.transport["item:torn-murloc-fin"] = {
  hash = "731ca3",
  fullHash = "731ca3",
  text = "Torn Murloc Fin. Torn Murloc Fins serve as proof of work for the Stormwind Army's standing bounty on hostile amphibians in eastern Elwynn Forest. Harvested from foragers and lurkers along the riverbanks, they demonstrate that local waterways are being systematically cleared. As the murloc population along eastern Elwynn's streams and lakes surged, the Stormwind Army authorized a direct bounty to cull their numbers. Guard Thomas, stationed at the bridge spanning the eastern river, collects these severed fins to verify kills. With Stormwind's military stretched thin defending against internal unrest and regional threats, local authorities rely heavily on traveling adventurers to bring in physical proof of cleared encampments.",
  ["1"] = {
    {file = "Audio/Transport/full_item_torn-murloc-fin-51bd99dede9f0faa9a0c/1-0000.mp3", duration = 41.2995918, start = 0},
  },
}
P.transport["item:totem-of-hawkwind"] = {
  hash = "eef516",
  fullHash = "eef516",
  text = "Totem of Hawkwind. The Totem of Hawkwind is a carved token carried by young tauren departing Camp Narache. Presented to Baine Bloodhoof in Bloodhoof Village, it serves as proof that the bearer has completed their initial trials and is prepared to undergo the remainder of the Rites of the Earthmother. Carved by the hand of Chief Hawkwind atop the Red Cloud Mesa, this wooden totem acts as an introduction and proof of passage for youth coming of age. In tauren tradition, formal writ is rarely used; instead, meaningful symbols and familiar tribal craft carry a leader's intent. When an aspiring youth completes their preliminary trials at Camp Narache, Hawkwind crafts this icon to send them forward along the road into the wider expanse of Mulgore. The distinctive carvings identify the bearer to Baine Bloodhoof, signaling that they possess the spirit and strength required to face the next trials and seek the eventual blessing of Thunder Bluff.",
  ["1"] = {
    {file = "Audio/Transport/full_item_totem-of-hawkwind-42d3e61e4d5acf998659/1-0000.mp3", duration = 53.76, start = 0},
  },
}
P.transport["item:tough-wolf-meat"] = {
  hash = "f3f339",
  fullHash = "f3f339",
  text = "Tough Wolf Meat. Tough Wolf Meat is raw game meat harvested from the predatory timber wolves and young wolves prowling Northshire Valley and Coldridge Valley. Though coarse and stringy, it serves as a staple ration for hungry locals like Eagan Peltskinner in Elwynn Forest and dwarven outfitters in Dun Morogh. The wolves roaming the outskirts of Northshire Valley and Dun Morogh pose a constant menace to local settlements, but they also offer a gritty source of sustenance. Tough Wolf Meat is notoriously sinewy and chewy compared to prime game, yet resource-strapped frontiersmen prize it all the same. Outside Northshire Abbey, Eagan Peltskinner despises the beasts for their viciousness but happily cooks their meat into rustic steaks, eagerly trading basic supplies and gear to anyone willing to cull the packs.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tough-wolf-meat-dbe55a0e08f3d051c848/1-0000.mp3", duration = 46.08, start = 0},
  },
}
P.transport["item:tourmaline-phial"] = {
  hash = "76cfd0",
  fullHash = "76cfd0",
  text = "Tourmaline Phial. The Tourmaline Phial is a specialized gem-crafted vessel given to travelers in Teldrassil by Corithras Moonrage. It is used to draw blessed waters from the moonwell beside the Pools of Arlithrien as part of ongoing rituals to monitor and soothe the boughs of the World Tree. Corithras Moonrage provides the Tourmaline Phial to aid in the rituals surrounding the World Tree. The druids in Dolanaar use such dedicated gemstone vials to safely collect pure moonwell waters from across Teldrassil. This particular phial is designated for the moonwell on the shores of the Pools of Arlithrien, southeast of the road leading to Darnassus, an area increasingly beleaguered by hostile Gnarlpine furbolgs.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tourmaline-phial-fdf39d2dc9be7f926137/1-0000.mp3", duration = 40.3330612, start = 0},
  },
}
P.transport["item:toxic-fogger"] = {
  hash = "698f0d",
  fullHash = "698f0d",
  text = "Toxic Fogger. The Toxic Fogger is a specialized dispersal device filled with lethal poison, concocted by the Forsaken Royal Apothecary Society. It is designed to contaminate the Venture Company's air transit operations in the Stonetalon Mountains. Carrying a toxin brewed by Apothecary Lydon in Tarren Mill and dispatched by Apothecary Zamah in Thunder Bluff, the Toxic Fogger serves as biological sabotage aimed directly at the Venture Company's strip-mining efforts. Suspecting that the goblins rely on courier flying machines to shuttle messages and light cargo between Stonetalon and their headquarters, Zamah sends the fogger to release its poison right where machines land and refuel. Rather than engaging in prolonged skirmishes with endless mercenary crews, the Forsaken method strikes at the logistical spine of the operation, ensuring that the poison travels directly back to corporate leadership.",
  ["1"] = {
    {file = "Audio/Transport/full_item_toxic-fogger-d4ab25735462fd169701/1-0000.mp3", duration = 51.2783673, start = 0},
  },
}
P.transport["item:treshala-s-pendant"] = {
  hash = "cbf8b3",
  fullHash = "cbf8b3",
  text = "Treshala's Pendant. Treshala's Pendant is an intimate heirloom of bonding belonging to Treshala Fallowbrook, a night elf dwelling in Darnassus. Carried into southern Kalimdor by her husband, Heralath, it was ripped away by the quilboar in Razorfen Kraul as he lay dying. The pendant serves as a symbol of deep marital devotion between Treshala and Heralath Fallowbrook. Before embarking on perilous journeys away from Teldrassil, Heralath carried the bonding necklace close as a reminder of his home and his beloved.",
  ["1"] = {
    {file = "Audio/Transport/full_item_treshala-s-pendant-27efb3e79edb3819b8e8/1-0000.mp3", duration = 26.9844898, start = 0},
  },
}
P.transport["item:trogg-stone-tooth"] = {
  hash = "a20cfe",
  fullHash = "a20cfe",
  text = "Trogg Stone Tooth. A Trogg Stone Tooth is a rugged, mineralized tooth taken from the Stonesplinter troggs infesting the hills of Loch Modan. Dwarven defenders use these teeth as physical proof that wandering adventurers are thinning the trogg numbers around the southern frontier. With the Ironforge Reserve committed to the Alliance Front, local dwarven garrisons are stretched thin across Khaz Modan. At the southern gate guard tower in Loch Modan, Captain Rugelfuss cannot spare his soldiers from their posts to mount offensive patrols against the lurking Stonesplinter troggs. Instead, he issues a standing call for volunteers to hunt the creatures in the nearby hills. To confirm that the menace is being driven back, Rugelfuss demands Trogg Stone Teeth as crude, undeniable evidence of every beast slain.",
  ["1"] = {
    {file = "Audio/Transport/full_item_trogg-stone-tooth-95b349522109aaa65722/1-0000.mp3", duration = 45.1395918, start = 0},
  },
}
P.transport["item:troll-charm"] = {
  hash = "175272",
  fullHash = "175272",
  text = "Troll Charm. Troll Charms are sacred spiritual amulets carried by the Darkspear trolls. A collection of them was recently looted by hostile Thistlefur furbolgs after an ambush along the northern reaches of Ashenvale. To the trolls of the Horde, spiritual charms are far more than mere ornamentation. As the scout Mitsuwa explains, a troll without their charm is considered as diminished as an orc without battle scars. When a party of Darkspear kin journeyed toward Zoram'gar Outpost through the dense canopy of Ashenvale, they were ambushed and slaughtered by the corrupted Thistlefur furbolgs. While their spirits were commended to the afterlife, the furbolgs looted the dead and carried off their sacred charms as trophies, stashing them in chests deep within Thistlefur Hold.",
  ["1"] = {
    {file = "Audio/Transport/full_item_troll-charm-731c0973512627102f73/1-0000.mp3", duration = 43.5983673, start = 0},
  },
}
P.transport["item:trophy-swoop-quill"] = {
  hash = "5762db",
  fullHash = "5762db",
  text = "Trophy Swoop Quill. A Trophy Swoop Quill is a prized hunting token plucked from the large birds of prey that circle over the plains of Mulgore. Among the tauren, gathering these feathers demonstrates keen eyesight, patience, and hunting skill. Swoops are cunning avian predators indigenous to Mulgore, known for riding high thermals and remaining difficult to track across the grasslands. For young tauren hunters and travelers striving to prove themselves in Bloodhoof Village, claiming a trophy quill from these birds is a traditional rite of cleverness and determination. Presenting these quills to elders such as Harken Windtotem honors the hunter's clan and signifies that one possesses the sharp senses needed to thrive upon the plains.",
  ["1"] = {
    {file = "Audio/Transport/full_item_trophy-swoop-quill-42c8a8cc05cf54e5daef/1-0000.mp3", duration = 40.8816327, start = 0},
  },
}
P.transport["item:twilight-pendant"] = {
  hash = "738c73",
  fullHash = "738c73",
  text = "Twilight Pendant. A Twilight Pendant is an insignia worn by cultists of the Twilight's Hammer deep within Blackfathom Deeps. To the Argent Dawn, these dark talismans serve as definitive proof of the cult's subversive operations on the coast of Ashenvale. Within the drowned ruins of Blackfathom Deeps, members of the Twilight's Hammer gather alongside the naga to conduct foul rites in veneration of the chaotic Old Gods. Cultists—ranging from shadowmages and aquamancers to reavers and loreseekers—wear these pendants as emblems of devotion to their shadowy patrons. Because the cult operates in secrecy beneath the former night elf temple, retrieving these ornaments is one of the few ways outside observers can gauge the cult's numbers and thwart their machinations. Argent Guard Manados in Darnassus actively seeks these pendants as evidence of a successful purge against the encroaching darkness. Blackfathom Deeps once housed a pristine moonwell, and its desecration by malevolent void-worshipers poses a severe threat to Kalimdor. Gathering the pendants confirms that the cultists' foothold in Ashenvale is being dismantled before their dark patrons can unleash greater terror.",
  ["1"] = {
    {file = "Audio/Transport/full_item_twilight-pendant-74b2f854d423a2474efe/1-0000.mp3", duration = 66.2204082, start = 0},
  },
}
P.transport["item:twilight-whisker"] = {
  hash = "854131",
  fullHash = "854131",
  text = "Twilight Whisker. Twilight Whiskers are harvested from twilight runners prowling the northern heights of the Stonetalon Mountains. In the settlement of Malaka'jin, Witch Doctor Jin'Zil covets them as an ingredient in a cruel, venomous concoction he mockingly names forest magic. The high crags near Stonetalon Peak are home to twilight runners, predatory felines attuned to the deep shadows of the ancient groves. While hunters prize their pelts, Witch Doctor Jin'Zil of Malaka'jin seeks their stiff whiskers for a far darker purpose. Seeking vengeance upon captured night elves who once defended these woodlands, Jin'Zil gathers components of the forest—resinous sap, countless eyes, fey dragon scales, and twilight whiskers—to brew a lethal draught intended to mock and poison his captives.",
  ["1"] = {
    {file = "Audio/Transport/full_item_twilight-whisker-f216f830c7e404bc3692/1-0000.mp3", duration = 45.4530612, start = 0},
  },
}
P.transport["item:twitching-antenna"] = {
  hash = "cb685c",
  fullHash = "cb685c",
  text = "Twitching Antenna. Twitching Antennae are severed sensory appendages gathered from the invasive silithid swarming the southern Barrens. Sought by the tauren warrior Ruga Ragetotem at Camp Taurajo, they serve as proof of a young warrior's swiftness and combat prowess before their lingering nerve twitches fade. Carved directly from the heads of silithid grubs, swarmers, and harvesters, these antennae retain residual nervous reflex even after detachment. Their violent spasming does not last long once severed from the insectoid host. Because of this brief window of vitality, bringing back still-twitching antennae serves as a strict test of speed, requiring an aspirant to hunt the beasts in the southern wastes and dash back across the scrublands before the twitching goes still. Beyond serving as a rite of passage, these antennae are troubling harbingers. Silithid are not native to the Barrens, and their recent burrowing mounds at the Field of Giants deeply unsettle the hunters of Camp Taurajo. Ruga Ragetotem demands these specimens to study the new threat while simultaneously steeling Horde warriors against an encroaching, alien menace.",
  ["1"] = {
    {file = "Audio/Transport/full_item_twitching-antenna-a7922c448082398a9088/1-0000.mp3", duration = 64.2873469, start = 0},
  },
}
P.transport["item:ukor-s-burden"] = {
  hash = "585d87",
  fullHash = "585d87",
  text = "Ukor's Burden. Ukor's Burden is a heavy bundle of rations hauled out of Razor Hill by a well-meaning orc peon. Intended to feed hungry novices in the Valley of Trials, the unwanted provisions must be hauled back before the wilderness scorpids and raptors pick up the scent. Orc peons rarely act on their own initiative, which makes Ukor's errand unusual. Packing a heavy load of provisions from the inn in Razor Hill, he braved the red dust and aggressive wildlife of Durotar to aid young recruits training in the Valley of Trials. To his dismay, the overseers and instructors turned him away—believing that hardship and lean bellies forge true warriors. Trapped outside the canyon's mouth and terrified of the beasts stalking the trail back, Ukor entrusted the sack to passing travelers to return it to Innkeeper Grosk.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ukor-s-burden-796dfb1302e6f668e042/1-0000.mp3", duration = 45.1395918, start = 0},
  },
}
P.transport["item:uncloven-satyr-hoof"] = {
  hash = "5eede8",
  fullHash = "5eede8",
  text = "Uncloven Satyr Hoof. An Uncloven Satyr Hoof is a swollen, solid hoof harvested from the satyrs lurking in Ashenvale. Saturated with corrupt magical energy leeched from the ancient forest, these grim trophies serve as potent crafting components for Darkspear troll armorers. Satyrs haunt the corrupted groves of northeastern Ashenvale, feeding directly upon the ancient forest's magical purity. As they gorge themselves on this essence, the corruption distorts their demonic physiology, causing their hooves to swell and lose their natural cleft. These solid, uncloven hooves become dense reservoirs of absorbed energy, holding volatile power that can be harvested by skilled shamans and leatherworkers. Down on the coast of Durotar in Sen'jin Village, the troll armorer Ula'elek knows how to turn demonic corruption into strength for Horde champions. By taking the hooves of these sated satyrs, he leeches out the trapped woodland magic, channeling the stolen power into the forging of brutal gauntlets designed to protect young warriors facing the rigors of Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_item_uncloven-satyr-hoof-a8cb6ee860bbd8bf9872/1-0000.mp3", duration = 60.6302041, start = 0},
  },
}
P.transport["item:underbelly-whelp-scale"] = {
  hash = "80981a",
  fullHash = "80981a",
  text = "Underbelly Whelp Scale. Underbelly Whelp Scales are harvested from the younger broods of the Black Dragonflight found roaming the Redridge Mountains. Valued by craftsmen for their resilient yet pliable texture, they serve as precious barter material among local artisans. Dragonhide and scales possess legendary durability, but full-grown black dragons are lethal beyond measure to ordinary folk. Instead, resourceful frontiersmen and craftsmen look toward the skies south of Lake Everstill, where young black dragon whelps nest among the crags. While the dorsal plating of a whelp is brittle or coarse, the scales running along its softer underbelly strike an ideal balance between flexibility and protection. As a result, these underbelly scales command substantial value in regional trade, functioning as high-end crafting material and dependable collateral for debts. In Lakeshire, the magistrate's craftsmen must often rely on barter when coin is scarce or trade routes are strained. Verner Osgood, the local blacksmith, found himself heavily indebted to the blacksmith Argus over a shipment of shoes brought in from Goldshire. Knowing Argus's fondness for rare trade goods, Verner relies on passing adventurers to harvest underbelly whelp scales to satisfy the debt and keep his workshop in good standing.",
  ["1"] = {
    {file = "Audio/Transport/full_item_underbelly-whelp-scale-9449bbd38f581a981f6f/1-0000.mp3", duration = 73.7436735, start = 0},
  },
}
P.transport["item:unidentified-ore"] = {
  hash = "dbecaf",
  fullHash = "dbecaf",
  text = "Unidentified Ore. Unidentified Ore is a peculiar mineral sample unearthed by Venture Company operations in the crags of the Stonetalon Mountains. Recovered by the disgruntled laborer Piznik, it was smuggled away to be analyzed by goblin tinker Ziz Fizziks and forwarded to engineers in Undermine. The Venture Company's relentless clear-cutting and strip mining in Windshear Crag tore deep into the crags of the Stonetalon Mountains, exposing unusual mineral strata. The site's new boss, Gerenzo Wrenchwhistle, ordered large amounts of a strange gold-green ore mined, and the demoted goblin worker Piznik, still loyal to his fired former boss Ziz Fizziks, secured a sample of it while plotting his exit from the outfit. Handed off to a traveler bound for the western ridge of the crag, the sample made its way into the hands of Ziz Fizziks, who planned to ship the prize back to Undermine for study, keeping a pocket-sized cut for personal profit.",
  ["1"] = {
    {file = "Audio/Transport/full_item_unidentified-ore-91cbddffea959e27439e/1-0000.mp3", duration = 53.9428571, start = 0},
  },
}
P.transport["item:unrefined-ore-sample"] = {
  hash = "d87e99",
  fullHash = "d87e99",
  text = "Unrefined Ore Sample. An Unrefined Ore Sample is a piece of unusual raw mineral mined by the Gravelsnout kobolds dwelling in Thousand Needles. Camp Taurajo's master weaponsmith, Tatternack Steelforge, seeks it out to evaluate whether the metal can be forged into superior weapons for Warchief Thrall's armies. South of the Barrens, within the canyon walls of Thousand Needles, a clan of kobolds known as the Gravelsnout burrow endlessly through stone and earth. Travelers returning north through the Barrens brought word of a curious mineral discovered among the slain vermin—an unrefined ore unlike the standard veins found across Kalimdor. While the travelers refused to surrender their prize to the Horde, the subterranean diggers and surveyors of Thousand Needles carry raw chunks of the stone straight from their excavations. In Camp Taurajo, the weaponsmith Tatternack Steelforge labours directly under orders from Warchief Thrall to develop stronger armaments for the Horde. Tatternack was infuriated by travelers who hoarded knowledge of the deposit, deeming it an insult to the Horde's war effort. By securing a raw sample of the mineral, Steelforge aims to test its tensile strength and temper, hoping to smelt it down and fashion a prototype blade worthy of Orgrimmar's approval.",
  ["1"] = {
    {file = "Audio/Transport/full_item_unrefined-ore-sample-efd9a58b47cbf050f04c/1-0000.mp3", duration = 70.0081633, start = 0},
  },
}
P.transport["item:ur-s-treatise-on-shadow-magic"] = {
  hash = "0db48a",
  fullHash = "0db48a",
  text = "Ur's Treatise on Shadow Magic. Ur's Treatise on Shadow Magic is a perilous arcane tome penned by the renowned wizard Ur of Dalaran. Originally safeguarded by the mages of Stormwind, the enchanted book was stolen by the renegade sorcerer Morganth and hidden away in the Tower of Ilgalar. Penned by the Dalaran scholar Ur, this treatise delves into the subtle and corruptive nature of shadow magic. Because delving into such arts invites doom and ruin for the unwary, the mages of the Wizard's Sanctum in Stormwind placed protective seals upon the volume to bar anyone from reading its contents. However, when the sorcerer Morganth surrendered to dark arts and was exiled from the city's magical circle, he made off with the tome, carrying it eastward into the Redridge Mountains to his stronghold at the Tower of Ilgalar.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ur-s-treatise-on-shadow-magic-e49a88a44f1a7e67ce78/1-0000.mp3", duration = 46.5763265, start = 0},
  },
}
P.transport["item:urgent-message"] = {
  hash = "e6c915",
  fullHash = "e6c915",
  text = "Urgent Message. The Urgent Message is a sealed dispatch penned by Brave Moonhorn warning Freewind Post of escalating centaur violence across Thousand Needles. Carried by travelers descending into the canyon, the letter alerts the tauren garrison that their supply lines and scouting parties are under immediate threat. Penned by Brave Moonhorn near the great lift that descends from the Barrens into Thousand Needles, the Urgent Message represents the first line of defense for travelers crossing the border. Moonhorn monitors the jagged canyons below, where aggressive centaur tribes have renewed their relentless raids against Horde travel. Addressed to Cliffwatcher Longhorn atop Freewind Post, the missive sounds the alarm about emboldened attackers striking dangerously close to crucial roadways, urging the local garrison to brace for sustained conflict and guard against secondary threats like the unpredictable Grimtotem clan.",
  ["1"] = {
    {file = "Audio/Transport/full_item_urgent-message-8e096e2ae96002658c71/1-0000.mp3", duration = 49.92, start = 0},
  },
}
P.transport["item:valdred-s-hands"] = {
  hash = "bd97ff",
  fullHash = "bd97ff",
  text = "Valdred's Hands. Valdred's Hands are the severed limbs of Valdred Moray, claimed after his death in southern Silverpine Forest. They are sought by Raleigh Andrean in the Undercity as a morbid trophy and proof of vengeance for the murder of his wife. Before the plague consumed Lordaeron, Valdred Moray and Raleigh Andrean were close friends. That bond was shattered when Valdred murdered Raleigh's wife, Deliah. Though Raleigh succumbed to death and arose as one of the Forsaken—professing an inability to genuinely grieve—the lingering hunger for retribution never left him. When Valdred attempted to flee southward past the Greymane Wall into Gilneas, Raleigh dispatched an emissary to end his former friend's flight, demanding his severed hands as definitive proof that the deed was done.",
  ["1"] = {
    {file = "Audio/Transport/full_item_valdred-s-hands-4840e78d3c5103520968/1-0000.mp3", duration = 43.8595918, start = 0},
  },
}
P.transport["item:velinde-s-journal"] = {
  hash = "42d897",
  fullHash = "42d897",
  text = "Velinde's Journal. Velinde's Journal is a personal record kept by the Night Elf priestess Velinde Starsong, stored away in the Sentinel bunkhouse in Darnassus. It holds crucial accounts of her duties and the mysterious circumstances surrounding her departure from the city. When Priestess Velinde Starsong departed Darnassus, her personal belongings were locked away in a footlocker within the Sentinels' bunkhouse in the Tradesmen's Terrace. Among her stored effects rests her personal journal, documenting her responsibilities and duties before she slipped away. While the Sentinels hold Velinde in high regard and assumed she simply had private matters to attend to, the contents of her journal suggest her unexplained absence is far more troubling than first believed.",
  ["1"] = {
    {file = "Audio/Transport/full_item_velinde-s-journal-08da0229439731c4b648/1-0000.mp3", duration = 40.4897959, start = 0},
  },
}
P.transport["item:velinde-s-key"] = {
  hash = "c33d15",
  fullHash = "c33d15",
  text = "Velinde's Key. Velinde's Key is a small key entrusted to adventurers by Thyn'tel Bladeweaver in Darnassus. It unlocks a personal storage locker within the Sentinel bunkhouse, containing the writings left behind by Priestess Velinde Starsong before her mysterious disappearance. Held in Darnassus by Thyn'tel Bladeweaver, this simple key secures the personal belongings of Priestess Velinde Starsong. Stored safely inside a footlocker in the Sentinel bunkhouse above the Tradesmen's Terrace, Velinde's worldly possessions were put aside after she departed night elf lands without warning. Bladeweaver only surrenders the key to those who present legitimate evidence—such as revelations uncovered in the Tome of Mel'Thandris—proving their genuine interest in discovering the priestess's fate.",
  ["1"] = {
    {file = "Audio/Transport/full_item_velinde-s-key-a92dff7e4a47cc264b8f/1-0000.mp3", duration = 43.3632653, start = 0},
  },
}
P.transport["item:venomtail-antidote"] = {
  hash = "801cb9",
  fullHash = "801cb9",
  text = "Venomtail Antidote. Venomtail Antidote is a specialized concoction brewed to neutralize the lethal toxins of Durotar's venomtail scorpids. Prepared by Kor'ghan in Orgrimmar, it serves as an urgent remedy for Rhinag, an afflicted troll scout stranded near the northwestern border of Durotar. The arid expanse of Durotar crawls with dangerous wildlife, none more hazardous to careless wanderers than the local scorpids. A deep sting from a venomtail delivers a virulent poison capable of killing an adult warrior within an hour. When the troll Rhinag found himself envenomed far from aid near the northwestern border, his only survival lay in obtaining a specialized remedy from Kor'ghan, an apothecary sequestered deep within Orgrimmar's subterranean Cleft of Shadow. Securing the antidote requires navigating the underbelly of Orgrimmar to locate Kor'ghan. Knowledgeable in desert toxins and harsh remedies, Kor'ghan prepares the vial to purge the venom before it turns fatal. Once delivered, the draught halts the venom's progression, sparing Rhinag a humiliating death in the wilderness—though Kor'ghan demands further trials and hunts from the scout to atone for his carelessness.",
  ["1"] = {
    {file = "Audio/Transport/full_item_venomtail-antidote-cf79ee748654fb25ce9d/1-0000.mp3", duration = 68.075102, start = 0},
  },
}
P.transport["item:venomtail-poison-sac"] = {
  hash = "9a37a5",
  fullHash = "9a37a5",
  text = "Venomtail Poison Sac. A Venomtail Poison Sac is a biological organ harvested from scorpids native to the arid expanses of Durotar. While containing a virulent toxin capable of incapacitating an unwary hunter, it is also the vital ingredient required to brew an effective counter-agent. The scorpids prowling the red rocks of Durotar—chiefly the Venomtail Scorpid, alongside mutated varieties like the Corrupted Scorpid and the notorious Death Flayer—produce a fast-acting, debilitating venom. Stored within specialized tail sacs, this poison can quickly overwhelm even seasoned warriors if left untreated. Ironically, the very sacs that deliver this lethal sting contain the primary compounds necessary to synthesize an antidote. When the hunter Rhinag fell victim to a sting outside Orgrimmar, local alchemists required four fresh poison sacs to concoct the remedy needed to neutralize the venom coursing through his veins.",
  ["1"] = {
    {file = "Audio/Transport/full_item_venomtail-poison-sac-d2ab8e72b0b7a04e1201/1-0000.mp3", duration = 52.6628571, start = 0},
  },
}
P.transport["item:venture-co-documents"] = {
  hash = "64a26c",
  fullHash = "64a26c",
  text = "Venture Co. Documents. These tightly bound papers were recovered from a crate amidst a ruined caravan in eastern Mulgore. They detail the operations of the Venture Company, confirming the predatory cartel's illegal strip-mining ventures within the tauren homeland. Discovered packed atop mined ore and minerals in the remnants of a ransacked wagon, these documents expose the scale of the Venture Company's intrusion into Mulgore. Known across Kalimdor for ruthless deforestation and uncontrolled excavation, the goblin-led cartel has quietly set up drilling and mining outposts in the eastern foothills. Morin Cloudstalker and the tauren Outrunners rely on these seized ledgers to gauge the threat to their sacred ancestral plains and rally hunters to drive the trespassers out.",
  ["1"] = {
    {file = "Audio/Transport/full_item_venture-co-documents-c3294cf1844b38a1a08b/1-0000.mp3", duration = 41.7697959, start = 0},
  },
}
P.transport["item:venture-co-engineering-plans"] = {
  hash = "ca2a73",
  fullHash = "ca2a73",
  text = "Venture Co. Engineering Plans. The Venture Co. Engineering Plans are mechanical schematics kept inside the goblin logging mill in Windshear Crag. Recovered by Alliance operatives, they detail the inner workings of the heavy machinery devastating the Stonetalon Mountains. Windshear Crag is choked with smoke and logging machinery as the Venture Company strips the forests of Stonetalon. Hidden inside their lumber mill south of Cragpool Lake, these engineering blueprints lay out the exact construction, strengths, and flaws of their specialized timber-harvesting contraptions.",
  ["1"] = {
    {file = "Audio/Transport/full_item_venture-co-engineering-plans-40e298e3cb8ba3c2054d/1-0000.mp3", duration = 31.1379592, start = 0},
  },
}
P.transport["item:venture-co-letters"] = {
  hash = "b0e934",
  fullHash = "b0e934",
  text = "Venture Co. Letters. The Venture Co. Letters are internal correspondence recovered from Windshear Mine in Stonetalon Mountains. Stolen under the cover of explosive distractions, they provide the night elf Sentinels with crucial intelligence on goblin industrial operations in the region. Windshear Crag has been overrun by the Venture Company, whose logging machines and strip-mining operations tear through the ancient woodland. To uncover the full scope of the cartel's ambitions, Alliance operatives deployed covert sabotage to create distractions and infiltrate Windshear Mine. These retrieved letters contain private communications and logistical records detailing the company's local activities, giving Sentinel leadership insight into how the defilers organize their workforce and supply lines.",
  ["1"] = {
    {file = "Audio/Transport/full_item_venture-co-letters-f910cda11d110008e6e6/1-0000.mp3", duration = 44.4081633, start = 0},
  },
}
P.transport["item:verdant-note"] = {
  hash = "af729c",
  fullHash = "af729c",
  text = "Verdant Note. The Verdant Note is a summons delivered to novice tauren druids in Camp Narache. Sent on behalf of the druid mentor Gart Mistrunner, it instructs young initiates to report for training and begin learning the rites of the Earthmother. Young tauren who demonstrate a spiritual affinity for nature receive the Verdant Note shortly after beginning their trials in the Red Cloud Mesa. Carried by a messenger sent by Gart Mistrunner, the brief missive directs the initiate to present themselves to the mentor at Camp Narache. Restless spirits and shifting elements have begun troubling Mulgore, making the instruction of new druids an urgent duty for the elders. Upon answering the note, initiates are inducted into the deeper mysteries of nature communion. Gart Mistrunner cautions young druids that although night elves share a common bond with the wild, their ancient pride keeps them distant and unwelcoming. Tauren druidism focuses strictly on reverence for the Earthmother, guiding initiates to listen to the land's restless ancestral voices and serve as her living instruments.",
  ["1"] = {
    {file = "Audio/Transport/full_item_verdant-note-50f9f3303028902cc0b9/1-0000.mp3", duration = 58.2269388, start = 0},
  },
}
P.transport["item:verdant-sigil"] = {
  hash = "0b5e93",
  fullHash = "0b5e93",
  text = "Verdant Sigil. The Verdant Sigil is an inscribed druidic token presented to fledgling night elf druids beginning their training in Shadowglen. Carried as a summons from the druid mentor Mardant Strongoak, it marks a novice's formal entry into the Cenarion teachings under the branches of Aldrassil. In the sheltered boughs of Shadowglen, young night elves who feel the call of the wild receive the Verdant Sigil from Conservator Ilthalaine. Sent via messenger from the trainer Mardant Strongoak, the token directs novices to climb into the boughs of the great tree Aldrassil. Carrying the sigil serves as a formal invitation to leave basic chores behind and commence serious training in communion with nature spirits and the deep mysteries of the Emerald Dream. Presenting the sigil to Mardant Strongoak initiates the young druid into their lifelong craft. While novices are not yet prepared to walk the sleeping trance of the Emerald Dream, acknowledging the sigil marks the start of their mentorship. Under Mardant's instruction, initiates learn to interpret the whispers of the wilderness and master early shapeshifting and healing arts in service of Teldrassil.",
  ["1"] = {
    {file = "Audio/Transport/full_item_verdant-sigil-e1cbf58eecbd584d628a/1-0000.mp3", duration = 64.235102, start = 0},
  },
}
P.transport["item:verna-s-westfall-stew-recipe"] = {
  hash = "311508",
  fullHash = "311508",
  text = "Verna's Westfall Stew Recipe. Verna's Westfall Stew Recipe is a handwritten culinary guide penned by Verna Furlbrow as she prepares to flee Westfall. Entrusted to travelers bound for Salma Saldean, it preserves a hearty regional staple amidst the collapse of the countryside. As the Defias Brotherhood and rogue harvest golems run rampant across Westfall, longtime homesteaders like Verna and Farmer Furlbrow have been forced to abandon their land. While waiting for their wagon to be repaired so they can escape toward Stormwind, Verna scribbles down her beloved formula for Westfall Stew. Rather than letting the recipe vanish with their departure, she entrusts it to passing travelers to deliver to her neighboring friend, Salma Saldean, ensuring that a warm, familiar comfort endures for those remaining behind.",
  ["1"] = {
    {file = "Audio/Transport/full_item_verna-s-westfall-stew-recipe-a17928930653ffbbf6af/1-0000.mp3", duration = 44.4081633, start = 0},
  },
}
P.transport["item:verner-s-note"] = {
  hash = "32fc6c",
  fullHash = "32fc6c",
  text = "Verner's Note. Verner's Note is a written requisition penned by Lakeshire's blacksmith, Verner Osgood, and carried to Smith Argus in Goldshire. It details a critical shortage of iron in Redridge, asking the Elwynn smith for emergency horseshoes. Maintaining the defense of Lakeshire demands a heavy toll in worked metal. With the Stormwind Guard stationed in town stretched thin against invading gnolls and local perils, Verner Osgood has consumed nearly all his iron reserves keeping soldiers armed and armored. As a result, Lakeshire's stables have fallen into neglect, lacking even basic horseshoes for their mounts. This letter represents Verner swallowing his pride to ask Smith Argus in Goldshire for an external shipment of prepared shoes to keep the town's horses mobile.",
  ["1"] = {
    {file = "Audio/Transport/full_item_verner-s-note-9f7ba111f439dfe9776b/1-0000.mp3", duration = 45.6097959, start = 0},
  },
}
P.transport["item:verog-s-head"] = {
  hash = "427b44",
  fullHash = "427b44",
  text = "Verog's Head. Verog's Head is the grisly trophy claimed from Verog the Dervish, a prominent Kolkar centaur leader who oversees forces around the Stagnant Oasis. It is sought by the orc Regthar Deathgate as proof of the chieftain's demise and to demoralize the aggressive Kolkar tribes threatening the Barrens. The Kolkar centaur pose a relentless threat to Horde travelers and supply routes across the northern Barrens. Verog the Dervish, known for his nomadic habits, leaves his command tent at the Stagnant Oasis vulnerable while roaming the arid scrubland. To bring him out into the open, Horde operatives attack his forces around his pavilion until an alarm is raised. Once Verog rushes back to defend his camp, he is slain and decapitated. Delivering his severed head to Regthar Deathgate serves as vital evidence that another dangerous Kolkar chieftain has been dismantled, joining the head of Barak Kodobane on display.",
  ["1"] = {
    {file = "Audio/Transport/full_item_verog-s-head-b58d2edf82b647f1b6db/1-0000.mp3", duration = 53.2636735, start = 0},
  },
}
P.transport["item:vial-of-innocent-blood"] = {
  hash = "c3f923",
  fullHash = "c3f923",
  text = "Vial of Innocent Blood. A Vial of Innocent Blood is a grim alchemical reagent gathered by Syndicate shadow mages lurking in the ruins of Durnholde Keep. Sought after by the Royal Apothecary Society in Tarren Mill, it serves as a key catalyst in brewing experimental toxins. Within the crumbled walls of Durnholde Keep, the fallen human nobles of the Syndicate practice dark and unsavory arts. Among them are shadow mages who systematically harvest the blood of innocents for their own occult rituals. This macabre practice has drawn the keen attention of Apothecary Lydon in Tarren Mill. Needing untainted blood to brew an experimental pacifying agent meant to neutralize the Venture Company in Stonetalon Mountains, the Forsaken apothecary sees the Syndicate's grim stores as a convenient shortcut for his work.",
  ["1"] = {
    {file = "Audio/Transport/full_item_vial-of-innocent-blood-7a6571620bb1d152a7a4/1-0000.mp3", duration = 48.404898, start = 0},
  },
}
P.transport["item:vial-of-phlogiston"] = {
  hash = "94e851",
  fullHash = "94e851",
  text = "Vial of Phlogiston. A Vial of Phlogiston is an alchemical substance used by master armorers to temper extraordinarily resilient mail. Guarded within the quilboar stronghold of Razorfen Kraul, it is coveted by both Alliance and Horde smiths forging specialized battle armor for promising warriors. Phlogiston is an intensely volatile, fire-bearing substance prized in esoteric metallurgy. Both the dwarven smith Furen Longbeard in Stormwind and the near-blind orc armorer Thun'grim Firegaze in the Barrens consider it an indispensable component for hardening warrior armor beyond ordinary physical limits. Without this alchemical agent, the specialized forging techniques required for Fire Hardened Mail or the Horde's Brutal Armor cannot be completed. Obtaining a Vial of Phlogiston requires venturing into the tangled thickets of Razorfen Kraul, located at the southern tip of the Barrens. The phlogiston is held deep within the bristling redoubt by the geomancer Roogug. Whether recovered for Furen in Stormwind or carried across the dust to Thun'grim's anvil, the substance demands a perilous descent into hostile quilboar territory.",
  ["1"] = {
    {file = "Audio/Transport/full_item_vial-of-phlogiston-77e1e0a5143ebaabd974/1-0000.mp3", duration = 66.1420408, start = 0},
  },
}
P.transport["item:vial-of-purest-water"] = {
  hash = "adacb4",
  fullHash = "adacb4",
  text = "Vial of Purest Water. The Vial of Purest Water is a sacred vessel blessed by the hermit Brine deep in the southern Barrens. Entrusted to an initiate shaman, its purified contents are essential for concocting the draught required to perceive elusive elemental spirits. Forged through trials of patience and cleansing under the guidance of Brine, the water sealed in this vial represents liquid in its uncorrupted elemental essence. Transported across the arid wastes of the Barrens back to the solitary shore where Islen Waterseer keeps watch, the vial serves as the vital component in brewing a water sapta. Without its pristine purity, a shaman cannot commune with the spiritual guardians that dwell in places far removed from the sunbaked flats.",
  ["1"] = {
    {file = "Audio/Transport/full_item_vial-of-purest-water-523afe9dcfa18bea8fc9/1-0000.mp3", duration = 42.004898, start = 0},
  },
}
P.transport["item:vial-of-spider-venom"] = {
  hash = "eeee04",
  fullHash = "eeee04",
  text = "Vial of Spider Venom. A Vial of Spider Venom contains the potent, necrotic poison harvested from the arachnids that infest the darkened woods of Duskwood. Madame Eva of Darkshire uses this dangerous extract alongside undead remains to craft protective wards against incoming harm. The shadowed thickets of Duskwood harbor monstrous arachnids—from skittering pygmy venom webs and green recluses to black widows and the notorious Naraxis. These creatures pump a foul, potent poison through their fangs, potent enough to paralyze travelers and decay flesh. Adventurers brave enough to slay these horrors can extract intact vials of the viscous fluid. In Darkshire, the fortune teller Madame Eva perceives ominous portents for travelers stepping out into the dark world. To craft a ward of retribution, she requires five vials of this raw venom, combined with ghoul fangs and skeleton fingers. Channeled through her craft, the venom’s predatory, biting nature is inverted into the Totem of Infliction, turning harm back upon anyone who attacks its bearer.",
  ["1"] = {
    {file = "Audio/Transport/full_item_vial-of-spider-venom-449fe0087b7cdf800f61/1-0000.mp3", duration = 61.1004082, start = 0},
  },
}
P.transport["item:vicious-night-web-spider-venom"] = {
  hash = "abdc12",
  fullHash = "abdc12",
  text = "Vicious Night Web Spider Venom. Vicious Night Web Spider Venom is a potent natural toxin gathered from the arachnids haunting eastern Tirisfal Glades. The Royal Apothecary Society prizes it for its peculiar ability to carry and preserve historical disease strains, making it a critical reagent in the development of the Forsaken's New Plague. According to research conducted by Apothecary Johaan in Brill, ancient texts chronicle a devastating historical plague that wiped out thousands of innocent victims. Curiously, the contagious agent behind that forgotten outbreak managed to endure over centuries by embedding itself within the venom of the local Night Web spiders. By hunting down the vicious breed lurking in Venomweb Vale south of the Scarlet Monastery, the apothecaries extract this preserved virulence to serve as a vital catalyst in their ongoing alchemical experiments.",
  ["1"] = {
    {file = "Audio/Transport/full_item_vicious-night-web-spider-venom-9aee90b6002f8303355c/1-0000.mp3", duration = 47.9346939, start = 0},
  },
}
P.transport["item:vile-familiar-head"] = {
  hash = "3cf64c",
  fullHash = "3cf64c",
  text = "Vile Familiar Head. A Vile Familiar Head is a gruesome trophy collected from the feral impish creatures dwelling near the Burning Blade Coven in the Valley of Trials. Young Horde warlocks gather them under the guidance of Ruzan as proof of their combat readiness before learning to bind their first demonic minions. The heads serve as a grim test of discipline, showing that an apprentice understands the lethality of the beings they intend to summon. Within the sun-baked canyon of the Valley of Trials, the warlock trainer Ruzan demands six Vile Familiar Heads from novices seeking to learn the art of summoning. The vile familiars that loiter outside the Burning Blade Coven are vicious, fiery imps whose diminutive stature conceals dangerous elemental cunning. Ruzan requires prospective summoners to face these fiends in battle and sever their heads to prove they can subdue and command demonic life rather than be overpowered by it. Because warlocks are barely tolerated within Thrall's Horde, training requires extreme caution; reckless novices who perish to their own conjurations only deepen the dishonor and suspicion cast upon practitioners of the dark arts.",
  ["1"] = {
    {file = "Audio/Transport/full_item_vile-familiar-head-d1d7f931732c26169250/1-0000.mp3", duration = 61.7534694, start = 0},
  },
}
P.transport["item:vile-fin-scale"] = {
  hash = "afae9d",
  fullHash = "afae9d",
  text = "Vile Fin Scale. Vile Fin Scales are harvested from the murloc tribes prowling the waterways and northern coasts of Tirisfal Glades. In Brill, the Royal Apothecary Society utilizes these resilient biological samples in their ongoing research to engineer a devastating new plague. The Royal Apothecary Society works relentlessly to craft a virulent blight capable of decimating both the living and the Scourge. Simple toxins are easy enough to brew, but creating an infectious disease that spreads effortlessly across populations requires specialized alchemical properties. Apothecary Johaan in Brill studies Vile Fin scales specifically to understand how their natural resilience and mucous coatings can aid in stabilizing and transmitting his experimental contagions. The Vile Fin tribe infests the northern shores and western shallows of Tirisfal Glades, threatening travelers and encroaching upon Forsaken territory. Gathering their scales serves a dual purpose for the Undercity: keeping the feral murloc populations in check while providing Johaan's laboratory with fresh organic components for biochemical warfare tests.",
  ["1"] = {
    {file = "Audio/Transport/full_item_vile-fin-scale-b250d5913570bfd4fbaf/1-0000.mp3", duration = 64.6269388, start = 0},
  },
}
P.transport["item:voodoo-charm"] = {
  hash = "a43358",
  fullHash = "a43358",
  text = "Voodoo Charm. The Voodoo Charm is a mystical talisman used within the barrows of Teldrassil to sever a sinister enchantment. Handed to adventurers by the spirit of Oben Rageclaw, it allows his corrupted, puppeted physical form to be permanently released so his soul may rest in the Emerald Dream.",
  ["1"] = {
    {file = "Audio/Transport/full_item_voodoo-charm-35406addf7ac98a51934/1-0000.mp3", duration = 16.117551, start = 0},
  },
}
P.transport["item:wailing-essence"] = {
  hash = "140853",
  fullHash = "140853",
  text = "Wailing Essence. Wailing Essence is a strange, concentrated substance found within the ectoplasms roaming deep inside the Wailing Caverns. Suspected of fueling the bizarre mutations spreading through the flora and fauna of the Barrens, it has drawn the attention of opportunistic alchemists eager to bottle its potent properties. The subterranean caverns beneath the central Barrens have grown thick with unnatural energy, warping beasts and giving rise to gelatinous ectoplasms. These oozing creatures concentrate a viscous substance known as Wailing Essence. While local druids observe these waters with growing dread, goblin entrepreneurs see only raw commercial opportunity. In the port town of Ratchet, an eccentric alchemist named Mebok Mizzyrix believes this essence is the missing active ingredient for a line of lucrative 'smart drinks' meant to enhance consumer intellect, utterly unconcerned with the nightmarish corruption it might actually harbor.",
  ["1"] = {
    {file = "Audio/Transport/full_item_wailing-essence-288b9dcd0d8abfdbd31b/1-0000.mp3", duration = 53.3681633, start = 0},
  },
}
P.transport["item:warsong-axe-shipment"] = {
  hash = "436d00",
  fullHash = "436d00",
  text = "Warsong Axe Shipment. The Warsong Axe Shipment is a heavy crate of newly forged axes waiting on the docks of Booty Bay in Stranglethorn Vale. Ordered by the Warsong Outriders to sustain their harvesting operations in Ashenvale, it serves as a crucial link in the Horde's overseas supply chain. Maintaining the logging operations at the Warsong Lumber Camp requires a continuous flow of durable tools that cannot always be forged on the front lines. To keep woodcutters supplied, orders are sent across the Great Sea to the neutral goblin port of Booty Bay. Stored near Wharfmaster Lozgil, this crate contains sharpened axes intended for shipment back to Splintertree Post, highlighting the logistical hurdles the Horde faces in keeping its distant frontier camps armed and functional.",
  ["1"] = {
    {file = "Audio/Transport/full_item_warsong-axe-shipment-caa4a16cfd6e4abba080/1-0000.mp3", duration = 44.2514286, start = 0},
  },
}
P.transport["item:warsong-oil"] = {
  hash = "987c2a",
  fullHash = "987c2a",
  text = "Warsong Oil. Warsong Oil is a crucial industrial lubricant intended for the machinery at the Warsong Lumber Camp in Ashenvale. A vital supply shipment was intercepted en route by local satyrs, who took the oil to their corrupted woodland sanctuaries for foul rituals. The Warsong Clan's logging efforts in Ashenvale rely heavily on heavy machinery, goblin-engineered shredders, and massive sawmills. Keeping this industrial equipment running requires a steady supply of specialized oil. Without it, the clan's timber harvest risks grinding to an abrupt halt, stalling the flow of lumber desperately needed to build Orgrimmar and fortify Horde settlements across Durotar and the Barrens. Rather than reaching Splintertree Post and the logging camps, a recent shipment of Warsong Oil was ambushed by the satyrs infesting the forest. Instead of discarding the refined fluid, the demonic servants carried the containers into their corrupted enclaves—including Night Run, Satyrnaar, and Xavian—to use the flammable lubricant in their dark, detestable rituals.",
  ["1"] = {
    {file = "Audio/Transport/full_item_warsong-oil-b32b0e577034a9d38d95/1-0000.mp3", duration = 60.2383673, start = 0},
  },
}
P.transport["item:warsong-outrider-update"] = {
  hash = "7642a7",
  fullHash = "7642a7",
  text = "Warsong Outrider Update. The Warsong Outrider Update is a military intelligence dispatch penned by a Warsong outrider stationed along the eastern borderlands of Ashenvale. Entrusted to couriers serving the Horde, it provides frontline observations vital for securing the crossing toward Azshara and strengthening the orcish foothold against night elf resistance. Stretching along the eastern road past Splintertree Post toward the ancient ruins of Azshara, the border of Ashenvale remains a volatile frontier. The Warsong Outrider Update compiles tactical sightings, patrol movements, and resource evaluations from the mounted orcish vanguards riding this perimeter. Sent back to Kadrak at the northern watchtower guarding the Barrens border, these field notes grant Horde commanders a clear assessment of enemy troop concentrations and territorial threats lurking beneath the forest canopy.",
  ["1"] = {
    {file = "Audio/Transport/full_item_warsong-outrider-update-73047405e70852983570/1-0000.mp3", duration = 48.64, start = 0},
  },
}
P.transport["item:warsong-runner-update"] = {
  hash = "c55d08",
  fullHash = "c55d08",
  text = "Warsong Runner Update. The Warsong Runner Update is a military dispatch carrying situational observations from the Zoram'gar Outpost along the western coast of Ashenvale. Delivered to the Horde commander Kadrak at the Barrens border, it helps coordinate the Warsong clan's ongoing campaign against the night elves. Positioned at the edge of the Zoram Strand, the Warsong runner at Zoram'gar Outpost keeps watch over coastal waters and nearby threats in western Ashenvale. This update contains critical intelligence gathered from the outpost's frontline scouts, documenting regional activity and securing supply lines. Carried back to Kadrak's watchtower on the Barrens border, the dispatch provides the Horde leadership with the clarity needed to fortify their position and plan subsequent movements deep in ancestral elven woods.",
  ["1"] = {
    {file = "Audio/Transport/full_item_warsong-runner-update-c8fd65ce795eaac985d7/1-0000.mp3", duration = 46.5763265, start = 0},
  },
}
P.transport["item:warsong-saw-blades"] = {
  hash = "abbfbe",
  fullHash = "abbfbe",
  text = "Warsong Saw Blades. Warsong Saw Blades are specialized industrial cutting tools ordered to supply the Horde's clear-cutting operations in Ashenvale. Delivered through goblin logistical networks, they are vital for keeping the Warsong Lumber Camp's timber machinery running. The Warsong Clan's logging efforts in Ashenvale rely heavily on heavy-duty machinery provided and maintained with goblin engineering. Standard axes alone cannot feed the Horde's massive appetite for Kalimdor lumber, requiring steam engines and circular saws that continually chew through raw timber. Because Ashenvale's ancient hardwood rapidly dulls and snaps ordinary blades, constant shipments of replacement saw blades are vital to keep the mills running at the Warsong Lumber Camp. Procuring mechanical parts deep in disputed territory is an ongoing logistical headache. While other logging supplies are frequently intercepted by hostile furbolgs or satyrs, shipments of saw blades are handled through goblin contacts like Pixel at Splintertree Post. Gathering these blades alongside rope, oil, and axes allows lumber master Locke Okarr to keep the camp operational despite constant sabotage from the native defenders.",
  ["1"] = {
    {file = "Audio/Transport/full_item_warsong-saw-blades-6c40b6b7321366effe86/1-0000.mp3", duration = 67.1085714, start = 0},
  },
}
P.transport["item:warsong-scout-update"] = {
  hash = "26a177",
  fullHash = "26a177",
  text = "Warsong Scout Update. The Warsong Scout Update is a written dispatch containing battlefield reconnaissance from Splintertree Post in Ashenvale. Gathered by a forward scout of the Warsong clan, it provides commander Kadrak with critical intelligence needed to secure the Horde's foothold against night elf resistance. As the Horde attempts to claim timber and establish supply routes through Ashenvale, scouts from the Warsong clan patrol deep behind enemy lines. The Warsong Scout Update compiles local observations from the fortified encampment of Splintertree Post, tracking night elf sentinels and territorial movements. Handed over to messengers trading routine orders, the document allows Kadrak at the Barrens-Ashenvale border to assess troop readiness and coordinate logistics in the contested woods.",
  ["1"] = {
    {file = "Audio/Transport/full_item_warsong-scout-update-49525d8277f1d41466b0/1-0000.mp3", duration = 43.3893878, start = 0},
  },
}
P.transport["item:water-of-the-seers"] = {
  hash = "1dba85",
  fullHash = "1dba85",
  text = "Water of the Seers. Water of the Seers is a sacred draught given to young tauren undertaking their tribal trials in Bloodhoof Village. Drinking the holy water near the tribal fire opens the mind to the spirit world, summoning an ethereal Plains Vision to guide the pilgrim on their spiritual journey. Prepared by tribal mystics, the Water of the Seers is an essential element of the ancient Rite of Vision. To pierce the veil between physical reality and ancestral guidance, the petitioner must drink the holy water before the central tribal fire in Bloodhoof Village. Once consumed, the potent draught grants spiritual sight, causing a ghostly guide known as the Plains Vision to materialize from the embers and lead the way toward Seer Wiserunner.",
  ["1"] = {
    {file = "Audio/Transport/full_item_water-of-the-seers-b4ce6ffa58b8f23f3490/1-0000.mp3", duration = 43.284898, start = 0},
  },
}
P.transport["item:water-pitcher"] = {
  hash = "3b2603",
  fullHash = "3b2603",
  text = "Water Pitcher. A simple vessel used to carry fresh spring water from the local well in the Red Cloud Mesa. Greatmother Hawkwind directs young tauren to haul it back to Camp Narache to instill the values of humility, service, and respect for tribal elders. Though modest in design, the water pitcher serves as an essential teaching tool for the youth of Camp Narache. Resting beside the water well on the plains southeast of the camp, it represents the daily labor required to sustain the community. By asking a novice to fill and carry the heavy vessel to Chief Hawkwind, Greatmother Hawkwind tests their character. The chore demonstrates that no duty is beneath a tribal protector, reminding young braves that tending to the everyday needs of their kin is just as vital as wielding a weapon on the hunt.",
  ["1"] = {
    {file = "Audio/Transport/full_item_water-pitcher-34e378976b6ed7a3bbd8/1-0000.mp3", duration = 44.0163265, start = 0},
  },
}
P.transport["item:webwood-egg"] = {
  hash = "dfbcc8",
  fullHash = "dfbcc8",
  text = "Webwood Egg. A Webwood Egg is an unhatched specimen gathered from the brooding nests within Shadowthread Cave in Shadowglen. Naturalists studying the corruption on Teldrassil seek out these viable eggs to study the newly hatched arachnids in secure laboratory conditions. Taming or subduing a fully grown, venomous Webwood spider is a perilous task far beyond the reach of solitary researchers. Rather than wrestling mature predators, scholars like Gilshalan Windwalker rely on unhatched eggs collected directly from clutches hidden in the dark recesses of Shadowthread Cave. Securing an unhatched egg allows naturalists to safely transport the creature and contain the emerging spiderlings upon hatching, giving them live subjects to study without facing the deadly fangs of fully grown beasts. The unnatural aggression and corruption plaguing the native wildlife of Teldrassil has alarmed scholars across the boughs. Once secured at Aldrassil, these collected eggs and gathered venoms are slated for transport down the boughs to the capital of Darnassus. Researchers hope that raising and examining the spiders in controlled environments will yield valuable insight into the dark affliction creeping through the World Tree's boughs.",
  ["1"] = {
    {file = "Audio/Transport/full_item_webwood-egg-120a2c03f842d38403f3/1-0000.mp3", duration = 70.1910204, start = 0},
  },
}
P.transport["item:webwood-ichor"] = {
  hash = "e82de4",
  fullHash = "e82de4",
  text = "Webwood Ichor. Webwood Ichor is a fluid harvested from Webwood spiders prowling Teldrassil. Dirania Silvershine needs it, along with hyacinth mushrooms and moonpetal lilies, to brew an antidote for the poisoned Iverron. The Webwood spiders that haunt Shadowglen carry a venom dangerous enough to leave Iverron gravely ill. Dirania Silvershine asks for ichor from these spiders, along with hyacinth mushrooms and moonpetal lilies, to prepare an antidote.",
  ["1"] = {
    {file = "Audio/Transport/full_item_webwood-ichor-ad5de511f78b807de313/1-0000.mp3", duration = 26.7493878, start = 0},
  },
}
P.transport["item:webwood-spider-silk"] = {
  hash = "67b326",
  fullHash = "67b326",
  text = "Webwood Spider Silk. Webwood Spider Silk is a fine, sticky thread harvested from Webwood Lurkers prowling the woods of Teldrassil. While spider silk has many craft uses, these particular swatches are sought out by suspicious figures in the boughs of the World Tree. Spun by the overgrown Webwood Lurkers that nest around Dolanaar, Webwood Spider Silk is light, remarkably strong, and dangerous to harvest. The satyr Zenn Foulhoof, who lurks along the forest road, hires young adventurers to harvest swatches of this silk alongside nightsaber fangs and strigid owl feathers. Claiming they are simply rare reagents necessary for his forest business, he relies on the naivety of newcomers to gather the wild components without questioning his corrupt nature or his true motives.",
  ["1"] = {
    {file = "Audio/Transport/full_item_webwood-spider-silk-6b081e7a1d1c9acab438/1-0000.mp3", duration = 43.5461224, start = 0},
  },
}
P.transport["item:webwood-venom-sac"] = {
  hash = "9ccff2",
  fullHash = "9ccff2",
  text = "Webwood Venom Sac. A Webwood Venom Sac is an organ harvested from the overgrown arachnids inhabiting Shadowglen on Teldrassil. Naturalists seek these samples to determine how the unnatural growth of the new World Tree has altered local wildlife. The webwood spiders dwelling around and within Shadowthread Cave are cousins to a far smaller breed of spider found elsewhere. Their sudden enlargement and predatory aggression have raised concerns among night elf researchers. Naturalists like Gilshalan Windwalker study the venom contained within these sacs to analyze its potency and composition, hoping to understand how the rapid, unblessed growth of Teldrassil is warping the creatures that live upon its boughs.",
  ["1"] = {
    {file = "Audio/Transport/full_item_webwood-venom-sac-17ae66f51d4027bbc7ce/1-0000.mp3", duration = 39.2881633, start = 0},
  },
}
P.transport["item:well-stone"] = {
  hash = "19e609",
  fullHash = "19e609",
  text = "Well Stone. Well Stones are small mineral rocks gathered from the banks and surroundings of Mulgore's water wells. Rich in subtle earthen energies, they serve as a vital component in brewing the Water of the Seers during the traditional tauren rites of passage. Resting naturally in the soft earth bordering the wells of Mulgore, Well Stones absorb the spiritual resonance of the plains and the waters beneath them. Shaman and seers such as Zarlman Two-Moons recognize these stones not as mundane river pebbles, but as receptacles of vital magic. When combined with grounded Ambercorn beneath the plains' mighty trees, their mineral properties temper the brew needed to awaken visionary trance states in young tauren undergoing the sacred Rite of Vision.",
  ["1"] = {
    {file = "Audio/Transport/full_item_well-stone-7a2b2e9dc8562d0a5b3e/1-0000.mp3", duration = 40.6465306, start = 0},
  },
}
P.transport["item:wendigo-mane"] = {
  hash = "c24eef",
  fullHash = "c24eef",
  text = "Wendigo Mane. Wendigo Manes are the thick, shaggy coats harvested from the savage wendigos roaming the frozen crags of Dun Morogh. Coveted for their heavy insulation against the biting mountain chill, these coarse pelts are tough enough to line cabin floors or the iron cabins of dwarven warmachines. The mountains of Dun Morogh are harsh and unyielding, prompting locals to make good use of the apex beasts stalking the snowdrifts. The coarse fur of a wendigo offers dense protection against bitter sub-zero drafts. Pilot Stonegear, stationed outside Kharanos, sends adventurers into the nearby Grizzled Den to gather these heavy manes. Rather than fashioning winter coats or cloaks, the eccentric pilot intends to weave them into a plush, insulating floor rug for the interior deck of his prized dwarven siege engine, Trollplow.",
  ["1"] = {
    {file = "Audio/Transport/full_item_wendigo-mane-beab24999b7722f8b567/1-0000.mp3", duration = 48.0130612, start = 0},
  },
}
P.transport["item:whitestone-oak-lumber"] = {
  hash = "1d70f7",
  fullHash = "1d70f7",
  text = "Whitestone Oak Lumber. Whitestone Oak Lumber is a sturdy crafting timber sourced from the subterranean shipyards beneath Moonbrook. Prized for its strength, it serves as a critical shaft material for sacred armaments forged by Alliance master smiths. Found deep inside the labyrinthine Deadmines of Westfall, Whitestone Oak is shaped by Goblin Woodcarvers constructing the Defias Brotherhood's clandestine war fleet. Its dense, resilient grain makes it ideally suited to bear structural strain and high-impact wear, drawing the interest of seasoned armorers who require more than common ash or pine for ceremonial and martial craft.",
  ["1"] = {
    {file = "Audio/Transport/full_item_whitestone-oak-lumber-9e91415f78999440c085/1-0000.mp3", duration = 35.0302041, start = 0},
  },
}
P.transport["item:wildmane-cleansing-totem"] = {
  hash = "b522ce",
  fullHash = "b522ce",
  text = "Wildmane Cleansing Totem. The Wildmane Cleansing Totem is a consecrated ritual implement crafted to purify the northern water well of Mulgore. Entrusted to young defenders of the land, it serves as the final instrument in driving out the toxic corruption left by encroaching goblin ventures. When goblin ventures began poisoning the land and fouling Mulgore's scarce water supplies, the tauren turned to sacred ritual to reverse the blight. After cleansing both the Winterhoof and Thunderhorn water wells, Mull Thunderhorn crafts this final totem to purge the remaining corruption at the Wildmane Water Well north of Thunder Bluff. Infused with natural spirits, the totem cleanses the fetid waters so pure life can nourish the plains once more.",
  ["1"] = {
    {file = "Audio/Transport/full_item_wildmane-cleansing-totem-7aa720452ee0a5ba12c0/1-0000.mp3", duration = 40.9338776, start = 0},
  },
}
P.transport["item:wiley-s-note"] = {
  hash = "66140b",
  fullHash = "66140b",
  text = "Wiley's Note. Wiley's Note is a confidential missive penned by the Lakeshire rogue Wiley the Black, paid as a debt to Gryan Stoutmantle. Its contents reveal alarming alliances formed by the Defias Brotherhood and draw Stormwind's intelligence service into the investigation. Penned in Redridge by the shady rogue Wiley the Black, this scribbled dispatch is handed over to settle an old favor owed to Gryan Stoutmantle. Within, Wiley exposes what he knows about the Defias Brotherhood's clandestine ambitions. His intelligence reveals that the brotherhood is not operating alone: they have brokered alliances with regional gnolls, kobolds, and goblin operatives to further their operations across the kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_item_wiley-s-note-f2d17c37d7cbc1914992/1-0000.mp3", duration = 39.7061224, start = 0},
  },
}
P.transport["item:william-s-shipment"] = {
  hash = "0a7550",
  fullHash = "0a7550",
  text = "William's Shipment. William's Shipment is a carefully boxed consignment of candles harvested from Elwynn Forest's troublesome kobolds. Packed by William Pestle in Goldshire, it is destined for his brother Morgan's alchemical business in the Stormwind Trade District. The Pestle brothers keep a steady mercantile line open between Goldshire and the capital. While William works out of Elwynn Forest gathering materials from local opportunists and adventurers, Morgan tends to the family storefront, Pestle's Apothecary, in Stormwind's Trade District. Because William cannot leave his own duties to travel north, he relies on couriers to carry this securely packed parcel of wax and candles into the city. The contents of the shipment are kobold candles, salvaged from the creatures infesting Elwynn's mines. William gathers the large candles for their wax and packs them for his brother Morgan at Pestle's Apothecary. Through William's enterprise, these reclaimed mining scavenges become useful stock for the capital's alchemical trade.",
  ["1"] = {
    {file = "Audio/Transport/full_item_william-s-shipment-1eb5407504e6ee547933/1-0000.mp3", duration = 57.6783673, start = 0},
  },
}
P.transport["item:wine-ticket"] = {
  hash = "8f0a87",
  fullHash = "8f0a87",
  text = "Wine Ticket. A Wine Ticket is a promotional voucher distributed in Stormwind to drum up business for the Gallina Winery. Presenting it to Suzetta Gallina at the family shop earns the bearer a complimentary bottle of Pinot Noir. Running a boutique vintage shop in a bustling metropolis like Stormwind requires savvy marketing. Renato Gallina hands out these printed tickets near the Trade District to draw thirsty patrons toward the Gallina Winery, which rests along the nearby canals. By promising a complimentary sample of their famous Pinot Noir, the Gallina family hopes to turn curious passersby and newly arrived adventurers into loyal lifelong customers.",
  ["1"] = {
    {file = "Audio/Transport/full_item_wine-ticket-fa9a332871c20274413a/1-0000.mp3", duration = 36.3363265, start = 0},
  },
}
P.transport["item:winterhoof-cleansing-totem"] = {
  hash = "020307",
  fullHash = "020307",
  text = "Winterhoof Cleansing Totem. The Winterhoof Cleansing Totem is a consecrated ritual implement crafted by Mull Thunderhorn in Bloodhoof Village. Carved to undo the toxic blight spread by Venture Company intruders, it channels the Earth Mother's power to purify the polluted Winterhoof Water Well. When the goblin engineers of the Venture Company encroached upon the plains of Mulgore, their industrial operations quickly tainted the land's precious subterranean water tables. In response, Mull Thunderhorn prepared the Winterhoof Cleansing Totem, imbuing the carved wood with protective magic intended to wash out the foreign poisons. Carried past hostile goblin guards to the edge of the Winterhoof Water Well, the totem disperses the contamination through a focused ritual, restoring pure drinking water to the wandering herds and native tribes of the plains.",
  ["1"] = {
    {file = "Audio/Transport/full_item_winterhoof-cleansing-totem-f1445b70e3c38c97a3ea/1-0000.mp3", duration = 46.4195918, start = 0},
  },
}
P.transport["item:witchwing-talon"] = {
  hash = "65614b",
  fullHash = "65614b",
  text = "Witchwing Talon. A Witchwing Talon is a severed claw taken from the aggressive harpies inhabiting the northwestern canyons of the Barrens. Collected as bloody proof of dead raiders, they are sought by Horde scouts at the Crossroads trying to secure vital caravan routes. The Witchwing harpies roost in the crags and ravines northwest of the Crossroads, routinely swooping down to pillage Horde supply caravans traversing the arid plains. To counter this threat, the scout Darsok Swiftdagger coordinates strikes against the flock's hierarchy. Rather than relying on simple reports, Darsok demands physical proof of every dead scavenger. Collecting these razor-sharp talons serves as concrete evidence that a marauder's throat has been cut, chipping away at the harpy rank and file before scouts dare strike higher up the chain of command.",
  ["1"] = {
    {file = "Audio/Transport/full_item_witchwing-talon-47934a62f5a09396d0c4/1-0000.mp3", duration = 44.2514286, start = 0},
  },
}
P.transport["item:wolf-heart-sample"] = {
  hash = "8a2c69",
  fullHash = "8a2c69",
  text = "Wolf Heart Sample. The Wolf Heart Sample is a preserved parcel of diseased wolf flesh transported from the blighted woodlands of Lordaeron to Kalimdor. Carried on behalf of the Royal Apothecary Society, it provides vital material for studying how northern plagues interact with the fauna of the Barrens. Harvested from the plagued wolves wandering the ruins of Lordaeron, this heart sample was originally collected through the efforts of Apothecary Renferrel before being packaged for transport across the Great Sea. The Forsaken's Royal Apothecary Society relentlessly seeks to expand its mastery over venom, blights, and biological reagents. Dispatched via courier to the Crossroads in the Barrens, the parcel represents the long reach of Undercity's chemical endeavors, connecting experiments in the scarred Eastern Kingdoms directly to the frontier outposts of Kalimdor. Upon arrival at the Crossroads, the sample is delivered into the hands of Apothecary Helbrim. Helbrim's field research centers on observing how the potent toxins born of Lordaeron's Scourge-ravaged landscape affect or adapt to the native wildlife of Kalimdor. By studying the toxicity preserved inside these wolf hearts, Helbrim hopes to uncover novel properties to refine and empower Forsaken poisons and elixirs far from home.",
  ["1"] = {
    {file = "Audio/Transport/full_item_wolf-heart-sample-65eb3c11c1fdda8303e9/1-0000.mp3", duration = 74.1616327, start = 0},
  },
}
P.transport["item:wolf-heart-samples"] = {
  hash = "566045",
  fullHash = "566045",
  text = "Wolf Heart Samples. Wolf Heart Samples are peculiar organic specimens gathered from corrupted wolves in Silverpine Forest. Despite their lethal toxicity, the hearts beat within the living creatures without killing them, drawing the intense scientific interest of the Royal Apothecary Society. While examining carcasses in Silverpine Forest, Apothecary Renferrel discovered that certain wolf hearts harbor a deadly compound. Strangely, the level of poison present within the tissue should easily be fatal to the wolves themselves. Recognizing the unique value of a physiology that thrives while saturated in lethal toxicity, Renferrel set aside tissue samples to be dispatched directly to Undercity. For the Forsaken, studying naturally resilient or toxic organisms is a critical step in mastering biological warfare and compounding new reagents. Entrusted to couriers heading deep beneath the ruins of Lordaeron, the samples are delivered to Apothecary Zinge within the Royal Apothecary Society's headquarters in the Apothecarium. Zinge and her colleagues prize novel toxins above almost all else. By dissecting and experimenting on these tainted tissues, the Society seeks to isolate the virulent compounds and unravel how the beasts survived them, hoping to apply the principles to their own alchemical projects.",
  ["1"] = {
    {file = "Audio/Transport/full_item_wolf-heart-samples-ffa8f2e71fc6dfcac20b/1-0000.mp3", duration = 72.3853061, start = 0},
  },
}
P.transport["item:wood-pulp"] = {
  hash = "528831",
  fullHash = "528831",
  text = "Wood Pulp. Wood pulp is a fibrous material carried by the dwarven personnel stationed at Bael Modan in the southern Barrens. Though harmless on its own, it serves as a key absorbent base used by the Bael'dun expedition to stabilize liquid explosives. The Ironforge dwarves at Bael Modan use heavy earth-moving equipment and chemical explosives to rip open the earth across ancestral tauren hunting grounds. Liquid nitroglycerin is notoriously unstable on its own; to make it practical for excavation and combat, dwarven engineers absorb the liquid into porous wood pulp alongside sodium nitrate to pack stable charges. Dwarven riflemen, soldiers, and officers keep bundles of this fibrous material on hand for sapping operations and field munitions.",
  ["1"] = {
    {file = "Audio/Transport/full_item_wood-pulp-f78b9e1fa2cd3c0929b6/1-0000.mp3", duration = 42.9714286, start = 0},
  },
}
P.transport["item:wooden-key"] = {
  hash = "f4c964",
  fullHash = "f4c964",
  text = "Wooden Key. The Wooden Key is a simple carved key carried by the maddened ancients roaming northern Ashenvale near the border of Felwood. It unlocks a concealed chest holding a remnant of Dartol's Rod, an ancient night elven relic. The Wooden Key is held by the Crazed and Withered Ancients wandering the shaded trails north of Raynewood Retreat. Shael'dryn once knew the local treants, but now describes their nature as twisted by corruption. One of them carries the key to a chest holding a piece of Dartol's Rod.",
  ["1"] = {
    {file = "Audio/Transport/full_item_wooden-key-1070ea906df19e1eecd2/1-0000.mp3", duration = 27.6897959, start = 0},
  },
}
P.transport["item:worn-parchment"] = {
  hash = "df3adf",
  fullHash = "df3adf",
  text = "Worn Parchment. Worn Parchments are fragmented ritual writings carried by cultists encamped around the Tower of Althalaxx in northern Darkshore. Gathered by scouts, these tattered scraps provide the first concrete clues identifying the sinister sect gathering in the ruins. North along the mist-shrouded coast of Darkshore, dark spellcasters and their zealous followers have seized the ruined Tower of Althalaxx. The foot soldiers patrolling the grounds outside, known as Dark Strand Fanatics, carry scraps of worn parchment among their personal effects. While a single piece appears as nothing more than fragmented scribbles and esoteric symbols, piecing together multiple fragments reveals the presence of a previously unknown organization: the Cult of the Dark Strand.",
  ["1"] = {
    {file = "Audio/Transport/full_item_worn-parchment-04bcfad4b5f55268dcbb/1-0000.mp3", duration = 43.2065306, start = 0},
  },
}
P.transport["item:worn-stone-token"] = {
  hash = "f29d0a",
  fullHash = "f29d0a",
  text = "Worn Stone Token. Worn Stone Tokens are small magical talismans carried by personnel and mages associated with Dalaran in the Alterac Mountains. Though their ambient magic has largely faded, they were crafted to help the Kirin Tor bind and command elemental servants. The magi of Dalaran have long possessed a formidable command over elemental entities, using specialized talismans to bend these extradimensional beings to their will. Worn Stone Tokens represent depleted or exhausted versions of these implements. Carried not only by theurgists and summoners but even by Dalaran laborers and guards stationed around the ruins and internment camps of Alterac, they demonstrate how deeply elemental binding is integrated into Dalaran's everyday operations. From their outpost in Tarren Mill, the Forsaken keep a watchful eye on the nearby wizards. Magus Voidglare sought specimens of these tokens to decipher Dalaran's methods of elemental enslavement. Keeper Bel'varil directs agents to collect worn, inert tokens first, allowing the Magus to safely analyze the foundational enchanting techniques before experimenting with more potent, volatile conduits.",
  ["1"] = {
    {file = "Audio/Transport/full_item_worn-stone-token-09de67036b038e1abfc5/1-0000.mp3", duration = 66.324898, start = 0},
  },
}
P.transport["item:woven-wand"] = {
  hash = "a18a0e",
  fullHash = "a18a0e",
  text = "Woven Wand. The Woven Wand is a unique enchanted relic crafted long ago by three Dalaran apprentice magi as a pledge of brotherhood. Following the fall of Lordaeron and bitter betrayals among its creators, the wand was hidden away in Fenris Keep before resurfacing in the hands of the Forsaken. In the days when Dalaran still trained the young magi of the north, three aspiring wizards—Bethor Iceshard, Gunther Arcanus, and Thule Ravenclaw—intertwined their individual apprentice wands into a single talisman. This Woven Wand served as both a conduit of combined magical power and a symbol of their enduring friendship. That fellowship shattered irrevocably when the Scourge swept through Lordaeron. Thule Ravenclaw chose to swear fealty to the Lich King, turning to foul necromancy. Meanwhile, the Plague of Undeath claimed both Bethor and Gunther, eventually cutting their ties to Dalaran entirely.",
  ["1"] = {
    {file = "Audio/Transport/full_item_woven-wand-25c97af1e85333f7a61a/1-0000.mp3", duration = 53.9167347, start = 0},
  },
}
P.transport["item:xavian-water-sample"] = {
  hash = "231321",
  fullHash = "231321",
  text = "Xavian Water Sample. A vial of pristine, magically infused water drawn from the base of the highest waterfall in the ancient elven ruins of Xavian. Horde mages in Orgrimmar seek it out to unravel the latent arcane powers preserved in Ashenvale's oldest sacred sites. Xavian is a fabled ancient elven city, and tales of its ancient knowledge are well known among the learned. Even in ruin, its waters are said to hold vast magical powers. Deino, an arcane instructor in Orgrimmar, tasks rising mages with trekking deep into Ashenvale to collect a fresh sample straight from the pool below Xavian's tallest waterfall. Securing it requires braving dangerous territory, as the ruins are now fiercely guarded by corrupt satyrs hostile to any meddling spellcasters.",
  ["1"] = {
    {file = "Audio/Transport/full_item_xavian-water-sample-d829acc1be242dedc099/1-0000.mp3", duration = 43.5461224, start = 0},
  },
}
P.transport["item:young-crocolisk-skin"] = {
  hash = "605730",
  fullHash = "605730",
  text = "Young Crocolisk Skin. Young Crocolisk Skin is a pliable reptile pelt harvested from juvenile crocolisks throughout the Wetlands. Prized by local tanners like James Halloran of Menethil Harbor, these softer hides are cured and exported to ports across Azeroth. Menethil Harbor serves as a bustling hub of commerce along the western coast of Khaz Modan, exporting marshland goods to distant ports. Among the town's most lucrative exports are the cured hides processed by the harbor's resident tanner, James Halloran. While full-grown crocolisks yield thick, tough scales, their young provide softer, far more workable leather. Because these juvenile skins are delicate and in high demand, Halloran relies on local hunters and passing travelers to scour the boggy marshes just outside town to keep his curing racks stocked.",
  ["1"] = {
    {file = "Audio/Transport/full_item_young-crocolisk-skin-b78489e2b9353686a0f1/1-0000.mp3", duration = 48.1697959, start = 0},
  },
}
P.transport["item:yowler-s-paw"] = {
  hash = "4f9f2a",
  fullHash = "4f9f2a",
  text = "Yowler's Paw. Yowler's Paw is the grisly trophy taken from Yowler, the ferocious pack leader of the gnolls menacing the hills above Lakeshire. Brought to the town artisan Verner Osgood, it serves as undeniable proof that the beast leading the local gnoll packs has been put down. The Redridge gnolls have long terrorized the heights surrounding Lake Everstill, their bloodcurdling howls echoing down into the settlement of Lakeshire. Among them, none is more feared than Yowler, the ruthless alpha driving their expansion. Because gnoll ears and paws are customary proof of bounties across the human territories, Verner Osgood asks brave adventurers to bring back Yowler's paw. Severing it marks not just the demise of an unusually cunning predator, but a deliberate move to shatter the chain of command among his disorganized followers. Bringing back Yowler's paw underscores the dire situation in Lakeshire. The Stormwind Army is completely consumed by the Blackrock orc threat entrenched around Stonewatch Keep, leaving civil authorities and townspeople to hire passing mercenaries for defense. In the absence of regular royal garrisons, securing proof like Yowler's paw is the only way settlers like Verner Osgood can ensure the local roads remain even marginally safe for trade and travel.",
  ["1"] = {
    {file = "Audio/Transport/full_item_yowler-s-paw-b0a5d1c57f95a20c3343/1-0000.mp3", duration = 72.1502041, start = 0},
  },
}
P.transport["item:zalazane-s-head"] = {
  hash = "a8ed48",
  fullHash = "a8ed48",
  text = "Zalazane's Head. Zalazane's Head is the grim trophy brought to Master Gadrin to confirm the fall of the traitorous witch doctor Zalazane. Its retrieval marks a crucial step in freeing the Echo Isles from the dark magic holding the Darkspear tribe's home hostage. When the witch doctor Zalazane betrayed the Darkspear tribe, he used mind-enslaving hexes to seize control of their island home, driving Vol'jin's people to the mainland shores of Durotar. From the Echo Isles, Zalazane continued to send hexed thralls across the waters to snatch more victims. To assure the anxious refugees in Sen'jin Village that the tyrant's reign of terror had broken, Master Gadrin demanded absolute physical proof of his demise. Returning the severed head not only confirms Zalazane's defeat in battle, but offers the displaced tribe a rare measure of peace and a hope of one day reclaiming their stolen islands.",
  ["1"] = {
    {file = "Audio/Transport/full_item_zalazane-s-head-2f89cdfd51869d019241/1-0000.mp3", duration = 51.5395918, start = 0},
  },
}
P.transport["item:zamah-s-note"] = {
  hash = "d540d5",
  fullHash = "d540d5",
  text = "Zamah's Note. Zamah's Note is a written dispatch sent from Zamah in Thunder Bluff across the Great Sea to Apothecary Lydon in Tarren Mill. It outlines an urgent request for an alchemical concoction capable of dealing with the Venture Company in the Stonetalon Mountains without relying on direct bloodshed. The goblin operations of the Venture Company have entrenched themselves deeply within the Stonetalon Mountains, deforesting and tearing up the sacred land. Zamah, seeking a specialized solution to dislodge them without inciting outright slaughter, turns to the expertise of the Forsaken Royal Apothecary Society. The note serves as formal correspondence detailing Stonetalon's dire situation to her colleague, Apothecary Lydon, stationed far away in Tarren Mill within the Hillsbrad Foothills of Lordaeron. Carrying the sealed message requires a long trek across continents, guiding Kalimdor travelers aboard zeppelins to the Undercity and down through Silverpine Forest into Hillsbrad. Upon receiving Zamah's dispatch, Lydon is immediately intrigued by her specific requirements, taking pride that word reached him from across the ocean and preparing to craft an alchemical answer to the goblin problem.",
  ["1"] = {
    {file = "Audio/Transport/full_item_zamah-s-note-bba5eaa2ede65304048f/1-0000.mp3", duration = 67.5004082, start = 0},
  },
}
P.transport["item:zargh-s-meats"] = {
  hash = "4e17e5",
  fullHash = "4e17e5",
  text = "Zargh's Meats. Zargh's Meats are a parcel of prime, raw cuts prepared by the orc Zargh at the Crossroads. Intended as a personal gift for Innkeeper Gryshka in Orgrimmar, they serve to introduce young Horde travelers to the regional wind rider network. Prepared by Zargh, a butcher and hunter stationed at the Crossroads in the Barrens, this package contains choice cuts of fresh meat destined for Gryshka, the innkeeper of the Valley of Strength in Orgrimmar. Because fresh game spoils quickly under the dry heat of the savannas, Zargh entrusts the parcel to couriers bound for the Crossroads roost. There, Wind Rider Master Devrak arranges swift aerial transit atop a wyvern directly to Orgrimmar's Skytower, sparing travelers an arduous overland trek through Durotar. While ostensibly an ordinary delivery of provisions, the shipment carries a fond personal sentiment. Upon receiving the bundle, Gryshka readily notes Zargh's knack for winning a lady's favor through quality game, eagerly preparing to sear the rare cuts for her inn's patrons and guests. For newly arrived orc and troll adventurers, carrying the meats provides an essential introduction to long-distance flight transit between Kalimdor's Horde settlements.",
  ["1"] = {
    {file = "Audio/Transport/full_item_zargh-s-meats-85993d9d323afef7583e/1-0000.mp3", duration = 71.6016327, start = 0},
  },
}
P.transport["item:zhevra-hooves"] = {
  hash = "b91691",
  fullHash = "b91691",
  text = "Zhevra Hooves. Zhevra Hooves are sturdy animal parts collected from the wild equines roaming the arid plains of the Barrens. They serve as hunting trophies brought to the Crossroads to prove a traveler's prowess against beasts far stronger than initial appearances suggest. Zhevras may appear to be simple striped grazers, but their compact, muscular legs carry considerable lethality. Sergra Darkthorn, the orc shaman in charge of the Crossroads, tests aspiring Horde scouts by sending them to harvest hooves from zhevra runners. The exercise is designed to hone a fledgling hunter's instincts and resilience, as a solid kick from a panicked runner is known to knock even a sturdy tauren flat on their haunches. Presenting intact hooves confirms that a hunter can handle swift, kicking quarry before moving on to Kalimdor's deadliest predators.",
  ["1"] = {
    {file = "Audio/Transport/full_item_zhevra-hooves-bf635cb985882d740a92/1-0000.mp3", duration = 46.2628571, start = 0},
  },
}
